// ============================================================================
// Helpers est�ticos para preprocesado de se�ales
// ============================================================================

static void mixToMono (const juce::AudioBuffer<float>& input, juce::AudioBuffer<float>& output)
{
    output.setSize (1, input.getNumSamples());
    output.clear();

    if (input.getNumChannels() == 1)
    {
        output.copyFrom (0, 0, input, 0, 0, input.getNumSamples());
    }
    else if (input.getNumChannels() > 1)
    {
        float invChannels = 1.0f / (float)input.getNumChannels();
        for (int channel = 0; channel < input.getNumChannels(); ++channel)
        {
            output.addFrom (0, 0, input, channel, 0, input.getNumSamples(), invChannels);
        }
    }
}

static int64_t findSilenceBoundary (const juce::AudioBuffer<float>& monoBuffer, float thresholdDb, bool leading)
{
    const float* readPtr = monoBuffer.getReadPointer (0);
    const int numSamples = monoBuffer.getNumSamples();
    const float thresholdLinear = std::pow (10.0f, thresholdDb / 20.0f);

    if (leading)
    {
        for (int i = 0; i < numSamples; ++i)
        {
            if (std::abs (readPtr[i]) >= thresholdLinear)
                return i;
        }
        return numSamples;
    }
    else
    {
        for (int i = numSamples - 1; i >= 0; --i)
        {
            if (std::abs (readPtr[i]) >= thresholdLinear)
                return i + 1;
        }
        return 0;
    }
}

// ============================================================================
// prepareSignal — Trim de silencio + mezcla a mono
// ============================================================================
AudioABComparator::PreparedSignal AudioABComparator::prepareSignal (const AudioABSignal& signal,
                                                                     const AudioABComparatorConfig& config,
                                                                     AudioABComparatorResult& /*result*/)
{
    juce::AudioBuffer<float> monoBuffer;
    mixToMono (signal.buffer, monoBuffer);

    int64_t leadingSilence = 0;
    int64_t trailingSilence = monoBuffer.getNumSamples();

    if (config.trimLeadingSilence)
        leadingSilence = findSilenceBoundary (monoBuffer, config.silenceThresholdDb, true);

    if (config.trimTrailingSilence)
        trailingSilence = findSilenceBoundary (monoBuffer, config.silenceThresholdDb, false);

    int64_t trimmedSamples = trailingSilence - leadingSilence;
    PreparedSignal prepared;
    if (trimmedSamples > 0)
    {
        prepared.buffer.setSize (1, (int)trimmedSamples);
        prepared.buffer.copyFrom (0, 0, monoBuffer, 0, (int)leadingSilence, (int)trimmedSamples);
        prepared.trimmedOffset = leadingSilence;
    }
    else
    {
        prepared.buffer.setSize (1, 0);
        prepared.trimmedOffset = 0;
    }
    return prepared;
}

// ============================================================================
// alignSignals — Correlaci�n cruzada para alinear reference y capture
// ============================================================================
void AudioABComparator::alignSignals (const PreparedSignal& ref,
                                      const PreparedSignal& cap,
                                      const AudioABComparatorConfig& config,
                                      AudioABComparatorResult& result,
                                      juce::AudioBuffer<float>& alignedRef,
                                      juce::AudioBuffer<float>& alignedCap)
{
    int offset = 0;
    double maxCorr = 0.0;

    const int N_ref = ref.buffer.getNumSamples();
    const int N_cap = cap.buffer.getNumSamples();

    if (config.enableCrossCorrelation)
    {
        int limit = std::min (config.maxAlignmentOffsetSamples, std::min (N_ref, N_cap) / 2);
        if (limit < 128) limit = std::min (N_ref, N_cap) - 1;

        double refEnergy = 0.0;
        const float* refPtr = ref.buffer.getReadPointer (0);
        for (int i = 0; i < N_ref; ++i) refEnergy += (double)(refPtr[i] * refPtr[i]);

        double capEnergy = 0.0;
        const float* capPtr = cap.buffer.getReadPointer (0);
        for (int i = 0; i < N_cap; ++i) capEnergy += (double)(capPtr[i] * capPtr[i]);

        double normFactor = std::sqrt (refEnergy * capEnergy);
        if (normFactor < 1e-9) normFactor = 1.0;

        for (int shift = -limit; shift <= limit; ++shift)
        {
            double sum = 0.0;
            int start_ref = std::max (0, -shift);
            int start_cap = std::max (0, shift);
            int len = std::min (N_ref - start_ref, N_cap - start_cap);
            if (len <= 0) continue;

            for (int k = 0; k < len; ++k)
                sum += (double)(refPtr[start_ref + k] * capPtr[start_cap + k]);

            double corr = sum / normFactor;
            if (corr > maxCorr)
            {
                maxCorr = corr;
                offset = shift;
            }
        }

        result.alignment.applied = true;
        result.alignment.sampleOffset = offset;
        result.alignment.timeOffsetMs = ((double)offset / result.input.sampleRate) * 1000.0;
        result.alignment.correlationPeak = maxCorr;
    }
    else
    {
        result.alignment.applied = false;
        result.alignment.sampleOffset = 0;
        result.alignment.timeOffsetMs = 0.0;
        result.alignment.correlationPeak = 1.0;
    }

    // Recortar al tramo com�n final alineado
    int start_ref = std::max (0, -offset);
    int start_cap = std::max (0, offset);
    int commonLength = std::min (N_ref - start_ref, N_cap - start_cap);

    if (commonLength > 0)
    {
        alignedRef.setSize (1, commonLength);
        alignedRef.copyFrom (0, 0, ref.buffer, 0, start_ref, commonLength);

        alignedCap.setSize (1, commonLength);
        alignedCap.copyFrom (0, 0, cap.buffer, 0, start_cap, commonLength);

        double totalOriginal = (double)std::max (N_ref, N_cap);
        result.alignment.overlapRatio = (double)commonLength / (totalOriginal > 0.0 ? totalOriginal : 1.0);
    }
    else
    {
        alignedRef.setSize (1, 0);
        alignedCap.setSize (1, 0);
        result.alignment.overlapRatio = 0.0;
    }
}

#include "AudioABComparator.h"
#include <juce_dsp/juce_dsp.h>
#include <cmath>

// ============================================================================
// computeSpectralMetrics — FFT, bandas espectrales, centroid, flatness
// ============================================================================
void AudioABComparator::computeSpectralMetrics (const juce::AudioBuffer<float>& ref,
                                                 const juce::AudioBuffer<float>& cap,
                                                 const AudioABComparatorConfig& config,
                                                 AudioABComparatorResult& result)
{
    const float* refPtr = ref.getReadPointer (0);
    const float* capPtr = cap.getReadPointer (0);
    const int N = ref.getNumSamples();

    const int fftSize = config.fftSize;
    if (N < fftSize)
    {
        result.warnings.add ("La se�al es demasiado corta para calcular m�tricas espectrales.");
        return;
    }

    // Ventana Hanning
    juce::AudioBuffer<float> window (1, fftSize);
    float* winPtr = window.getWritePointer (0);
    for (int i = 0; i < fftSize; ++i)
        winPtr[i] = 0.5f * (1.0f - std::cos (2.0f * juce::MathConstants<float>::pi * (float)i / (float)(fftSize - 1)));

    juce::dsp::FFT fft (std::log2 (fftSize));
    const int numBins = fftSize / 2 + 1;

    std::vector<double> avgMagRef (numBins, 0.0);
    std::vector<double> avgMagCap (numBins, 0.0);

    int count = 0;
    for (int start = 0; start <= N - fftSize; start += fftSize / 2) // 50% overlap
    {
        std::vector<float> frameRef (fftSize * 2, 0.0f);
        std::vector<float> frameCap (fftSize * 2, 0.0f);

        for (int i = 0; i < fftSize; ++i)
        {
            frameRef[i] = refPtr[start + i] * winPtr[i];
            frameCap[i] = capPtr[start + i] * winPtr[i];
        }

        fft.performFrequencyOnlyForwardTransform (frameRef.data());
        fft.performFrequencyOnlyForwardTransform (frameCap.data());

        for (int bin = 0; bin < numBins; ++bin)
        {
            avgMagRef[bin] += (double)frameRef[bin];
            avgMagCap[bin] += (double)frameCap[bin];
        }
        count++;
    }

    if (count > 0)
    {
        for (int bin = 0; bin < numBins; ++bin)
        {
            avgMagRef[bin] /= (double)count;
            avgMagCap[bin] /= (double)count;
        }
    }

    // Diferencias acumuladas por bandas
    double logMagDiffSum = 0.0;
    double centroidRef = 0.0, centroidCap = 0.0;
    double sumRef = 0.0, sumCap = 0.0;
    double logSumRef = 0.0, logSumCap = 0.0;
    int validBins = 0;

    double binWidthHz = result.input.sampleRate / (double)fftSize;
    double lowSum = 0.0, midSum = 0.0, highSum = 0.0;
    int lowCount = 0, midCount = 0, highCount = 0;

    for (int bin = 0; bin < numBins; ++bin)
    {
        double freqHz = (double)bin * binWidthHz;
        double refDb = 20.0 * std::log10 (std::max (avgMagRef[bin], 1e-5));
        double capDb = 20.0 * std::log10 (std::max (avgMagCap[bin], 1e-5));

        double diffDb = std::abs (refDb - capDb);
        logMagDiffSum += diffDb;

        centroidRef += freqHz * avgMagRef[bin];
        sumRef += avgMagRef[bin];
        centroidCap += freqHz * avgMagCap[bin];
        sumCap += avgMagCap[bin];

        logSumRef += std::log (std::max (avgMagRef[bin], 1e-12));
        logSumCap += std::log (std::max (avgMagCap[bin], 1e-12));
        validBins++;

        if (freqHz < 200.0)       { lowSum  += diffDb; lowCount++;  }
        else if (freqHz < 2000.0) { midSum  += diffDb; midCount++;  }
        else                      { highSum += diffDb; highCount++; }
    }

    result.spectral.logMagMeanAbsDiffDb = logMagDiffSum / (double)numBins;
    result.spectral.spectralCentroidDeltaHz = std::abs (
        (sumRef > 0.0 ? centroidRef / sumRef : 0.0) - (sumCap > 0.0 ? centroidCap / sumCap : 0.0));

    double arithMeanRef = sumRef / (double)validBins;
    double arithMeanCap = sumCap / (double)validBins;
    double geoMeanRef = std::exp (logSumRef / (double)validBins);
    double geoMeanCap = std::exp (logSumCap / (double)validBins);
    double flatnessRef = (arithMeanRef > 1e-12) ? geoMeanRef / arithMeanRef : 0.0;
    double flatnessCap = (arithMeanCap > 1e-12) ? geoMeanCap / arithMeanCap : 0.0;
    result.spectral.spectralFlatnessDelta = std::abs (flatnessRef - flatnessCap);

    result.spectral.lowBandDeltaDb  = lowCount  > 0 ? lowSum  / (double)lowCount  : 0.0;
    result.spectral.midBandDeltaDb  = midCount  > 0 ? midSum  / (double)midCount  : 0.0;
    result.spectral.highBandDeltaDb = highCount > 0 ? highSum / (double)highCount : 0.0;
}

/**
 * @purpose Audio A/B Recorder: lifecycle, file I/O, analysis, and manifest writing.
 * Audio streaming methods (processHardwareInput, renderSoftwareReference) are
 * in AudioABRecorder_Process.cpp.
 */
#include "AudioABRecorder.h"

AudioABRecorder::AudioABRecorder() {}
AudioABRecorder::~AudioABRecorder() {}

void AudioABRecorder::prepare(double sampleRate_, int maxBlockSize_,
                               int numInputChannels_, int numOutputChannels_)
{
    (void)maxBlockSize_;
    (void)numOutputChannels_;
    sampleRate = sampleRate_;
    maxBlockSize = maxBlockSize_;
    numInputChannels = numInputChannels_;
    numOutputChannels = numOutputChannels_;
}

void AudioABRecorder::setOutputRoot(const juce::File& rootDir)
{
    outputRoot = rootDir;
}

bool AudioABRecorder::beginRun(const AudioABRunConfig& config, const juce::String& snapshotJson)
{
    if (running)
        return false;

    currentConfig = config;
    patchSnapshotJson = snapshotJson;
    startedAt = juce::Time::getCurrentTime();

    if (!outputRoot.exists())
        outputRoot.createDirectory();

    currentRunDir = outputRoot.getChildFile(currentConfig.runId);
    if (!currentRunDir.exists())
        currentRunDir.createDirectory();

    double totalDuration = currentConfig.noteDurationSec + currentConfig.tailDurationSec;
    int totalSamples = (int)(totalDuration * currentConfig.sampleRate);

    hardwareBuffer.setSize(currentConfig.numChannels, totalSamples);
    hardwareBuffer.clear();
    hardwareWritePos = 0;

    softwareBuffer.setSize(currentConfig.numChannels, totalSamples);
    softwareBuffer.clear();

    running = true;
    return true;
}

bool AudioABRecorder::finishRun(AudioABRunResult& result)
{
    if (!running)
        return false;

    running = false;

    juce::File hwWavFile = currentRunDir.getChildFile("hardware.wav");
    juce::File swWavFile = currentRunDir.getChildFile("software.wav");

    bool hwWriteOk = writeWav(hwWavFile, hardwareBuffer, currentConfig.sampleRate, currentConfig.bitDepth);
    bool swWriteOk = writeWav(swWavFile, softwareBuffer, currentConfig.sampleRate, currentConfig.bitDepth);

    if (!hwWriteOk || !swWriteOk)
    {
        result.ok = false;
        result.error = "Error writing WAV files.";
        return false;
    }

    result.runId = currentConfig.runId;
    result.patchName = currentConfig.patchName;
    result.startedAt = startedAt;
    result.outputDir = currentRunDir;
    result.hardwareTake = buildTakeInfo("hardware", hwWavFile, hardwareBuffer, currentConfig.sampleRate);
    result.softwareTake = buildTakeInfo("software", swWavFile, softwareBuffer, currentConfig.sampleRate);
    result.manifestFile = currentRunDir.getChildFile("audio_ab_manifest.json");

    if (!writeManifest(result, patchSnapshotJson))
    {
        result.ok = false;
        result.error = "Error writing manifest.json.";
        return false;
    }

    result.ok = true;
    return true;
}

void AudioABRecorder::abortRun()
{
    running = false;
}

bool AudioABRecorder::isRunning() const noexcept
{
    return running;
}

// ---- File I/O and analysis helpers ----

bool AudioABRecorder::writeWav(const juce::File& file, const juce::AudioBuffer<float>& buffer,
                                double sampleRate, int bitDepth)
{
    file.deleteFile();

    std::unique_ptr<juce::FileOutputStream> fileStream(file.createOutputStream());
    if (fileStream == nullptr)
        return false;

    juce::WavAudioFormat wavFormat;
    std::unique_ptr<juce::AudioFormatWriter> writer(wavFormat.createWriterFor(
        fileStream.get(), sampleRate, buffer.getNumChannels(), bitDepth, {}, 0
    ));

    if (writer == nullptr)
        return false;

    fileStream.release(); // writer now owns the stream
    return writer->writeFromAudioSampleBuffer(buffer, 0, buffer.getNumSamples());
}

AudioABTakeInfo AudioABRecorder::buildTakeInfo(const juce::String& kind,
                                                const juce::File& wavFile,
                                                const juce::AudioBuffer<float>& buffer,
                                                double sampleRate) const
{
    AudioABTakeInfo info;
    info.kind = kind;
    info.wavFile = wavFile;
    info.numSamples = buffer.getNumSamples();
    info.sampleRate = sampleRate;
    info.numChannels = buffer.getNumChannels();
    info.durationSec = (double)info.numSamples / sampleRate;

    // Compute peak and RMS across all channels
    float peak = 0.0f;
    double sumSquares = 0.0;

    for (int ch = 0; ch < buffer.getNumChannels(); ++ch)
    {
        float p = buffer.getMagnitude(ch, 0, buffer.getNumSamples());
        if (p > peak)
            peak = p;

        const float* readPtr = buffer.getReadPointer(ch);
        for (int i = 0; i < buffer.getNumSamples(); ++i)
            sumSquares += readPtr[i] * readPtr[i];
    }

    double rms = std::sqrt(sumSquares / (buffer.getNumSamples() * buffer.getNumChannels()));
    info.peakDbfs = juce::Decibels::gainToDecibels(peak);
    info.rmsDbfs = juce::Decibels::gainToDecibels((float)rms);

    return info;
}

bool AudioABRecorder::writeManifest(const AudioABRunResult& result, const juce::String& snapshotJson) const
{
    juce::DynamicObject::Ptr root = new juce::DynamicObject();
    root->setProperty("schema_version", "1.0.0");
    root->setProperty("run_id", result.runId);
    root->setProperty("patch_name", result.patchName);
    root->setProperty("started_at_utc", result.startedAt.toString(true, true));

    juce::DynamicObject::Ptr engine = new juce::DynamicObject();
    engine->setProperty("sample_rate", currentConfig.sampleRate);
    engine->setProperty("bit_depth", currentConfig.bitDepth);
    engine->setProperty("channels", currentConfig.numChannels);
    engine->setProperty("note", currentConfig.midiNote);
    engine->setProperty("velocity", currentConfig.velocity);
    engine->setProperty("note_duration_sec", currentConfig.noteDurationSec);
    engine->setProperty("tail_duration_sec", currentConfig.tailDurationSec);
    root->setProperty("engine", engine.get());

    juce::DynamicObject::Ptr files = new juce::DynamicObject();
    files->setProperty("hardware_wav", result.hardwareTake.wavFile.getFileName());
    files->setProperty("software_wav", result.softwareTake.wavFile.getFileName());
    files->setProperty("patch_snapshot_json", "patch_snapshot.json");
    root->setProperty("files", files.get());

    auto addTakeStats = [](juce::DynamicObject* obj, const AudioABTakeInfo& take)
    {
        obj->setProperty("num_samples", (int64)take.numSamples);
        obj->setProperty("duration_sec", take.durationSec);
        obj->setProperty("peak_dbfs", take.peakDbfs);
        obj->setProperty("rms_dbfs", take.rmsDbfs);
    };

    juce::DynamicObject::Ptr hw = new juce::DynamicObject();
    addTakeStats(hw.get(), result.hardwareTake);
    root->setProperty("hardware", hw.get());

    juce::DynamicObject::Ptr sw = new juce::DynamicObject();
    addTakeStats(sw.get(), result.softwareTake);
    root->setProperty("software", sw.get());

    juce::DynamicObject::Ptr comparison = new juce::DynamicObject();
    comparison->setProperty("status", "pending");
    comparison->setProperty("latency_offset_samples", juce::var());
    comparison->setProperty("rms_delta_db", juce::var());
    comparison->setProperty("spectral_distance", juce::var());
    root->setProperty("comparison", comparison.get());

    juce::var rootVar(root.get());
    juce::String jsonStr = juce::JSON::toString(rootVar);

    result.manifestFile.deleteFile();
    if (!result.manifestFile.appendText(jsonStr))
        return false;

    juce::File snapFile = currentRunDir.getChildFile("patch_snapshot.json");
    snapFile.deleteFile();
    return snapFile.appendText(snapshotJson);
}

