namespace ABD
{
    DriftEngine::DriftEngine()
    {
        // Initialize to silent state — no random offsets.
        // setDriftParams() kicks the oscillators into motion when
        // the user actually turns up drift amount.
        for (auto* osc : { &osc1Pitch, &osc2Pitch, &vcfCutoff, &vcfResonance, &envTime })
        {
            osc->targetValue  = 0.0f;
            osc->currentValue = 0.0f;
            osc->samplesUntilNextTarget = 0.0;
        }
    }

    void DriftEngine::setSampleRate(double newSampleRate)
    {
        sampleRate = std::max(1.0, newSampleRate);

        // Recalculate target intervals for all oscillators at the new sample rate
        double interval = computeTargetInterval();
        for (auto* osc : { &osc1Pitch, &osc2Pitch, &vcfCutoff, &vcfResonance, &envTime })
        {
            osc->targetIntervalSamples = interval;
        }
    }

    void DriftEngine::setDriftParams(float voiceDriftNorm, float paramDriftNorm, float driftRateNorm)
    {
        // voiceDrift: 0-1 → 0 a 50 cents de desviación máxima
        voiceDriftAmount = std::clamp(voiceDriftNorm, 0.0f, 1.0f);
        // paramDrift: 0-1 → 0 a 0.2 de modulación normalizada
        paramDriftAmount = std::clamp(paramDriftNorm, 0.0f, 1.0f);
        // driftRate: 0-1 → 0.01Hz a 10Hz (período de 100s a 0.1s)
        driftRate = std::clamp(driftRateNorm, 0.0f, 1.0f);

        // Recalcular intervalos de target para todos los osciladores
        double interval = computeTargetInterval();
        for (auto* osc : { &osc1Pitch, &osc2Pitch, &vcfCutoff, &vcfResonance, &envTime })
        {
            osc->targetIntervalSamples = interval;
        }
    }

    double DriftEngine::computeTargetInterval() const
    {
        // driftRate mapea:
        //   0.0 → período muy largo (~10 segundos = slow drift)
        //   0.5 → período medio (~1 segundo)
        //   1.0 → período rápido (~0.1 segundos = micro-shimmer)
        double minInterval = sampleRate * 0.05;   // 50ms (rápido)
        double maxInterval = sampleRate * 10.0;   // 10s (lento)
        // Mapeo exponencial para mejor respuesta perceptual
        double t = (double)driftRate;
        double interval = maxInterval * std::pow(minInterval / maxInterval, t);
        return std::max(minInterval, interval);
    }

    void DriftEngine::resetForNote(float /*voiceIndex*/)
    {
        // Drift is a continuous background process — reset state on Note-On to start
        // clean, which also ensures correct parameter scaling.
        for (auto* osc : { &osc1Pitch, &osc2Pitch, &vcfCutoff, &vcfResonance, &envTime })
        {
            osc->currentValue = 0.0f;
            osc->targetValue = 0.0f;
            // nextRandomFloat() devuelve [-1, +1]; mapear a [0, 1] y escalar
            float r = nextRandomFloat() * 0.5f + 0.5f; // [0, 1]
            osc->samplesUntilNextTarget = osc->targetIntervalSamples * (0.5 + 0.5 * r);
        }
    }

    void DriftEngine::nextSample()
    {
        // Cada oscilador de drift se actualiza una muestra
        updateOscillator(osc1Pitch, voiceDriftAmount, osc1PitchDrift);
        updateOscillator(osc2Pitch, voiceDriftAmount, osc2PitchDrift);
        updateOscillator(vcfCutoff, paramDriftAmount, vcfCutoffDrift);
        updateOscillator(vcfResonance, paramDriftAmount, vcfResonanceDrift);
        updateOscillator(envTime, paramDriftAmount, envTimeDrift);
    }

    void DriftEngine::updateOscillator(DriftOsc& osc, float amplitudeScale, float& output)
    {
        // When amplitudeScale is zero, no drift is requested — hold at zero
        // deterministically.  This makes drift=0 useful for calibration.
        if (amplitudeScale <= 0.0f)
        {
            osc.currentValue = 0.0f;
            osc.targetValue  = 0.0f;
            output = 0.0f;
            return;
        }

        // 1. Decrementar contador de samples hasta el próximo target
        osc.samplesUntilNextTarget -= 1.0;

        if (osc.samplesUntilNextTarget <= 0.0)
        {
            // Elegir nuevo target aleatorio con el LCG local
            osc.pickNewTarget(amplitudeScale, nextRandomFloat());
            // El slew factor determina qué tan rápido llegar al target.
            // Se expresa en Hz (per-second) y se divide por el sampleRate del DAW
            // para obtener el factor per-sample: el comportamiento físico queda
            // invariante entre sample rates.
            double slewBase = (kSlewBasePerSec + driftRate * kSlewRatePerSec) / sampleRate;
            // Variar el slew aleatoriamente en cada nuevo target
            float r1 = nextRandomFloat() * 0.5f + 0.5f; // [0, 1]
            osc.slewFactor = (float)(slewBase * (0.5 + r1));
            // Programar el próximo cambio de target con un poco de jitter
            float r2 = nextRandomFloat() * 0.5f + 0.5f; // [0, 1]
            osc.samplesUntilNextTarget = osc.targetIntervalSamples * (0.8 + 0.4 * r2);
        }

        // 2. Glide suave hacia el target (filtro de 1-polo)
        float diff = osc.targetValue - osc.currentValue;
        osc.currentValue += diff * osc.slewFactor;

        // 3. currentValue already scaled by amplitudeScale in pickNewTarget
        //    (removed double-scaling that produced amplitudeScale² output)

        // 4. Saturación suave para evitar valores extremos
        output = std::tanh(osc.currentValue * 2.0f) / 2.0f;
    }
    float DriftEngine::nextRandomFloat()
    {
        // LCG clásico (misma implementación que LFO::nextRandomFloat)
        driftSeed = driftSeed * 1664525u + 1013904223u;
        return -1.0f + 2.0f * (static_cast<float>(driftSeed & 0x7FFFFFFFu) / 2147483647.0f);
    }
}

#pragma once

#include <cstdint>
#include <cmath>
#include <algorithm>

namespace ABD
{
    /**
     * DriftEngine genera fluctuaciones lentas y aleatorias (Brownian noise)
     * para simular la inestabilidad de componentes analógicos (VCO, VCF, envolventes).
     *
     * Cada oscilador de drift es un random-walk suavizado:
     *   - A intervalos regulares (controlados por driftRate) se elige un nuevo target aleatorio
     *   - El valor actual glidea suavemente hacia el target
     *   - La amplitud del drift se escala por voiceDrift o paramDrift
     */
    class DriftEngine
    {
    public:
        DriftEngine();
        ~DriftEngine() = default;

        void setSampleRate(double sampleRate);

        /** Configura los parámetros de drift (llamar desde updateParameters) */
        void setDriftParams(float voiceDriftNorm, float paramDriftNorm, float driftRateNorm);

        /** Prepara el motor para una nueva nota.
         *  Solo re-randomiza el timing offset; NO toca targets ni currentValue
         *  (el drift es un proceso Browniano continuo en background). */
        void resetForNote(float voiceIndex);

        /**
         * Avanza los osciladores de drift una muestra.
         * Debe llamarse una vez por muestra en processSample.
         */
        void nextSample();

        // --- Salidas de drift ---
        /** Drift de afinación para OSC1 en semitonos (± rango según voiceDrift) */
        float getOsc1PitchDrift() const { return osc1PitchDrift; }
        /** Drift de afinación para OSC2 en semitonos (independiente de OSC1) */
        float getOsc2PitchDrift() const { return osc2PitchDrift; }
        /** Drift para VCF Cutoff (normalizado, se suma al cutoff) */
        float getVcfCutoffDrift() const { return vcfCutoffDrift; }
        /** Drift para VCF Resonance (normalizado, se suma a la resonancia) */
        float getVcfResonanceDrift() const { return vcfResonanceDrift; }
        /** Drift para tiempos de envolvente (normalizado, escala attack/decay/release) */
        float getEnvTimeDrift() const { return envTimeDrift; }

    private:
        double sampleRate = 44100.0;

        // --- Tuning del slew de drift, en Hz (por segundo), derivado del tuning
        //     legacy por-muestra a 44.1 kHz: base 0.0001/sample y 0.01/sample por
        //     unidad de driftRate -> x44100 muestras/s. El cómputo per-sample usa
        //     solo sampleRate (DAW): slew/sample = (basePerSec + drift·ratePerSec)/sr.
        static constexpr double kSlewBasePerSec = 4.41;       // 0.0001 * 44100
        static constexpr double kSlewRatePerSec = 441.0;      // 0.01 * 44100

        // --- Parámetros (normalizados 0-1 desde la UI) ---
        float voiceDriftAmount = 0.0f;   // escala para pitch drift (cents)
        float paramDriftAmount = 0.0f;   // escala para VCF/Env drift
        float driftRate = 0.0f;           // velocidad de cambio (0=lentísimo, 1=rápido)

        // --- Estado de cada oscilador de drift ---
        struct DriftOsc
        {
            double samplesUntilNextTarget = 0.0;
            double targetIntervalSamples = 44100.0; // samples entre cambios de target (set en setSampleRate)
            float currentValue = 0.0f;
            float targetValue = 0.0f;
            float slewFactor = 0.001f; // qué tan rápido glidea (mayor = más rápido)

            void pickNewTarget(float amplitudeScale, float randomVal)
            {
                // randomVal viene en [-1, +1] desde DriftEngine::nextRandomFloat()
                // Escalar por amplitud deseada
                targetValue = randomVal * amplitudeScale;
            }
        };

        DriftOsc osc1Pitch;    // Drift de afinación OSC1
        DriftOsc osc2Pitch;    // Drift de afinación OSC2
        DriftOsc vcfCutoff;    // Drift de cutoff del filtro
        DriftOsc vcfResonance; // Drift de resonancia del filtro
        DriftOsc envTime;      // Drift de tiempos de envolvente

        // Valores de salida actuales
        float osc1PitchDrift = 0.0f;
        float osc2PitchDrift = 0.0f;
        float vcfCutoffDrift = 0.0f;
        float vcfResonanceDrift = 0.0f;
        float envTimeDrift = 0.0f;

        /** Actualiza un oscilador: avanza el random walk una muestra */
        void updateOscillator(DriftOsc& osc, float amplitudeScale, float& output);

        /** Calcula el intervalo en samples entre cambios de target según driftRate */
        double computeTargetInterval() const;

        /**
         * Genera un valor aleatorio en [-1, 1] usando LCG (Linear Congruential Generator).
         * Thread-safe porque solo el audio thread llama a nextSample().
         * Misma implementación que LFO::nextRandomFloat() para consistencia.
         */
        float nextRandomFloat();

        /** Semilla del LCG local (no compartida, thread-safe por diseño) */
        uint32_t driftSeed = 1;
    };
}

#pragma once
#include <cmath>
#include <algorithm>
#include <cstdint>
#include <bit>

namespace ABD
{
namespace DSP
{
    /**
     * 2nd-order PolyBLEP residual for anti-aliasing at waveform discontinuities.
     *
     * @param t  Current phase position in [0, 1).
     * @param dt Phase increment (freq / sampleRate).
     * @return   Correction sample to add/subtract near the discontinuity, 0 otherwise.
     *
     * Algorithm: two 2nd-order polynomial pieces (one on each side of the discontinuity)
     * that smoothly remove the staircase error from bandlimited step functions.
     * Cheaper than 4th-order (polyBlep4 in ABDJUNiO601) — sufficient for 2x oversampling
     * and good enough for the junior dev team's DSP learning curve.
     */
    inline float polyBlep2(float t, float dt)
    {
        // Near start discontinuity (phase wrap: jumps from +1 down to -1)
        if (t < dt)
        {
            float n = t / dt;
            return n + n - n * n - 1.0f;
        }
        // Near end discontinuity (approaching the wrap)
        if (t > 1.0f - dt)
        {
            float n = (t - 1.0f) / dt;
            return n + n + n * n + 1.0f;
        }
        return 0.0f;
    }

    /**
     * Sawtooth curvature — adds a parabolic bulge to a linear ramp [0, 1).
     *
     * At curvature = 0: pure linear ramp (ideal mathematical saw).
     * At curvature > 0: the ramp is slightly bowed upward, being steeper near the
     * midpoint and flatter near the ends. This models the slight nonlinearity of
     * analog RC integration circuits (Juno-106, DeepMind, etc.).
     *
     * Default calibration value from ABDJUNiO601: 0.15.
     *
     * @param phase      Current phase in [0, 1).
     * @param curvature  Bow amount, typically 0.0–0.3.
     * @return           Curved phase value in [0, 1).
     */
    inline float sawCurvature(float phase, float curvature)
    {
        return phase * (1.0f + curvature * (1.0f - phase));
    }

    /**
     * Simple 1-pole exponential smoother for slew limiting.
     *
     * @param current   Current value.
     * @param target    Target value.
     * @param coeff     Smoothing coefficient (0..1). Higher = faster response.
     * @return          Updated value.
     */
    inline float slewLimit(float current, float target, float coeff)
    {
        return current + (target - current) * coeff;
    }

    /**
     * Convert a smoothing time constant (in seconds) to the per-sample
     * coefficient of a 1-pole exponential smoother.
     *
     * A 1-pole smoother with per-sample coefficient c has time constant
     *   tau = -1/ln(1-c) samples = -1/(ln(1-c)·sr) seconds,
     * so the coefficient that realizes a given tau at sample rate sr is
     *   c(tau, sr) = 1 - exp(-1/(tau·sr)).
     *
     * Use the DAW-provided sample rate here (prepare()/setSampleRate()), never a
     * hardcoded rate: this keeps the physical response identical across sample
     * rates. Tuning constants are expressed in seconds (legacy 44.1 kHz values
     * are converted to seconds at the call sites, with the conversion documented).
     * Call once in prepare()/setSampleRate(), never per-sample (exp is hot).
     */
    inline float slewCoeffFromTimeConstant(float tauSeconds, double sampleRate)
    {
        const double sr = std::max(1.0, sampleRate);
        return 1.0f - static_cast<float>(std::exp(-1.0 / (static_cast<double>(tauSeconds) * sr)));
    }

    /**
     * VCF keytracking ratio — 1:1 per octave, multiplicative, pivoting at middle C.
     *
     *   cutoff_keytracked = cutoff * filterKeyTrackRatio(freqHz, referenceHz, keyTrackAmount)
     *
     * keyTrackAmount 0.0 → ratio 1 (cutoff unchanged for every note).
     * keyTrackAmount 1.0 → a note one octave above the reference doubles the
     * cutoff; one octave below halves it (1:1 pitch tracking, hardware behavior).
     * Intermediate values scale the tracking linearly (the ratio is the exponent).
     * referenceHz is the pivot note — hardware middle C (261.63 Hz).
     */
    inline float filterKeyTrackRatio(float freqHz, float referenceHz, float keyTrackAmount)
    {
        if (keyTrackAmount <= 0.0f || freqHz <= 0.0f || referenceHz <= 0.0f)
            return 1.0f;
        return std::pow(freqHz / referenceHz, keyTrackAmount);
    }

    /**
     * Fast tangent for the ZDF VCF, replacing std::tan on a bounded domain.
     *
     * Computes tan(x) = sin(x) / cos(x) via truncated Taylor series. Valid only
     * for x in [0, ~1.43]: the VCF clamps cutoff to 0.85·f_s so x = π·fc/f_s
     * never exceeds π·0.85 ≈ 2.67 at the filter itself, and in-engine sweeps cap
     * at fc=20 kHz with f_s=44.1 kHz (x = 1.425). No pole inside the domain, so
     * both series converge and the relative error is deterministic:
     *
     *   max |fastTan(x) - tan(x)| / |tan(x)|  <  1e-6   on [0.0001, 1.425]
     *
     * Verified against IEEE double std::tan on a dense sweep (see FastMath tests).
     * Cost: ~14 FMAs + 1 division vs MSVC std::tan (range reduction + polynomial).
     *
     * NOTE: must NOT be called with |x| >= 1.425 (error degrades sharply past
     * the Taylor convergence knee).
     */
    inline float fastTan(float x)
    {
        x = std::clamp(x, 0.0f, 1.425f);
        float x2 = x * x;
        float s = x * (1.0f + x2 * (-1.0f / 6.0f + x2 * (1.0f / 120.0f + x2 * (-1.0f / 5040.0f
                  + x2 * (1.0f / 362880.0f + x2 * (-1.0f / 39916800.0f))))));
        float c = 1.0f + x2 * (-1.0f / 2.0f + x2 * (1.0f / 24.0f + x2 * (-1.0f / 720.0f
                  + x2 * (1.0f / 40320.0f + x2 * (-1.0f / 3628800.0f)))));
        return (c > 1.0e-7f) ? (s / c) : (s * 1.0e7f);
    }

    /**
     * Fast 2^x on [-10, 10], replacing std::pow(2.0, x) in pitch/coeff paths.
     *
     * Splits x = n + f with n integer, f in [0, 1). 2^n is built exactly via
     * IEEE-754 exponent bits; 2^f uses a degree-5 least-squares (near-minimax)
     * polynomial. Verified pitch error over [-10, 10]:
     *
     *   max |1200·log2(fastExp2(x) / 2^x)|  <  0.001 cents
     *
     * The 2^f polynomial alone is accurate to ~2.3e-7 relative, so the pitch
     * error is dominated by the exponent-bit construction (exact) — total is far
     * under the 0.01 cents threshold agreed with the DSP Inspector.
     * Cost: ~7 FLOPs vs std::pow (log + exp path).
     */
    inline float fastExp2(float x)
    {
        if (x <= -126.0f) return 0.0f;
        if (x >= 126.0f) return 8.50705917e+37f;

        const float n = std::floor(x);
        const float f = x - n;
        float y = 0.99999976988588368f
                + f * (0.69315677328528258f
                + f * (0.24013170481445656f
                + f * (0.05587653949897675f
                + f * (0.00894058820920421f
                + f * 0.00189438161165486f))));

        int32_t expVal = static_cast<int32_t>(n) + 127;
        if (expVal <= 0) return 0.0f;
        if (expVal >= 255) expVal = 254;

        const std::uint32_t e = static_cast<std::uint32_t>(expVal);
        return y * std::bit_cast<float>(e << 23);
    }

    /**
     * Master output soft-clip: tanh with configurable headroom.
     *
     *   headroom == 1.0f  →  y = tanh(x)            (legacy behaviour, knee at |x| = 1.0)
     *   headroom == 2.0f  →  y = 2·tanh(x/2)        (linear up to |x| ~ 2.0, only extreme peaks fold)
     *
     * Preserves low-level signals (y ≈ x near 0 regardless of headroom) and bounds the
     * final output magnitude to exactly |y| ≤ headroom.
     */
    inline float masterSoftClip(float x, float headroom)
    {
        const float inv = 1.0f / headroom;
        return headroom * std::tanh(x * inv);
    }

    // Master soft-clip headroom mapping (SynthEngine master bus, F3-4):
    // the normalized 0..1 UI headroom is expanded to a 0..6 dB range, then
    // converted to a linear voltage ratio (20 dB per voltage decade).
    constexpr float kMasterSoftclipMaxHeadroomDb = 6.0f;
    constexpr float kDbPerVoltageRatio = 20.0f;

    /**
     * Minimal LCG random generator for deterministic per-voice personality.
     *
     * Constants from Numerical Recipes (multiplier=1664525, increment=1013904223).
     * Output: 16-bit precision normalized to [0, 1].
     */
    struct LCG {
        uint32_t state;
        explicit LCG(uint32_t seed) : state(seed) {}
        float next() {
            state = state * 1664525u + 1013904223u;
            return (float)(state & 0xFFFF) / 65535.0f;
        }
    };

} // namespace DSP
} // namespace ABD

#include "Envelope.h"
#include <cmath>
#include <algorithm>

namespace ABD
{
    Envelope::Envelope()
    {
        reset();
    }

    void Envelope::setSampleRate(double newSampleRate)
    {
        sampleRate = std::max(1.0, newSampleRate);
    }

    void Envelope::setParameters(float attackTimeSec, float decayTimeSec, float sustainLvl, float releaseTimeSec)
    {
        attackTime = std::max(0.001f, attackTimeSec);
        decayTime = std::max(0.001f, decayTimeSec);
        sustainLevel = std::clamp(sustainLvl, 0.0f, 1.0f);
        releaseTime = std::max(0.001f, releaseTimeSec);
    }

    void Envelope::setCurves(float attackCrv, float decayCrv, float sustainCrv, float releaseCrv)
    {
        attackCurve = std::clamp(attackCrv, -1.0f, 1.0f);
        decayCurve = std::clamp(decayCrv, -1.0f, 1.0f);
        sustainCurve = std::clamp(sustainCrv, -1.0f, 1.0f);
        releaseCurve = std::clamp(releaseCrv, -1.0f, 1.0f);
    }

    void Envelope::trigger()
    {
        startLevel = currentLevel;
        targetLevel = 1.0f;
        changeStage(Stage::kAttack);
    }

    void Envelope::release()
    {
        if (currentStage != Stage::kIdle)
        {
            startLevel = currentLevel;
            targetLevel = 0.0f;
            changeStage(Stage::kRelease);
        }
    }

    void Envelope::reset()
    {
        currentStage = Stage::kIdle;
        currentLevel = 0.0f;
        currentProgress = 0.0;
        progressIncrement = 0.0;
    }

    void Envelope::changeStage(Stage newStage)
    {
        currentStage = newStage;
        currentProgress = 0.0;

        switch (currentStage)
        {
            case Stage::kAttack:
                currentStageDurationSec = attackTime;
                break;
            case Stage::kDecay:
                currentStageDurationSec = decayTime;
                break;
            case Stage::kSustain:
                currentStageDurationSec = 1.0; // No increment until release
                break;
            case Stage::kRelease:
                currentStageDurationSec = releaseTime;
                break;
            case Stage::kIdle:
            default:
                currentStageDurationSec = 1.0;
                break;
        }

        progressIncrement = 1.0 / (currentStageDurationSec * sampleRate * (double)timeScale);
    }

    void Envelope::setLoopMode(bool loop)
    {
        loopMode = loop;
    }

    void Envelope::setBypassSustain(bool bypass)
    {
        bypassSustain = bypass;
    }

    void Envelope::setTimeScale(float scale)
    {
        scale = std::max(0.1f, scale); // evitar scale ≤ 0
        if (scale == timeScale) return; // hot-path guard (se llama por muestra)
        timeScale = scale;
        progressIncrement = 1.0 / (currentStageDurationSec * sampleRate * (double)scale);
    }

    float Envelope::applyCurve(float progress, float curveAmount)
    {
        if (std::abs(curveAmount) < 0.005f)
            return progress;

        float exponent = 1.0f;
        if (curveAmount < 0.0f)
            exponent = 1.0f - curveAmount * 3.0f; // curves up to 4.0
        else
            exponent = 1.0f / (1.0f + curveAmount * 3.0f); // curves down to 0.25

        return std::pow(progress, exponent);
    }

    float Envelope::nextSample()
    {
        if (currentStage == Stage::kIdle)
            return 0.0f;

        if (currentStage == Stage::kSustain)
        {
            // Sustain curve: modula sutilmente el nivel sostenido sobre el tiempo
            //   curve=0:  sustain plano (comportamiento estándar)
            //   curve<0:  el nivel decrece gradualmente (slow fade)
            //   curve>0:  el nivel crece gradualmente (slow swell)
            currentProgress += progressIncrement;
            if (currentProgress >= 1.0) currentProgress = 1.0;

            float curveMod = 0.0f;
            if (std::abs(sustainCurve) > 0.005f)
            {
                float progress = (float)currentProgress;
                float curvedProgress = applyCurve(progress, sustainCurve);
                // Desviación máxima: ±10% del sustain level
                float deviation = (curvedProgress - progress) * sustainLevel * 0.1f;
                curveMod = deviation;
            }
            currentLevel = std::clamp(sustainLevel + curveMod, 0.0f, 1.0f);
            return currentLevel;
        }

        currentProgress += progressIncrement;
        if (currentProgress >= 1.0)
        {
            currentProgress = 1.0;

            // Advance stage
            if (currentStage == Stage::kAttack)
            {
                startLevel = 1.0f;
                targetLevel = sustainLevel;
                changeStage(Stage::kDecay);
            }
            else if (currentStage == Stage::kDecay)
            {
                if (loopMode)
                {
                    // Loop mode: al completar Decay, re-trigger a Attack (sin Sustain)
                    startLevel = currentLevel;
                    targetLevel = 1.0f;
                    changeStage(Stage::kAttack);
                }
                else if (bypassSustain)
                {
                    // One-shot: salta Sustain y va directo a Release
                    startLevel = currentLevel;
                    targetLevel = 0.0f;
                    changeStage(Stage::kRelease);
                }
                else
                {
                    changeStage(Stage::kSustain);
                }
            }
            else if (currentStage == Stage::kRelease)
            {
                reset();
                return 0.0f;
            }
        }

        float progress = (float)currentProgress;
        float curvedProgress = progress;

        if (currentStage == Stage::kAttack)
        {
            // Curva de ataque: norm 0 (internal -1) = exponential (subida rápida inicial),
            // norm 255 (internal +1) = logarithmic (subida lenta inicial). applyCurve(+,amount)
            // da exponent<1 → subida rápida inicial. Se niega para invertir la polaridad.
            curvedProgress = applyCurve(progress, -attackCurve);
            currentLevel = startLevel + (targetLevel - startLevel) * curvedProgress;
        }
        else if (currentStage == Stage::kDecay)
        {
            // Curva de decay: norm 0 (internal -1) = exponential (caída rápida inicial),
            // norm 255 (internal +1) = logarithmic (caída lenta inicial). El complemento
            // 1-(1-p)^e con signo positivo da caída rápida inicial cuando decayCurve<0.
            curvedProgress = 1.0f - applyCurve(1.0f - progress, decayCurve);
            currentLevel = startLevel + (targetLevel - startLevel) * curvedProgress;
        }
        else if (currentStage == Stage::kRelease)
        {
            // Misma semántica que decay: exponencial = caída rápida inicial (norm 0),
            // logarítmica = caída lenta inicial (norm 255).
            curvedProgress = 1.0f - applyCurve(1.0f - progress, releaseCurve);
            currentLevel = startLevel + (targetLevel - startLevel) * curvedProgress;
        }

        return currentLevel;
    }
}

