{
    switch (index)
    {
        case 0: grainSizeParam = value; break;
        case 1: densityParam = value; break;
        case 2: feedbackParam = value; break;
        case 3: pitchParam = value; break;
        case 4: mix = value; break;
        default: break;
    }
}

