    private:
        double sampleRate = 44100.0;
        bool vintage;

        // Parámetros voice 1 y 2
        float semi1 = 0.5f, cent1 = 0.5f, delay1 = 0.3f;
        float gain1 = 0.5f, pan1 = 0.5f;
        float semi2 = 0.5f, cent2 = 0.5f, delay2 = 0.3f;
        float gain2 = 0.5f, pan2 = 0.5f;
