namespace ABD
{
    /**
     * FXSimpleReverb: Reverberador Schroeder-Moorer (4 comb + 3 all-pass).
     * 
     * Sirve para múltiples tipos de reverb del DeepMind 12:
     *   Hall (1), Plate (2), Rich Plate (3), Ambience (4),
     *   Gated (5), Reverse (6), Chamber (26), Room (27), Vintage (28)
     * 
     * Parámetros:
     *   0: Decay (0-1, tiempo de reverb)
     *   1: Pre-delay (0-1, 0-200ms)
     *   2: Damping (0-1, absorción HF)
     *   3: Diffusion (0-1, densidad all-pass)
     *   4: Room Size (0-1, escala longitudes de comb)
     */
    class FXSimpleReverb : public FXBase
    {
    public:
        FXSimpleReverb(int reverbType = 1); // 1=Hall, 2=Plate, etc.
        ~FXSimpleReverb() override = default;

        void prepare(double sampleRate, int samplesPerBlock) override;
        void process(const float* inL, const float* inR,
                      float* outL, float* outR,
                      int numSamples) override;
        void setParameter(int index, float value) override;
        void reset() override;
        int getNumParameters() const override { return 5; }
        juce::String getEffectName() const override;

    private:
        int reverbType;
        double sampleRate = 44100.0;

        // Parámetros
        float decay = 0.5f;
        float preDelayTime = 0.0f;
        float damping = 0.5f;
        float diffusion = 0.5f;
        float roomSize = 0.5f;

        // Pre-delay buffer
        juce::AudioSampleBuffer preDelayBuffer;
        int preDelaySamples = 0;
        int preDelayWritePos = 0;

        // Comb filters: 4 por canal
        struct CombFilter {
            float* buffer = nullptr;
            int bufferSize = 0;
            int writePos = 0;
            float feedback = 0.5f;
            float damp1 = 0.5f;
            float damp2 = 0.5f;
            float filterState = 0.0f;
        };

        CombFilter combL[4], combR[4];

        // All-pass filters: 3 por canal
        struct AllPassFilter {
            float* buffer = nullptr;
            int bufferSize = 0;
            int writePos = 0;
            float gain = 0.5f;
        };

        AllPassFilter allpassL[3], allpassR[3];

        // Almacenamiento de buffers
        juce::AudioBuffer<float> combBufferL;
        juce::AudioBuffer<float> combBufferR;
        juce::AudioBuffer<float> allpassBufferL;
        juce::AudioBuffer<float> allpassBufferR;

        void updateFilters();
        void updateCombParams();
        void setDefaultsForType(int type);
        float processComb(CombFilter& comb, float input);
        float processAllPass(AllPassFilter& ap, float input);
    };
}

/**
 * @purpose DSP audio processing kernel for FXSimpleReverb.
 * Contains the hot-path methods: processComb(), processAllPass(), and process().
 */
#include "FXSimpleReverb.h"

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

namespace ABD
{

    float FXSimpleReverb::processComb(CombFilter& comb, float input)
    {
        int readPos = comb.writePos;
        float output = comb.buffer[readPos];

        // Low-pass damping in feedback
        comb.filterState = output * comb.damp1 + comb.filterState * comb.damp2;

        // Write: input + damped feedback
        comb.buffer[comb.writePos] = input + comb.filterState * comb.feedback;

        // Advance pointer
        comb.writePos = (comb.writePos + 1) % comb.bufferSize;

        return output;
    }

    float FXSimpleReverb::processAllPass(AllPassFilter& ap, float input)
    {
        int readPos = ap.writePos;
        float bufOut = ap.buffer[readPos];
        float output = -input + bufOut;
        ap.buffer[ap.writePos] = input + bufOut * ap.gain;
        ap.writePos = (ap.writePos + 1) % ap.bufferSize;
        return output;
    }

    void FXSimpleReverb::process(const float* inL, const float* inR,
                                  float* outL, float* outR,
                                  int numSamples)
    {
        for (int s = 0; s < numSamples; ++s)
        {
            // Pre-delay
            float wetL = inL[s];
            float wetR = inR[s];

            if (preDelaySamples > 0)
            {
                int preDelayReadPos = preDelayWritePos - preDelaySamples;
                if (preDelayReadPos < 0)
                    preDelayReadPos += (int)(sampleRate * 0.2);

                float* preData = preDelayBuffer.getWritePointer(0);
                wetL = preData[preDelayReadPos];
                wetR = preData[preDelayReadPos];
                preData[preDelayWritePos] = (inL[s] + inR[s]) * 0.5f;
                preDelayWritePos = (preDelayWritePos + 1) % (int)(sampleRate * 0.2);
            }

            // Reverse: inverted phase (gated is handled by reverbScale below)
            if (reverbType == 6)
                wetL = -wetL;

            // Process comb filters in parallel
            float combSumL = 0.0f, combSumR = 0.0f;
            for (int i = 0; i < 4; ++i)
            {
                combSumL += processComb(combL[i], wetL);
                combSumR += processComb(combR[i], wetR);
            }
            combSumL *= 0.25f; // Average
            combSumR *= 0.25f;

            // Process all-pass filters in series
            for (int i = 0; i < 3; ++i)
            {
                combSumL = processAllPass(allpassL[i], combSumL);
                combSumR = processAllPass(allpassR[i], combSumR);
            }

            // Scale by decay (gated: short decay)
            float reverbScale = (decay < 0) ? 0.5f : decay * 0.7f + 0.3f;

            // 100% wet (the FXSlot handles dry/wet mix)
            outL[s] = combSumL * reverbScale;
            outR[s] = combSumR * reverbScale;
        }
    }

} // namespace ABD

#include "FXSlot.h"
#include <algorithm>

namespace ABD
{
    FXSlot::FXSlot()
    {
        std::fill(std::begin(params), std::end(params), 0.5f);
    }

    void FXSlot::prepare(double newSampleRate, int samplesPerBlock)
    {
        lastSampleRate = newSampleRate;
        lastSamplesPerBlock = samplesPerBlock;
        if (effect)
            effect->prepare(newSampleRate, samplesPerBlock);
        buffersPrepared = false;
    }

    void FXSlot::prepareBuffers(int numChannels, int numSamples)
    {
        if (buffersPrepared && wetBuffer.getNumSamples() >= numSamples
            && wetBuffer.getNumChannels() >= numChannels)
            return; // Ya preparado y suficientemente grande

        wetBuffer.setSize(numChannels, numSamples, false, false, true);
        buffersPrepared = true;
    }

    void FXSlot::setType(int newType)
    {
        newType = std::clamp(newType, 0, 56);
        if (newType == type && effect)
            return; // Mismo tipo, no recrear

        type = newType;

        if (type == 0)
        {
            effect.reset(); // Bypass
            return;
        }

        effect = createEffect(type);
        if (effect)
        {
            effect->prepare(lastSampleRate, lastSamplesPerBlock); // Auto-prepare with stored values
            syncParameters();
        }
    }

    void FXSlot::setParameter(int index, float value)
    {
        if (index >= 0 && index < 12)
        {
            params[index] = std::clamp(value, 0.0f, 1.0f);
            if (effect && index < effect->getNumParameters())
                effect->setParameter(index, params[index]);
        }
    }

    void FXSlot::setGain(float newGain)
    {
        gain = std::clamp(newGain, 0.0f, 1.0f);
    }

    void FXSlot::setMix(float newMix)
    {
        mix = std::clamp(newMix, 0.0f, 1.0f);
    }

    void FXSlot::process(juce::AudioBuffer<float>& buffer, int numSamples)
    {
        if (!isActive())
            return;

        int numChannels = std::min(buffer.getNumChannels(), 2);
        if (numChannels == 0) return;

        // Usar buffer pre-alocado (evita alocaciones en audio thread)
        prepareBuffers(numChannels, numSamples);
        wetBuffer.clear();

        const float* inL = buffer.getReadPointer(0);
        const float* inR = (numChannels > 1) ? buffer.getReadPointer(1) : buffer.getReadPointer(0);
        float* outL = wetBuffer.getWritePointer(0);
        float* outR = (numChannels > 1) ? wetBuffer.getWritePointer(1) : wetBuffer.getWritePointer(0);

        // Procesar el efecto
        effect->process(inL, inR, outL, outR, numSamples);

        // Aplicar ganancia y mezcla wet/dry
        for (int ch = 0; ch < numChannels; ++ch)
        {
            const float* dry = buffer.getReadPointer(ch);
            float* wet = wetBuffer.getWritePointer(ch);
            float* out = buffer.getWritePointer(ch);

            for (int s = 0; s < numSamples; ++s)
            {
                out[s] = dry[s] * (1.0f - mix) + wet[s] * mix * gain;
            }
        }
    }

    void FXSlot::setModulatorInput(const float* modL, const float* modR, int numSamples)
    {
        if (effect)
            effect->setModulatorInput(modL, modR, numSamples);
    }

    void FXSlot::reset()
    {
        if (effect)
            effect->reset();
    }

    void FXSlot::syncParameters()
    {
        if (!effect) return;
        int numParams = std::min(12, effect->getNumParameters());
        for (int i = 0; i < numParams; ++i)
            effect->setParameter(i, params[i]);
    }


}

