    /**
     * FXSlot: Contenedor para un slot de efecto individual.
     * 
     * Administra:
         *   - El tipo de efecto (0-56, 0=Bypass)
     *   - 12 parámetros normalizados
     *   - La ganancia de salida
     *   - La mezcla wet/dry
     *   - La instancia del efecto concreto (creada por factory)
     */
    class FXSlot
    {
    public:
        FXSlot();
        ~FXSlot() = default;

        void prepare(double sampleRate, int samplesPerBlock);
        void prepareBuffers(int numChannels, int numSamples);

        void setType(int type);
        int getType() const { return type; }

        void setParameter(int index, float value);
        float getParameter(int index) const { return (index >= 0 && index < 12) ? params[index] : 0.0f; }

        void setGain(float gain);
        float getGain() const { return gain; }

        void setMix(float mix);
        float getMix() const { return mix; }

        bool isActive() const { return type != 0 && effect != nullptr; }

        /** Forward external modulator audio to the effect (used by FXVocoder). */
        void setModulatorInput(const float* modL, const float* modR, int numSamples);

        void process(juce::AudioBuffer<float>& buffer, int numSamples);

        void reset();

    private:
        int type = 0;                 // 0=Bypass, 1-49=tipos de efecto
        float params[12] = {};        // Parámetros normalizados 0-1
        float gain = 1.0f;            // Ganancia de salida
        float mix = 0.5f;             // Mezcla wet/dry

        std::unique_ptr<FXBase> effect;

        double lastSampleRate = 44100.0;
        int lastSamplesPerBlock = 256;

        // Buffers pre-alocados para evitar alocaciones en hot-path
        juce::AudioBuffer<float> wetBuffer;
        bool buffersPrepared = false;

        void syncParameters();
        static std::unique_ptr<FXBase> createEffect(int type);
    };
}

#include "FXSlot.h"

namespace ABD
{
    std::unique_ptr<FXBase> FXSlot::createEffect(int newType)
    {
        switch (newType)
        {
            // Reverbs (Schroeder-Moorer)
            case 1:  return std::make_unique<FXSimpleReverb>(1);  // Hall
            case 2:  return std::make_unique<FXSimpleReverb>(2);  // Plate
            case 3:  return std::make_unique<FXSimpleReverb>(3);  // Rich Plate
            case 4:  return std::make_unique<FXSimpleReverb>(4);  // Ambience
            case 5:  return std::make_unique<FXSimpleReverb>(5);  // Gated
            case 6:  return std::make_unique<FXSimpleReverb>(6);  // Reverse
            case 22: return std::make_unique<FXSimpleReverb>(22); // Deep Verb
            case 26: return std::make_unique<FXSimpleReverb>(26); // Chamber
            case 27: return std::make_unique<FXSimpleReverb>(27); // Room
            case 28: return std::make_unique<FXSimpleReverb>(28); // Vintage

            // Phaser
            case 9:
                return std::make_unique<FXPhaser>();

            case 11: // Flanger
                return std::make_unique<FXFlanger>();

            case 10: // Stereo Chorus
                return std::make_unique<FXChorus>();
            case 17: // Chorus-D
                return std::make_unique<FXChorusD>();

            case 13: // Delay (single)
                return std::make_unique<FXDelay>();
            case 14: // 3Tap Delay
                return std::make_unique<FXMultiTapDelay>(3);
            case 15: // 4Tap Delay
                return std::make_unique<FXMultiTapDelay>(4);

            // Rotary Speaker
            case 16:
                return std::make_unique<FXRotarySpeaker>();

