            juce::AudioBuffer<float> buffer(2, 128);
            buffer.clear();

            for (int step = 0; step < 20; ++step)
            {
                float normalizedStep = (step < 10) ? step / 9.0f : 1.0f - (step - 10) / 9.0f;
                for (int p = 0; p < 12; ++p)
                    slot.setParameter(p, normalizedStep);

                for (int s = 0; s < 128; ++s)
