                slot.process(buffer, 128);

                for (int ch = 0; ch < 2; ++ch)
                    for (int s = 0; s < 128; ++s)
                        expect(std::isfinite(buffer.getSample(ch, s)),
                            "Sweep type " + juce::String(type) + " step " + juce::String(step) + " non-finite");
            }
            logMessage("Type " + juce::String(type) + " sweep: OK");
        }
    }
