namespace ABD
{
    /**
     * Generador de LFO multionda (Seno, Triángulo, Cuadrada, Rampas, S&H, S&G).
     */
    class LFO
    {
    public:
        enum class Shape
        {
            kSine = 0,
            kTriangle,
            kSquare,
            kRampUp,
            kRampDown,
            kSampleHold,
            kSampleGlide
        };

        LFO();
