namespace ABD
{
    /**
     * OSC1: Saw + Pulse with PWM (DeepMind Classic style).
     *
     * Improvements over original:
     *   - PolyBLEP anti-aliasing on saw and pulse edges
     *   - Sawtooth curvature modeling analog RC integration
     *   - Smooth PWM duty cycle to prevent clicks
     */
    class OSC1 : public Oscillator
    {
    public:
        OSC1();
        ~OSC1() override = default;

        void prepare(double sampleRate) override;
        void setFrequency(double hz) override;
        void setModulationValue(int destination, float value) override;

        void setSawActive(bool active);
        void setSquareActive(bool active);

        /** Set sawtooth curvature (0.0 = linear, 0.15 = analog-like, 0.3 = strong bow). */
        void setSawCurvature(float curve) { sawCurve = std::max(0.0f, std::min(curve, 1.0f)); }

        float nextSample() override;
        void resetPhase() override { phase = 0.0; }
        double getPhase() const override { return phase; }

    private:
        double currentSampleRate = 44100.0;
        double baseFrequency = 440.0;
        double phase = 0.0;
        double phaseInc = 0.0;          // track phase increment for PolyBLEP

        float pitchModValue = 0.0f;
        float pwmModValue = 0.5f;
        float currentPwmDuty = 0.5f;    // slew-limited PWM duty for smooth transitions
        float pwmSlewCoeff = 0.1f;      // per-sample slew coeff, recomputed in prepare() from DAW SR
        // PWM slew time constant in seconds. Legacy per-sample coeff was 0.1 @
        // 44.1 kHz: tau = -1/(ln(1-0.1)·44100) = 0.0002152 s.
        static constexpr float kPwmSlewTauSec = 0.00021522f;

        bool sawActive = true;
        bool squareActive = false;

        float sawCurve = 0.15f;         // analog curvature depth (ABDJUNiO601 default)
    };
}

#include "OSC2.h"
#include "DSPHelpers.h"
#include <cmath>
#include <algorithm>

namespace ABD
{
    OSC2::OSC2() {}

    void OSC2::prepare(double sampleRate)
    {
        currentSampleRate = sampleRate;
        phase = 0.0;
        phaseInc = 0.0;
        currentDuty = 0.5;
        dutySlewCoeff = DSP::slewCoeffFromTimeConstant(kDutySlewTauSec, sampleRate);
    }

    void OSC2::setFrequency(double hz)
    {
        baseFrequency = hz;
    }

    void OSC2::setModulationValue(int destination, float value)
    {
        if (destination == kPitchMod)
        {
            pitchModValue = value;
        }
        else if (destination == kToneMod)
        {
            toneModValue = std::max(0.0f, std::min(value, 1.0f));
        }
    }

    float OSC2::nextSample()
    {
        if (currentSampleRate <= 0.0) return 0.0f;

        // --- Phase advance ---
        double modHz = baseFrequency * std::pow(2.0, pitchModValue / 12.0);
        double dt = modHz / currentSampleRate;
        phase += dt;
        bool phaseWrapped = (phase >= 1.0);
        if (phaseWrapped)
            phase -= 1.0;

        phaseInc = dt;

        // --- Duty cycle with slew limiting (prevents clicks on Tone Mod changes) ---
        float targetDuty = 0.5f + toneModValue * 0.45f;
        targetDuty = std::clamp(targetDuty, 0.01f, 0.99f);
        currentDuty = DSP::slewLimit(currentDuty, targetDuty, dutySlewCoeff);

        // --- Generate square/pulse with PolyBLEP ---
        float square = (phase < currentDuty) ? 1.0f : -1.0f;
        float blepDt = static_cast<float>(dt);

        // PolyBLEP at phase wrap — RISING edge (-1 → +1)
        // polyBlep2 handles both sides: t≈0 (after wrap, +1 side) and t≈1 (before wrap, -1 side)
        square += DSP::polyBlep2(static_cast<float>(phase), blepDt);

        // PolyBLEP at duty edge — FALLING edge (+1 → -1), so subtract
        float distFromEdge = static_cast<float>(phase) - currentDuty;
        if (distFromEdge < 0.0f)
            distFromEdge += 1.0f;
        square -= DSP::polyBlep2(distFromEdge, blepDt);

        // --- Tone Mod: blend square → tanh-compressed triangle ---
        float outSample = square;

        if (toneModValue > 0.01f)
        {
            float tri = 1.0f - 2.0f * std::abs(static_cast<float>(phase) - 0.5f);
            float drive = 1.0f + toneModValue * 4.0f;
            float softClip = std::tanh(tri * drive);

            outSample = square * (1.0f - toneModValue) + softClip * toneModValue;
        }

        return outSample;
    }
}

