namespace ABD
{
    /**
     * SynthEngine coordina la polifonía (12 voces por defecto), el ruteo de MIDI,
     * la sincronización de parámetros de APVTS y el cálculo de la matriz de modulación.
     */
    class SynthEngine
    {
    public:
        SynthEngine();
        ~SynthEngine() = default;

        void prepare(double sampleRate, int samplesPerBlock);

        // Sincroniza los parámetros desde la APVTS
        void updateParameters(juce::AudioProcessorValueTreeState& apvts);

        // Procesamiento del bloque de audio y lectura de MIDI
        void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer& midiMessages);

        ModulationMatrix& getModulationMatrix() { return modMatrix; }
        const ModulationMatrix& getModulationMatrix() const { return modMatrix; }

        FXEngine& getFXEngine() { return fxEngine; }
        const FXEngine& getFXEngine() const { return fxEngine; }

        // Global HPF (post-VCA, pre-FX) — test/diagnostics hook. En producción estos
        // valores se sincronizan desde la APVTS en updateParameters().
        void setGlobalHpfCutoff(float hz) { globalHpfCutoffHz = hz; }
        void setGlobalHpfBassBoost(bool on) { globalHpfBassBoost = on; }
        float getGlobalHpfCutoff() const { return globalHpfCutoffHz; }

        /** Retorna el estado actual de las 12 voces para el DebugPanel (C++ → WebUI bridge) */
        /** Thread-safe: lee de un snapshot protegido por voiceStateLock */
        juce::var getVoiceState() const;

        /** Retorna el buffer de captura de audio para el osciloscopio en tiempo real */
        /** Retorna un Array<var> con las últimas kAudioCaptureSize muestras del canal izquierdo */
        juce::var getAudioWaveform() const;

        void panic();
        /** Reset global MIDI controllers (pitch bend, mod wheel, aftertouch, sustain)
         *  to their default values, and propagate to all active voices.
         *  Useful when entering bypass to prevent controller jumps on un-bypass. */
        void resetMidiControllers();
        bool isVoiceActive(int voiceIndex) const { return voiceIndex >= 0 && voiceIndex < kNumVoices ? voices[voiceIndex].isActive() : false; }

        /**
         * Retorna un JSON string con las notas activas y sus velocidades.
         * Ej: "[[60,0.8],[64,0.75],[67,0.82]]"
         * Thread-safe: lee del snapshot bajo voiceStateLock.
         */
        juce::String getActiveNotesJSON() const;

        EngineDiagnosticSnapshot getDiagnosticSnapshot() const;

        //==============================================================================
        // Calibration — thread-safe get/set, per-block immutable snapshot
        //==============================================================================
        /** Load calibration from JSON. Returns true on success. */
        bool loadCalibrationFromJson(const juce::String& json);
        /** Get current calibration as JSON string. */
        juce::String getCalibrationJson() const;
        /** Get the effective calibration for the current block (immutable snapshot). */
        const CalibrationSpec& getCalibration() const { return activeCalibration; }
        /** Get factory defaults. */
        static CalibrationSpec getFactoryDefaults() { return CalibrationSpec::factoryDefaults(); }

    private:
        static constexpr int kNumVoices = 12;
        SynthVoice voices[kNumVoices];
        ModulationMatrix modMatrix;
        FXEngine fxEngine;

        // --- Snapshot thread-safe para DebugPanel ---
        // El audio thread copia el estado de las voces al final de processBlock()
        // bajo voiceStateLock. getVoiceState() lee el snapshot bajo el mismo lock.
        struct VoiceSnapshot
        {
            bool active = false;
            int midiNote = -1;
            float velocity = 0.0f;
            float detuneSemitones = 0.0f;
            float panPosition = 0.5f;
            float voicePanSpread = 0.0f;
            float modOsc1DetuneSemitones = 0.0f;
            float modOsc2DetuneSemitones = 0.0f;
            float modPan = 0.5f;
            float modVcfCutoffHz = 1000.0f;
        };

        // Controladores MIDI globales (snapshot para DebugPanel)
        float snapPitchBend = 0.0f;
        float snapModWheel = 0.0f;
        float snapAftertouch = 0.0f;
        float snapSustainPedal = 0.0f;

        // Peak level de salida de audio (VU Meter para DebugPanel)
        float snapPeakLevel = 0.0f;
        mutable VoiceSnapshot voiceSnapshots[kNumVoices];
        mutable juce::CriticalSection voiceStateLock;
        mutable EngineDiagnosticSnapshot currentDiagnosticSnapshot;

        // --- Calibration: master state + per-block immutable snapshot ---
        CalibrationSpec pendingCalibration;    // written from UI/bridge thread
        CalibrationSpec activeCalibration;     // resolved once per block, read by voices
        mutable juce::CriticalSection calibrationLock;

        void updateVoiceSnapshot();

        double sampleRate = 44100.0;
        int samplesPerBlock = 512;

        // --- Voice Mode & Unison ---
        int voiceMode = 0;             // 0=Poly, 1=Uni2, 2=Uni3, 3=Uni4, 4=Uni6, 5=Uni12,
                                       // 6=Mono, 7=Mono2, 8=Mono3, 9=Mono4, 10=Mono6, 11=Poly6, 12=Poly8
        float unisonDetune = 0.0f;     // normalized 0-1, symmetrical detune ±0..±50 cents
        float vcaPanSpread = 0.0f;     // normalized 0-1, stereo spread for stacked voices

        /** Retorna cuántas voces apilar por nota en el modo actual */
        static int getVoicesPerNote(int mode);
        /** Calcula detune (semitonos) y pan (0-1) para una voz dentro de un grupo Unison */
        void getUnisonParams(int voiceInGroup, int totalInGroup,
                             float& detuneSemitones, float& panPosition) const;

        // --- Chord Memory & Poly Chord ---
        bool chordEnable = false;
        bool polyChordEnable = false;
        int chordKey = 0;      // 0=C, 1=C#, ... 11=B
        int chordType = 0;     // 0=Memory, 1=Major, 2=Minor, 3=Major7, 4=Minor7, 5=Dom7, 6=Sus4, 7=Power

        static const int* getChordIntervals(int type, int& numNotes);

        // Poly Chord: held root notes accumulator (max 12 simultaneous)
        static constexpr int kMaxChordNotes = 12;
        int polyChordHeldNotes[kMaxChordNotes] = {};
        int polyChordNoteCount = 0;

        // Transpose & Global Tune
        int transposeSemitones = 0;       // -48 .. +48 semitones
        float globalTuneCents = 0.0f;     // -128 .. +127 cents

        // Portamento / Glide
        float globalPortamentoTime = 0.0f;  // normalized 0-1
        int portaMode = 0;                  // 0-9
        float portaOscBal = 0.0f;           // -128..127

        // Note Priority (for Mono mode)
        int notePriority = 0;               // 0=Lowest, 1=Highest, 2=Last
        // Held notes tracker for Mono mode (max 12 simultaneous)
        int monoHeldNotes[12] = {};
        int monoHeldNoteCount = 0;

        // Alojamiento de voces
        int findFreeVoice();
        void triggerNote(int midiNoteNumber, float velocity);
        void triggerChordForRoot(int rootNote, int numChordNotes, const int* intervals, float velocity);
        void releaseNote(int midiNoteNumber);

        // Sustain pedal latch (CC64 hardware behavior): notes key-released while
        // the pedal is down stay sounding (envelope held at sustain). They are
        // released when the pedal goes up, but only if the finger already let go.
        int sustainLatchedNotes[128] = {};
        int sustainLatchCount = 0;
        bool isSustainLatched(int midiNoteNumber) const;
        void releaseSustainLatchedNotes();

        // LFO global para modos Mono/Spread
        LFO globalLfo1, globalLfo2;
        float lfo1MonoMode = 0.0f;
        float lfo2MonoMode = 0.0f;
        juce::Array<float> globalLfo1Buffer, globalLfo2Buffer;

        // Arpeggiator clock frequency (Hz) para LFO Arp Sync y MIDI clock
        float arpClockHz = 1.0f;
        bool arpSyncActive = false;  // true si alguna voz tiene lfoArpSync activo (para global LFOs)

        // LFO Arp Sync rates desde la tabla de Clock Divide del hardware (lfo_rate → división)
        float globalLfo1ArpSyncHz = 1.0f;
        float globalLfo2ArpSyncHz = 1.0f;

    public:
        /**
         * Mapea el rate normalizado de un LFO (0-1 → byte 0-255) a la frecuencia de Arp Sync,
         * reinterpretando el rate como división de la tabla de Clock Divide del hardware DM12
         * (20 divisiones, raw 8..255, docs lfos.md:23-48). El sync se deriva del Master BPM:
         * f = (bpm/60) / (división×4). Devuelve Hz.
         */
        static float lfoArpSyncHzFromRate(float rateNorm, float bpm);

    private:
        // Master Gain
        float globalVolume = 0.8f;

        // Global HPF (post-VCA, post-SUM, pre-FX) — hardware: VCF → VCA → SUM → HPF → FX.
        // Actúa sobre la suma de todas las voces; cutoff modulado desde fuentes "common".
        // Un filtro por canal para no acoplar el estado de los canales estéreo.
        HPF globalHpf[2];
        float globalHpfMinHz = 40.0f;
        float globalHpfMaxHz = 2000.0f;
        float globalHpfModScaleHz = 18000.0f;
        float globalHpfCutoffHz = 20.0f;       // base física del param hpf_cutoff (20-2000 Hz)
        bool  globalHpfBassBoost = false;
        float globalHpfBassBoostGain = 1.0f;

        // Master Soft-Clip (bypass + headroom)
        bool masterSoftclipBypass = false;      // true = sin soft-clip en la salida final
        float masterSoftclipHeadroom = 0.0f;    // normalized 0..1 → 0..6 dB (1.0x..~2.0x)

        // Controladores MIDI globales
        float currentPitchBend = 0.0f;
        float currentModWheel = 0.0f;
        float currentAftertouch = 0.0f;
        float currentSustainPedal = 0.0f;

        // Peak level de salida (para VU Meter en DebugPanel)
        float currentPeakLevel = 0.0f;

        // --- Audio waveform capture buffer for real-time oscilloscope ---
        static constexpr int kAudioCaptureSize = 512; // muestras por canal
        float audioCaptureBuffer[kAudioCaptureSize * 2] = {0.0f}; // stereo interleaved
        int audioCaptureWritePos = 0;

        // --- Note event tracking for WebUI LCD display ---
        // Atomic exchange pattern: audio thread writes, UI timer reads + clears.
        // -1 = no pending event.
        std::atomic<int> pendingNoteOnNote   = {-1};
        std::atomic<float> pendingNoteOnVel  = {0.0f};
        std::atomic<int> pendingNoteOffNote  = {-1};
    };
}

#include "SynthEngine.h"
#include <algorithm>
#include <cstring>

namespace ABD
{
    void SynthEngine::triggerChordForRoot(int rootNote, int numChordNotes, const int* intervals, float velocity)
    {
        int voicesPerNote = getVoicesPerNote(voiceMode);

        for (int iv = 0; iv < numChordNotes && intervals[iv] >= 0; ++iv)
        {
            int chordNote = std::clamp(rootNote + intervals[iv], 0, 127);

            for (int v = 0; v < voicesPerNote; ++v)
            {
                int voiceIdx = findFreeVoice();
                if (voiceIdx < 0 || voiceIdx >= kNumVoices)
                    break;

                float detuneST = 0.0f;
                float panPos = 0.5f;
                if (voicesPerNote > 1)
                    getUnisonParams(v, voicesPerNote, detuneST, panPos);

                voices[voiceIdx].unisonDetuneSemitones = detuneST;
                voices[voiceIdx].unisonPanPosition = panPos;
                if (voices[voiceIdx].isActive())
                    voices[voiceIdx].stopNote(true);
                voices[voiceIdx].startNote(chordNote, velocity, (float)voiceIdx / (float)(kNumVoices - 1));
                voices[voiceIdx].setRootNote(rootNote);

                voices[voiceIdx].setExternalModulation(ModSource::kPitchBend, currentPitchBend);
                voices[voiceIdx].setExternalModulation(ModSource::kModWheel, currentModWheel);
                voices[voiceIdx].setExternalModulation(ModSource::kKeyPressure, currentAftertouch);
                voices[voiceIdx].setExternalModulation(ModSource::kSustainPedal, currentSustainPedal);
            }
        }
    }

    void SynthEngine::triggerNote(int midiNoteNumber, float velocity)
    {
        // --- Chord Memory / Poly Chord expansion ---
        if (chordEnable || polyChordEnable)
        {
            int numChordNotes = 0;
            const int* intervals = getChordIntervals(chordType, numChordNotes);

            if (polyChordEnable)
            {
                // Poly Chord: acumular notas raíz
                if (polyChordNoteCount < kMaxChordNotes)
                {
                    bool alreadyHeld = false;
                    for (int h = 0; h < polyChordNoteCount; ++h)
                    {
                        if (polyChordHeldNotes[h] == midiNoteNumber)
                        {
                            alreadyHeld = true;
                            break;
                        }
                    }
                    if (!alreadyHeld)
                    {
                        polyChordHeldNotes[polyChordNoteCount++] = midiNoteNumber;
                    }
                }

                for (int i = 0; i < kNumVoices; ++i)
                {
                    if (voices[i].isActive())
                        voices[i].stopNote(true);
                }

                for (int h = 0; h < polyChordNoteCount; ++h)
                {
                    triggerChordForRoot(polyChordHeldNotes[h], numChordNotes, intervals, velocity);
                }
            }
            else
            {
                if (voiceMode >= 6 && voiceMode <= 10)
                {
                    for (int i = 0; i < kNumVoices; ++i)
                    {
                        if (voices[i].isActive())
                            voices[i].stopNote(true);
                    }
                }
                triggerChordForRoot(midiNoteNumber, numChordNotes, intervals, velocity);
            }

            pendingNoteOnNote.store(midiNoteNumber, std::memory_order_release);
            pendingNoteOnVel.store(velocity, std::memory_order_release);

            DBG("[SynthEngine] triggerNote (Chord): note=" + juce::String(midiNoteNumber)
                + " type=" + juce::String(chordType)
                + " notes=" + juce::String(numChordNotes)
                + " poly=" + juce::String(polyChordNoteCount));
            return;
        }

        // --- Normal note trigger (no chord) ---
        int voicesPerNote = getVoicesPerNote(voiceMode);

        if (voiceMode >= 6 && voiceMode <= 10)
        {
            bool alreadyHeld = false;
            for (int h = 0; h < monoHeldNoteCount; ++h)
            {
                if (monoHeldNotes[h] == midiNoteNumber)
                {
                    alreadyHeld = true;
                    break;
                }
            }
            if (!alreadyHeld && monoHeldNoteCount < 12)
                monoHeldNotes[monoHeldNoteCount++] = midiNoteNumber;

            bool shouldPlay = true;
            if (notePriority == 0 && monoHeldNoteCount > 1)
            {
                for (int h = 0; h < monoHeldNoteCount; ++h)
                {
                    if (monoHeldNotes[h] < midiNoteNumber)
                    {
                        shouldPlay = false;
                        break;
                    }
                }
            }
            else if (notePriority == 1 && monoHeldNoteCount > 1)
            {
                for (int h = 0; h < monoHeldNoteCount; ++h)
                {
                    if (monoHeldNotes[h] > midiNoteNumber)
                    {
                        shouldPlay = false;
                        break;
                    }
                }
            }

            if (shouldPlay)
            {
                for (int i = 0; i < kNumVoices; ++i)
                {
                    if (voices[i].isActive())
                        voices[i].stopNote(true);
                }
            }
            else
            {
                monoHeldNoteCount--;
                return;
            }
        }

        DBG("[SynthEngine] triggerNote: note=" + juce::String(midiNoteNumber)
            + " vel=" + juce::String(velocity)
            + " mode=" + juce::String(voiceMode)
            + " stack=" + juce::String(voicesPerNote));

        pendingNoteOnNote.store(midiNoteNumber, std::memory_order_release);
        pendingNoteOnVel.store(velocity, std::memory_order_release);

        for (int v = 0; v < voicesPerNote; ++v)
        {
            int voiceIdx = findFreeVoice();
            if (voiceIdx < 0 || voiceIdx >= kNumVoices)
                break;

            float voiceNormalized = (float)voiceIdx / (float)(kNumVoices - 1);
            float detuneST = 0.0f;
            float panPos = 0.5f;
            if (voicesPerNote > 1)
                getUnisonParams(v, voicesPerNote, detuneST, panPos);

            voices[voiceIdx].unisonDetuneSemitones = detuneST;
            voices[voiceIdx].unisonPanPosition = panPos;
            if (voices[voiceIdx].isActive())
                voices[voiceIdx].stopNote(true);
            voices[voiceIdx].startNote(midiNoteNumber, velocity, voiceNormalized);
            voices[voiceIdx].setRootNote(midiNoteNumber);

            voices[voiceIdx].setExternalModulation(ModSource::kPitchBend, currentPitchBend);
            voices[voiceIdx].setExternalModulation(ModSource::kModWheel, currentModWheel);
            voices[voiceIdx].setExternalModulation(ModSource::kKeyPressure, currentAftertouch);
            voices[voiceIdx].setExternalModulation(ModSource::kSustainPedal, currentSustainPedal);
        }
    }

    void SynthEngine::releaseNote(int midiNoteNumber)
    {
        // Sustain pedal latch: a key released while the pedal is down does NOT
        // enter its release phase — the envelope stays at sustain. The note is
        // remembered and released when the pedal goes up (releaseSustainLatchedNotes).
        if (currentSustainPedal >= 0.5f)
        {
            bool anyVoiceActive = false;
            for (int i = 0; i < kNumVoices; ++i)
            {
                if (voices[i].isActive() && voices[i].getRootNote() == midiNoteNumber)
                {
                    anyVoiceActive = true;
                    break;
                }
            }
            if (anyVoiceActive && !isSustainLatched(midiNoteNumber) && sustainLatchCount < 128)
                sustainLatchedNotes[sustainLatchCount++] = midiNoteNumber;
            return;
        }

        if (polyChordEnable)
        {
            for (int h = 0; h < polyChordNoteCount; ++h)
            {
                if (polyChordHeldNotes[h] == midiNoteNumber)
                {
                    for (int r = h; r < polyChordNoteCount - 1; ++r)
                        polyChordHeldNotes[r] = polyChordHeldNotes[r + 1];
                    polyChordNoteCount--;
                    break;
                }
            }

            if (polyChordNoteCount == 0)
            {
                for (int i = 0; i < kNumVoices; ++i)
                {
                    if (voices[i].isActive())
                        voices[i].stopNote(false);
                }
            }
            else
            {
                for (int i = 0; i < kNumVoices; ++i)
                {
                    if (voices[i].isActive() && voices[i].getRootNote() == midiNoteNumber)
                        voices[i].stopNote(false);
                }
            }
            return;
        }

        // Mono mode
        if (voiceMode >= 6 && voiceMode <= 10)
        {
            for (int h = 0; h < monoHeldNoteCount; ++h)
            {
                if (monoHeldNotes[h] == midiNoteNumber)
                {
                    for (int r = h; r < monoHeldNoteCount - 1; ++r)
                        monoHeldNotes[r] = monoHeldNotes[r + 1];
                    monoHeldNoteCount--;
                    break;
                }
            }

            if (monoHeldNoteCount > 0)
            {
                int nextNote = monoHeldNotes[0];
                if (notePriority == 1)
                {
                    for (int h = 1; h < monoHeldNoteCount; ++h)
                        if (monoHeldNotes[h] > nextNote) nextNote = monoHeldNotes[h];
                }
                else if (notePriority == 0)
                {
                    for (int h = 1; h < monoHeldNoteCount; ++h)
                        if (monoHeldNotes[h] < nextNote) nextNote = monoHeldNotes[h];
                }
                else
                {
                    nextNote = monoHeldNotes[monoHeldNoteCount - 1];
                }

                for (int i = 0; i < kNumVoices; ++i)
                {
                    if (voices[i].isActive())
                        voices[i].stopNote(true);
                }
                triggerNote(nextNote, 0.8f);
                return;
            }

            for (int i = 0; i < kNumVoices; ++i)
            {
                if (voices[i].isActive())
                    voices[i].stopNote(false);
            }
            return;
        }

        // Emitir note-off para la UI web
        pendingNoteOffNote.store(midiNoteNumber, std::memory_order_release);

        // Poly mode: liberar voces cuya nota raíz coincide con la nota liberada
        for (int i = 0; i < kNumVoices; ++i)
        {
            if (voices[i].isActive() && voices[i].getRootNote() == midiNoteNumber)
            {
                voices[i].stopNote(false);
            }
        }
    }

    bool SynthEngine::isSustainLatched(int midiNoteNumber) const
    {
        for (int i = 0; i < sustainLatchCount; ++i)
        {
            if (sustainLatchedNotes[i] == midiNoteNumber)
                return true;
        }
        return false;
    }

    void SynthEngine::releaseSustainLatchedNotes()
    {
        const int count = sustainLatchCount;
        sustainLatchCount = 0;
        for (int i = 0; i < count; ++i)
            releaseNote(sustainLatchedNotes[i]);
    }
}

#include "SynthEngine.h"
#include <algorithm>

namespace ABD
{
    float SynthEngine::lfoArpSyncHzFromRate(float rateNorm, float bpm)
    {
        // Tabla de Clock Divide del hardware DM12 (docs lfos.md:23-48): 20 divisiones
        // mapeadas a raw byte 8..255. El sync se deriva del Master BPM, no del reloj de arp.
        static const float clockDivisions[20] = {
            4.0f, 3.0f, 2.0f, 1.0f, 0.5f, 3.0f / 8.0f, 1.0f / 3.0f, 1.0f / 4.0f,
            3.0f / 16.0f, 1.0f / 6.0f, 1.0f / 8.0f, 3.0f / 32.0f, 1.0f / 12.0f,
            1.0f / 16.0f, 3.0f / 64.0f, 1.0f / 24.0f, 1.0f / 32.0f,
            3.0f / 128.0f, 1.0f / 48.0f, 1.0f / 64.0f
        };
        static const int tableSize = (int)(sizeof(clockDivisions) / sizeof(clockDivisions[0]));

        // Normalizar rateNorm → raw byte hardware (0..255), clampeado al rango de la tabla (8..255)
        int raw = std::clamp((int)(rateNorm * 255.0f + 0.5f), 8, 255);
        int index = std::min((int)((raw - 8) / 247.0f * (tableSize - 1) + 0.5f), tableSize - 1);
        const float division = clockDivisions[index];

        // El LFO completa un ciclo cada 'division' (en notas enteras) → division*4 negras.
        // frecuencia (Hz) = (bpm/60) / (division*4)
        return std::max(bpm, 20.0f) / 60.0f / (division * 4.0f);
    }

    void SynthEngine::updateParameters(juce::AudioProcessorValueTreeState& apvts)
    {
        // Lambda auxiliar para leer floats
        auto getFloat = [&](const juce::String& id) -> float {
            if (auto* param = apvts.getRawParameterValue(id))
                return param->load();
            jassertfalse; // Parámetro no encontrado — revisar ParametersSpec
            return 0.0f;
        };

        // Lambda auxiliar para leer bools
        auto getBool = [&](const juce::String& id) -> bool {
            if (auto* param = apvts.getRawParameterValue(id))
                return param->load() > 0.5f;
            jassertfalse; // Parámetro no encontrado — revisar ParametersSpec
            return false;
        };

        // Lambda auxiliar para leer enums (AudioParameterChoice)
        auto getInt = [&](const juce::String& id) -> int {
            if (auto* param = apvts.getParameter(id))
                if (auto* choice = dynamic_cast<juce::AudioParameterChoice*>(param))
                    return choice->getIndex();
            return 0;
        };

        // One-shot diagnostic: confirm updateParameters runs and params are readable
        // NOTA: Solo se imprime en Debug builds — cero I/O en hilo de audio en Release
#if JUCE_DEBUG
        {
            static bool logged = false;
            if (!logged)
            {
                logged = true;
                auto* cutoffP = apvts.getRawParameterValue("vcf_cutoff");
                auto* vcaP = apvts.getRawParameterValue("vca_level");
                auto* volP = apvts.getRawParameterValue("global_volume");
                DBG("[DSP] updateParameters FIRST CALL:"
                    + juce::String(" vcf_cutoff raw=" + juce::String(cutoffP ? cutoffP->load() : -1.0f))
                    + " vca_level raw=" + juce::String(vcaP ? vcaP->load() : -1.0f)
                    + " global_volume raw=" + juce::String(volP ? volP->load() : -1.0f));
            }
        }
#endif

        // Actualizar parámetros comunes para todas las voces
        for (int i = 0; i < kNumVoices; ++i)
        {
            auto& p = voices[i].params;

            // OSC 1
            p.osc1SawEnable = getBool("osc1_saw_enable");
            p.osc1PulseEnable = getBool("osc1_square_enable");
            p.osc1PwmAmount = getFloat("osc1_pwm_amount");
            p.osc1Range = getInt("osc1_range");
            p.osc1PitchMod = getFloat("osc1_pitch_mod");
            p.osc1PmSource = std::clamp(getInt("osc1_pm_source"), 0, 6);
            p.osc1PwmSource = std::clamp(getInt("osc1_pwm_source"), 0, 5);
            p.osc1PmMode = std::clamp(getInt("osc1_pm_mode"), 0, 1);
            p.osc1LfoAftertouch = getFloat("osc1_lfo_aftertouch");
            p.osc1LfoModwheel = getFloat("osc1_lfo_modwheel");

            // OSC 2
            p.osc2Pitch = getFloat("osc2_pitch");
            p.osc2ToneMod = getFloat("osc2_tone_mod");
            p.osc2Level = getFloat("osc2_level");
            p.osc2PitchMod = getFloat("osc2_pitch_mod");
            p.osc2Range = getInt("osc2_range");
            p.osc2PmSource = std::clamp(getInt("osc2_pm_source"), 0, 6);
            p.osc2TpmSource = std::clamp(getInt("osc2_tpm_source"), 0, 5);
            p.osc2AftertouchPitch = getFloat("osc2_aftertouch_pitch");
            p.osc2ModwheelPitch = getFloat("osc2_modwheel_pitch");

            // Global/Noise/Sub
            p.oscSync = getBool("osc_sync_enable");
            p.noiseLevel = getFloat("noise_level");
            p.subLevel = getFloat("sub_level");

            // VCF
            p.vcfCutoff = getFloat("vcf_cutoff");
            p.vcfResonance = getFloat("vcf_resonance");
            p.vcfPoleMode = getInt("vcf_pole_mode");
            p.vcfOversample = std::clamp(getInt("vcf_oversample"), 0, 2);
#if DEEP_TARGET_MODEL >= 2
            p.vcfModel = std::clamp(getInt("vcf_model"), 0, 2);
            p.vcfMoogSubMode = std::clamp(getInt("vcf_moog_submode"), 0, 2);
            p.vcfKorgSubMode = std::clamp(getInt("vcf_korg_submode"), 0, 1);
#endif
            p.vcfVoicingMode = getInt("vcf_voicing_mode");
            p.vcfEnvDepth = getFloat("vcf_env_depth");
            p.vcfEnvVel = getFloat("vcf_env_vel");
            p.vcfLfoDepth = getFloat("vcf_lfo_depth");
            p.vcfLfoSelect = getInt("vcf_lfo_select");
            p.vcfEnvPolarity = getInt("vcf_env_polarity");
            p.vcfKeyTrack = getFloat("vcf_key_tracking");
            p.vcfPitchBend = getFloat("vcf_pitch_bend");
            p.vcfAftertouchLfo = getFloat("vcf_aftertouch_lfo");
            p.vcfModwheelLfo = getFloat("vcf_modwheel_lfo");

            // HPF (params con rango físico: cutoff 20-2000 Hz, bass boost gain 0.1-3.0)
            p.hpfCutoff = getFloat("hpf_cutoff");
            p.hpfBassBoost = getBool("hpf_boost_enable");
            p.hpfBassBoostGain = getFloat("hpf_bass_boost_gain");

            // VCA
            p.vcaLevel = getFloat("vca_level");
            p.vcaMode = getInt("vca_mode");
            p.vcaEnvDepth = getFloat("vca_env_depth");
            p.vcaVelSens = getFloat("vca_vel_sens");

            // Analog Drift
            p.voiceDrift = getFloat("voice_drift");
            p.paramDrift = getFloat("param_drift");
            p.driftRate = getFloat("drift_rate");

            // Sincronizar drift engine de cada voz
            voices[i].drift.setDriftParams(p.voiceDrift, p.paramDrift, p.driftRate);

            // Sincronizar Envelopes con mapeo lineal físico (hardware DM12: raw/255*10 = 0-10s)
#if DEEP_TARGET_MODEL >= 2
            const auto& cal = activeCalibration;
#else
            struct { struct { struct { float maxTimeSec; } envelopes;
                               struct { float rateScale, rateExp; } lfo; } transfer; } cal;
            cal.transfer.envelopes.maxTimeSec = 10.0f;
            cal.transfer.lfo = { 0.041f, 7.3747f };
#endif
            auto mapEnvTime = [&cal](float rawVal) -> float {
                float normVal = juce::jlimit(0.0f, 1.0f, rawVal);
                return normVal * cal.transfer.envelopes.maxTimeSec;
            };

            voices[i].env1VCA.setParameters(
                mapEnvTime(getFloat("env1_attack")),
                mapEnvTime(getFloat("env1_decay")),
                getFloat("env1_sustain"),
                mapEnvTime(getFloat("env1_release"))
            );
            voices[i].env1VCA.setCurves(
                (getFloat("env1_attack_curve") - 0.5f) * 2.0f,
                (getFloat("env1_decay_curve") - 0.5f) * 2.0f,
                (getFloat("env1_sustain_curve") - 0.5f) * 2.0f,
                (getFloat("env1_release_curve") - 0.5f) * 2.0f
            );

            voices[i].env2VCF.setParameters(
                mapEnvTime(getFloat("env2_attack")),
                mapEnvTime(getFloat("env2_decay")),
                getFloat("env2_sustain"),
                mapEnvTime(getFloat("env2_release"))
            );
            voices[i].env2VCF.setCurves(
                (getFloat("env2_attack_curve") - 0.5f) * 2.0f,
                (getFloat("env2_decay_curve") - 0.5f) * 2.0f,
                (getFloat("env2_sustain_curve") - 0.5f) * 2.0f,
                (getFloat("env2_release_curve") - 0.5f) * 2.0f
            );

            voices[i].env3MOD.setParameters(
                mapEnvTime(getFloat("env3_attack")),
                mapEnvTime(getFloat("env3_decay")),
                getFloat("env3_sustain"),
                mapEnvTime(getFloat("env3_release"))
            );
            voices[i].env3MOD.setCurves(
                (getFloat("env3_attack_curve") - 0.5f) * 2.0f,
                (getFloat("env3_decay_curve") - 0.5f) * 2.0f,
                (getFloat("env3_sustain_curve") - 0.5f) * 2.0f,
                (getFloat("env3_release_curve") - 0.5f) * 2.0f
            );

            // Sincronizar LFOs con mapeo físico real (DeepMind 12 specs)
#if DEEP_TARGET_MODEL >= 2
            float lfo1RateHz = activeCalibration.transfer.lfo.rateScale * std::exp(activeCalibration.transfer.lfo.rateExp * getFloat("lfo1_rate"));
            float lfo1DelaySec = getFloat("lfo1_delay") * 6.59f;
            float lfo2RateHz = activeCalibration.transfer.lfo.rateScale * std::exp(activeCalibration.transfer.lfo.rateExp * getFloat("lfo2_rate"));
            float lfo2DelaySec = getFloat("lfo2_delay") * 6.59f;
#else
            static constexpr float kDefaultRateScale = 0.041f;
            static constexpr float kDefaultRateExp   = 7.3747f;
            float lfo1RateHz = kDefaultRateScale * std::exp(kDefaultRateExp * getFloat("lfo1_rate"));
            float lfo1DelaySec = getFloat("lfo1_delay") * 6.59f;
            float lfo2RateHz = kDefaultRateScale * std::exp(kDefaultRateExp * getFloat("lfo2_rate"));
            float lfo2DelaySec = getFloat("lfo2_delay") * 6.59f;
#endif

            voices[i].lfo1.setRate(lfo1RateHz);
            voices[i].lfo1.setDelay(lfo1DelaySec);
            voices[i].lfo1.setSlew(getFloat("lfo1_slew"));
            voices[i].lfo1.setShape(getInt("lfo1_shape"));
            voices[i].lfo1.setKeySync(getBool("lfo1_key_sync"));

            voices[i].lfo2.setRate(lfo2RateHz);
            voices[i].lfo2.setDelay(lfo2DelaySec);
            voices[i].lfo2.setSlew(getFloat("lfo2_slew"));
            voices[i].lfo2.setShape(getInt("lfo2_shape"));
            voices[i].lfo2.setKeySync(getBool("lfo2_key_sync"));
        }

        // Leer modo Mono/Spread para LFOs globales
        lfo1MonoMode = getFloat("lfo1_mono_mode");
        lfo2MonoMode = getFloat("lfo2_mono_mode");

        // Calcular mapeo físico para LFOs globales
#if DEEP_TARGET_MODEL >= 2
        float globalLfo1RateHz = activeCalibration.transfer.lfo.rateScale * std::exp(activeCalibration.transfer.lfo.rateExp * getFloat("lfo1_rate"));
        float globalLfo1DelaySec = getFloat("lfo1_delay") * 6.59f;
        float globalLfo2RateHz = activeCalibration.transfer.lfo.rateScale * std::exp(activeCalibration.transfer.lfo.rateExp * getFloat("lfo2_rate"));
        float globalLfo2DelaySec = getFloat("lfo2_delay") * 6.59f;
#else
        static constexpr float kDefaultRateScale = 0.041f;
        static constexpr float kDefaultRateExp   = 7.3747f;
        float globalLfo1RateHz = kDefaultRateScale * std::exp(kDefaultRateExp * getFloat("lfo1_rate"));
        float globalLfo1DelaySec = getFloat("lfo1_delay") * 6.59f;
        float globalLfo2RateHz = kDefaultRateScale * std::exp(kDefaultRateExp * getFloat("lfo2_rate"));
        float globalLfo2DelaySec = getFloat("lfo2_delay") * 6.59f;
#endif

        // Sincronizar LFOs globales con los mismos parámetros que las voces
        globalLfo1.setRate(globalLfo1RateHz);
        globalLfo1.setDelay(globalLfo1DelaySec);
        globalLfo1.setSlew(getFloat("lfo1_slew"));
        globalLfo1.setShape(getInt("lfo1_shape"));
        globalLfo1.setKeySync(getBool("lfo1_key_sync"));

        globalLfo2.setRate(globalLfo2RateHz);
        globalLfo2.setDelay(globalLfo2DelaySec);
        globalLfo2.setSlew(getFloat("lfo2_slew"));
        globalLfo2.setShape(getInt("lfo2_shape"));
        globalLfo2.setKeySync(getBool("lfo2_key_sync"));

        // Configurar el modo Mono/Spread en cada voz
        for (int i = 0; i < kNumVoices; ++i)
        {
            voices[i].lfo1MonoMode = lfo1MonoMode;
            voices[i].lfo2MonoMode = lfo2MonoMode;
        }

        // Leer parámetros de Voice Mode y Unison
        voiceMode = std::clamp(getInt("voice_mode"), 0, 12);
        unisonDetune = getFloat("unison_detune");
        vcaPanSpread = getFloat("vca_pan_spread");

        // Propagar vcaPanSpread a todas las voces
        for (int i = 0; i < kNumVoices; ++i)
            voices[i].voicePanSpread = vcaPanSpread;

        // Leer parámetros de Chord Memory
        chordEnable = getBool("chord_enable");
        polyChordEnable = getBool("poly_chord_enable");
        chordKey = std::clamp(getInt("chord_key"), 0, 11);
        chordType = std::clamp(getInt("chord_type"), 0, 7);
        
        if (!polyChordEnable)
        {
            // Si Poly Chord se desactiva, limpiar el acumulador de notas
            polyChordNoteCount = 0;
            std::memset(polyChordHeldNotes, 0, sizeof(polyChordHeldNotes));
        }

        // Leer Transpose & Global Tune
        transposeSemitones = (int)std::round(getFloat("transpose"));
        globalTuneCents = getFloat("global_tune");

        // Propagar globalTuneCents a todas las voces
        for (int i = 0; i < kNumVoices; ++i)
            voices[i].globalTuneCents = globalTuneCents;

        // Master Gain — permite boost hasta 2x (para presets que necesiten ganancia extra)
        globalVolume = std::clamp(getFloat("global_volume"), 0.0f, 2.0f);

        // Global HPF (post-VCA) — base física del cutoff y bass boost del módulo HPF
        globalHpfCutoffHz = getFloat("hpf_cutoff");
        globalHpfBassBoost = getBool("hpf_boost_enable");
        globalHpfBassBoostGain = getFloat("hpf_bass_boost_gain");

        // Master Soft-Clip — bypass y headroom configurable (0..1 → 0..6 dB)
        masterSoftclipBypass = getBool("master_softclip_bypass");
        masterSoftclipHeadroom = std::clamp(getFloat("master_softclip_headroom"), 0.0f, 1.0f);

        // Leer parámetros del arpegiador para Arp Sync de LFOs
        float arpRate = getFloat("arp_rate");
        int arpClockDiv = std::clamp(getInt("arp_clock_divider"), 0, 12);
        // Multiplicadores = negras por pulso (1 / ratio de nota). Tabla hardware arp-sequencer.md:44-60.
        static const float clockMultipliers[13] = {
            0.5f, 2.0f / 3.0f, 0.75f, 1.0f, 4.0f / 3.0f, 1.5f, 2.0f,
            8.0f / 3.0f, 3.0f, 4.0f, 6.0f, 8.0f, 12.0f
        };
        arpClockHz = (arpRate / 60.0f) * clockMultipliers[arpClockDiv];
        arpClockHz = std::max(arpClockHz, 0.01f);

        // Propagar arpClockHz a todas las voces
        for (int i = 0; i < kNumVoices; ++i)
            voices[i].arpClockHz = arpClockHz;

        // Leer Note Priority, Trigger Mode y Pitch Bend Range
        notePriority = std::clamp(getInt("note_priority"), 0, 2);
        float pitchBendUp = getFloat("pitch_bend_up");
        float pitchBendDown = getFloat("pitch_bend_down");
        for (int i = 0; i < kNumVoices; ++i)
        {
            voices[i].params.triggerMode = std::clamp(getInt("trigger_mode"), 0, 3);
            voices[i].params.oscKeyReset = getBool("osc_key_reset");
            voices[i].params.pitchBendUp = pitchBendUp;
            voices[i].params.pitchBendDown = pitchBendDown;
            voices[i].params.env1TriggerMode = std::clamp(getInt("env1_trigger_mode"), 0, 4);
            voices[i].params.env2TriggerMode = std::clamp(getInt("env2_trigger_mode"), 0, 4);
            voices[i].params.env3TriggerMode = std::clamp(getInt("env3_trigger_mode"), 0, 4);
            voices[i].params.lfo1ArpSync = getBool("lfo1_arp_sync");
            voices[i].params.lfo2ArpSync = getBool("lfo2_arp_sync");
        }

        // Verificar si alguna voz tiene arp sync activo — tras asignar lfo1ArpSync/lfo2ArpSync,
        // para no quedarnos una update por detrás (stale timing).
        arpSyncActive = false;
        for (int i = 0; i < kNumVoices && !arpSyncActive; ++i)
            arpSyncActive = voices[i].params.lfo1ArpSync || voices[i].params.lfo2ArpSync;

        // LFO Arp Sync: derivar frecuencias desde la tabla de Clock Divide del hardware
        // (docs lfos.md:23-48), basada en el Master BPM, no en el reloj de arp.
        if (arpSyncActive)
        {
            float lfo1SyncHz = SynthEngine::lfoArpSyncHzFromRate(getFloat("lfo1_rate"), arpRate);
            float lfo2SyncHz = SynthEngine::lfoArpSyncHzFromRate(getFloat("lfo2_rate"), arpRate);
            globalLfo1ArpSyncHz = lfo1SyncHz;
            globalLfo2ArpSyncHz = lfo2SyncHz;
            for (int i = 0; i < kNumVoices; ++i)
            {
                voices[i].lfo1ArpSyncHz = lfo1SyncHz;
                voices[i].lfo2ArpSyncHz = lfo2SyncHz;
            }
        }
        else
        {
            globalLfo1ArpSyncHz = 1.0f;
            globalLfo2ArpSyncHz = 1.0f;
            for (int i = 0; i < kNumVoices; ++i)
            {
                voices[i].lfo1ArpSyncHz = 1.0f;
                voices[i].lfo2ArpSyncHz = 1.0f;
            }
        }

        // Leer y propagar parámetros de Portamento / Glide
        globalPortamentoTime = getFloat("global_portamento");
        portaMode = std::clamp(getInt("porta_mode"), 0, 13);
        portaOscBal = getFloat("porta_osc_bal");
        for (int i = 0; i < kNumVoices; ++i)
        {
            voices[i].params.portaTime = globalPortamentoTime;
            voices[i].params.portaMode = portaMode;
            voices[i].params.portaOscBal = portaOscBal;
        }

        // Actualizar ruteos de la Mod Matrix desde la APVTS (8 Slots)
        for (int slot = 0; slot < ModulationMatrix::kNumSlots; ++slot)
        {
            juce::String prefix = "mod_matrix_slot" + juce::String(slot + 1);
            int srcVal = getInt(prefix + "_src");
            int destVal = getInt(prefix + "_dest");
            float amount = getFloat(prefix + "_depth");

            modMatrix.setRoute(slot, 
                               static_cast<ModSource>(srcVal), 
                               static_cast<ModDestination>(destVal), 
                               amount);
        }

        // Actualizar FX Engine
        fxEngine.updateParameters(apvts);
    }
}

