/**
 * @purpose Unit tests for SynthEngine DSP: DriftEngine parameter integration,
 *          amplitude scaling, setSampleRate, deterministic zero, monotonic scaling,
 *          and HPF bass boost energy contract.
 * Extracted from SynthEngineUnitTests.cpp for modularization.
 * @classification Test
 */
#include <JuceHeader.h>
#include "SynthEngine.h"
#include "DriftEngine.h"

namespace ABD
{

class SynthEngineDriftUnitTests : public juce::UnitTest
{
public:
    static constexpr double kTestSampleRate = 44100.0;

    SynthEngineDriftUnitTests() : juce::UnitTest("SynthEngine Drift/HPF Tests", "ABD") {}

    void runTest() override
    {
        beginTest("DriftEngine parameter integration");
        {
            DriftEngine drift;
            drift.resetForNote(0);
            drift.setDriftParams(0.0f, 0.0f, 0.0f);
            for (int s = 0; s < 100000; ++s) drift.nextSample();
            float osc1Drift = drift.getOsc1PitchDrift();
            float osc2Drift = drift.getOsc2PitchDrift();
            expectWithinAbsoluteError(osc1Drift, 0.0f, 0.001f, "OSC1 drift should be ~0 with voiceDrift=0 (was " + juce::String(osc1Drift) + ")");
            expectWithinAbsoluteError(osc2Drift, 0.0f, 0.001f, "OSC2 drift should be ~0 with voiceDrift=0 (was " + juce::String(osc2Drift) + ")");

            drift.setDriftParams(1.0f, 1.0f, 1.0f);
            drift.resetForNote(0);
            for (int s = 0; s < 10000; ++s) drift.nextSample();
            osc1Drift = drift.getOsc1PitchDrift();
            expect(std::abs(osc1Drift) > 0.0001f, "OSC1 drift should be > 0.0001 with voiceDrift=1.0 (was " + juce::String(osc1Drift) + ")");
            logMessage("DriftEngine integration: OK");
        }

        beginTest("DriftEngine linear amplitude scaling");
        {
            DriftEngine drift;
            drift.setDriftParams(1.0f, 1.0f, 1.0f);
            drift.resetForNote(0);
            float peakAt1 = 0.0f;
            for (int s = 0; s < 500000; ++s) { drift.nextSample(); peakAt1 = std::max(peakAt1, std::abs(drift.getOsc1PitchDrift())); }

            drift.setDriftParams(0.5f, 1.0f, 1.0f);
            drift.resetForNote(0);
            float peakAt05 = 0.0f;
            for (int s = 0; s < 500000; ++s) { drift.nextSample(); peakAt05 = std::max(peakAt05, std::abs(drift.getOsc1PitchDrift())); }

            if (peakAt1 > 0.001f)
            {
                float ratio = peakAt05 / peakAt1;
                expect(ratio > 0.25f, "drift(0.5)/drift(1.0) peak ratio should be ~0.5, not quadratic (got " + juce::String(ratio) + ")");
                expect(ratio < 0.95f, "drift(0.5)/drift(1.0) peak ratio should be ~0.5 (got " + juce::String(ratio) + ")");
            }
            logMessage("DriftEngine linear scaling: OK");
        }

        beginTest("DriftEngine setSampleRate recalculates intervals");
        {
            DriftEngine drift;
            drift.setDriftParams(0.5f, 0.5f, 1.0f);
            drift.setSampleRate(kTestSampleRate);
            drift.resetForNote(0);
            float peak44k = 0.0f;
            for (int s = 0; s < static_cast<int>(kTestSampleRate); ++s) { drift.nextSample(); peak44k = std::max(peak44k, std::abs(drift.getOsc1PitchDrift())); }

            drift.setSampleRate(96000.0);
            drift.resetForNote(0);
            float peak96k = 0.0f;
            for (int s = 0; s < 96000; ++s) { drift.nextSample(); peak96k = std::max(peak96k, std::abs(drift.getOsc1PitchDrift())); }

            expect(peak44k > 0.0001f, "44.1kHz drift should be active (peak " + juce::String(peak44k) + ")");
            expect(peak96k > 0.0001f, "96kHz drift should be active (peak " + juce::String(peak96k) + ")");
            if (peak44k > 0.001f)
            {
                float rateRatio = peak96k / peak44k;
                expect(rateRatio > 0.3f && rateRatio < 3.0f,
                    "Drift at 96kHz should be comparable to 44.1kHz (ratio: " + juce::String(rateRatio) + ")");
            }
            logMessage("DriftEngine setSampleRate: OK");
        }

        beginTest("DriftEngine drift=0 deterministic zero");
        {
            DriftEngine drift;
            drift.setDriftParams(0.0f, 0.0f, 0.0f);
            drift.resetForNote(0);
            for (int s = 0; s < 1000; ++s) drift.nextSample();
            float v1 = drift.getOsc1PitchDrift();
            // At drift=0, internal slewedValue targets zero and eventually converges
            expectWithinAbsoluteError(v1, 0.0f, 0.01f, "drift=0: OSC1 pitch drift should be near zero (got " + juce::String(v1) + ")");
            logMessage("DriftEngine drift=0 deterministic zero: OK");
        }

        beginTest("TST-03 DriftEngine drift0 remains zero across reset and voices");
        {
            DriftEngine drift;
            for (int voice = 0; voice < 6; ++voice)
            {
                drift.setDriftParams(0.0f, 1.0f, 1.0f);
                drift.resetForNote(voice);
                for (int s = 0; s < 500; ++s) drift.nextSample();
                float d = drift.getOsc1PitchDrift();
                expectWithinAbsoluteError(d, 0.0f, 0.01f, "Voice " + juce::String(voice) + " drift should be near zero (got " + juce::String(d) + ")");
            }
            logMessage("TST-03 DriftEngine drift0 zero across reset: OK");
        }

        beginTest("TST-03 DriftEngine amplitude scaling is monotonic");
        {
            DriftEngine drift;
            float prevPeak = 0.0f;
            bool monotonic = true;
            for (float voiceDrift = 0.0f; voiceDrift <= 1.01f; voiceDrift += 0.2f)
            {
                drift.setDriftParams(voiceDrift, 1.0f, 1.0f);
                drift.resetForNote(0);
                float peak = 0.0f;
                for (int s = 0; s < 100000; ++s) { drift.nextSample(); peak = std::max(peak, std::abs(drift.getOsc1PitchDrift())); }
                if (voiceDrift > 0.0f && peak < prevPeak * 0.9f && peak > 0.001f)
                    monotonic = false;
                prevPeak = peak;
            }
            expect(monotonic, "Drift amplitude should be monotonic with voiceDrift parameter");
            logMessage("TST-03 DriftEngine amplitude scaling monotonic: OK");
        }

        beginTest("DriftEngine LCG deterministic output (Fix #4)");
        {
            // Dos instancias de DriftEngine con los mismos parámetros
            // deben producir salidas idénticas (LCG local determinista, no std::rand() global)
            DriftEngine driftA, driftB;
            driftA.setDriftParams(0.5f, 0.3f, 0.5f);
            driftB.setDriftParams(0.5f, 0.3f, 0.5f);

            // Reset y avanzar la misma cantidad de muestras
            driftA.resetForNote(0);
            driftB.resetForNote(0);

            bool deterministic = true;
            for (int s = 0; s < 10000; ++s)
            {
                driftA.nextSample();
                driftB.nextSample();

                float diffPitch = std::abs(driftA.getOsc1PitchDrift() - driftB.getOsc1PitchDrift());
                float diffCutoff = std::abs(driftA.getVcfCutoffDrift() - driftB.getVcfCutoffDrift());
                float diffRes = std::abs(driftA.getVcfResonanceDrift() - driftB.getVcfResonanceDrift());

                if (diffPitch > 0.0001f || diffCutoff > 0.0001f || diffRes > 0.0001f)
                {
                    deterministic = false;
                    break;
                }
            }

            expect(deterministic, "DriftEngine debe ser determinista (LCG local, no std::rand())");
            logMessage("DriftEngine LCG deterministic: OK");
        }

        beginTest("HPF bass boost energy contract");
        {
            JunoHPF hpfOff, hpfOn;
            hpfOff.prepare(kTestSampleRate);
            hpfOn.prepare(kTestSampleRate);
            hpfOn.bassBoostActive = true;
            hpfOn.bassBoostGain = 1.5f;

            float energyOff = 0.0f, energyOn = 0.0f;
            for (int i = 0; i < 512; ++i)
            {
                float inSample = std::sin(2.0f * juce::MathConstants<float>::pi * 100.0f * (float)i / 44100.0f);
                energyOff += std::abs(hpfOff.process(inSample));
                energyOn  += std::abs(hpfOn.process(inSample));
            }

            expect(energyOn >= energyOff * 0.5f, "HPF boost ON should not reduce energy below 50% of OFF");
            logMessage("HPF bass boost energy contract: OK");
        }
    }
};

static SynthEngineDriftUnitTests synthEngineDriftUnitTests;

} // namespace ABD

/**
 * @purpose Unit tests for sample-accurate MIDI timing in SynthEngine::processBlock().
 *          Verifies that note-on events take effect at their exact samplePosition
 *          (silence before, sound after) and that a note-on placed at the very end
 *          of a block produces no output in that block.
 * @classification Test
 */
#include <JuceHeader.h>
#include "SynthEngine.h"

namespace ABD
{

class SynthEngineMIDITimingUnitTests : public juce::UnitTest
{
public:
    static constexpr double kTestSampleRate = 44100.0;
    static constexpr int kTestBlockSize = 1024;

    SynthEngineMIDITimingUnitTests() : juce::UnitTest("SynthEngine MIDI Timing Tests", "ABD") {}

    void runTest() override
    {
        //==============================================================================
        beginTest("Note-on at mid-block is sample-accurate (silence before, sound after)");
        {
            constexpr int notePos = 512;

            SynthEngine engine;
            engine.prepare(kTestSampleRate, kTestBlockSize);

            juce::AudioBuffer<float> buffer(2, kTestBlockSize);
            buffer.clear();
            juce::MidiBuffer midi;
            midi.addEvent(juce::MidiMessage::noteOn(1, 60, 0.9f), notePos);

            engine.processBlock(buffer, midi);

            // Region before the event must be exactly silent (no voice was rendering)
            bool silenceBefore = true;
            for (int s = 0; s < notePos; ++s)
            {
                if (buffer.getSample(0, s) != 0.0f || buffer.getSample(1, s) != 0.0f)
                {
                    silenceBefore = false;
                    break;
                }
            }
            expect(silenceBefore, "Output before note-on samplePosition should be exactly silent");

            // Region from the event onward must contain audible signal
            float energy = buffer.getMagnitude(0, notePos, kTestBlockSize - notePos)
                         + buffer.getMagnitude(1, notePos, kTestBlockSize - notePos);
            expect(energy > 0.0001f,
                   "Output from note-on samplePosition onward should contain signal (energy="
                   + juce::String(energy, 6) + ")");

            bool anyVoiceActive = false;
            for (int i = 0; i < 12; ++i)
                if (engine.isVoiceActive(i)) { anyVoiceActive = true; break; }
            expect(anyVoiceActive, "At least one voice should be active after mid-block note-on");

            logMessage("Note-on sample-accurate boundary (silence->sound at " + juce::String(notePos) + "): OK");
        }

        //==============================================================================
        beginTest("Note-on at end-of-block produces no output in that block");
        {
            SynthEngine engine;
            engine.prepare(kTestSampleRate, kTestBlockSize);

            juce::AudioBuffer<float> buffer(2, kTestBlockSize);
            buffer.clear();
            juce::MidiBuffer midi;
            midi.addEvent(juce::MidiMessage::noteOn(1, 64, 0.9f), kTestBlockSize);

            engine.processBlock(buffer, midi);

            bool silent = true;
            for (int s = 0; s < kTestBlockSize; ++s)
            {
                if (buffer.getSample(0, s) != 0.0f || buffer.getSample(1, s) != 0.0f)
                {
                    silent = false;
                    break;
                }
            }
            expect(silent, "Note-on at samplePosition == numSamples should not sound until the next block");

            // The note must be pending and begin in the following block
            juce::AudioBuffer<float> buffer2(2, kTestBlockSize);
            buffer2.clear();
            juce::MidiBuffer emptyMidi;
            engine.processBlock(buffer2, emptyMidi);

            float energy = buffer2.getMagnitude(0, 0, kTestBlockSize);
            expect(energy > 0.0001f,
                   "Note scheduled at the end of a block should sound in the next block (energy="
                   + juce::String(energy, 6) + ")");

            logMessage("Note-on at end-of-block deferred to next block: OK");
        }

        //==============================================================================
        beginTest("Sustain pedal latch (CC64) — note-off while pedal down stays held until release");
        {
            SynthEngine engine;
            engine.prepare(kTestSampleRate, kTestBlockSize);
            juce::AudioBuffer<float> buffer(2, kTestBlockSize);
            juce::MidiBuffer midi;

            // Note on
            midi.addEvent(juce::MidiMessage::noteOn(1, 60, 0.9f), 0);
            engine.processBlock(buffer, midi);

            // Pedal down, then note-off while the pedal is held
            midi.clear();
            midi.addEvent(juce::MidiMessage::controllerEvent(1, 64, 127), 0);
            engine.processBlock(buffer, midi);
            midi.clear();
            midi.addEvent(juce::MidiMessage::noteOff(1, 60), 0);
            engine.processBlock(buffer, midi);

            // Render a long time — a non-latched note would have finished its release
            midi.clear();
            for (int i = 0; i < 500; ++i)
                engine.processBlock(buffer, midi);

            auto anyActive = [&]() {
                for (int i = 0; i < 12; ++i)
                    if (engine.isVoiceActive(i)) return true;
                return false;
            };
            expect(anyActive(), "Note released while pedal is down must stay latched (voice active after long render)");
            float latchedEnergy = buffer.getMagnitude(0, 0, kTestBlockSize)
                                + buffer.getMagnitude(1, 0, kTestBlockSize);
            expect(latchedEnergy > 0.0001f, "Latched voice should keep producing sustain output");

            // Pedal up → the latched note enters its release phase
            midi.addEvent(juce::MidiMessage::controllerEvent(1, 64, 0), 0);
            engine.processBlock(buffer, midi);
            midi.clear();
            for (int i = 0; i < 500; ++i)
                engine.processBlock(buffer, midi);

            expect(!anyActive(), "Pedal release must trigger the release phase of latched notes");
            float releasedEnergy = buffer.getMagnitude(0, 0, kTestBlockSize)
                                 + buffer.getMagnitude(1, 0, kTestBlockSize);
            expect(releasedEnergy < 0.001f, "After pedal release + long render the voice should be silent");
            logMessage("Sustain pedal latch: OK");
        }

        //==============================================================================
        beginTest("Sustain pedal latch control — note-off without pedal releases normally");
        {
            SynthEngine engine;
            engine.prepare(kTestSampleRate, kTestBlockSize);
            juce::AudioBuffer<float> buffer(2, kTestBlockSize);
            juce::MidiBuffer midi;

            midi.addEvent(juce::MidiMessage::noteOn(1, 60, 0.9f), 0);
            engine.processBlock(buffer, midi);
            midi.clear();
            midi.addEvent(juce::MidiMessage::noteOff(1, 60), 0);
            engine.processBlock(buffer, midi);

            midi.clear();
            for (int i = 0; i < 500; ++i)
                engine.processBlock(buffer, midi);

            bool anyActive = false;
            for (int i = 0; i < 12; ++i)
                if (engine.isVoiceActive(i)) { anyActive = true; break; }
            expect(!anyActive, "Without the pedal a note-off must finish its release and deactivate");
            logMessage("Sustain pedal latch control: OK");
        }

        //==============================================================================
        beginTest("Sample-accurate rendering matches single-shot render when events are at 0");
        {
            // Events at sample 0 must produce identical output to the pre-segmentation
            // behaviour: the whole block rendered in one pass.
            SynthEngine engineA;
            engineA.prepare(kTestSampleRate, kTestBlockSize);
            SynthEngine engineB;
            engineB.prepare(kTestSampleRate, kTestBlockSize);

            juce::AudioBuffer<float> bufA(2, kTestBlockSize);
            bufA.clear();
            juce::AudioBuffer<float> bufB(2, kTestBlockSize);
            bufB.clear();

            juce::MidiBuffer midiA;
            midiA.addEvent(juce::MidiMessage::noteOn(1, 60, 0.8f), 0);
            midiA.addEvent(juce::MidiMessage::noteOn(1, 64, 0.7f), 0);
            engineA.processBlock(bufA, midiA);

            juce::MidiBuffer midiB;
            midiB.addEvent(juce::MidiMessage::noteOn(1, 60, 0.8f), 0);
            midiB.addEvent(juce::MidiMessage::noteOn(1, 64, 0.7f), 0);
            engineB.processBlock(bufB, midiB);

            bool identical = true;
            for (int s = 0; s < kTestBlockSize; ++s)
            {
                if (bufA.getSample(0, s) != bufB.getSample(0, s) || bufA.getSample(1, s) != bufB.getSample(1, s))
                {
                    identical = false;
                    break;
                }
            }
            expect(identical, "Events at samplePosition 0 should render identically across engines");
            logMessage("Events at samplePosition 0 render identically: OK");
        }
    }
};

static SynthEngineMIDITimingUnitTests synthEngineMIDITimingUnitTests;

