/**
 * @purpose Unit tests for SynthEngine::panic() and SynthEngine::resetMidiControllers().
 *          Verifies that panic() silences all active voices and resetMidiControllers()
 *          returns pitch bend, mod wheel, aftertouch, and sustain to their default values.
 *          These are the critical operations called from processBlockBypassed()
 *          to prevent stuck notes and controller jumps when the DAW bypasses the plugin.
 * @classification Test
 */
#include <JuceHeader.h>
#include "SynthEngine.h"

namespace ABD
{

class SynthEnginePanicUnitTests : public juce::UnitTest
{
public:
    static constexpr double kTestSampleRate = 44100.0;
    static constexpr int kTestBlockSize = 512;

    SynthEnginePanicUnitTests() : juce::UnitTest("SynthEngine Panic/Bypass Tests", "ABD") {}

    void runTest() override
    {
        //==============================================================================
        beginTest("panic() silences all active voices");
        {
            SynthEngine engine;
            engine.prepare(kTestSampleRate, kTestBlockSize);

            // Create audio buffer and MIDI buffer
            juce::AudioBuffer<float> buffer(2, kTestBlockSize);
            buffer.clear();
            juce::MidiBuffer midiMessages;

            // Send note-on for C4 (MIDI 60), velocity 0.8
            midiMessages.addEvent(juce::MidiMessage::noteOn(1, 60, 0.8f), 0);

            // Process block — should activate a voice
            engine.processBlock(buffer, midiMessages);

            // Process a few more blocks to allow envelope to reach sustain
            for (int b = 0; b < 5; ++b)
            {
                juce::MidiBuffer emptyMidi;
                engine.processBlock(buffer, emptyMidi);
            }

            // Verify at least one voice is active
            bool anyVoiceActive = false;
            for (int i = 0; i < 12; ++i)
            {
                if (engine.isVoiceActive(i))
                {
                    anyVoiceActive = true;
                    break;
                }
            }
            expect(anyVoiceActive, "At least one voice should be active after note-on");

            // Capture voice states before panic
            int prePanicActiveCount = 0;
            for (int i = 0; i < 12; ++i)
                if (engine.isVoiceActive(i))
                    prePanicActiveCount++;
            logMessage("Active voices before panic: " + juce::String(prePanicActiveCount));

            // Call panic — this should stop all voices immediately
            engine.panic();

            // Process a few blocks to let stopped voices finish their release tail
            for (int b = 0; b < 20; ++b)
            {
                juce::MidiBuffer emptyMidi;
                engine.processBlock(buffer, emptyMidi);
            }

            // Verify all voices are inactive
            int postPanicActiveCount = 0;
            for (int i = 0; i < 12; ++i)
            {
                if (engine.isVoiceActive(i))
                    postPanicActiveCount++;
            }
            expectEquals(postPanicActiveCount, 0,
                "All voices should be inactive after panic (active="
                + juce::String(postPanicActiveCount) + ")");
            logMessage("Active voices after panic: " + juce::String(postPanicActiveCount) + " ✅");
        }

        //==============================================================================
        beginTest("panic() clears held note accumulators (poly chord + mono)");
        {
            SynthEngine engine;
            engine.prepare(kTestSampleRate, kTestBlockSize);

            juce::AudioBuffer<float> buffer(2, kTestBlockSize);
            buffer.clear();

            // Play a chord: 3 simultaneous notes
            {
                juce::MidiBuffer midiOn;
                midiOn.addEvent(juce::MidiMessage::noteOn(1, 60, 0.8f), 0);
                midiOn.addEvent(juce::MidiMessage::noteOn(1, 64, 0.7f), 10);
                midiOn.addEvent(juce::MidiMessage::noteOn(1, 67, 0.75f), 20);
                engine.processBlock(buffer, midiOn);
            }
            for (int b = 0; b < 20; ++b)
            {
                juce::MidiBuffer emptyMidi;
                engine.processBlock(buffer, emptyMidi);
            }

            // Verify multiple voices are active (at least 2 for a chord)
            int activeCount = 0;
            for (int i = 0; i < 12; ++i)
                if (engine.isVoiceActive(i)) activeCount++;
            expect(activeCount >= 2,
                "At least 2 voices should be active for a 3-note chord (got " + juce::String(activeCount) + ")");

            // Call panic and process release
            engine.panic();
            for (int b = 0; b < 20; ++b)
            {
                juce::MidiBuffer emptyMidi;
                engine.processBlock(buffer, emptyMidi);
            }

            // All voices must be silent
            for (int i = 0; i < 12; ++i)
            {
                expect(!engine.isVoiceActive(i),
                    "Voice " + juce::String(i) + " should be inactive after panic on 3-note chord");
            }
            logMessage("panic() clears polyphonic chord voices: ✅");
        }

        //==============================================================================
        beginTest("resetMidiControllers() resets all global controllers to default");
        {
            SynthEngine engine;
            engine.prepare(kTestSampleRate, kTestBlockSize);

            juce::AudioBuffer<float> buffer(2, kTestBlockSize);
            buffer.clear();

            // First get the diagnostic snapshot baseline (default values)
            auto baselineSnapshot = engine.getDiagnosticSnapshot();

            // Defaults should be 0.0
            expectWithinAbsoluteError(baselineSnapshot.pitchBend, 0.0f, 0.001f,
                "pitchBend should be 0.0 by default");
            expectWithinAbsoluteError(baselineSnapshot.modWheel, 0.0f, 0.001f,
                "modWheel should be 0.0 by default");
            expectWithinAbsoluteError(baselineSnapshot.aftertouch, 0.0f, 0.001f,
                "aftertouch should be 0.0 by default");
            expectWithinAbsoluteError(baselineSnapshot.sustainPedal, 0.0f, 0.001f,
                "sustainPedal should be 0.0 by default");

            // Send MIDI CC messages to set controllers to non-default values
            {
                juce::MidiBuffer midiCC;
                // Mod wheel = CC 1, value 127 (max)
                midiCC.addEvent(juce::MidiMessage::controllerEvent(1, 1, 127), 0);
                // Sustain pedal = CC 64, value 127 (on)
                midiCC.addEvent(juce::MidiMessage::controllerEvent(1, 64, 127), 10);
                engine.processBlock(buffer, midiCC);
            }

            // Send pitch bend (max upward = 16383)
            {
                juce::MidiBuffer midiPB;
                midiPB.addEvent(juce::MidiMessage::pitchWheel(1, 16383), 0);
                engine.processBlock(buffer, midiPB);
            }

            // Send aftertouch (channel pressure)
            {
                juce::MidiBuffer midiAT;
                midiAT.addEvent(juce::MidiMessage::channelPressureChange(1, 127), 0);
                engine.processBlock(buffer, midiAT);
            }

            // Process a few blocks to update the diagnostic snapshot
            for (int b = 0; b < 3; ++b)
            {
                juce::MidiBuffer emptyMidi;
                engine.processBlock(buffer, emptyMidi);
            }

            // Verify controllers are now at non-default values
            auto midModSnapshot = engine.getDiagnosticSnapshot();
            // pitchBend normalized: (16383 / 8192) - 1.0 = 1.0
            expectWithinAbsoluteError(midModSnapshot.pitchBend, 1.0f, 0.01f,
                "pitchBend should be ~1.0 after max pitch wheel");
            // modWheel: 127 / 127 = 1.0
            expectWithinAbsoluteError(midModSnapshot.modWheel, 1.0f, 0.01f,
                "modWheel should be ~1.0 after max CC1");
            // aftertouch: 127 / 127 = 1.0
            expectWithinAbsoluteError(midModSnapshot.aftertouch, 1.0f, 0.01f,
                "aftertouch should be ~1.0 after max channel pressure");
            // sustainPedal: 127 / 127 = 1.0
            expectWithinAbsoluteError(midModSnapshot.sustainPedal, 1.0f, 0.01f,
                "sustainPedal should be ~1.0 after max CC64");

            // Now call resetMidiControllers
            engine.resetMidiControllers();

            // Process a block to update the diagnostic snapshot
            for (int b = 0; b < 3; ++b)
            {
                juce::MidiBuffer emptyMidi;
                engine.processBlock(buffer, emptyMidi);
            }

            // Verify controllers are back to defaults
            auto afterResetSnapshot = engine.getDiagnosticSnapshot();
            expectWithinAbsoluteError(afterResetSnapshot.pitchBend, 0.0f, 0.001f,
                "pitchBend should be 0.0 after resetMidiControllers (was "
                + juce::String(afterResetSnapshot.pitchBend) + ")");
            expectWithinAbsoluteError(afterResetSnapshot.modWheel, 0.0f, 0.001f,
                "modWheel should be 0.0 after resetMidiControllers (was "
                + juce::String(afterResetSnapshot.modWheel) + ")");
            expectWithinAbsoluteError(afterResetSnapshot.aftertouch, 0.0f, 0.001f,
                "aftertouch should be 0.0 after resetMidiControllers (was "
                + juce::String(afterResetSnapshot.aftertouch) + ")");
            expectWithinAbsoluteError(afterResetSnapshot.sustainPedal, 0.0f, 0.001f,
                "sustainPedal should be 0.0 after resetMidiControllers (was "
                + juce::String(afterResetSnapshot.sustainPedal) + ")");

            logMessage("resetMidiControllers(): pitchBend=0, modWheel=0, aftertouch=0, sustain=0 ✅");
        }

        //==============================================================================
        beginTest("panic() + resetMidiControllers() — integration sequence (simulates processBlockBypassed)");
        {
            SynthEngine engine;
            engine.prepare(kTestSampleRate, kTestBlockSize);

            juce::AudioBuffer<float> buffer(2, kTestBlockSize);
            buffer.clear();

            // Step 1: Start a note + set controllers to non-default
            {
                juce::MidiBuffer midiEvents;
                midiEvents.addEvent(juce::MidiMessage::noteOn(1, 72, 0.9f), 0);
                midiEvents.addEvent(juce::MidiMessage::controllerEvent(1, 1, 80), 20);
                midiEvents.addEvent(juce::MidiMessage::pitchWheel(1, 8192 + 4096), 40);
                engine.processBlock(buffer, midiEvents);
            }
            for (int b = 0; b < 10; ++b)
            {
                juce::MidiBuffer emptyMidi;
                engine.processBlock(buffer, emptyMidi);
            }

            // Verify note is playing and controllers are set
            bool noteActive = false;
            for (int i = 0; i < 12; ++i)
                if (engine.isVoiceActive(i)) { noteActive = true; break; }
            expect(noteActive, "Note should be active before bypass sequence");

            auto preBypass = engine.getDiagnosticSnapshot();
            bool controllersSet = (std::abs(preBypass.pitchBend) > 0.1f || std::abs(preBypass.modWheel) > 0.1f);
            // At least mod wheel should be set
            expect(preBypass.modWheel > 0.1f,
                "Mod wheel should be elevated before bypass (was " + juce::String(preBypass.modWheel) + ")");

            // Step 2: Simulate processBlockBypassed — call panic() then resetMidiControllers()
            engine.panic();
            engine.resetMidiControllers();

            // Step 3: Process a few blocks to release voices and update snapshot
            for (int b = 0; b < 20; ++b)
            {
                juce::MidiBuffer emptyMidi;
                engine.processBlock(buffer, emptyMidi);
            }

            // Step 4: Verify all voices silenced
            bool anyVoiceStillActive = false;
            for (int i = 0; i < 12; ++i)
                if (engine.isVoiceActive(i)) { anyVoiceStillActive = true; break; }
            expect(!anyVoiceStillActive, "No voices should be active after bypass sequence");

            // Step 5: Verify controllers reset to defaults
            auto postBypass = engine.getDiagnosticSnapshot();
            expectWithinAbsoluteError(postBypass.pitchBend, 0.0f, 0.001f,
                "pitchBend=0 after bypass (was " + juce::String(postBypass.pitchBend) + ")");
            expectWithinAbsoluteError(postBypass.modWheel, 0.0f, 0.001f,
                "modWheel=0 after bypass (was " + juce::String(postBypass.modWheel) + ")");
            expectWithinAbsoluteError(postBypass.aftertouch, 0.0f, 0.001f,
                "aftertouch=0 after bypass (was " + juce::String(postBypass.aftertouch) + ")");
            expectWithinAbsoluteError(postBypass.sustainPedal, 0.0f, 0.001f,
                "sustainPedal=0 after bypass (was " + juce::String(postBypass.sustainPedal) + ")");

            logMessage("Bypass integration sequence: panic() + resetMidiControllers() → voices off, controllers reset ✅");
        }
    }
};

static SynthEnginePanicUnitTests synthEnginePanicUnitTests;

} // namespace ABD

/**
 * @purpose Unit tests for SynthEngine DSP: transpose, global tune, and pitch bend ranges.
 * Extracted from SynthEngineUnitTests.cpp for modularization.
 * @classification Test
 */
#include <JuceHeader.h>
#include "SynthEngine.h"

namespace ABD
{

class SynthEnginePitchUnitTests : public juce::UnitTest
{
public:
    static constexpr double kTestSampleRate = 44100.0;

    SynthEnginePitchUnitTests() : juce::UnitTest("SynthEngine Pitch Tests", "ABD") {}

    void runTest() override
    {
        //==============================================================================
        beginTest("Transpose and global tune ranges");
        {
            auto calcTranspose = [](float normalized) -> int { return (int)std::round(normalized * 96.0f - 48.0f); };
            expectEquals(calcTranspose(0.0f), -48, "Transpose 0 → -48 st");
            expectEquals(calcTranspose(0.25f), -24, "Transpose 0.25 → -24 st");
            expectEquals(calcTranspose(0.5f), 0, "Transpose 0.5 → 0 st");
            expectEquals(calcTranspose(0.75f), 24, "Transpose 0.75 → +24 st");
            expectEquals(calcTranspose(1.0f), 48, "Transpose 1.0 → +48 st");

            auto calcTune = [](float normalized) -> float { return normalized * 255.0f - 128.0f; };
            expectWithinAbsoluteError(calcTune(0.0f), -128.0f, 0.001f, "Tune 0 → -128¢");
            expectWithinAbsoluteError(calcTune(0.5f), -0.5f, 0.001f, "Tune 0.5 → -0.5¢");
            expectWithinAbsoluteError(calcTune(1.0f), 127.0f, 0.001f, "Tune 1.0 → +127¢");
            expectEquals(std::clamp(60 + (-48), 0, 127), 12, "C4 + transpose -48 should map to C1");
            expectEquals(std::clamp(60 + 48, 0, 127), 108, "C4 + transpose +48 should map to C8");
            logMessage("Transpose and tune mapping: OK");
        }

        //==============================================================================
        beginTest("Pitch Bend range scaling");
        {
            auto calcBendUp = [](float normalized) -> float { return normalized * 24.0f; };
            auto calcBendDown = [](float normalized) -> float { return normalized * 24.0f; };
            expectWithinAbsoluteError(calcBendUp(0.0f), 0.0f, 0.001f, "Pitch bend up min should be 0");
            expectWithinAbsoluteError(calcBendUp(1.0f), 24.0f, 0.001f, "Pitch bend up max should be 24");
            expectWithinAbsoluteError(calcBendDown(0.5f), 12.0f, 0.001f, "Pitch bend down mid should be 12");
            logMessage("Pitch bend range scaling: OK");
        }
    }
};

static SynthEnginePitchUnitTests synthEnginePitchUnitTests;

} // namespace ABD

/**
 * @purpose Rapid sweep tests for SynthEngine DSP modules.
 *          Sweeps all parameters from 0→1 in steps, verifying no NaN/Inf outputs.
 *          Complements the existing FX sweep tests in FXUnitTests_Standard.cpp
 *          and FXUnitTests_Advanced.cpp by covering the synth engine.
 * @classification Test/DSP
 */
#include <JuceHeader.h>
#include <cmath>
#include "SynthEngine.h"
#include "SynthVoice.h"
#include "Envelope.h"
#include "LFO.h"
#include "OSC1.h"
#include "OSC2.h"
#include "Filter.h"
#include "DriftEngine.h"
#include "ModulationMatrix.h"
#if DEEP_TARGET_MODEL >= 2
#include "MoogLadderVCF.h"
#include "KorgMS20VCF.h"
#endif
#include "../Core/CalibrationSpec.h"

namespace ABD
{

class SynthEngineRapidSweepTests : public juce::UnitTest
{
public:
    static constexpr double kTestSampleRate = 44100.0;

    SynthEngineRapidSweepTests() : juce::UnitTest("SynthEngine Rapid Sweep Tests", "ABD") {}

    void runTest() override
    {
        //==============================================================================
        beginTest("Envelope parameter rapid sweep — attack, decay, sustain, release");

        {
            Envelope env;
            env.setSampleRate(kTestSampleRate);

            const float timeValues[] = { 0.001f, 0.01f, 0.1f, 0.5f, 1.0f };
            const float sustainValues[] = { 0.0f, 0.5f, 1.0f };
            const float curveValues[] = { -1.0f, 0.0f, 1.0f };

            int totalCombos = 0;
            for (float a : timeValues)
            {
                for (float d : timeValues)
                {
                    for (float s : sustainValues)
                    {
                        for (float r : timeValues)
                        {
                            env.setParameters(a, d, s, r);

                            for (float curve : curveValues)
                            {
                                env.setCurves(curve, curve, curve, curve);
                                totalCombos++;

                                env.trigger();
                                for (int i = 0; i < 500; ++i)
                                {
                                    float sample = env.nextSample();
                                    expect(std::isfinite(sample),
                                        "Envelope NaN at a=" + juce::String(a)
                                        + " d=" + juce::String(d)
                                        + " s=" + juce::String(s));
                                }
                                env.release();
                                for (int i = 0; i < 1000; ++i)
                                {
                                    float sample = env.nextSample();
                                    expect(std::isfinite(sample),
                                        "Envelope NaN after release");
                                }
                            }
                        }
                    }
                }
            }
            logMessage("Envelope rapid sweep: OK (" + juce::String(totalCombos) + " combos)");
        }

        //==============================================================================
        beginTest("LFO parameter rapid sweep — shapes, rates, phases");

        {
            LFO lfo;
            lfo.setSampleRate(kTestSampleRate);

            for (int shape = 0; shape <= 6; ++shape)
            {
                lfo.setShape(shape);
                lfo.reset();
                lfo.trigger();

                for (float rate = 0.041f; rate <= 65.5f; rate *= 1.5f)
                {
                    lfo.setRate(rate);

                    for (float delay = 0.0f; delay <= 6.5f; delay += 1.0f)
                    {
                        lfo.setDelay(delay);

                        for (int s = 0; s < 500; ++s)
                        {
                            float sample = lfo.nextSample();
                            expect(std::isfinite(sample),
                                "LFO NaN shape=" + juce::String(shape)
                                + " rate=" + juce::String(rate));
                        }
                    }
                }
            }
            logMessage("LFO rapid sweep: OK (7 shapes x 11 rates)");
        }

        //==============================================================================
        beginTest("LFO key sync + slew rapid sweep");

        {
            LFO lfo;
            lfo.setSampleRate(kTestSampleRate);

            for (int shape = 0; shape <= 6; ++shape)
            {
                lfo.setShape(shape);
                lfo.setKeySync(true);
                lfo.trigger();

                for (float slew = 0.0f; slew <= 1.0f; slew += 0.2f)
                {
                    lfo.setSlew(slew);
                    for (int s = 0; s < 200; ++s)
                    {
                        float sample = lfo.nextSample();
                        expect(std::isfinite(sample),
                            "LFO keySync NaN shape=" + juce::String(shape));
                    }
                }
            }
            logMessage("LFO keySync + slew sweep: OK");
        }

        //==============================================================================
        beginTest("VCF (JunoVCF_ZDF) rapid sweep — cutoff, resonance, pole modes");

        {
            JunoVCF_ZDF vcf;
            vcf.prepare(kTestSampleRate);
            vcf.setMode(JunoVCF_ZDF::Mode::DeepMind);

            for (auto mode : { JunoVCF_ZDF::PoleMode::FourPole, JunoVCF_ZDF::PoleMode::TwoPole })
            {
                vcf.setPoleMode(mode);

                for (int cutoffStep = 0; cutoffStep <= 20; ++cutoffStep)
                {
                    float frq = 0.025f + cutoffStep * 0.025f;  // 0.025 to 0.525 (Nyquist clamp)
                    if (frq > 0.50f) frq = 0.50f;

                    for (int resStep = 0; resStep <= 15; ++resStep)
                    {
                        float res = resStep / 15.0f;

                        float input = std::sin(6.283185f * 220.0f * cutoffStep / static_cast<float>(kTestSampleRate)) * 0.5f;
                        float output = vcf.process(input, frq, res);

                        expect(std::isfinite(output),
                            "JunoVCF NaN frq=" + juce::String(frq)
                            + " res=" + juce::String(res));
                    }
                }
            }
            logMessage("JunoVCF_ZDF rapid sweep: OK (2 modes x 21 cutoffs x 16 resonances)");
        }

        //==============================================================================
#if DEEP_TARGET_MODEL >= 2
        beginTest("MoogLadderVCF rapid sweep — cutoff, resonance, pole/sub modes");

        {
            MoogLadderVCF vcf;
            vcf.prepare(kTestSampleRate);

            for (int poleMode = 0; poleMode <= 1; ++poleMode)
            {
                vcf.setPoleMode(poleMode);

                for (int subMode = 0; subMode <= 2; ++subMode)
                {
                    vcf.setSubMode(subMode);

                    for (int cutoffStep = 0; cutoffStep <= 15; ++cutoffStep)
                    {
                        float cutoffHz = 50.0f * std::pow(400.0f, cutoffStep / 15.0f);
                        vcf.setCutoff(cutoffHz);

                        for (int resStep = 0; resStep <= 10; ++resStep)
                        {
                            float res = resStep / 10.0f;
                            vcf.setResonance(res);

                            float input = std::sin(6.283185f * 220.0f * (cutoffStep + 1) / static_cast<float>(kTestSampleRate)) * 0.5f;
                            for (int s = 0; s < 5; ++s)
                            {
                                float output = vcf.process(input);
                                expect(std::isfinite(output),
                                    "MoogLadder NaN pole=" + juce::String(poleMode)
                                    + " sub=" + juce::String(subMode)
                                    + " cutoff=" + juce::String(cutoffHz));
                            }
                        }
                    }
                }
            }
            logMessage("MoogLadderVCF rapid sweep: OK (2 poles x 3 subs x 16 cutoffs x 11 resonances)");
        }

        //==============================================================================
        beginTest("KorgMS20VCF rapid sweep — cutoff, resonance, pole/sub modes");

        {
            KorgMS20VCF vcf;
            vcf.prepare(kTestSampleRate);

            for (int poleMode = 0; poleMode <= 1; ++poleMode)
            {
                vcf.setPoleMode(poleMode);

                for (int subMode = 0; subMode <= 1; ++subMode)
                {
                    vcf.setSubMode(subMode);

                    for (int cutoffStep = 0; cutoffStep <= 15; ++cutoffStep)
                    {
                        float cutoffHz = 50.0f * std::pow(400.0f, cutoffStep / 15.0f);
                        vcf.setCutoff(cutoffHz);

                        for (int resStep = 0; resStep <= 10; ++resStep)
                        {
                            float res = resStep / 10.0f;
                            vcf.setResonance(res);

                            float input = std::sin(6.283185f * 220.0f * (cutoffStep + 1) / static_cast<float>(kTestSampleRate)) * 0.5f;
                            for (int s = 0; s < 5; ++s)
                            {
                                float output = vcf.process(input);
                                expect(std::isfinite(output),
                                    "KorgMS20 NaN pole=" + juce::String(poleMode)
                                    + " sub=" + juce::String(subMode));
                            }
                        }
                    }
                }
            }
            logMessage("KorgMS20VCF rapid sweep: OK (2 poles x 2 subs x 16 cutoffs x 11 resonances)");
        }
#endif

        //==============================================================================
        beginTest("HPF (JunoHPF) rapid sweep — cutoff, bass boost, gain");

        {
            HPF hpf;
            hpf.prepare(kTestSampleRate);

            for (int cutoffStep = 0; cutoffStep <= 15; ++cutoffStep)
            {
                float cutoffHz = 20.0f * std::pow(100.0f, cutoffStep / 15.0f);  // 20Hz to 2kHz
                hpf.setCutoff(cutoffHz);

                for (int boostStep = 0; boostStep <= 5; ++boostStep)
                {
                    bool boostActive = (boostStep % 2 == 0);
                    float boostGain = (boostStep < 3) ? 1.0f : 2.0f;
                    hpf.setBassBoostActive(boostActive);
                    hpf.setBassBoostGain(boostGain);

                    float input = std::sin(6.283185f * 110.0f * (cutoffStep + 1) / static_cast<float>(kTestSampleRate)) * 0.5f;
                    float output = hpf.process(input);

                    expect(std::isfinite(output),
                        "HPF NaN cutoff=" + juce::String(cutoffHz)
                        + " boost=" + (boostActive ? "true" : "false"));
                }
            }
            logMessage("HPF rapid sweep: OK (16 cutoffs x 6 boost combos)");
        }

        //==============================================================================
        beginTest("DriftEngine rapid sweep — drift params");

        {
            DriftEngine drift;
            drift.setSampleRate(kTestSampleRate);

            for (float voiceDrift = 0.0f; voiceDrift <= 1.0f; voiceDrift += 0.1f)
            {
                for (float paramDrift = 0.0f; paramDrift <= 1.0f; paramDrift += 0.1f)
                {
                    for (float driftRate = 0.0f; driftRate <= 1.0f; driftRate += 0.1f)
                    {
                        drift.setDriftParams(voiceDrift, paramDrift, driftRate);

                        drift.nextSample();
                        float driftVal = drift.getOsc1PitchDrift();
                        expect(std::isfinite(driftVal),
                            "Drift NaN vd=" + juce::String(voiceDrift)
                            + " pd=" + juce::String(paramDrift));
                    }
                }
            }
            logMessage("DriftEngine rapid sweep: OK (11x11x11 combos)");
        }

        //==============================================================================
        beginTest("ModulationMatrix rapid sweep — route amounts");

        {
            ModulationMatrix matrix;
            float sourceValues[(int)ModSource::kMaxSources] = {};

            // Fill all sources with varying values
            for (int src = 0; src < (int)ModSource::kMaxSources; ++src)
                sourceValues[src] = std::sin((float)src) * 0.5f + 0.5f;

            // Sweep all routes with all source/destinations
            for (int slot = 0; slot < ModulationMatrix::kNumSlots; ++slot)
            {
                for (int src = 0; src < (int)ModSource::kMaxSources; ++src)
                {
                    for (int dest = 0; dest < (int)ModDestination::kMaxDestinations; ++dest)
                    {
                        for (float amount = -1.0f; amount <= 1.0f; amount += 0.25f)
                        {
                            matrix.setRoute(slot,
                                static_cast<ModSource>(src),
                                static_cast<ModDestination>(dest),
                                amount);

                            float modValue = matrix.getModulationValue(
                                static_cast<ModDestination>(dest),
                                sourceValues);

                            expect(std::isfinite(modValue),
                                "ModMatrix NaN slot=" + juce::String(slot));
                        }
                    }
                }
            }
            logMessage("ModulationMatrix rapid sweep: OK");
        }

        //==============================================================================
        beginTest("OSC1 rapid sweep — saw, pulse, PWM, range, phase reset");

        {
            OSC1 osc1;
            osc1.prepare(kTestSampleRate);
            osc1.setFrequency(440.0);

            for (int sawEn = 0; sawEn <= 1; ++sawEn)
            {
                for (int pulseEn = 0; pulseEn <= 1; ++pulseEn)
                {
                    if (sawEn == 0 && pulseEn == 0) continue;

                    for (float pwm = 0.0f; pwm <= 1.0f; pwm += 0.25f)
                    {
                        for (int range = 0; range <= 2; ++range)
                        {
                            float sample = osc1.nextSample();
                            expect(std::isfinite(sample),
                                "OSC1 NaN saw=" + juce::String(sawEn)
                                + " pulse=" + juce::String(pulseEn)
                                + " pwm=" + juce::String(pwm));
                        }
                    }
                }
            }
            logMessage("OSC1 rapid sweep: OK");
        }

        //==============================================================================
        beginTest("OSC2 rapid sweep — pitch, tone mod, level");

        {
            OSC2 osc2;
            osc2.prepare(kTestSampleRate);

            for (float pitch = -1.0f; pitch <= 1.0f; pitch += 0.5f)
            {
                osc2.setFrequency(440.0 * std::pow(2.0, pitch / 12.0));

                for (float toneMod = 0.0f; toneMod <= 1.0f; toneMod += 0.25f)
                {
                    osc2.setModulationValue(OSC2::kToneMod, toneMod);

                    for (float level = 0.0f; level <= 1.0f; level += 0.25f)
                    {
                        float sample = osc2.nextSample();
                        expect(std::isfinite(sample),
                            "OSC2 NaN pitch=" + juce::String(pitch)
                            + " tone=" + juce::String(toneMod));
                    }
                }
            }
            logMessage("OSC2 rapid sweep: OK");
        }

        //==============================================================================
        beginTest("VCA section rapid sweep — level, mode, env depth, vel sensitivity");

        {
            SynthVoice voice;
            voice.prepare(kTestSampleRate);

            const ModulationMatrix dummyMatrix;

            for (float vcaLevel = 0.0f; vcaLevel <= 1.0f; vcaLevel += 0.2f)
            {
                voice.params.vcaLevel = vcaLevel;

                for (int vcaMode = 0; vcaMode <= 1; ++vcaMode)
                {
                    voice.params.vcaMode = vcaMode;

                    for (float vcaEnvDepth = 0.0f; vcaEnvDepth <= 1.0f; vcaEnvDepth += 0.25f)
                    {
                        voice.params.vcaEnvDepth = vcaEnvDepth;

                        for (float vcaVelSens = 0.0f; vcaVelSens <= 1.0f; vcaVelSens += 0.25f)
                        {
                            voice.params.vcaVelSens = vcaVelSens;

                            voice.startNote(60, 0.8f, 0.0f);
                            juce::AudioBuffer<float> buf(2, 128);
                            buf.clear();
                            voice.process(buf, 0, 128, dummyMatrix);

                            for (int ch = 0; ch < 2; ++ch)
                                for (int s = 0; s < 128; ++s)
                                    expect(std::isfinite(buf.getSample(ch, s)),
                                        "VCA NaN level=" + juce::String(vcaLevel)
                                        + " mode=" + juce::String(vcaMode));

                            voice.stopNote(true);
                        }
                    }
                }
            }
            logMessage("VCA section rapid sweep: OK (6 levels x 2 modes x 5 depths x 5 sems)");
        }

        //==============================================================================
        beginTest("SynthEngine full integration — rapid parameter sweep via MIDI");

        {
            // Create a full engine, prepare it, and sweep while sending MIDI notes
            // This tests the entire signal chain: MIDI → voices → audio output
            SynthEngine engine;
            engine.prepare(kTestSampleRate, 256);

            // Send notes across the range
            for (int note = 36; note <= 96; note += 12)
            {
                // NoteOn
                juce::MidiBuffer midi;
                midi.addEvent(juce::MidiMessage::noteOn(1, note, (juce::uint8)100), 0);

                juce::AudioBuffer<float> buffer(2, 256);
                buffer.clear();

                engine.processBlock(buffer, midi);

                for (int ch = 0; ch < 2; ++ch)
                    for (int s = 0; s < 256; ++s)
                        expect(std::isfinite(buffer.getSample(ch, s)),
                            "Engine NaN note=" + juce::String(note)
                            + " ch=" + juce::String(ch));
            }

            // Test with all notes off (should produce zero/silence)
            {
                juce::MidiBuffer midi;
                for (int note = 36; note <= 96; note += 12)
                    midi.addEvent(juce::MidiMessage::noteOff(1, note), 0);

                juce::AudioBuffer<float> buffer(2, 256);
                buffer.clear();

                engine.processBlock(buffer, midi);

                for (int ch = 0; ch < 2; ++ch)
                    for (int s = 0; s < 256; ++s)
                        expect(std::isfinite(buffer.getSample(ch, s)),
                            "Engine NaN after noteOff");
            }

            logMessage("SynthEngine integration rapid sweep: OK (6 notes x 256 samples)");
        }
    }
};

static SynthEngineRapidSweepTests synthEngineRapidSweepTests;

