/* ── CATEGORY PICKER OPTION BUTTONS ── */
.cat-picker-btn {
    width: 100%;
    text-align: left;
    padding: 8px 12px;
    font-size: 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: var(--bg-elevated, #222);
    border: 1px solid var(--border-dim, #333);
    color: var(--text-primary, #ddd);
}

.cat-picker-btn.active {
    border-color: var(--brand-accent, #ff9900);
    color: var(--brand-accent, #ff9900);
}

/* ── SAVE-AS BANKS & SLOTS (edit_persistence.js) ── */
.saveas-bank-item {
    padding: 8px;
    font-size: 11px;
    border-radius: 3px;
    font-weight: bold;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
}
.saveas-bank-item.is-factory {
    background: var(--bg-header);
    color: var(--text-faint);
    cursor: not-allowed;
    opacity: 0.4;
}
.saveas-bank-item.is-user {
    background: var(--bg-header);
    color: var(--text-secondary);
    border: 1px solid var(--border);
}
.saveas-bank-item.is-selected {
    background: linear-gradient(180deg, color-mix(in srgb, var(--accent-primary) 28%, #111), color-mix(in srgb, var(--accent-primary) 10%, #000));
    color: var(--text-primary);
    border: 1px solid var(--brand-accent);
}

.saveas-slot-item {
    padding: 4px 6px;
    font-size: 9px;
    border-radius: 2px;
    cursor: pointer;
    display: flex;
    align-items: center;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    background: var(--bg-elevated);
    border: 1px solid var(--border-dim);
}
.saveas-slot-item.is-selected {
    background: var(--brand-accent);
    color: #000;
    border: 1px solid #fff;
}
.saveas-slot-item.is-empty {
    color: var(--text-dim);
}
.saveas-slot-item.is-occupied {
    color: var(--text-secondary);
}

.saveas-lock-badge {
    font-size: var(--text-xs);
    color: var(--color-danger);
    text-transform: uppercase;
}

/* ── SHORTCUTS SETTINGS ── */
.shortcuts-empty {
    padding: 20px;
    font-size: var(--text-sm);
    text-align: center;
    color: var(--text-dim);
}

.shortcut-group-header {
    font-size: var(--text-xs);
    text-transform: uppercase;
    font-weight: bold;
    padding: 6px 8px;
    border-bottom: 1px solid var(--border-dim);
    margin: 4px 0 2px 0;
}

.shortcut-group-header[data-group="global"]    { color: var(--accent-cyan); }
.shortcut-group-header[data-group="sequencer"] { color: var(--accent-pink); }
.shortcut-group-header[data-group="other"]      { color: var(--text-dim); }

.shortcut-config-row {
    display: grid;
    grid-template-columns: 1fr auto 60px;
    gap: 10px;
    align-items: center;
    padding: 6px 8px;
    border-radius: var(--radius-xs);
    font-size: var(--text-sm);
    cursor: pointer;
    transition: background 0.15s ease;
}

.shortcut-config-row:hover:not(.is-capturing) {
    background: var(--bg-hover);
}

.shortcut-config-row.is-capturing {
    background: color-mix(in srgb, var(--accent-primary) 20%, transparent);
    outline: 1px solid var(--accent-primary);
}

.shortcut-label {
    color: var(--text-primary);
    font-weight: bold;
}

.shortcut-description {
    color: var(--text-dim);
    font-size: var(--text-2xs);
}

.kbd-tag {
    display: inline-block;
    background: var(--bg-deepest);
    border: 1px solid var(--border);
    border-radius: 3px;
    padding: 2px 7px;
    font-family: 'Share Tech Mono', monospace;
    font-size: 10px;
    color: var(--text-primary);
    min-width: 90px;
    text-align: center;
}

.shortcut-reset-btn {
    background: none;
    border: 1px solid var(--border-dim);
    color: var(--text-faint);
    border-radius: 2px;
    cursor: pointer;
    padding: 1px 6px;
    font-size: 9px;
    transition: all 0.15s ease;
}

.shortcut-reset-btn:hover {
    border-color: var(--accent-primary);
    color: var(--accent-primary);
}

.shortcut-feedback {
    opacity: 0;
    transition: opacity 0.35s ease;
}

.shortcut-feedback.is-visible {
    opacity: 1;
}

.shortcut-feedback.is-info {
    color: var(--accent-cyan);
}

.shortcut-feedback.is-success {
    color: var(--accent-green);
}

.shortcut-feedback.is-error {
    color: var(--accent-orange);
}

/* ── SEQ PRESET ITEMS (sequencer_presets.js) ── */
.seq-preset-list-item {
    padding: 3px;
    cursor: pointer;
    border-radius: var(--radius-xs);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

/* ── BROWSER LIST ITEMS ── */
.browser-list-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 3px 6px;
    gap: 4px;
    overflow: hidden;
}

/* ── HW BANK BUTTONS (browser.js) ── */
.hw-bank-btn {
    background: var(--bg-hover) !important;
}
.hw-bank-btn.is-active {
    background: var(--brand-accent) !important;
}

/* ── SEQUENCER MODE BADGES ── */
.seq-mode-badge {
    display: inline-block;
    font-weight: bold;
    border: 1px solid;
    padding: 0 5px;
    border-radius: 3px;
    font-size: 9px;
    vertical-align: middle;
}
.seq-mode-badge.free        { color: var(--accent-green); border-color: var(--accent-green); }
.seq-mode-badge.free-forced { color: var(--accent-yellow); border-color: var(--accent-yellow); cursor: help; }
.seq-mode-badge.key         { color: var(--accent-blue); border-color: var(--accent-blue); }
.seq-mode-badge.loop        { color: var(--accent-teal); border-color: var(--accent-teal); }

