    color: var(--text-primary);
    border: 1px solid var(--border-dim);
    border-radius: var(--radius-xs);
    font-size: var(--text-2xs);
    padding: 2px 4px;
    outline: none;
}

.fx-preset-select option {
    background-color: #12161f;
    color: #e6edf3;
    padding: 4px;
}

.fx-preset-select option:disabled {
