/* ── FX PRESET FILTER BAR ── */
.fx-preset-filter-bar {
    display: flex;
    gap: 2px;
    margin-bottom: 4px;
}

.fx-preset-filter-btn {
    flex: 1;
    padding: 2px 4px;
    border: 1px solid var(--border-dim);
    border-radius: var(--radius-xs);
