/* Container base for effect templates */
.fx-module {
    width: 95%;
    border-radius: var(--radius);
    padding: 8px;
    font-family: sans-serif;
    color: #fff;
    box-sizing: border-box;
}

.fx-row {
    display: flex;
    align-items: center;
}

.fx-row-around {
    display: flex;
    align-items: center;
    justify-content: space-around;
}

.fx-row-between {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.fx-col {
    display: flex;
    flex-direction: column;
}

.fx-grid {
    display: grid;
    text-align: center;
}

.fx-param {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
}

/* Badges used in effect headers */
.fx-badge {
    border-radius: var(--radius-xs);
    font-family: 'Share Tech Mono', monospace;
    font-weight: bold;
    text-transform: uppercase;
}

.badge-blue {
    background: #0088ff;
    color: #000;
    box-shadow: 0 0 8px rgba(0, 136, 255, 0.6);
}

.badge-green {
    background: #00ff66;
    color: #000;
    box-shadow: 0 0 8px rgba(0, 255, 102, 0.6);
}

.badge-red {
    background: #ff2200;
    color: #000;
    box-shadow: 0 0 8px rgba(255, 34, 0, 0.6);
}

.badge-purple {
    background: #7b5ea7;
    color: #fff;
}

.badge-dark {
    background: #111;
    color: #666;
}

.badge-active {
    background: var(--border-dim);
    color: var(--text-primary);
}

.badge-pill {
    padding: 1px 3px;
    border-radius: 2px;
}

/* Tiny buttons used in effect templates */
.fx-btn-tiny {
    font-size: 6px;
    padding: 2px 4px;
    border: none;
    border-radius: var(--radius-xs);
    font-weight: bold;
    cursor: pointer;
}

.fx-mode-selector {
    display: flex;
    background: #111;
    padding: 1px;
    border: 1px solid var(--border-dim);
    border-radius: var(--radius-xs);
}

.fx-btn-tiny.orange { background: #ff5500; color: #fff; }
.fx-btn-tiny.dark   { background: #333; color: #aaa; }

.fx-btn-tiny-solo {
    width: 16px;
    height: 16px;
    margin: 0 auto 3px;
    padding: 0;
    cursor: pointer;
}

/* Text sizes commonly used in effect templates */
.txt-4  { font-size: 4px; }
.txt-5  { font-size: 5px; }
.txt-6  { font-size: 6px; }
.txt-7  { font-size: 7px; }
.txt-8  { font-size: 8px; }
.txt-9  { font-size: 9px; }
.txt-10 { font-size: 10px; }
.txt-11 { font-size: 11px; }
.txt-12 { font-size: 12px; }

.txt-upper   { text-transform: uppercase; }
.txt-nowrap  { white-space: nowrap; }
.txt-bold    { font-weight: bold; }
.txt-light   { color: #fff; }
.txt-dark    { color: #000; }
.txt-dim-soft { color: #aaa; }
.txt-dim-hard { color: #666; }
.txt-accent-cyan { color: #00ccff; }
.txt-accent-orange { color: #ff5500; }
.txt-accent-purple { color: #7b5ea7; }
.txt-accent-green-soft { color: #4a8a4a; }
.txt-accent-red-soft { color: #8a4a4a; }
.txt-accent-blue-soft { color: #3a6a9a; }
.txt-accent-brown { color: #8a6a3a; }

/* Knob color modifiers */
.knob-dark  { border-color: #000; }
.knob-dark .knob-pointer  { background: #000; }
.knob-light { border-color: #fff; }
.knob-light .knob-pointer { background: #fff; }

/* Knob size helpers */
.knob-xs { width: 18px; height: 18px; margin-bottom: 2px; }
.knob-sm { width: 20px; height: 20px; margin-bottom: 2px; }
.knob-md { width: 22px; height: 22px; margin: 0 auto 2px; }
.knob-lg { width: 24px; height: 24px; margin: 0 auto 3px; }
.knob-xl { width: 26px; height: 26px; margin: 0 auto 3px; }
.knob-xxl { width: 36px; height: 36px; margin: 0 auto 4px; }

/* Generic variable-based effect theme */
.fx-theme-custom {
    background: var(--fx-bg, #111);
    border: 1px solid var(--fx-border, #333);
    color: var(--fx-text, #fff);
}

/* Value box used in VintageRoomReverb */
.fx-value-box {
    border-radius: var(--radius-xs);
    padding: 4px;
    text-align: center;
    font-family: 'Share Tech Mono', monospace;
    background: var(--fx-bg, #050000);
    border: 1px solid var(--fx-border, #ff2200);
    color: var(--fx-text, #ff2200);
}

.fx-value-box-label {
    color: #661100;
}

.fx-value-box .label {
    color: #661100;
}

/* LED indicator */
.fx-led {
    border-radius: 50%;
    border: 1px solid #ccc;
    margin: 0 auto 3px;
}

.fx-led.green {
    background: #00ff66;
    box-shadow: 0 0 6px #00ff66;
}

.fx-led.off {
    background: var(--border-dim);
    border-color: #000;
}

.fx-led.size-28 {
    width: 28px;
    height: 28px;
}

.fx-led.size-14 {
    width: 14px;
    height: 14px;
}

.fx-led.size-12 {
    width: 12px;
    height: 12px;
}

.fx-led.freeze {
    background: var(--text-dim);
    border: 2px solid #ccc;
    box-shadow: inset 0 2px 4px rgba(0,0,0,0.6);
}

/* Freeze panel */
.fx-freeze-label {
    margin-top: 4px;
}

.fx-freeze-panel {
    align-items: center;
    justify-content: center;
    background: var(--bg-header);
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-dim);
    padding: 4px;
}

/* Bypass message */
.fx-bypass-msg {
    color: var(--text-faint);
    font-size: 12px;
    font-family: 'Share Tech Mono', monospace;
    text-transform: uppercase;
}

/* Knob label colors */
.txt-fx-label-cyan  { color: #00ccff; }
.txt-fx-label-orange { color: #ff5500; }

/* ── SEQUENCER STEPS ── */
.seq-step-wrap {
    position: relative;
    cursor: ns-resize;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    height: 100%;
    background: var(--bg-header);
    border-radius: 1px;
    transition: box-shadow 0.12s ease, outline 0.12s ease;
}

.seq-zero-line {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 50%;
    height: 1px;
    background: rgba(255, 255, 255, 0.08);
    z-index: 1;
    pointer-events: none;
}

.seq-fill-bar {
    width: 100%;
    position: absolute;
    bottom: 50%;
    height: 0%;
    background: var(--accent-pink);
    border-radius: 1px;
    pointer-events: none;
}

.seq-skip-badge {
    position: absolute;
    top: 1px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 6px;
    font-weight: bold;
    color: var(--color-danger);
    background: rgba(255, 0, 0, 0.12);
    padding: 0 2px;
    border-radius: 1px;
    display: none;
    pointer-events: none;
    white-space: nowrap;
    letter-spacing: 0.5px;
}

.seq-skip-badge.visible {
    display: block;
}

.seq-num-label {
    position: absolute;
    bottom: 1px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 5px;
    color: var(--text-faint);
    pointer-events: none;
    line-height: 1;
}

/* ── SEQUENCER EDITOR ── */
.seq-editor-step {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    height: 100%;
    cursor: ns-resize;
    position: relative;
    background: var(--bg-deepest);
    border-left: 1px solid var(--border-dim);
    transition: box-shadow 0.12s ease, outline 0.12s ease;
}

.seq-step-num {
    font-size: var(--text-xs);
    font-weight: bold;
    color: var(--text-secondary);
    background: var(--bg-header);
    border: 1px solid var(--border);
    border-radius: var(--radius-xs);
    padding: 2px 4px 0 4px;
    min-width: 20px;
    text-align: center;
    line-height: 1.2;
}

.seq-step-raw {
    font-size: 7px;
    font-weight: normal;
    color: var(--text-faint);
    text-align: center;
    line-height: 1;
    margin-bottom: 3px;
}

.seq-step-bar-container {
    width: 15px;
    height: 85px;
    background: var(--bg-header);
    position: relative;
    border-radius: 1px;
}

.seq-step-zero-line {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 50%;
    height: 1px;
    background: rgba(255, 255, 255, 0.15);
    z-index: 1;
}

.seq-step-fill-bar {
    width: 100%;
    position: absolute;
    background: var(--brand-accent);
    bottom: 50%;
    height: 0%;
}

.seq-lcd-value {
    font-size: 15px;
    color: var(--accent-pink);
}

/* ── SEQUENCER STEP VISUAL STATES ── */
.seq-step-wrap.is-inactive {
    opacity: 0.3;
}
.seq-step-wrap.is-active {
    opacity: 1;
}
.seq-num-label.is-inactive {
    color: var(--text-dim);
    opacity: 0.3;
}
.seq-num-label.is-active {
    color: var(--text-faint);
    opacity: 1;
}
.seq-fill-bar.is-skip {
    background: transparent;
    border-top: 1px dashed var(--color-danger);
}
.seq-fill-bar.is-positive {
    background: var(--accent-pink);
    border-top: none;
}
.seq-fill-bar.is-negative {
    background: color-mix(in srgb, var(--accent-pink) 40%, #000);
    border-top: none;
}
.seq-step-wrap.row-2 {
    grid-row: 2;
}

/* ── LCD TEXT HELPERS ── */
.lcd-text-xl {
    font-size: 16px;
    letter-spacing: 1px;
    color: var(--text-primary);
}

.lcd-text-lg {
    font-size: 14px;
}

.lcd-text-sub {
    font-size: 7px;
    color: var(--text-faint);
    letter-spacing: 0.5px;
}

.lcd-scroll-text {
    font-size: 16px;
    color: var(--text-primary);
    letter-spacing: 1px;
}

.lcd-text-sub-sm {
    font-size: 8px;
    color: var(--text-dim);
}

.lcd-text-18 { font-size: 18px; color: var(--brand-accent); letter-spacing: 1px; }
.lcd-text-11 { font-size: 11px; color: var(--text-dim); }
.lcd-text-10 { font-size: 10px; color: var(--text-dim); }

/* ── LCD LABELS ── */
.lcd-label {
    font-size: 10px;
    opacity: 0.6;
}

.lcd-value {
    font-size: 15px;
    color: var(--color-gold, #f0c040);
}

.lcd-sub {
    font-size: 11px;
    color: var(--text-dim);
}

.lcd-sub-sm {
    font-size: 9px;
    color: var(--text-dim);
}

/* ── LCD COLOR HELPERS ── */
.lcd-color-green { color: var(--accent-green); }
.lcd-color-pink  { color: var(--accent-pink); }
.lcd-color-blue  { color: var(--accent-blue); }
.lcd-color-orange { color: var(--accent-orange); }
.lcd-color-yellow { color: var(--accent-yellow); }
.lcd-color-red    { color: var(--color-danger); }
.lcd-color-faint  { color: var(--text-faint); }
.lcd-color-gold   { color: var(--color-gold); }
.lcd-color-danger { color: var(--color-danger); }
.lcd-color-cyan { color: var(--accent-cyan); }
.lcd-color-teal { color: var(--accent-teal); }

.lcd-clip-badge {
    font-size: 10px;
    color: var(--color-danger);
    font-weight: bold;
}

.lcd-dbg-badge { float: right; font-size: 6px; color: var(--color-danger); border: 1px solid var(--color-danger); padding: 0 2px; border-radius: 1px; line-height: 10px; }

/* ── LCD SEQUENCER DEBUG ── */
.lcd-seq-debug-header { font-size: 9px; opacity: 0.6; }
.lcd-seq-debug-info { display: block; font-size: 7px; color: var(--text-dim); margin-bottom: 2px; }
.lcd-seq-slew-info { display: block; font-size: 6px; color: var(--text-dim); margin-bottom: 1px; opacity: 0.7; }
.lcd-seq-debug-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; font-size: 6.5px; font-family: monospace; color: var(--text-faint); line-height: 1.3; }
.lcd-seq-debug-cell-active { color: var(--text-primary); background: color-mix(in srgb, var(--accent-pink) 18%, transparent); outline: 1px solid color-mix(in srgb, var(--accent-pink) 40%, transparent); }

.lcd-seq-mode-badge-free-forced { color: var(--accent-yellow); font-weight: bold; font-size: 8px; cursor: help; }
.lcd-seq-mode-badge-free { color: var(--accent-green); font-size: 8px; }
.lcd-seq-mode-badge-key { color: var(--accent-blue); font-size: 8px; }
.lcd-seq-mode-badge-loop { color: var(--accent-teal); font-size: 8px; }

.lcd-seq-skip-text { color: var(--color-danger); font-weight: bold; font-size: 9px; }
.lcd-seq-val-skip { font-size: 8px; color: var(--color-danger); margin-left: 4px; }
.lcd-seq-val-norm { font-size: 8px; color: var(--accent-pink); margin-left: 4px; }
.lcd-seq-bars { font-size: 8px; letter-spacing: 0; color: var(--text-faint); }

/* ===============================================================
   module-midi.css — Componentes específicos MIDI
   ===============================================================
   Extraído de utilities.css (refactor 2026-07-27)
   Dispositivos MIDI, MIDI Learn, monitor SysEx.
   =============================================================== */

/* ── MIDI DEVICE LIST ITEMS ── */
.midi-dev-item {
    padding: 6px;
    font-size: var(--text-md);
    color: var(--text-secondary);
    cursor: pointer;
    border-radius: var(--radius-xs);
}

.midi-dev-item.active {
    font-size: var(--text-base);
    background: linear-gradient(180deg, color-mix(in srgb, var(--accent-primary) 28%, #111), color-mix(in srgb, var(--accent-primary) 10%, #000));
    border: 1px solid var(--accent-primary);
    border-radius: var(--radius-sm);
    font-weight: bold;
    color: var(--text-primary);
}

/* ── MIDI LEARN SETTINGS ── */
.midi-learn-empty {
    padding: 20px;
    font-size: var(--text-sm);
}

.midi-learn-row {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 4px 6px;
    border-bottom: 1px solid var(--border-dim);
    font-size: var(--text-sm);
}

.midi-learn-key {
    color: var(--accent-blue);
    font-weight: bold;
    font-family: 'Share Tech Mono', monospace;
    min-width: 80px;
}

.midi-learn-arrow {
    color: var(--text-secondary);
}

.midi-learn-param {
    color: var(--brand-accent);
    flex: 1;
}

.midi-learn-del-btn {
    background: none;
    border: 1px solid var(--color-danger);
    color: var(--color-danger);
    border-radius: 2px;
    cursor: pointer;
    padding: 1px 6px;
    font-size: 9px;
}

.midi-learn-del-btn:hover {
    background: color-mix(in srgb, var(--color-danger) 10%, transparent);
}

/* ── MIDI LEARN TOOLTIP LABELS ── */
.midi-learn-label {
    color: var(--accent-blue);
    font-weight: bold;
    font-size: 9px;
}

.midi-learn-title { font-size: 10px; }
.midi-learn-line { font-size: 7px; color: var(--text-dim); }

/* ── MIDI LEARN BUTTON ── */
.midi-learn-btn {
    background: transparent;
    border-color: var(--accent-blue);
    box-shadow: none;
    color: var(--accent-blue);
}
.midi-learn-btn.is-active {
    background: color-mix(in srgb, var(--accent-blue) 35%, transparent);
    box-shadow: 0 0 12px var(--accent-blue);
}

/* ── SYSEX MONITOR PRO WARNING ── */
.sysex-byte-pro-warning {
    background: color-mix(in srgb, var(--accent-red, #ff4d4d) 25%, transparent) !important;
    border: 1px solid var(--accent-red, #ff4d4d) !important;
    color: var(--accent-red, #ff4d4d) !important;
    font-weight: bold;
}

/* ── SYSEX MONITOR BUTTONS ── */
.sysex-btn {
    transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}
.sysex-btn.is-zoom-active {
    color: var(--color-danger);
    border-color: var(--color-danger);
    background: color-mix(in srgb, var(--color-danger) 15%, transparent);
}
.sysex-btn.is-zoom-inactive {
    color: var(--accent-green);
    border-color: var(--accent-green);
    background: color-mix(in srgb, var(--accent-green) 15%, transparent);
}
.sysex-btn.is-export-done {
    color: var(--accent-green);
    border-color: var(--accent-green);
}
.sysex-btn.is-export-idle {
    color: var(--accent-pink);
    border-color: var(--accent-pink);
}
.sysex-btn.is-copy-done {
    color: var(--accent-green);
    border-color: var(--accent-green);
}
.sysex-btn.is-copy-idle {
    color: inherit;
    border-color: inherit;
}

/* ── PASTE SYSEX STATUS ── */
.paste-status {
    color: var(--text-dim);
}
.paste-status.target  { color: var(--accent-teal); }
.paste-status.success { color: var(--accent-green); }
.paste-status.warning { color: var(--accent-primary); }
.paste-status.error   { color: var(--accent-red); }

/* --- MENU SUPERIOR / NAVIGATION BAR --- */

#top-bar {
    height: 32px;
    background: var(--bg-elevated);
    border-bottom: 2.5px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 20px;
    font-size: var(--text-base);
    font-weight: bold;
    color: var(--text-secondary);
    user-select: none;
    position: relative;
    z-index: 99999 !important;
}

.menu-nav {
    display: flex;
    gap: 25px;
    position: relative;
    z-index: 999999 !important;
}

.menu-item {
    position: relative;
    cursor: pointer;
    padding: 6px 0;
    transition: color 0.15s ease;
    z-index: 999999 !important;
}

.menu-item:hover {
    color: var(--brand-accent);
}

.dropdown {
    position: absolute;
    top: 100%;
    left: 0;
    background: var(--bg-header);
    border: 1.5px solid var(--border);
    border-radius: var(--radius);
    width: 190px;
    display: none;
    flex-direction: column;
    z-index: 9999999 !important;
    box-shadow: var(--shadow-dropdown);
    padding: 5px 0;
    margin: 0;
    list-style: none;
    padding-left: 0;
}

.dropdown li {
    padding: 8px 16px;
    list-style: none;
    color: var(--text-secondary);
    transition: background 0.1s, color 0.1s;
    font-size: var(--text-base);
}

.dropdown li:hover {
    background: var(--brand-accent);
    color: #000;
    font-weight: bold;
}

.dropdown .divider {
    height: 1px;
    background: var(--border);
    margin: 5px 0;
    pointer-events: none;
}

.menu-item:hover .dropdown {
    display: flex;
}

#app-title-mini {
    font-weight: 900;
    color: var(--text-faint);
    letter-spacing: 0.5px;
}

/* --- Controller Overlay Permanente (Top Bar) --- */

#ctrl-overlay {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0 8px;
    flex-shrink: 0;
}

.ctrl-overlay-item {
    display: flex;
    align-items: center;
    gap: 4px;
}

.ctrl-overlay-label {
    font-size: 7px;
    font-weight: 900;
    color: var(--text-faint);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    min-width: 16px;
    text-align: right;
}

.ctrl-overlay-track {
    width: 48px;
    height: 6px;
    background: var(--bg-header);
    border-radius: 3px;
    position: relative;
    overflow: hidden;
    border: 1px solid var(--border);
}

/* Mono-directional track (Mod Wheel, Aftertouch) */
.ctrl-overlay-track-mono {
    width: 36px;
}

.ctrl-overlay-fill {
    position: absolute;
    top: 0;
    height: 100%;
    border-radius: 2px;
    transition: width 0.06s linear, left 0.06s linear, background 0.1s;
}

.ctrl-overlay-center {
    position: absolute;
    left: 50%;
    top: 0;
    width: 1px;
    height: 100%;
    background: var(--border-strong);
    opacity: 0.5;
}

.ctrl-overlay-value {
    font-size: 7px;
    font-weight: 700;
    font-family: 'Share Tech Mono', monospace;
    color: var(--text-faint);
    min-width: 28px;
    text-align: left;
    transition: color 0.1s;
}

/* --- PANEL DE EDICIÓN DESLIZABLE DE ALTO RENDIMIENTO (LOOK & FEEL ANÁLOGO) --- */

.slide-edit-panel {
    position: absolute;
    top: 32px; /* Alineado justo debajo del top-bar */
    left: -320px; /* Escondido por defecto a la izquierda */
    width: 310px;
    height: calc(100% - 32px - 160px); /* Ajustado para que acabe exactamente donde empieza la keyboard-container (teclado + ruedas) */
    background: var(--bg-surface);
    border-right: 2px solid var(--border);
    border-bottom: 2px solid var(--border);
    box-shadow: var(--shadow-panel);
    z-index: 4000 !important;
    display: flex;
    flex-direction: column;
    transition: left 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}

.slide-edit-panel.active {
    left: 0; /* Desliza y se posiciona a la izquierda */
}

.slide-edit-panel .panel-header {
    background: var(--bg-header);
    padding: 10px 15px;
    border-bottom: 1.5px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.slide-edit-panel .panel-header h3 {
    margin: 0;
    font-size: var(--text-base);
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--brand-accent);
}

.slide-edit-panel .panel-content {
    flex: 1;
    padding: 15px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 15px;
}

/* SUBCOMPONENTES DE DISEÑO PARA CONTROLES DE EDICIÓN */

.panel-row {
    display: flex;
    flex-direction: row;
    gap: 12px;
    justify-content: space-between;
    align-items: center;
}

.panel-section-title {
    font-size: var(--text-xs);
    font-weight: 900;
    color: var(--text-dim);
    text-transform: uppercase;
    border-bottom: 1px dashed var(--border);
    padding-bottom: 3px;
    margin-bottom: 5px;
}

/* Selector de ondas: Filas de leds horizontales */
.shape-selector-container {
    display: flex;
    flex-direction: column;
    gap: 4px;
    background: var(--bg-deepest);
    padding: 8px;
    border-radius: var(--radius);
    border: 1px solid var(--border-dim);
    width: 100%;
}

.shape-led-row {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    padding: 3px 6px;
    cursor: pointer;
    border-radius: var(--radius-xs);
    transition: background 0.1s;
}

.shape-led-row:hover {
    background: color-mix(in srgb, var(--accent-primary) 5%, transparent);
}

.shape-led-row.active {
    background: color-mix(in srgb, var(--accent-primary) 10%, transparent);
}

.shape-led-row .led-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--border-strong);
    transition: all 0.2s;
    box-shadow: none;
}

.shape-led-row.active .led-dot {
    background: var(--brand-accent);
    box-shadow: var(--brand-accent-glow);
}

.shape-led-row .shape-name {
    font-size: var(--text-xs);
    font-weight: bold;
    color: var(--text-dim);
    text-transform: uppercase;
}
.shape-led-row.active .shape-name {
    color: var(--text-primary);
}

/* Switch análogo en caja */
.toggle-box {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: var(--bg-deepest);
    padding: 6px 10px;
    border-radius: var(--radius);
    border: 1px solid var(--border-dim);
    cursor: pointer;
    flex: 1;
}

.toggle-box .toggle-label {
    font-size: var(--text-xs);
    font-weight: bold;
    color: var(--text-dim);
    text-transform: uppercase;
}

.toggle-box .toggle-led {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--border-strong);
    transition: all 0.2s;
}

.toggle-box.active .toggle-led {
    background: var(--brand-accent);
    box-shadow: var(--brand-accent-glow);
}

.toggle-box.active .toggle-label {
    color: var(--text-primary);
}

/* Radio-style selector buttons used in OSC range, pitch mode, VCF poles, etc. */
.env-type-btn {
    background: var(--bg-deepest);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    color: var(--text-dim);
    font-size: var(--text-xs);
    font-weight: 700;
    font-family: 'Share Tech Mono', monospace;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 5px 2px;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s, color 0.15s, box-shadow 0.15s;
}
.env-type-btn:hover {
    background: color-mix(in srgb, var(--accent-primary) 7%, transparent);
    border-color: color-mix(in srgb, var(--accent-primary) 40%, transparent);
    color: var(--text-secondary);
}
.env-type-btn.active {
    background: color-mix(in srgb, var(--accent-primary) 18%, transparent);
    border-color: var(--brand-accent);
    color: var(--brand-accent);
    box-shadow: 0 0 8px color-mix(in srgb, var(--accent-primary) 30%, transparent);
}

/* Custom scrollbar for sliding edit panel content */
.slide-edit-panel .panel-content::-webkit-scrollbar {
    width: 6px;
}
.slide-edit-panel .panel-content::-webkit-scrollbar-track {
    background: var(--bg-surface);
}.slide-edit-panel .panel-content::-webkit-scrollbar-thumb        { background: var(--brand-accent); border-radius: var(--radius-sm); }
.slide-edit-panel .panel-content::-webkit-scrollbar-thumb:hover  { background: color-mix(in srgb, var(--accent-primary) 88%, #000); }

/* Collapse/Expand toggle button for the graphic screen */
#panel-graphic-toggle {
    display: block;
    transition: color 0.2s, background 0.2s;
}
#panel-graphic-toggle:hover {
    color: var(--brand-accent) !important;
    background: var(--bg-elevated) !important;
}

/* ── SCOPE TOOLBAR ── */
.scope-btn {
    background: var(--bg-deepest);
    border: 1px solid var(--border-dim);
    border-radius: var(--radius-xs);
    color: var(--text-dim);
    font-size: 8px;
    padding: 1px 4px;
    cursor: pointer;
    font-family: 'Share Tech Mono', monospace;
    line-height: 1.6;
    transition: all 0.12s;
    user-select: none;
    -webkit-user-select: none;
}
.scope-btn:hover {
    background: var(--bg-hover);
    color: var(--text-primary);
    border-color: var(--border);
}
.scope-btn.active {
    background: color-mix(in srgb, var(--accent-primary) 15%, transparent);
    border-color: var(--brand-accent);
    color: var(--brand-accent);
    box-shadow: 0 0 4px color-mix(in srgb, var(--accent-primary) 20%, transparent);
}
.scope-btn .scope-color-indicator {
    font-size: 10px;
    line-height: 1;
    filter: drop-shadow(0 0 2px currentColor);
}
.scope-zoom-btn {
    font-size: 7px;
    padding: 1px 3px;
}

/* --- RUEDAS DE MODULACIÓN, PITCH BEND Y MANDO DE VOLUMEN/PORTAMENTO --- */

/* Ruedas de Rendimiento Izquierdas */
.performance-wheels {
    position: absolute;
    left: 8px;
    bottom: 15px;
    width: 65px;
    height: 150px;
    display: flex;
    gap: 10px;
    z-index: 10;
}

.wheel-slot {
    flex: 1;
    background: var(--bg-deepest);
    border: 2px solid var(--bg-hover);
    border-radius: var(--radius-sm);
    position: relative;
    cursor: ns-resize;
    box-shadow: inset 0 3px 8px rgba(0, 0, 0, 0.9);
}

.wheel {
    position: absolute;
    width: 100%;
    height: 40px;
    background: linear-gradient(to bottom, var(--bg-header) 0%, var(--border-strong) 50%, var(--bg-header) 100%);
    border-radius: var(--radius-xs);
    border: 1px solid var(--bg-deepest);
    left: 0;
    bottom: 55px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.6);
}

/* Potenciómetros rotatorios globales y botones en matriz de 2x3 */
.performance-matrix-panel {
    position: absolute;
    left: 90px;
    top: 50%;
    transform: translateY(-50%);
    width: 140px;
    height: 140px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 15px;
    z-index: 10;
}

.matrix-row {
    display: flex;
    flex-direction: row;
    align-items: center;
    width: 100%;
}

.row-top {
    height: 60px;
    justify-content: space-between;
}

.row-bottom {
    height: 35px;
    justify-content: space-between;
    padding-top: 5px;
    border-top: 1px solid var(--bg-header);
}

.matrix-cell {
    display: flex;
    justify-content: center;
    align-items: center;
}

.col-porta {
    width: 45px;
}

.col-volume {
    width: 85px; /* fusionada (col 2 y 3) */
}

.col-porta-edit, .col-oct-down, .col-oct-up {
    width: 38px;
}

/* --- PANTALLA LCD Y BOTONES DE DATA ENTRY DEL PROGRAMADOR --- */

.programmer-layout {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 15px;
}

.lcd-screen {
    width: 170px;
    height: 90px;
    /* Scanlines integradas en el fondo (debajo del texto) más el color base del LCD */
    background:
        repeating-linear-gradient(
            to bottom,
            transparent 0px,
            transparent 1px,
            rgba(0, 0, 0, 0.06) 1px,
            rgba(0, 0, 0, 0.06) 2px
        ),
        radial-gradient(
            ellipse at center,
            rgba(255, 255, 255, 0.025) 0%,
            transparent 70%
        ),
        color-mix(in srgb, var(--accent-primary) 5%, #000);
    border: 2.5px solid color-mix(in srgb, var(--accent-primary) 20%, transparent);
    border-radius: var(--radius);
    padding: 8px;
    box-shadow: inset 0 0 15px rgba(0, 0, 0, 0.9), 0 0 20px rgba(0,0,0,0.6);
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
}

#lcd-text {
    font-family: 'Share Tech Mono', monospace;
    font-size: var(--text-xl);
    color: var(--brand-accent);
    text-shadow: 0 0 2px color-mix(in srgb, var(--accent-primary) 15%, transparent);
    text-align: center;
    line-height: 1.4;
}

/* Cursor parpadeante para la animación typewriter del LCD */
.lcd-cursor {
    animation: lcdCursorBlink 0.6s step-end infinite;
    color: var(--brand-accent);
}

@keyframes lcdCursorBlink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0; }
}

/* Elemento contenedor del glow pulse del secuenciador.
   Se posiciona detrás del texto y no interfiere con el box-shadow base del .lcd-screen. */
#lcd-glow-pulse {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border-radius: inherit;
    pointer-events: none;
    z-index: 0;
    /* Sin box-shadow por defecto — el JS lo añade/elimina dinámicamente */
}

/* --- LCD scrolling text for long patch names --- */
.lcd-scroll-container {
    overflow: hidden;
    white-space: nowrap;
    width: 100%;
}
.lcd-scroll-text {
    display: inline-block;
    white-space: nowrap;
    will-change: transform;
}
.lcd-scroll-text.animate {
    animation: lcdMarquee linear infinite;
}
.lcd-scroll-container:hover .lcd-scroll-text.animate,
.lcd-scroll-text.animate.paused {
    animation-play-state: paused;
}
@keyframes lcdMarquee {
    0% { transform: translateX(0); }
    85% { transform: translateX(-100%); }
    100% { transform: translateX(0); }
}

/* --- VOICE LED MONITOR --- */
.voice-led {
    width: 11px;
    height: 11px;
    border-radius: 50%;
    font-family: 'Share Tech Mono', monospace;
    font-size: 7px;
    line-height: 11px;
    text-align: center;
    background: #111;
    border: 1px solid #333;
    color: #444;
    font-weight: bold;
    transition: all 0.05s ease-out;
    cursor: default;
}
.voice-led.active {
    background: #00ff66;
    border-color: #55ffaa;
    color: #000;
    box-shadow: 0 0 5px #00ff66, inset 0 0 2px #fff;
}

/* --- SETTINGS: Global Dump refresh button (replaces inline cssText) --- */
.settings-global-dump-btn {
    font-size: 9px;
    padding: 2px 8px;
    margin-top: 6px;
    margin-left: auto;
    display: block;
}

/* --- COMPARE MODE button states (replaces inline styles in settings.js) --- */
#programmer-compare-btn.compare-mode-btn {
    background: color-mix(in srgb, var(--accent-primary) 20%, transparent);
    border-color: var(--brand-accent);
    color: var(--brand-accent);
}
#programmer-compare-btn.compare-mode-btn.active {
    background: var(--brand-accent);
    border-color: var(--brand-accent);
    color: #000;
}

/* --- LCD compare helper text --- */
.lcd-compare-original {
    font-size: 9px;
    color: var(--text-dim);
}

/* --- MONITOR HEXADECIMAL DE SYSEX --- */

.sysex-monitor-container {
    width: 210px;
    height: 90px;
    background: var(--bg-deepest);
    border: 2px solid var(--border);
    border-radius: var(--radius);
    display: flex;
    flex-direction: column;
    padding: 5px;
    box-shadow: var(--shadow-inset);
}
.sysex-monitor-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--border-dim);
    padding-bottom: 3px;
    margin-bottom: 4px;
}

.sysex-monitor-title {
    font-size: var(--text-xs);
    font-weight: bold;
    color: var(--text-labels);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.sysex-copy-btn {
    background: var(--bg-hover);
    border: 1px solid var(--border-strong);
    color: var(--brand-accent);
    font-size: 7.5px;
    font-weight: bold;
    padding: 1px 4px;
    cursor: pointer;
    border-radius: var(--radius-xs);
}

.sysex-copy-btn:hover {
    background: var(--brand-accent);
    color: #000;
}



.sysex-hex-grid {
    flex: 1;
    overflow-y: auto;
    font-family: 'Share Tech Mono', monospace;
    font-size: var(--text-sm);
    color: var(--accent-green);
    line-height: 1.2;
    padding: 2px;
    word-break: break-all;
    white-space: pre-wrap;
    text-shadow: 0 0 4px color-mix(in srgb, var(--accent-green) 30%, transparent);
}

.hex-byte {
    display: inline-block;
    margin-right: 3px;
    transition: background 0.15s, color 0.15s;
    border-radius: 1px;
    padding: 0 1px;
    cursor: pointer;
}

.hex-byte:hover {
    background: rgba(255, 255, 255, 0.08);
}

.hex-byte.selected {
    background: var(--accent-primary) !important;
    color: #000 !important;
    font-weight: bold;
    text-shadow: none;
    outline: 1px solid var(--brand-accent);
    outline-offset: 0px;
}

/* Byte modificado por slider/control en la UI — fondo verde (negativo) */
.hex-byte.changed {
    background: var(--accent-green) !important;
    color: #000 !important;
    font-weight: bold;
    text-shadow: none;
}

/* Barra de información de selección */
.sysex-selection-info {
    font-size: var(--text-2xs);
    color: var(--text-dim);
    padding: 2px 4px;
    min-height: 14px;
    line-height: 1.3;
    border-top: 1px solid var(--border-dim);
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-family: 'Share Tech Mono', monospace;
}

/* WIDESCREEN HORIZONTAL MODE */
.sysex-monitor-container.widescreen {
    width: auto;
    height: 78px;
    margin: 10px 15px 5px 15px;
    background: var(--bg-deepest);
    border: 2px solid var(--border);
    box-shadow: inset 0 0 12px rgba(0, 0, 0, 0.95);
}
.sysex-monitor-container.widescreen .sysex-hex-grid {
    font-size: 10.5px;
    line-height: 1.4;
    padding: 6px 12px;
    overflow-y: auto;
    letter-spacing: 0.5px;
}

.sysex-monitor-container.widescreen .hex-byte {
    margin-right: 6px;
}

/* WIDESCREEN INLINE (ABOVE THE LCD SCREEN) */
.sysex-monitor-container.widescreen-inline {
    width: 98%;
    height: 82px !important;
    margin-bottom: 0px !important;
    background: var(--bg-deepest);
    border: 2px solid var(--border);
    border-radius: var(--radius);
    box-shadow: inset 0 0 15px rgba(0, 0, 0, 0.95);
    display: flex;
    flex-direction: column;
    padding: 3px 5px;
    box-sizing: border-box;
    overflow: hidden;
    transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.sysex-monitor-container.widescreen-inline .sysex-hex-grid {
    font-size: 7.9px !important;
    line-height: 1.0 !important;
    padding: 1px !important;
    overflow-y: auto !important;
    white-space: pre-wrap !important;
    letter-spacing: 0.1px !important;
    transition: all 0.2s ease;
}

.sysex-monitor-container.widescreen-inline .hex-byte {
    margin-right: 1.5px !important;
}

/* MODO LUPA / ZOOM AMPLIADO POR ENCIMA */
.sysex-monitor-container.widescreen-inline.zoomed {
    position: absolute;
    top: 15px;
    left: 2%;
    width: 96%;
    height: auto !important;
    max-height: 85vh !important;
    z-index: 5000 !important;
    box-shadow: var(--shadow-zoomed);
    background: var(--bg-deepest);
    border-color: var(--accent-green);
    padding: 8px 10px;
}

.sysex-monitor-container.widescreen-inline.zoomed .sysex-monitor-header {
    margin-bottom: 8px;
}

.sysex-monitor-container.widescreen-inline.zoomed .sysex-hex-grid {
    font-size: var(--text-xl) !important; /* Letras y dígitos grandes */
    line-height: 1.3 !important;
    letter-spacing: 1.5px !important;
    overflow-y: auto !important; /* Permitir scroll si es necesario al estar en zoom */
    min-height: 200px !important;
    max-height: none !important;
}

.sysex-monitor-container.widescreen-inline.zoomed .hex-byte {
    margin-right: 6px !important;
}

.sysex-monitor-container.widescreen-inline.zoomed #programmer-scope-view-block {
    height: 280px !important;
    margin-top: 4px;
}

.sysex-monitor-container.widescreen-inline.zoomed #programmer-scope-canvas {
    height: 280px !important;
    border-color: var(--accent-green) !important;
}

/* Ocultar patch label en modo zoom — solo datos + botones superiores */
.sysex-monitor-container.widescreen-inline.zoomed #sysex-active-patch-label {
    display: none !important;
}

