    --shadow-float:   0 10px 30px rgba(0,0,0,0.9);
    --shadow-zoomed:  0 20px 45px rgba(0,0,0,0.9);

    /* Dimensiones Base (no cromáticas, aquí tienen sentido) */
    --slider-height: 125px;
