/* --- ABDEEP ARPEGGIATOR PRESETS MODULE ---
   Arpeggiator pattern presets: data, localStorage CRUD, and list rendering.
   Extracted from arpeggiator.js — pure functions, no closure state.
   Depends on: nothing (Logger is optional, used in try/catch fallback).
*/
/* global Logger */

// ── Built-in default presets ─────────────────────────────────
const DEFAULT_ARP_PRESETS = [
    {
        name: 'Default (UP-DOWN)',
        steps: Array(32).fill(false).map((_, i) => i % 2 === 0)
    },
    {
        name: '8-Step Disco',
        steps: Array(32).fill(false).map((_, i) => i % 4 === 0 || i % 8 === 2)
    },
    {
        name: 'Syncopated',
        steps: Array(32).fill(false).map(() => Math.random() > 0.5)
    }
];

// ── localStorage CRUD ────────────────────────────────────────

/** Load user arp presets from localStorage. On first run, initialize with defaults. */
function loadUserArpPresets() {
    try {
        const raw = localStorage.getItem('abd-eep-arp-presets');
        if (raw) {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed)) {return parsed;}
        } else {
            localStorage.setItem('abd-eep-arp-presets', JSON.stringify(DEFAULT_ARP_PRESETS));
            return DEFAULT_ARP_PRESETS;
        }
    } catch (e) {
        Logger.error('arp presets load error', e);
    }
    return [];
}

/** Save an arpeggiator preset. If name already exists, update in place; otherwise append. */
function saveArpPreset(name, steps) {
    const cleanName = String(name).trim().replace(/[<>"'&]/g, '');
    if (!cleanName) {return { success: false, error: 'Invalid name' };}

    const presets = loadUserArpPresets();
    const existingIdx = presets.findIndex(p => p.name === cleanName);
    const newPreset = { name: cleanName, steps: steps || Array(32).fill(false) };

    if (existingIdx >= 0) {
        presets[existingIdx] = newPreset;
    } else {
        presets.push(newPreset);
    }

    localStorage.setItem('abd-eep-arp-presets', JSON.stringify(presets));
    return { success: true, existingIdx: existingIdx >= 0, preset: newPreset };
}

/** Delete an arpeggiator preset by name. */
function deleteArpPreset(name) {
    let presets = loadUserArpPresets();
    presets = presets.filter(p => p.name !== name);
    localStorage.setItem('abd-eep-arp-presets', JSON.stringify(presets));
}

// ── DOM Rendering ────────────────────────────────────────────

/**
 * Render the arpeggiator preset list into a container element.
 * @param {HTMLElement} containerEl - The presets list container (e.g. #modal-arp-presets-list)
 * @param {function} selectedCallback - Called with (presetObject) when a preset is selected
 * @param {function} deleteCallback - Called with (presetObject) when delete button is clicked
 */
function renderArpPresetsList(containerEl, selectedCallback, deleteCallback) {
    if (!containerEl) {return;}
    containerEl.innerHTML = '';
    const presets = loadUserArpPresets();
    presets.forEach(p => {
        const item = document.createElement('div');
        item.className = 'seq-preset-list-item text-sm text-primary';
        item.innerHTML = '<span class="arp-preset-name">' + String(p.name).replace(/[<>"'&]/g, '') + '</span>' +
                         '<span class="delete-arp-preset-btn">\u2715</span>';

        item.addEventListener('click', function(e) {
            if (e.target.classList.contains('delete-arp-preset-btn')) {return;}
            // Deselect all siblings
            containerEl.querySelectorAll('.seq-preset-list-item').forEach(function(sibling) {
                sibling.style.background = 'transparent';
                sibling.classList.remove('selected');
            });
            item.style.background = 'color-mix(in srgb, var(--accent-primary) 20%, transparent)';
            item.classList.add('selected');
            if (typeof selectedCallback === 'function') {selectedCallback(p);}
        });

        const delBtn = item.querySelector('.delete-arp-preset-btn');
        if (delBtn) {
            delBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                if (typeof deleteCallback === 'function') {deleteCallback(p);}
            });
        }

        containerEl.appendChild(item);
    });
}

// ── Export ───────────────────────────────────────────────────
globalThis.DEFAULT_ARP_PRESETS = DEFAULT_ARP_PRESETS;
globalThis.loadUserArpPresets = loadUserArpPresets;
globalThis.saveArpPreset = saveArpPreset;
globalThis.deleteArpPreset = deleteArpPreset;
globalThis.renderArpPresetsList = renderArpPresetsList;

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        DEFAULT_ARP_PRESETS,
        loadUserArpPresets,
        saveArpPreset,
        deleteArpPreset,
        renderArpPresetsList,
    };
}

/**
 * @purpose Arpeggiator Step Pattern Editor — builds and manages the 32-step interactive grid.
 * Extracted from arpeggiator.js for SRP separation.
 */

/**
 * Crea la cuadrícula interactiva de 32 pasos para el editor de patrones del arpegiador.
 * @param {HTMLElement} stepsGrid - Contenedor de las barras de paso
 * @param {HTMLElement} stepsLabels - Contenedor de las etiquetas numéricas
 * @param {Function} onStepToggle - Callback(index, newState) cuando se conmuta un paso
 * @returns {{ getSteps: () => boolean[], setSteps: (boolean[]) => void, syncVisuals: () => void }}
 */
window.createArpStepGrid = function(stepsGrid, stepsLabels, onStepToggle) {
    /** @type {boolean[]} */
    const steps = Array(32).fill(false);

    stepsGrid.innerHTML = '';
    stepsLabels.innerHTML = '';

    for (let i = 0; i < 32; i++) {
        (function(index) {
            const stepUnit = document.createElement('div');
            stepUnit.style.display = 'flex';
            stepUnit.style.flexDirection = 'column';
            stepUnit.style.justifyContent = 'flex-end';
            stepUnit.style.height = '100%';
            stepUnit.style.cursor = 'pointer';

            const stepBar = document.createElement('div');
            stepBar.style.width = '100%';
            stepBar.style.height = '15%';
            stepBar.style.background = 'var(--bg-hover)';
            stepBar.style.borderRadius = 'var(--radius-xs)';
            stepBar.style.transition = 'background 0.1s, height 0.1s';

            stepUnit.appendChild(stepBar);
            stepUnit.title = 'Step ' + (index + 1) + ': GATE OFF';

            stepUnit.addEventListener('click', function() {
                steps[index] = !steps[index];
                _updateStepVisual(index);
                if (typeof onStepToggle === 'function') {
                    onStepToggle(index, steps[index]);
                }
            });

            stepsGrid.appendChild(stepUnit);

            const label = document.createElement('span');
            label.innerText = index + 1;
            stepsLabels.appendChild(label);
        })(i);
    }

    /**
     * Actualiza la apariencia visual de un paso individual
     */
    function _updateStepVisual(index) {
        const unit = stepsGrid.children[index];
        if (!unit) { return; }
        const bar = unit.querySelector('div');
        if (!bar) { return; }
        bar.style.height = steps[index] ? '90%' : '15%';
        bar.style.background = steps[index] ? 'var(--brand-accent)' : 'var(--bg-hover)';
        unit.title = 'Step ' + (index + 1) + ': GATE ' + (steps[index] ? 'ON' : 'OFF');
    }

    /**
     * Sincroniza las 32 barras visuales con el estado actual de steps[]
     */
    function _syncAllVisuals() {
        for (let j = 0; j < 32; j++) {
            _updateStepVisual(j);
        }
    }

    return {
        /** Retorna una copia del array de pasos actual */
        getSteps: function() { return steps.slice(); },

        /** Establece un nuevo patrón de pasos y sincroniza la UI */
        setSteps: function(newSteps) {
            if (!Array.isArray(newSteps)) { return; }
            for (let k = 0; k < 32; k++) {
                steps[k] = !!(newSteps[k]);
            }
            _syncAllVisuals();
        },

        /** Refresca todas las barras visuales desde el estado actual */
        syncVisuals: function() {
            _syncAllVisuals();
        }
    };
};

/**
 * @purpose Arpeggiator modal UI sync — extracted from arpeggiator.js.
 * Synchronises modal controls (boxes, selects, sliders) with patch bytes.
 * Uses document.getElementById instead of closure variables for independence.
 */

window.syncArpModalUI = function() {
    if (typeof currentActivePatchIndex === 'undefined' || currentActivePatchIndex === -1) {return;}
    const activeBank = loadedBanks[currentActiveBank];
    if (!activeBank) {return;}
    const patch = activeBank[currentActivePatchIndex];
    if (!patch || !patch.unpackedBytes) {return;}

    // Offsets corregidos del manual oficial: ARP (MSB=1, LSB 155-164)
    const arpEn = patch.unpackedBytes[155] > 0.5;
    const modeVal = patch.unpackedBytes[156] || 0;
    const clockVal = patch.unpackedBytes[158] || 0;
    const keySyncEn = patch.unpackedBytes[159] > 0.5;
    const holdEn = patch.unpackedBytes[161] > 0.5;
    const octaveVal = patch.unpackedBytes[164] || 0;
    const velGateVal = patch.unpackedBytes[112] || 0;

    const arpBox = document.getElementById('modal-arp-enable-box');
    const holdBox = document.getElementById('modal-arp-hold-box');
    const keySyncBox = document.getElementById('modal-arp-keysync-box');
    const selectClock = document.getElementById('modal-arp-clock-select');
    const selectVelGate = document.getElementById('modal-arp-velgate-select');
    const selectMode = document.getElementById('modal-arp-mode-select');
    const selectOctave = document.getElementById('modal-arp-octave-select');

    if (arpBox) {arpBox.classList.toggle('active', arpEn);}
    if (holdBox) {holdBox.classList.toggle('active', holdEn);}
    if (keySyncBox) {keySyncBox.classList.toggle('active', keySyncEn);}

    if (selectClock) {selectClock.value = Math.round(clockVal);}
    if (selectVelGate) {selectVelGate.value = Math.round(velGateVal);}
    if (selectMode) {selectMode.value = Math.round(modeVal);}
    if (selectOctave) {selectOctave.value = Math.round(octaveVal);}

    // Offsets corregidos del manual: arp_swing=163, arp_rate=157, arp_gate_time=160
    const sliders = [
        { id: 'arp_swing', val: patch.unpackedBytes[163] / 25.0 },
        { id: 'arp_rate', val: patch.unpackedBytes[157] / 255.0 },
        { id: 'arp_gate_time', val: patch.unpackedBytes[160] / 255.0 }
    ];

    const backdrop = document.getElementById('arp-modal-backdrop');
    sliders.forEach(sliderInfo => {
        if (!backdrop) {return;}
        const sliderEl = backdrop.querySelector(`[data-param="${sliderInfo.id}"] .v-slider`);
        if (sliderEl) {
            const handle = sliderEl.querySelector('.handle');
            const updatePos = () => {
                const rect = sliderEl.getBoundingClientRect();
                if (rect.height > 0) {
                    const handleHeight = 16;
                    const pos = (1.0 - sliderInfo.val) * (rect.height - handleHeight);
                    handle.style.top = pos + 'px';
                } else {
                    setTimeout(updatePos, 100);
                }
            };
            updatePos();
        }
    });
};

window.syncArpModalUIFromState = function() {
    const backdrop = document.getElementById('arp-modal-backdrop');
    if (backdrop && backdrop.style.display !== 'none') {
        window.syncArpModalUI();
    }
};

