    DualMidiBridge.prototype._updateConnectionUI = function() {
        const indicator = document.getElementById('midi-connection-indicator');
        const statusBtn = document.getElementById('settings-connection-status');
        const reconnectBtn = document.getElementById('reconnect-hw-btn');
        const connected = this._connected && (this.isJuce || (this.midiOutput && this.midiInput));
        const hasHardware = this._hardwareInfo && this._hardwareInfo.globalDumpBytes;

        let color = 'var(--color-danger)';
        let shadow = '0 0 4px var(--color-danger)';
        let statusText = 'Disconnected';
        let tooltipText = 'MIDI: Disconnected';
        let statusColor = 'var(--text-primary)';
        let statusBorder = '1px solid var(--color-danger)';

        if (connected) {
            if (this.isJuce && !hasHardware) {
                color = '#00d2ff';
                shadow = '0 0 6px #00d2ff';
                statusText = 'Local DSP Active';
                tooltipText = 'Engine: Connected (Emulator Mode)';
                statusColor = '#00d2ff';
                statusBorder = '1px solid #00d2ff';
            } else {
                color = 'var(--accent-green)';
                shadow = '0 0 6px var(--accent-green)';
                statusText = 'Connected';
                tooltipText = 'MIDI: Connected to Hardware';
                statusColor = 'var(--accent-green)';
                statusBorder = '1px solid var(--accent-green)';
            }
        }

        if (indicator) {
            indicator.style.backgroundColor = color;
            indicator.style.boxShadow = shadow;
            indicator.setAttribute('data-ctrl-tooltip', tooltipText);
        }
        if (statusBtn) {
            statusBtn.textContent = statusText;
            statusBtn.style.color = statusColor;
            statusBtn.style.border = statusBorder;
        }
        if (reconnectBtn) {
            reconnectBtn.style.display = connected ? 'none' : 'inline-block';
            if (!reconnectBtn._wired) {
                reconnectBtn._wired = true;
                reconnectBtn.addEventListener('click', async () => {
                    reconnectBtn.textContent = 'CONNECTING...';
                    reconnectBtn.disabled = true;
                    try {
                        const ok = await this.resetMidiConnection();
                        if (!ok) {
                            throw new Error('Reconnection failed');
                        }
                    } catch (e) {
                        Logger.warn('[Bridge] Reconnection failed, opening settings:', e.message);
                        const modal = document.getElementById('settings-modal-backdrop');
                        if (modal) {
                            modal.style.display = 'flex';
                            if (typeof window.populateMidiPortsLists === 'function') {
                                window.populateMidiPortsLists();
                            }
                            if (typeof window._updateSettingsHardwareInfo === 'function') {
                                window._updateSettingsHardwareInfo();
                            }
                            const connTabBtn = document.querySelector('.btn[data-tab="connections"]');
                            if (connTabBtn) {
                                connTabBtn.click();
                            }
                        }
                    } finally {
                        reconnectBtn.textContent = 'RE-CONNECT HARDWARE';
                        reconnectBtn.disabled = false;
                        this._updateConnectionUI();
                    }
                });
            }
        }
    };

    Logger.log('[Bridge] Connection utils module loaded');
})();

// eslint-disable-next-line no-var
var Logger = globalThis.Logger || console;

/**
 * @purpose Web MIDI initialization + connection management + audio/piano methods for DualMidiBridge
 * @purpose_en Web MIDI init, connection management, and audio/piano methods for DualMidiBridge
 * @classification Module/Connection
 * @complexity High
 *
 * Refactored into sub-modules:
 *   - bridge_connection_utils.js: _isLikelyVirtualPort, _detectConnectionType, _selectMidiPort,
 *     _signalMidiActivity, _showNoteOnLcd, _midiNoteToName, getHardwareInfo, _updateConnectionUI
 *   - bridge_connection_midi.js: initWebMidi, scanMidiDevices, resetMidiConnection,
 *     startAutoReconnect, sendWebMidiParameter
 *   - bridge_connection_juce.js: getVoiceState, getAudioWaveform, getDiagnosticSnapshot,
 *     getCalibration, setCalibration, Audio AB methods, runRoundTripValidator
 */

/* global _selectMidiPort, _signalMidiActivity, _updateConnectionUI */

(function() {
    if (typeof DualMidiBridge === 'undefined') {
        Logger.warn('[Bridge-Connection] DualMidiBridge not found — deferring...');
        return;
    }

    DualMidiBridge.prototype.pianoNoteOn = function(note, velocity) {
        if (this.isJuce) {
            if (window.juce && typeof window.juce.pianoNoteOn === 'function') {
                window.juce.pianoNoteOn(note, velocity || 100);
            }
        } else {
            velocity = velocity === undefined ? 100 : Math.round(Math.max(1, Math.min(127, velocity * 127)));
            Logger.log(`[Bridge Web-MIDI] Note On: ${note} (vel=${velocity})`);
            if (this.midiOutput) {
                const channel = (this.midiChannel ? this.midiChannel - 1 : 0) & 0x0F;
                this.midiOutput.send([0x90 | channel, note, velocity]);
                this._signalMidiActivity();
            }
            if (window.wasmBridge) {
                window.wasmBridge.noteOn(note, velocity / 127.0);
            }
        }
        this._showNoteOnLcd(note, velocity);
    };

    DualMidiBridge.prototype.pianoNoteOff = function(note) {
        if (this.isJuce) {
            if (window.juce && typeof window.juce.pianoNoteOff === 'function') {
                window.juce.pianoNoteOff(note);
            }
        } else {
            Logger.log(`[Bridge Web-MIDI] Note Off: ${note}`);
            if (this.midiOutput) {
                const channel = (this.midiChannel ? this.midiChannel - 1 : 0) & 0x0F;
                this.midiOutput.send([0x80 | channel, note, 0]);
                this._signalMidiActivity();
            }
            if (window.wasmBridge) {
                window.wasmBridge.noteOff(note);
            }
        }
    };

    DualMidiBridge.prototype.panic = function() {
        if (this.isJuce) {
            if (window.juce && typeof window.juce.panic === 'function') {
                window.juce.panic();
            }
        }
    };

    DualMidiBridge.prototype.isConnected = async function() {
        if (this.isJuce) {
            this._connected = true;
            this._updateConnectionUI();
            return true;
        }
        if (!this.midiOutput || !this.midiInput) {
            this._connected = false;
            this._updateConnectionUI();
            return false;
        }

        const inquiry = [0xF0, 0x7E, 0x7F, 0x06, 0x01, 0xF7];
        const isIdentityReply = (msg) => {
            return msg.length >= 10 &&
                   msg[0] === 0xF0 &&
                   msg[1] === 0x7E &&
                   msg[3] === 0x06 &&
                   msg[4] === 0x02 &&
                   msg[5] === 0x00 &&
                   msg[6] === 0x20 &&
                   msg[7] === 0x32;
        };

        try {
            const response = await this.requestSysEx(inquiry, 2000, isIdentityReply);
            const isDeepMind = response[8] === 0x20 && response[9] === 0x00;

            if (response.length >= 16) {
                const deviceId = response[2] & 0x0F;
                this._hardwareInfo.deviceId = String(deviceId);
                this._hardwareInfo.midiChannel = deviceId + 1;
                this._hardwareInfo.connectionType = this._detectConnectionType(this.midiOutput.name);

                const mainMajor = response[12] >> 4;
                const mainMinor = response[12] & 0x0F;
                this._hardwareInfo.hostVersion = mainMajor + '.' + mainMinor;
                this._hardwareInfo.voiceVersion = response[14] + '.' + response[15];

                if (typeof window._updateSettingsHardwareInfo === 'function') {
                    window._hardwareInfo = this._hardwareInfo;
                    window._updateSettingsHardwareInfo();
                }
            }

            this._connected = isDeepMind;
            this._updateConnectionUI();
            return isDeepMind;
        } catch (err) {
            this._connected = false;
            this._updateConnectionUI();
            return false;
        }
    };

    Logger.log('[Bridge] Connection module loaded');
})();

// eslint-disable-next-line no-var
var Logger = globalThis.Logger || console;

/**
 * @purpose Puente de comunicación dual unificada entre la UI web y el backend nativo JUCE o la Web MIDI API.
 * @purpose_en Unified dual communication bridge between the web UI and the native JUCE backend or Web MIDI API.
 * @classification Network/Communication Infrastructure
 * @complexity Medium
 *
 * Methods have been extracted into separate modules loaded after this file:
 *   - bridge-dual_init.js:     init(), waitForReady(), setupJuceListeners()
 *   - bridge-dual_params.js:   setParameter(), readFactoryBankFile(),
 *                              handleParameterChangeFromBackend(),
 *                              onParameterChanged(), offParameterChanged()
 *   - bridge-sysex.js:         requestMidiDump, requestSysEx, _parseGlobalDump, etc.
 *   - bridge-midi-rx.js:       handleIncomingMidi, sendNRPN, _nrpn*, _applyMidiLearnMapping, etc.
 *   - bridge-connection.js:    initWebMidi, scanMidiDevices, pianoNoteOn/Off, panic,
 *                              isConnected, resetMidiConnection, startAutoReconnect, etc.
 *   - bridge-midi-learn.js:    toggleMidiLearn, startMidiLearn, stopMidiLearn, etc.
 *   - bridge-engines.js:       initArpEngine, initSeqEngine, _updateSeqEngine, etc.
 */
class DualMidiBridge {
    get isJuce() {
        return this._isJuce || !!(window.__JUCE__ && window.__JUCE__.backend);
    }
    set isJuce(val) {
        this._isJuce = val;
    }
    constructor() {
        this._isJuce = false;
        this.midiAccess = null;
        this.midiOutput = null;
        this.midiInput = null;
        this.midiChannel = 1; // Canal MIDI base (1-16)
        this.parameterCache = {};
        this._globalParams = {};
        this.onParameterChangedCallbacks = [];

        // Sistema de peticiones SysEx con timeout
        this._pendingSysExRequests = [];
        this._connected = false;

        // Variables de MIDI Learn
        this.midiLearnActive = false;
        this.midiLearnTargetParam = null;
        this.midiLearnPendingCC = null;
        this.midiLearnMappings = {};
        this.midiLearnChangeCallbacks = [];

        // Info de hardware capturada
        this._hardwareInfo = {
            hostVersion: '-',
            voiceVersion: '-',
            dspVersion: '-',
            bootVersion: '-',
            wifiVersion: '-',
            deviceId: '0',
            midiChannel: 1,
            connectionType: '-',
            globalDumpBytes: null  // Bytes crudos del Global Dump
        };

        // Cache de envío de NRPN
        this._lastNrpnMsb = null;
        this._lastNrpnLsb = null;
        this._lastNrpnValue = null;
        this._lastNrpnByte = null;

        // Estado NRPN entrante (para decode desde hardware)
        this._nrpnInMsb = null;      // último CC99 recibido
        this._nrpnInLsb = null;      // último CC98 recibido
        this._nrpnInDataMsb = 0;     // último CC6 recibido
        this._nrpnInTimestamp = 0;   // timestamp del último CC99/CC98

        // Tráfico NRPN
        this._nrpnTxBytes = 0;
        this._nrpnRxBytes = 0;
        this._nrpnPktCount = 0;
        this._nrpnTrafficCallbacks = [];

        // Estado de cambio de banco/programa para auto-dump
        this._lastBankSelectMSB = null;
        this._lastBankSelectLSB = null;
        this._lastProgramChange = null;
        this._autoDumpTimer = null;

        // Colección de bank dump
        this._bankDumpInProgress = false;
        this._bankDumpCallback = null;
        this._bankDumpCancel = false;
        this._bankDumpResolve = null;
        this._bankDumpTimeout = null;

        this.init();
    }

    // --- MAPAS DE PARÁMETROS ---
    get paramToByteOffset() {
        return window.BRIDGE_PARAM_MAPS ? window.BRIDGE_PARAM_MAPS.PARAM_TO_BYTE_OFFSET : {};
    }

    get byteOffsetToParamIds() {
        return window.BRIDGE_PARAM_MAPS ? window.BRIDGE_PARAM_MAPS.BYTE_OFFSET_TO_PARAM_IDS : {};
    }

    get paramToCC() {
        return window.BRIDGE_PARAM_MAPS ? window.BRIDGE_PARAM_MAPS.PARAM_TO_CC : {};
    }

    get ccToParam() {
        return window.BRIDGE_PARAM_MAPS ? window.BRIDGE_PARAM_MAPS.CC_TO_PARAM : {};
    }

    async init() {
        // NOTE: Do NOT overwrite window.juce — the bootstrap sets up the JUCE 8
        // compatibility shim with event-based native function wrappers.
        this._ready = false;
        this._readyPromise = new Promise((resolve) => {
            this._resolveReady = resolve;
        });

        // Expose bridge instance for bootstrap event callbacks
        window._bridgeInstance = this;

        // Helper: check if any JUCE native bridge is available
        const isJuceAvailable = () => !!(window.juce || window.__juce__ || window.__JUCE__);

        // Detectar si la URL o el UA sugieren entorno JUCE
        const isJuceHost = window.location.protocol === 'juce:' ||
                           (window.location.hostname === 'localhost' && window.location.port === '') ||
                           window.navigator.userAgent.includes('WebView') ||
                           window.navigator.userAgent.includes('Edge/');
        const maxAttempts = isJuceHost ? 150 : 5; // hasta 3 segundos en JUCE, 100ms en navegador normal

        // Esperar por JUCE native bridge de forma asíncrona
        for (let i = 0; i < maxAttempts; i++) {
            if (isJuceAvailable()) {
                Logger.log('[Bridge] JUCE native found after ' + (i * 20) + 'ms');
                break;
            }
            await new Promise(r => setTimeout(r, 20));
        }

        // Log final detection state for diagnostics
        Logger.log('[Bridge] Detection result: __juce__=' + typeof window.__juce__
            + ' __JUCE__=' + typeof window.__JUCE__
            + ' juce=' + typeof window.juce
            + ' chrome.webview=' + typeof (window.chrome && window.chrome.webview));

        // Detectar si estamos en el entorno embebido de JUCE (Webview2)
        if (isJuceAvailable()) {
            this.isJuce = true;
            this._connected = true;

            Logger.log('[Bridge] Entorno JUCE 8 detectado. Canal nativo activo.');
            this.setupJuceListeners();
            this._ready = true;
            this._resolveReady(true);
            // _updateConnectionUI is defined in bridge-connection.js (loaded after this file)
            if (typeof this._updateConnectionUI === 'function') {
                this._updateConnectionUI();
            }
        } else {
            Logger.log('[Bridge] Ejecución en Navegador Web detectada. Inicializando Web MIDI API...');
            if (typeof this.initWebMidi === 'function') {
                await this.initWebMidi();
            }
            this._ready = true;
            this._resolveReady(true);
        }
    }

    // --- RAW <-> NORMALIZED CONVERSIÓN ---
    _rawToNormalized(byteOffset, rawValue) {
        return window.BRIDGE_PARAM_MAPS ? window.BRIDGE_PARAM_MAPS.rawToNormalized(byteOffset, rawValue) : rawValue / 255.0;
    }

    _normalizedToRaw(byteOffset, normalizedValue) {
        return window.BRIDGE_PARAM_MAPS ? window.BRIDGE_PARAM_MAPS.normalizedToRaw(byteOffset, normalizedValue) : Math.round(normalizedValue * 255);
    }
}

// Exportar clase a globalThis para que los módulos IIFE (bridge-sysex.js, bridge-midi-rx.js, bridge-connection.js)
// puedan encontrar DualMidiBridge incluso en entornos module-scoped (tests con eval/require)
globalThis.DualMidiBridge = DualMidiBridge;

// Instancia Global
window.dualMidiBridge = new DualMidiBridge();

/**
 * @purpose DualMidiBridge init-related methods: waitForReady(), setupJuceListeners().
 * init() permanece como método de clase en bridge-dual.js porque se llama desde el constructor.
 * Extraído de bridge-dual.js para modularización.
 * @classification Module/Bridge/Init
 * @complexity Low
 */

(function() {
    if (typeof DualMidiBridge === 'undefined') {
        if (typeof console !== 'undefined') {console.warn('[Bridge-Init] DualMidiBridge not found — deferring...');}
        return;
    }

    const Logger = globalThis.Logger || console;

    DualMidiBridge.prototype.waitForReady = async function(timeoutMs) {
        if (timeoutMs === undefined) { timeoutMs = 10000; }
        if (this._ready) {return true;}
        try {
            await Promise.race([
                this._readyPromise,
                new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), timeoutMs))
            ]);
            return true;
        } catch (e) {
            Logger.warn('[Bridge] waitForReady timeout after ' + timeoutMs + 'ms — proceeding anyway');
            return false;
        }
    };

    DualMidiBridge.prototype.setupJuceListeners = function() {
        // JUCE 8 uses window.__JUCE__.backend.addEventListener for C++ → JS events.
        if (window.__JUCE__ && window.__JUCE__.backend) {
            window.__JUCE__.backend.addEventListener('onParameterChanged', (data) => {
                this.handleParameterChangeFromBackend(data.id, data.value);
            });
        }
        // Legacy fallback
        window.onJuceEvent = (name, data) => {
            if (name === 'onParameterChanged') {
                this.handleParameterChangeFromBackend(data.id, data.value);
            }
        };
    };

    Logger.log('[Bridge] Init module loaded');
})();

/**
 * @purpose DualMidiBridge parameter methods: setParameter(), readFactoryBankFile(),
 * handleParameterChangeFromBackend(), onParameterChanged(), offParameterChanged().
 * Extraído de bridge-dual.js para modularización.
 * @classification Module/Bridge/Params
 * @complexity Medium
 */

(function() {
    if (typeof DualMidiBridge === 'undefined') {
        if (typeof console !== 'undefined') {console.warn('[Bridge-Params] DualMidiBridge not found — deferring...');}
        return;
    }

    const Logger = globalThis.Logger || console;

    // --- ENVIAR PARÁMETRO (Hacia el Sinte / Hardware) ---
    DualMidiBridge.prototype.setParameter = function(paramId, normalizedValue, forceResend) {
        // Nivel 1: Evitar envío si el valor no cambia significativamente (excepto en carga forzada)
        const cached = this.parameterCache[paramId];
        if (!forceResend && cached !== undefined && Math.abs(cached - normalizedValue) < 0.001) {
            this.parameterCache[paramId] = normalizedValue;
            return;
        }

        this.parameterCache[paramId] = normalizedValue;

        if (this.isJuce) {
            if (window.juce && typeof window.juce.setParameter === 'function') {
                window.juce.setParameter(paramId, normalizedValue);
            }
            this.handleParameterChangeFromBackend(paramId, normalizedValue);
        } else {
            this.sendWebMidiParameter(paramId, normalizedValue);
            this.handleParameterChangeFromBackend(paramId, normalizedValue);
            if (window.wasmBridge) {
                window.wasmBridge.setParameter(paramId, normalizedValue);
            }
        }
    };

    DualMidiBridge.prototype.readFactoryBankFile = async function(letter) {
        if (this.isJuce) {
            if (window.juce && typeof window.juce.readFactoryBankFile === 'function') {
                return window.juce.readFactoryBankFile(letter);
            }
        }
        return null;
    };

    DualMidiBridge.prototype.handleParameterChangeFromBackend = function(paramId, normalizedValue) {
        this.parameterCache[paramId] = normalizedValue;
        this.onParameterChangedCallbacks.forEach(cb => cb(paramId, normalizedValue));
    };

    DualMidiBridge.prototype.onParameterChanged = function(callback) {
        this.onParameterChangedCallbacks.push(callback);
    };

    DualMidiBridge.prototype.offParameterChanged = function(callback) {
        const idx = this.onParameterChangedCallbacks.indexOf(callback);
        if (idx !== -1) {
            this.onParameterChangedCallbacks.splice(idx, 1);
        }
    };

    Logger.log('[Bridge] Params module loaded');
})();

/**
 * @purpose Motor initialization orchestrator for DualMidiBridge.
 * Arp engine → bridge-engines-arp.js (initArpEngine, _arpStep, _arpKillAllNotes)
 * Seq engine → bridge-engines-seq.js (initSeqEngine, _updateSeqEngine, _seqStep)
 * Param handlers → bridge-param-handlers.js
 */

/**
 * Modo de operación: el WebUI puede actuar como controlador del hardware
 * (deepmind_hw_controller) o como simulador local (deepmind_web_standalone /
 * abyssmind_pro). En modo controlador SOLO se reenvían parámetros al hardware:
 * el arp/seq/chord lo ejecuta la propia máquina, por lo que los motores locales
 * NO deben computar (si no, las secuencias se repetirían). En modo simulador,
 * el software es el que sonariza y los motores locales SÍ deben ejecutarse.
 */
DualMidiBridge.prototype._isSimulatorMode = function() {
    const w = globalThis.wasmBridge;
    if (!w || typeof w.getMode !== 'function') { return true; } // fallback: preserva comportamiento actual
    return w.getMode() !== 'deepmind_hw_controller';
};

// --- Inicialización de motores después de la creación del bridge ---
(function() {
    let _initAttempts = 0;
    const _maxInitAttempts = 200;
    const checkBridge = setInterval(function() {
        _initAttempts++;
        if (_initAttempts > _maxInitAttempts) {
            clearInterval(checkBridge);
            const Logger = globalThis.Logger || console;
            Logger.warn('[Bridge] Engine init timeout — bridge not available after 10s');
            return;
        }
        const bridge = window.dualMidiBridge;
        if (bridge && typeof bridge.startAutoReconnect === 'function') {
            clearInterval(checkBridge);

            bridge.startAutoReconnect();
            bridge.initArpEngine();
            bridge.initSeqEngine();

            if (typeof window._initChordMemory === 'function') {
                window._initChordMemory();
            }
            if (typeof window._initPolyChordNotes === 'function') {
                window._initPolyChordNotes();
            }

            if (typeof bridge.onParameterChanged === 'function') {
                bridge.onParameterChanged(function(paramId, val) {
                    if (typeof window._handleEngineParamChange === 'function') {
                        window._handleEngineParamChange(paramId, val, bridge);
                    }
                });
            }

            const Logger = globalThis.Logger || console;
            Logger.log('[Bridge] Engine initialization complete');
        }
    }, 50);
})();

/**
 * @purpose Arpeggiator engine for DualMidiBridge — extracted from bridge-engines.js IIFE 1.
 * Adds prototype methods: initArpEngine, _arpStep, _arpKillAllNotes.
 */

(function() {
    if (typeof DualMidiBridge === 'undefined') {
        const Logger = globalThis.Logger || console;
        Logger.warn('[Engines-Arp] DualMidiBridge not found — deferring...');
        return;
    }

    /** Initialize the arpeggiator engine. Call once. */
    DualMidiBridge.prototype.initArpEngine = function() {
        if (this._arpEngine) {return;}
        const self = this;
        this._arpEngine = {
            heldNotes: [],
            running: false,
            stepIndex: 0,
            timerId: null,
            currentDirection: 1,

            isRunning: function() {
                return this.running;
            },

            addHeldNote: function(note, velocity) {
                if (!self._isSimulatorMode()) {return;} // controlador: el arp lo ejecuta el hardware
                for (let i = 0; i < this.heldNotes.length; i++) {
                    if (this.heldNotes[i].note === note) {return;}
                }
                this.heldNotes.push({ note: note, velocity: velocity });
                this.heldNotes.sort(function(a, b) { return a.note - b.note; });
                if (!this.running && self.parameterCache['arp_enable'] > 0.5) {
                    this.start();
                }
            },

            removeHeldNote: function(note) {
                for (let i = 0; i < this.heldNotes.length; i++) {
                    if (this.heldNotes[i].note === note) {
                        this.heldNotes.splice(i, 1);
                        break;
                    }
                }
                if (this.heldNotes.length === 0) {
                    this.stop();
                }
            },

            start: function() {
                if (!self._isSimulatorMode()) {return;} // controlador: no crear timer local
                if (this.running || this.heldNotes.length === 0) {return;}
                this.running = true;
                this.stepIndex = 0;
                this.currentDirection = 1;
                const _self2 = this;
                const bpm = 20 + (self.parameterCache['arp_rate'] || 0.5) * 220;
                const rawClockDiv = self.parameterCache['arp_clock_divider'] !== undefined ? self.parameterCache['arp_clock_divider'] : 0;
                const clockIdx = Math.max(0, Math.min(12, Math.round(rawClockDiv * 12)));
                const stepsPerBeat = [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0, 8.0, 12.0, 16.0, 24.0][clockIdx] || 1.0;
                let intervalMs = (60000 / bpm) / stepsPerBeat;
                intervalMs = Math.max(20, Math.min(5000, intervalMs));
                this.intervalMs = intervalMs;

                this.timerId = setInterval(function() {
                    self._arpStep(self);
                }, intervalMs);
                const Logger = globalThis.Logger || console;
                Logger.log('[ArpEngine] Started at', Math.round(bpm), 'BPM, steps/beat', stepsPerBeat, 'interval', Math.round(intervalMs) + 'ms');
            },

            stop: function() {
                if (!this.running) {return;}
                this.running = false;
                if (this.timerId) {
                    clearInterval(this.timerId);
                    this.timerId = null;
                }
                self._arpKillAllNotes();
                const Logger = globalThis.Logger || console;
                Logger.log('[ArpEngine] Stopped');
            },

            updateTimer: function() {
                if (!this.running || !self._isSimulatorMode()) {return;}
                const _self2 = this;
                const bpm = 20 + (self.parameterCache['arp_rate'] || 0.5) * 220;
                const rawClockDiv = self.parameterCache['arp_clock_divider'] !== undefined ? self.parameterCache['arp_clock_divider'] : 0;
                const clockIdx = Math.max(0, Math.min(12, Math.round(rawClockDiv * 12)));
                const stepsPerBeat = [0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0, 8.0, 12.0, 16.0, 24.0][clockIdx] || 1.0;
                let intervalMs = (60000 / bpm) / stepsPerBeat;
                intervalMs = Math.max(20, Math.min(5000, intervalMs));

                if (Math.abs(intervalMs - this.intervalMs) > 2) {
                    this.intervalMs = intervalMs;
                    clearInterval(this.timerId);
