        'fx3_param8': 200, 'fx3_param9': 201, 'fx3_param10': 202, 'fx3_param11': 203, 'fx3_param12': 204,
        'fx4_type': 205, 'fx4_param1': 206, 'fx4_param2': 207, 'fx4_param3': 208,
        'fx4_param4': 209, 'fx4_param5': 210, 'fx4_param6': 211, 'fx4_param7': 212,
        'fx4_param8': 213, 'fx4_param9': 214, 'fx4_param10': 215, 'fx4_param11': 216, 'fx4_param12': 217,
        'fx1_gain': 218, 'fx2_gain': 219, 'fx3_gain': 220, 'fx4_gain': 221,
        'fx_mode': 222,
        'fx_feedback_gain': 223,
        'fx_send_level': 225,
        'vcf_model': 245,
        'vcf_moog_submode': 246,
        'vcf_korg_submode': 247
    };

    // Mapa: paramId → MIDI CC
    const PARAM_TO_CC = {
        'lfo1_rate': 16, 'lfo1_delay': 17,
        'osc1_pitch_mod': 20, 'osc1_pwm_amount': 21,
        'osc2_pitch_mod': 23, 'osc2_tone_mod': 24, 'osc2_pitch': 25, 'osc2_level': 26,
        'noise_level': 27,
        'global_portamento': 5,
        'vcf_cutoff': 29, 'vcf_resonance': 30, 'vcf_env_depth': 31,
        'vcf_lfo_depth': 33, 'vcf_key_tracking': 34, 'hpf_cutoff': 35,
        'vca_level': 36,
        'env1_attack': 37, 'env1_decay': 39, 'env1_sustain': 40, 'env1_release': 41,
        'env2_attack': 42, 'env2_decay': 43, 'env2_sustain': 44, 'env2_release': 45,
        'env3_attack': 46, 'env3_decay': 47, 'env3_sustain': 48, 'env3_release': 49,
        'unison_detune': 28,
        'arp_rate': 12, 'arp_gate_time': 13, 'arp_gate': 13,
        'global_volume': 7,
        'global_tune': 81,
        'transpose': 82
    };

    // Mapa inverso: byteOffset → [paramId, ...]
    function buildReverseMap() {
        const map = {};
        for (const paramId in PARAM_TO_BYTE_OFFSET) {
            if (PARAM_TO_BYTE_OFFSET.hasOwnProperty(paramId)) {
                const byteOff = PARAM_TO_BYTE_OFFSET[paramId];
                if (!map[byteOff]) {map[byteOff] = [];}
                if (map[byteOff].indexOf(paramId) === -1) {
                    map[byteOff].push(paramId);
                }
            }
        }
        return map;
    }

    const BYTE_OFFSET_TO_PARAM_IDS = buildReverseMap();

    function buildReverseCCMap() {
        const map = {};
        for (const paramId in PARAM_TO_CC) {
            if (PARAM_TO_CC.hasOwnProperty(paramId)) {
                map[PARAM_TO_CC[paramId]] = paramId;
            }
        }
        return map;
    }

    const CC_TO_PARAM = buildReverseCCMap();

    const ADVANCED_TO_HW_FALLBACK = {
        36: 29, // Roland BBD Chorus → Chorus-D
        37: 28, // Solina Ensemble → Stereo Chorus
        38: 32, // Ring Modulator → Mood Filter
        39: 25, // Space Echo RE-201 → T-RayDelay
        40: 22, // Analog Tape Delay → Delay
        41: 27, // Shimmer Delay → ModDlyRev
        42: 23, // Granular Delay → 3Tap Delay
        43: 24, // Pattern Freeze → 4Tap Delay
        44: 22, // Ducking Delay → Delay
        45: 25, // Spectral Dly → T-RayDelay
        46: 33, // Freq Shifter → Dual Pitch
        47: 32, // HarmonicReso → Mood Filter
        48: 32, // Combulator → Mood Filter
        49: 15  // MB Vocoder → Enhancer
    };

    return {
        BIPOLAR_BYTES: BIPOLAR_BYTES,
        ENUM_BYTES: ENUM_BYTES,
        PARAM_TO_BYTE_OFFSET: PARAM_TO_BYTE_OFFSET,
        PARAM_TO_CC: PARAM_TO_CC,
        BYTE_OFFSET_TO_PARAM_IDS: BYTE_OFFSET_TO_PARAM_IDS,
        CC_TO_PARAM: CC_TO_PARAM,
        ADVANCED_TO_HW_FALLBACK: ADVANCED_TO_HW_FALLBACK,

        /** Convierte valor raw (0-255) a normalized (0-1). Maneja bipolares y enums. */
        rawToNormalized: function(byteOffset, rawValue) {
            if (BIPOLAR_BYTES.has(byteOffset)) {
                return Math.max(0, Math.min(1, ((rawValue - 128) / 127.0 + 1) / 2));
            }
            if (ENUM_BYTES[byteOffset] !== undefined) {
                return Math.min(1, rawValue / ENUM_BYTES[byteOffset]);
            }
            return rawValue / 255.0;
        },

        /** Convierte valor normalized (0-1) a raw (0-255). Maneja bipolares y enums. */
        normalizedToRaw: function(byteOffset, normalizedValue) {
            if (BIPOLAR_BYTES.has(byteOffset)) {
                const val = ((normalizedValue * 2.0) - 1.0) * 127.0;
                return Math.round(val + 128);
            }
            if (ENUM_BYTES[byteOffset] !== undefined) {
                return Math.round(normalizedValue * ENUM_BYTES[byteOffset]);
            }
            return Math.round(normalizedValue * 255.0);
        }
    };
})();

/**
 * @purpose Core SysEx request protocol for DualMidiBridge: requestMidiDump and requestSysEx.
 * Global dump parsing, bank dump, and auto-dump handlers have been extracted
 * to bridge-sysex-handlers.js.
 * @classification Module/SysEx
 * @complexity Medium
 */

(function() {
    if (typeof DualMidiBridge === 'undefined') {
        console.warn('[Bridge-SysEx] DualMidiBridge not found — deferring...');
        return;
    }

    const Logger = globalThis.Logger || console;

    DualMidiBridge.prototype.requestMidiDump = async function(type, timeoutMs = 3000, retries = 2) {
        if (this.isJuce) {
            if (window.juce && typeof window.juce.requestMidiDump === 'function') {
                return window.juce.requestMidiDump(type);
            }
            return null;
        }

        if (!this.midiOutput || !this.midiInput) {
            Logger.warn('[SysEx] No MIDI ports available for dump request');
            return null;
        }

        let requestBytes = [];
        let dumpCommand = 0;
        const devId = parseInt(this._hardwareInfo.deviceId) || 0;

        if (type === 'edit') {
            requestBytes = [0xF0, 0x00, 0x20, 0x32, 0x20, devId & 0x0F, 0x03, 0xF7];
            dumpCommand = 0x04;
        } else if (type === 'global') {
            requestBytes = [0xF0, 0x00, 0x20, 0x32, 0x20, devId & 0x0F, 0x05, 0xF7];
            dumpCommand = 0x06;
        } else {
            Logger.warn('[SysEx] Unknown dump type: ' + type);
            return null;
        }

        const isDumpResponse = (msg) => {
            return msg.length >= 10 &&
                   msg[0] === 0xF0 &&
                   msg[1] === 0x00 &&
                   msg[2] === 0x20 &&
                   msg[3] === 0x32 &&
                   msg[6] === dumpCommand;
        };

        for (let attempt = 1; attempt <= Math.max(1, retries + 1); attempt++) {
            try {
                Logger.log('[SysEx] Solicitando dump ' + type + ' (intento ' + attempt + '/' + (retries + 1) + ') con timeout ' + timeoutMs + 'ms...');
                const response = await this.requestSysEx(requestBytes, timeoutMs, isDumpResponse);
                return response;
            } catch (err) {
                if (attempt <= retries) {
                    Logger.warn('[SysEx] Intento ' + attempt + ' falló, re-intentando en 500ms: ' + err.message);
                    await new Promise(r => setTimeout(r, 500));
                } else {
                    Logger.error('[SysEx] Todos los intentos fallaron para dump ' + type + ': ' + err.message);
                    return null;
                }
            }
        }
        return null;
    };


    DualMidiBridge.prototype.requestSysEx = async function(requestBytes, timeoutMs = 3000, predicate = null) {
        if (!this.midiOutput || !this.midiInput) {
            throw new Error('[SysEx] No MIDI port available');
        }

        return new Promise((resolve, reject) => {
            const start = Date.now();
            let timer = null;
            let disposed = false;

            const done = (err, msg) => {
                if (disposed) {return;}
                disposed = true;
                if (timer) {clearTimeout(timer);}
                this._pendingSysExRequests = this._pendingSysExRequests.filter(r => r !== entry);
                if (err) {return reject(err);}
                resolve(msg);
            };

            const entry = {
                predicate: predicate || (() => true),
                resolve: (msg) => done(null, msg),
                reject: (err) => done(err),
                timer: null
            };

            timer = setTimeout(() => {
                const elapsed = Date.now() - start;
                done(new Error('[SysEx] Timeout after ' + elapsed + 'ms waiting for response'), null);
            }, timeoutMs);

            entry.timer = timer;
            this._pendingSysExRequests.push(entry);

            this._signalMidiActivity();
            this.midiOutput.send(requestBytes);
        });
    };

    DualMidiBridge.prototype.sendPatchToHardware = function(patch) {
        if (!patch) { return false; }
        if (typeof window.inspectPatchAdvancedFeatures === 'function') {
            const check = window.inspectPatchAdvancedFeatures(patch);
            if (check.isAdvanced) {
                Logger.warn('[SysEx] Bloqueado envío de preset Pro a hardware DM12:', check.reasons);
                const lcdUpdate = window.lcdSafeUpdate || function() {};
                lcdUpdate('⚠️ PRO PATCH: CANNOT SEND TO DM12 HW');
                alert(
                    `⚠️ No se puede enviar el preset "${patch.name || 'Pro'}" al sintetizador físico DeepMind 12 por incluir funciones Pro:\n\n` +
                    `- ${check.reasons.join('\n- ')}\n\n` +
                    'Utiliza "Convert to Classic DM12" para exportar o transmitir una versión compatible.'
                );
                return false;
            }
        }
        if (this.midiOutput && patch.unpackedBytes) {
            const syxMsg = window.buildSingleSysex ? window.buildSingleSysex(patch) : patch.unpackedBytes;
            this.midiOutput.send(syxMsg);
            return true;
        }
        return false;
    };

    Logger.log('[Bridge] SysEx core module loaded');
})();

/**
 * @purpose SysEx dump + settings handlers fachada para DualMidiBridge.
 * Los handlers están divididos en:
 *   - bridge-sysex-handlers-dump.js: requestBankDump, cancelBankDump, _scheduleAutoDump
 *   - bridge-sysex-handlers-settings.js: _parseGlobalDump, sendGlobalDump, getGlobalParameter, setGlobalParameter
 * @classification Module/SysEx
 * @complexity Low (Fachada)
 */

(function() {
    if (typeof DualMidiBridge === 'undefined') {
        console.warn('[Bridge-SysEx-Handlers] DualMidiBridge not found — deferring...');
        return;
    }

    const Logger = globalThis.Logger || console;
    Logger.log('[Bridge] SysEx handlers module loaded');
})();

/**
 * @purpose SysEx bank dump + auto-dump handlers for DualMidiBridge.
 * Extraído de bridge-sysex-handlers.js.
 */

(function() {
    if (typeof DualMidiBridge === 'undefined') {
        console.warn('[Bridge-SysEx-Dump] DualMidiBridge not found — deferring...');
        return;
    }

    const Logger = globalThis.Logger || console;

    DualMidiBridge.prototype.requestBankDump = async function(bankNumber, options = {}) {
        if (this.isJuce) {
            return window.juce && typeof window.juce.requestBankDump === 'function'
                ? window.juce.requestBankDump(bankNumber)
                : 0;
        }

        if (!this.midiOutput) {
            Logger.warn('[BankDump] No MIDI output available');
            return 0;
        }

        const { patchSpacingMs = 35, timeoutMs = 45000, onProgress = null } = options;

        if (this._bankDumpInProgress) {
            throw new Error('[BankDump] A bank dump is already in progress');
        }

        const bankIndex = typeof bankNumber === 'string'
            ? bankNumber.toUpperCase().charCodeAt(0) - 65
            : bankNumber;
        if (bankIndex < 0 || bankIndex > 7) {
            throw new Error('[BankDump] Invalid bank number: ' + bankNumber);
        }

        this._bankDumpInProgress = true;
        this._bankDumpCancel = false;
        let collectedCount = 0;
        const bankLetter = String.fromCharCode(65 + bankIndex);

        Logger.log('[BankDump] Solicitando banco ' + bankLetter + ' (' + bankIndex + ') — 128 programas');

        try {
            const result = await new Promise((resolve) => {
                this._bankDumpResolve = resolve;

                const bankDumpTimeout = setTimeout(() => {
                    this._bankDumpInProgress = false;
                    this._bankDumpCallback = null;
                    this._bankDumpTimeout = null;
                    Logger.warn('[BankDump] Timeout: recogidos ' + collectedCount + '/128 patches');
                    resolve(collectedCount);
                }, timeoutMs);
                this._bankDumpTimeout = bankDumpTimeout;

                this._bankDumpCallback = (_patchData) => {
                    if (this._bankDumpCancel) {return;}
                    collectedCount++;
                    if (onProgress) {onProgress(collectedCount, 128);}
                    if (collectedCount >= 128) {
                        clearTimeout(bankDumpTimeout);
                        this._bankDumpTimeout = null;
                        this._bankDumpInProgress = false;
                        this._bankDumpCallback = null;
                        this._bankDumpResolve = null;
                        Logger.log('[BankDump] Banco ' + bankLetter + ' completo: 128/128 patches recibidos');
                        resolve(128);
                    }
                };

                for (let i = 0; i < 128; i++) {
                    setTimeout(() => {
                        if (this._bankDumpCancel || !this._bankDumpInProgress) {return;}
                        const req = new Uint8Array([
                            0xF0, 0x00, 0x20, 0x32, 0x20,
                            0x7F, // broadcast device ID
                            0x01, // Program Dump Request
                            bankIndex,
                            i,
                            0xF7
                        ]);
                        this._signalMidiActivity();
                        this.midiOutput.send(req);
                    }, i * patchSpacingMs);
                }
            });

            return result;
        } catch (err) {
            this._bankDumpInProgress = false;
            this._bankDumpCallback = null;
            Logger.error('[BankDump] Error:', err.message);
            throw err;
        }
    };


    DualMidiBridge.prototype.cancelBankDump = function() {
        if (!this._bankDumpInProgress) {return;}
        this._bankDumpCancel = true;
        this._bankDumpInProgress = false;
        this._bankDumpCallback = null;
        if (this._bankDumpTimeout) {
            clearTimeout(this._bankDumpTimeout);
            this._bankDumpTimeout = null;
        }
        if (this._bankDumpResolve) {
            this._bankDumpResolve(0);
            this._bankDumpResolve = null;
        }
        Logger.log('[BankDump] Cancelado por el usuario');
    };


    DualMidiBridge.prototype._scheduleAutoDump = function() {
        if (this._autoDumpTimer) {clearTimeout(this._autoDumpTimer);}
        this._autoDumpTimer = setTimeout(() => {
            if (!this.midiOutput || !this.midiInput) {return;}
            Logger.log('[Bridge] Auto-dump triggered by Bank/Program change → requesting edit buffer dump');
            if (typeof this.requestMidiDump === 'function') {
                this.requestMidiDump('edit', 4000, 1).then((response) => {
                    if (!response) {
                        Logger.warn('[Bridge] Auto-dump failed — no response from hardware');
                    }
                }).catch((err) => {
                    Logger.warn('[Bridge] Auto-dump error:', err.message || err);
                });
            }
        }, 200);
    };


    Logger.log('[Bridge] SysEx dump handlers module loaded');
})();

/**
 * @purpose Global parameter and settings handlers for DualMidiBridge.
 * Extraído de bridge-sysex-handlers.js.
 */

(function() {
    if (typeof DualMidiBridge === 'undefined') {
        console.warn('[Bridge-SysEx-Settings] DualMidiBridge not found — deferring...');
        return;
    }

    const Logger = globalThis.Logger || console;

    DualMidiBridge.prototype._parseGlobalDump = function(dump) {
        if (!dump || dump.length < 15) {return;}

        let payload = [];
        for (let i = 8; i < dump.length - 1; i++) {
            payload.push(dump[i]);
        }

        // Unpack payload if unpack7to8 is available
        if (typeof window.unpack7to8 === 'function') {
            try {
                const unpacked = window.unpack7to8(new Uint8Array(payload));
                payload = Array.from(unpacked);
            } catch (e) {
                Logger.warn('[Bridge] Error unpacking global dump:', e);
            }
        }

        this._hardwareInfo.globalDumpBytes = payload;

        if (payload.length >= 3) {
            const ch = payload[0] & 0x0F;
            if (ch >= 0 && ch <= 15) {
                this._hardwareInfo.midiChannel = ch + 1;
            }
            const devId = (payload[0] >> 4) & 0x0F;
            if (devId >= 0 && devId <= 15) {
                this._hardwareInfo.deviceId = String(devId);
            }

            const tuneVal = payload[1];
            const transpRaw = Math.min(payload[2], 96);
            const velCurveRaw = payload.length > 3 ? Math.min(payload[3], 4) : 0;
            const pedalRaw = payload.length > 4 ? payload[4] : 0;
            const contrastRaw = payload.length > 5 ? Math.min(payload[5], 14) : 10;

            const globals = this._globalParams || {};

            // Preserve localStorage values over hardware Global Dump
            // User settings from Settings modal should take priority
            const lsTune = typeof localStorage !== 'undefined' ? localStorage.getItem('abd-eep-master-tune') : null;
            const lsTranspose = typeof localStorage !== 'undefined' ? localStorage.getItem('abd-eep-transpose') : null;

            globals['global_tune'] = lsTune !== null ? globals['global_tune'] : tuneVal / 255.0;
            globals['transpose'] = lsTranspose !== null ? globals['transpose'] : transpRaw / 96.0;
            globals['velocity_curve'] = velCurveRaw / 4.0;
            globals['pedal_polarity'] = pedalRaw > 0 ? 1.0 : 0.0;
            globals['lcd_contrast'] = contrastRaw / 14.0;
            this._globalParams = globals;

            if (this.parameterCache) {
                this.parameterCache['global_tune'] = lsTune !== null ? this.parameterCache['global_tune'] : tuneVal / 255.0;
                this.parameterCache['transpose'] = lsTranspose !== null ? this.parameterCache['transpose'] : transpRaw / 96.0;
                this.parameterCache['velocity_curve'] = velCurveRaw / 4.0;
                this.parameterCache['pedal_polarity'] = pedalRaw > 0 ? 1.0 : 0.0;
                this.parameterCache['lcd_contrast'] = contrastRaw / 14.0;
            }
        }
    };


    DualMidiBridge.prototype.sendGlobalDump = function(payloadBytes) {
        if (!this.midiOutput || !payloadBytes || payloadBytes.length < 3) {return;}

        const devId = parseInt(this._hardwareInfo.deviceId) || 0;
        const msg = new Uint8Array(8 + payloadBytes.length + 1);
        msg[0] = 0xF0;
        msg[1] = 0x00;
        msg[2] = 0x20;
        msg[3] = 0x32;
        msg[4] = 0x20;
        msg[5] = devId & 0x0F;
        msg[6] = 0x06;
        msg[7] = 0x06;

        for (let i = 0; i < payloadBytes.length; i++) {
            msg[8 + i] = payloadBytes[i];
        }
        msg[msg.length - 1] = 0xF7;

        this._signalMidiActivity();
        this.midiOutput.send(msg);
        Logger.log('[Bridge] Global Dump escrito vía SysEx (' + payloadBytes.length + ' bytes, devId=' + devId + ')');
    };


    DualMidiBridge.prototype.getGlobalParameter = function(paramId) {
        if (this._globalParams && paramId in this._globalParams) {
            return this._globalParams[paramId];
        }
        return this.parameterCache[paramId];
    };


    DualMidiBridge.prototype.setGlobalParameter = function(paramId, normalizedValue) {
        if (this._globalParams) {
            this._globalParams[paramId] = normalizedValue;
        }
        this.parameterCache[paramId] = normalizedValue;
        this.handleParameterChangeFromBackend(paramId, normalizedValue);

        let raw8Bit = -1;
        let byteOffset = -1;
        if (paramId === 'device_id') {
            const devId = Math.round(normalizedValue * 15);
            if (this._hardwareInfo && this._hardwareInfo.globalDumpBytes) {
                const cached = this._hardwareInfo.globalDumpBytes;
                const ch = (cached[0] & 0x0F);
                const bytes = new Uint8Array(cached);
                bytes[0] = ((devId & 0x0F) << 4) | ch;
                this.sendGlobalDump(Array.from(bytes));
            }
            return;
        } else if (paramId === 'global_tune') {
            raw8Bit = Math.round(normalizedValue * 255);
            byteOffset = 1;
        } else if (paramId === 'transpose') {
            raw8Bit = Math.round(normalizedValue * 96);
            byteOffset = 2;
        } else if (paramId === 'velocity_curve') {
            raw8Bit = Math.round(normalizedValue * 4);
            byteOffset = 3;
        } else if (paramId === 'pedal_polarity') {
            raw8Bit = normalizedValue > 0.5 ? 1 : 0;
            byteOffset = 4;
        } else if (paramId === 'lcd_contrast') {
            raw8Bit = Math.round(normalizedValue * 14);
            byteOffset = 5;
        }

        if (byteOffset >= 0 && this._hardwareInfo && this._hardwareInfo.globalDumpBytes) {
            const cached = this._hardwareInfo.globalDumpBytes;
            if (cached && cached.length > byteOffset) {
                const bytes = new Uint8Array(cached);
                bytes[byteOffset] = Math.min(255, Math.max(0, raw8Bit));
                this.sendGlobalDump(Array.from(bytes));
                return;
            }
        }

        if (this.isJuce) {
            if (window.juce && typeof window.juce.setParameter === 'function') {
                window.juce.setParameter(paramId, normalizedValue);
            }
        } else {
            this.sendWebMidiParameter(paramId, normalizedValue);
        }
    };


    Logger.log('[Bridge] SysEx settings handlers module loaded');
})();

/**
 * @purpose Fachada del Bank Manager. Inicializa la UI del gestor de bancos dual
 * (hardware + local). Las funciones de renderizado están en browser_render.js,
 * los modales/menús en browser_modals.js, y las operaciones CRUD/SysEx en browser_events.js.
 * Carga secuencial vía script tags.
 */

document.addEventListener('DOMContentLoaded', () => {
    initBankManager();
});

function initBankManager() {
    if (typeof window.loadAllFactoryBanksNatively === 'function') {
        window.loadAllFactoryBanksNatively();
    }

    const browserModal = document.getElementById('browser-modal-backdrop');

    const showBrowser = () => {
        if (browserModal) {
            browserModal.style.display = 'flex';
            window.updateLocalBanksDropdown();
            window.renderPatchesForBank(window.currentActiveBank);
            window.renderHardwarePatches();
        }
    };

    document.addEventListener('click', (e) => {
        if (e.target.closest('#menu-bank-manager')) {
            e.preventDefault();
            showBrowser();
        }
    });

    const progMngrBtn = document.getElementById('programmer-bank-mngr-btn');
    if (progMngrBtn) {progMngrBtn.addEventListener('click', showBrowser);}

    const closeBtn = document.getElementById('browser-close-btn');
    if (closeBtn) {closeBtn.addEventListener('click', () => browserModal.style.display = 'none');}

    const patchUpBtn = document.getElementById('programmer-patch-up-btn');
    if (patchUpBtn) {patchUpBtn.addEventListener('click', () => {
        if (typeof window.playKeyLedAnimation === 'function') {window.playKeyLedAnimation('patch-up');}
        window.navigatePatch(-1);
    });}
    const patchDownBtn = document.getElementById('programmer-patch-down-btn');
    if (patchDownBtn) {patchDownBtn.addEventListener('click', () => {
        if (typeof window.playKeyLedAnimation === 'function') {window.playKeyLedAnimation('patch-down');}
        window.navigatePatch(+1);
    });}

    window._currentCategoryFilter = '';
    window._browserViewMode = 'list';

    const localSelect = document.getElementById('local-bank-select');
    if (localSelect) {
        localSelect.addEventListener('change', function(e) {
            window.currentActiveBank = e.target.value;
            window.currentActivePatchIndex = 0;
            const searchInput = document.getElementById('browser-search-input');
            if (searchInput) {searchInput.value = '';}
            window.renderPatchesForBank(window.currentActiveBank);
        });
    }

    const searchInput = document.getElementById('browser-search-input');
    const searchClear = document.getElementById('browser-search-clear');

    function applySearch() {
        const term = searchInput ? searchInput.value : '';
        window.renderPatchesForBank(window.currentActiveBank, term);
    }

    if (searchInput) {searchInput.addEventListener('input', applySearch);}
    if (searchClear) {
        searchClear.addEventListener('click', function() {
            if (searchInput) {searchInput.value = '';}
            applySearch();
            if (searchInput) {searchInput.focus();}
        });
    }

    const catFilters = document.querySelectorAll('.cat-filter');
    catFilters.forEach(function(el) {
        el.addEventListener('click', function() {
            const cat = this.getAttribute('data-cat');
            window._currentCategoryFilter = cat;
            catFilters.forEach(function(c) { c.classList.remove('active'); });
            this.classList.add('active');
            window.renderPatchesForBank(window.currentActiveBank, searchInput ? searchInput.value : '');
        });
    });

    const viewToggle = document.getElementById('browser-view-toggle');
    if (viewToggle) {
        viewToggle.addEventListener('click', function() {
            if (window._browserViewMode === 'list') {
                window._browserViewMode = 'grid';
                this.textContent = '☰';
                this.title = 'Switch to list view';
            } else {
                window._browserViewMode = 'list';
                this.textContent = '⊞';
                this.title = 'Switch to grid view';
            }
            window.renderPatchesForBank(window.currentActiveBank, searchInput ? searchInput.value : '');
        });
    }

    const hwLetters = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'];
    hwLetters.forEach((l, i) => {
        const btn = document.getElementById('hw-bank-' + l + '-btn');
        if (btn) {
            btn.classList.add('hw-bank-btn');
            if (i === 0) {btn.classList.add('is-active');}
            btn.addEventListener('click', () => {
                window.currentHwBankLetter = l.toUpperCase();
                document.querySelectorAll('.hw-bank-btn').forEach(b => b.classList.remove('is-active'));
                btn.classList.add('is-active');
                window.renderHardwarePatches();
            });
        }
    });

    // Bank CRUD buttons
    const createBankBtn = document.getElementById('mngr-create-bank');
    if (createBankBtn) {createBankBtn.addEventListener('click', window._handleBankCreate);}

    const renameBankBtn = document.getElementById('mngr-rename-bank');
    if (renameBankBtn) {renameBankBtn.addEventListener('click', window._handleBankRename);}

    const deleteBankBtn = document.getElementById('mngr-delete-bank');
    if (deleteBankBtn) {deleteBankBtn.addEventListener('click', window._handleBankDelete);}

    const pasteSysexBtn = document.getElementById('mngr-paste-sysex');
    if (pasteSysexBtn) {pasteSysexBtn.addEventListener('click', window._handlePasteSysex);}

    // Export patch button
    if (typeof window._initExportPatchButton === 'function') {
        window._initExportPatchButton();
    }

    // SysEx drop zone
    if (typeof window._initSysexDropZone === 'function') {
        window._initSysexDropZone(browserModal);
    }

    // HW/Local load buttons
    const hwLoadBtn = document.getElementById('hw-load-btn');
    if (hwLoadBtn) {
        hwLoadBtn.addEventListener('click', function() { window._handleHWLoad(browserModal); });
    }

    const localLoadBtn = document.getElementById('local-load-btn');
    if (localLoadBtn) {
        localLoadBtn.addEventListener('click', function() { window._handleLocalLoad(browserModal); });
    }
}
window.initBankManager = initBankManager;

/**
 * @purpose Event handlers for Bank Manager: bank CRUD, SysEx import/export, HW/Local load, drop zone.
 * Extraído de browser.js para modularización.
 * @classification Module/Browser/Events
 * @complexity Medium
 */

window._handleBankCreate = function() {
    const name = prompt('Escribe el nombre del nuevo banco local:', 'User Bank ' + (Object.keys(window.loadedBanks).length - 7));
    if (!name || name.trim() === '' || window.loadedBanks[name]) {return;}
    window.loadedBanks[name] = window.createEmptyBank();
    window.currentActiveBank = name;
    window.updateLocalBanksDropdown();
    window.renderPatchesForBank(window.currentActiveBank);
    if (typeof window._saveUserBanksToStorage === 'function') {window._saveUserBanksToStorage();}
};

window._handleBankRename = function() {
    if (window.FACTORY_BANKS_LIST.includes(window.currentActiveBank)) {return alert('No se pueden renombrar bancos de fábrica.');}
    const newName = prompt('Escribe el nuevo nombre para "' + window.currentActiveBank + '":', window.currentActiveBank);
    if (!newName || newName.trim() === '' || window.loadedBanks[newName]) {return;}
    window.loadedBanks[newName] = window.loadedBanks[window.currentActiveBank];
    delete window.loadedBanks[window.currentActiveBank];
    window.currentActiveBank = newName;
    window.updateLocalBanksDropdown();
    window.renderPatchesForBank(window.currentActiveBank);
    if (typeof window._saveUserBanksToStorage === 'function') {window._saveUserBanksToStorage();}
};

window._handleBankDelete = function() {
    if (window.FACTORY_BANKS_LIST.includes(window.currentActiveBank)) {return alert('No se pueden borrar bancos de fábrica.');}
    if (confirm('¿Borrar banco local "' + window.currentActiveBank + '"?')) {
        delete window.loadedBanks[window.currentActiveBank];
        window.currentActiveBank = Object.keys(window.loadedBanks)[0];
        window.updateLocalBanksDropdown();
        window.renderPatchesForBank(window.currentActiveBank);
        if (typeof window._saveUserBanksToStorage === 'function') {window._saveUserBanksToStorage();}
    }
};

window._handlePasteSysex = function() {
    if (window.FACTORY_BANKS_LIST.includes(window.currentActiveBank)) {
        return alert('No está permitido pegar SysEx en bancos de fábrica.');
    }
    if (typeof window.pasteSysexFromClipboard === 'function') {
        window.pasteSysexFromClipboard(window.currentActiveBank, window.currentActivePatchIndex);
    }
};

window._initExportPatchButton = function() {
    const localToolbar = document.querySelector('.dual-bank-panel:last-child .flex-row.border-bottom');
    if (!localToolbar || document.getElementById('local-export-patch-btn')) {return;}
    const exportPatchBtn = document.createElement('button');
    exportPatchBtn.id = 'local-export-patch-btn';
    exportPatchBtn.className = 'manager-btn patch-export-btn';
    exportPatchBtn.setAttribute('data-ctrl-tooltip', 'Export current patch as standalone SysEx file (.syx)');
    exportPatchBtn.textContent = 'Export Patch';
    exportPatchBtn.addEventListener('click', function() {
        const bank = window.loadedBanks[window.currentActiveBank];
        if (!bank || window.currentActivePatchIndex < 0) {alert('Select a patch first.'); return;}
        const patch = bank[window.currentActivePatchIndex];
        if (typeof window.exportSinglePatch === 'function') {
            window.exportSinglePatch(patch, (window.currentActivePatchIndex + 1).toString().padStart(3, '0') + '_' + patch.name.replace(/[^a-zA-Z0-9_\\-]/g, '_') + '.syx');
        }
    });
    localToolbar.appendChild(exportPatchBtn);
};

window._handleHWLoad = function(browserModal) {
    if (window.currentHwPatchIndex === -1) {alert('Selecciona primero un slot de la rejilla de Hardware.'); return;}
    const patch = window.hardwareBanks[window.currentHwBankLetter][window.currentHwPatchIndex];
    if (patch && patch.unpackedBytes) {
        if (typeof window.triggerMidiDump === 'function') {window.triggerMidiDump(patch);}
        const lcdText = document.getElementById('lcd-text');
        if (lcdText) {lcdText.innerHTML = '<span class="lcd-label">LOADED FROM SYNTH</span><br><strong>' + patch.name.toUpperCase() + '</strong>';}
        if (browserModal) {browserModal.style.display = 'none';}
    }
};

window._handleLocalLoad = function(browserModal) {
    if (window.currentActivePatchIndex === -1) {alert('Selecciona primero un slot de la rejilla Local.'); return;}
    const patch = window.loadedBanks[window.currentActiveBank][window.currentActivePatchIndex];
    if (patch && patch.unpackedBytes) {
        if (typeof window.triggerMidiDump === 'function') {window.triggerMidiDump(patch);}
        const lcdText = document.getElementById('lcd-text');
        if (lcdText) {lcdText.innerHTML = '<span class="lcd-label">LOADED FROM LIBRARY</span><br><strong>' + patch.name.toUpperCase() + '</strong>';}
        if (browserModal) {browserModal.style.display = 'none';}
    }
};

window._initSysexDropZone = function(browserModal) {
    if (!browserModal) {return;}
    browserModal.addEventListener('dragover', function(e) {
        e.preventDefault(); e.stopPropagation();
        browserModal.style.outline = '2px dashed var(--accent-primary, #ff9900)';
        browserModal.style.outlineOffset = '-10px';
    });
    browserModal.addEventListener('dragleave', function(e) {
        e.preventDefault(); e.stopPropagation();
        browserModal.style.outline = ''; browserModal.style.outlineOffset = '';
    });
    browserModal.addEventListener('drop', function(e) {
        e.preventDefault(); e.stopPropagation();
        browserModal.style.outline = ''; browserModal.style.outlineOffset = '';
        const files = e.dataTransfer.files;
        if (!files || files.length === 0) {return;}
        const file = files[0];
        if (!file.name.toLowerCase().endsWith('.syx')) {alert('Solo se admiten archivos .syx (SysEx).'); return;}
        const reader = new FileReader();
        reader.onload = function(ev) {
            const bytes = new Uint8Array(ev.target.result);
            if (typeof window.parseSyxFile !== 'function') {return;}
            const parsed = window.parseSyxFile(bytes);
            if (parsed.patches.length === 0) {alert('SysEx inválido o archivo vacío.'); return;}
            if (parsed.isSinglePatch) {
                const patch = parsed.patches[0];
                const bank = window.loadedBanks[window.currentActiveBank];
                if (bank && bank[window.currentActivePatchIndex]) {
                    const confirmed = confirm('Drop SysEx: "' + patch.name + '"\n¿Cargar en el slot actual ' + (window.currentActivePatchIndex + 1) + '?');
                    if (confirmed) {
                        bank[window.currentActivePatchIndex].name = patch.name;
                        bank[window.currentActivePatchIndex].unpackedBytes = new Uint8Array(patch.unpackedBytes);
                        bank[window.currentActivePatchIndex].meta = patch.meta ? JSON.parse(JSON.stringify(patch.meta)) : window.createDefaultMeta();
                        if (typeof window.triggerMidiDump === 'function') {window.triggerMidiDump(bank[window.currentActivePatchIndex]);}
                        window.renderPatchesForBank(window.currentActiveBank);
                        if (typeof window._saveUserBanksToStorage === 'function') {window._saveUserBanksToStorage();}
                    }
                }
            } else {
                const bankName = file.name.replace(/\.[^/.]+$/, '');
                if (confirm('Drop bank "' + bankName + '" con ' + parsed.patches.length + ' patches. ¿Importar?')) {
                    window.loadedBanks[bankName] = parsed.patches;
                    window.currentActiveBank = bankName;
                    window.updateLocalBanksDropdown();
                    window.renderPatchesForBank(window.currentActiveBank);
                    if (typeof window._saveUserBanksToStorage === 'function') {window._saveUserBanksToStorage();}
                }
            }
        };
        reader.readAsArrayBuffer(file);
    });
};

