var Logger = globalThis.Logger || console;

/**
 * @purpose Fachada de browser I/O: bank loading y paste logic.
 *   - loadAllFactoryBanksNatively  → browser_io_load.js
 *   - pasteSysexFromClipboard      → browser_io_paste.js
 *   - parseSysexText, parseSysexBytes, parseSyxFile  → browser_io_parse.js
 *   - exportSinglePatch, exportBankJson  → browser_io_parse_export.js, browser_io_export.js
 */

document.addEventListener('DOMContentLoaded', function() {
    if (typeof window._wireBrowserIOEvents === 'function') {
        window._wireBrowserIOEvents();
    }
});

/**
 * @purpose Import/export/IO event handlers for bank operations — extracted from browser_io.js.
 * Handles: SysEx file import, bank export, hardware dump, fetch bank progress UI.
 */

// ── Fetch Bank progress UI helpers ──

let _fetchBankCancel = false;
let _fetchBankProgress = 0;
let _fetchBankTotal = 128;

function _updateFetchProgress() {
    const lcdText = document.getElementById('lcd-text');
    const fetchBtn = document.getElementById('hw-fetch-from-synth');
    if (!lcdText) {return;}
    const pct = Math.round(_fetchBankProgress / _fetchBankTotal * 100);
    const barLen = Math.round(_fetchBankProgress / _fetchBankTotal * 20);
    const bar = '\u2588'.repeat(barLen) + '\u2591'.repeat(20 - barLen);
    const html = '<span class="lcd-sub-sm op-60">FETCHING BANK ' + window.currentHwBankLetter + '</span><br>'
        + '<strong class="lcd-sub">' + _fetchBankProgress + '/' + _fetchBankTotal + '</strong><br>'
        + '<span class="lcd-sub-sm lcd-color-blue fetch-progress-bar">' + bar + ' ' + pct + '%</span>';
    window.lcdSafeUpdate(lcdText, html);
    if (fetchBtn) {
        fetchBtn.textContent = 'Fetching ' + _fetchBankProgress + '/' + _fetchBankTotal + '...';
        fetchBtn.classList.add('is-loading');
    }
}

function _onFetchComplete() {
    const lcdText = document.getElementById('lcd-text');
    const fetchBtn = document.getElementById('hw-fetch-from-synth');
    if (lcdText) {
        const html = '<span class="lcd-label">FETCH COMPLETE</span><br>'
            + '<strong class="lcd-color-green">BANK ' + window.currentHwBankLetter + ' READY</strong>';
        window.lcdSafeUpdate(lcdText, html);
    }
    if (fetchBtn) {
        fetchBtn.textContent = 'Fetch Bank';
        fetchBtn.classList.remove('is-loading');
    }
    if (typeof window.renderHardwarePatches === 'function') {window.renderHardwarePatches();}
    _fetchBankCancel = false;
}

/** Wire all browser I/O event handlers (fetch, dump, import, export) */
window._wireBrowserIOEvents = function() {
    // ── Fetch Bank ──
    const fetchHwBtn = document.getElementById('hw-fetch-from-synth');
    if (fetchHwBtn) {
        fetchHwBtn.addEventListener('click', async () => {
            if (!window.dualMidiBridge || !window.dualMidiBridge.midiOutput) {
                alert('Conexi\u00F3n MIDI no disponible. Aseg\u00FArate de configurar los puertos en Settings.');
                return;
            }

            if (window.dualMidiBridge._bankDumpInProgress) {
                window.dualMidiBridge.cancelBankDump();
                fetchHwBtn.textContent = 'Fetch Bank';
                fetchHwBtn.classList.remove('is-loading');
                const lcd = document.getElementById('lcd-text');
                if (lcd) {lcd.innerText = 'FETCH CANCELLED';}
                _fetchBankProgress = 0;
                return;
            }

            _fetchBankCancel = false;
            _fetchBankProgress = 0;
            _fetchBankTotal = 128;

            try {
                const count = await window.dualMidiBridge.requestBankDump(window.currentHwBankLetter, {
                    patchSpacingMs: 35,
                    timeoutMs: 45000,
                    onProgress: (received, total) => {
                        _fetchBankProgress = received;
                        _fetchBankTotal = total;
                        _updateFetchProgress();
                        if (received >= total) {
                            _onFetchComplete();
                        }
                    }
                });

                if (count > 0 && count < 128) {
                    const lcdText = document.getElementById('lcd-text');
                    if (lcdText) {
                        const html = '<span class="lcd-sub-sm op-60">FETCH TIMEOUT</span><br>'
                            + '<strong class="lcd-color-orange">RECEIVED ' + count + '/128</strong>';
                        window.lcdSafeUpdate(lcdText, html);
                    }
                    fetchHwBtn.textContent = 'Fetch Bank (' + count + '/' + 128 + ')';
                    fetchHwBtn.classList.add('is-loading');
                }
            } catch (err) {
                const Logger = globalThis.Logger || console;
                Logger.error('[BankDump] Error fetching bank:', err);
                const lcdText = document.getElementById('lcd-text');
                if (lcdText) {lcdText.innerText = 'FETCH ERROR: ' + err.message;}
                fetchHwBtn.textContent = 'Fetch Bank';
                fetchHwBtn.classList.remove('is-loading');
            }
        });
    }

    // ── Dump to Hardware ──
    const dumpHwBtn = document.getElementById('hw-dump-to-synth');
    if (dumpHwBtn) {
        dumpHwBtn.addEventListener('click', () => {
            if (!window.dualMidiBridge || !window.dualMidiBridge.midiOutput) {
                alert('Conexi\u00F3n MIDI no disponible. Aseg\u00FArate de configurar los puertos en Settings.');
                return;
            }

            if (!confirm(`\u00BFEst\u00E1s seguro de que deseas sobrescribir el banco ${window.currentHwBankLetter} completo en el sintetizador f\u00EDsico?`)) {
                return;
            }

            if (typeof window._dumpBankToHw === 'function') {
                window._dumpBankToHw(window.currentHwBankLetter, window.hardwareBanks[window.currentHwBankLetter], {
                    onComplete: function() {
                        const lcdText = document.getElementById('lcd-text');
                        if (lcdText) {lcdText.innerText = 'DUMP COMPLETED';}
                    }
                });
            }
        });
    }

    // ── Import .syx File ──
    const loadInput = document.createElement('input');
    loadInput.type = 'file';
    loadInput.accept = '.syx';
    loadInput.classList.add('hidden');
    document.body.appendChild(loadInput);

    const importBtn = document.getElementById('mngr-import-sysex');
    if (importBtn) {importBtn.addEventListener('click', function() { loadInput.click(); });}

    loadInput.addEventListener('change', function(e) {
        const file = e.target.files[0];
        if (!file) {return;}
        const reader = new FileReader();
        reader.onload = function(ev) {
            const bytes = new Uint8Array(ev.target.result);
            const parsed = parseSyxFile(bytes);

            if (typeof window._handleImportSyxResult === 'function') {
                window._handleImportSyxResult(parsed, file.name, {
                    onPatchImported: function(patch) {
                        const lcdText = document.getElementById('lcd-text');
                        if (lcdText) {
                            lcdText.innerHTML = '<span class="lcd-label">IMPORTED SINGLE PATCH</span><br>'
                                + '<strong class="lcd-color-green">' + patch.name.toUpperCase() + '</strong><br>'
                                + '<span class="lcd-sub-sm">' + (window.currentActivePatchIndex + 1) + ' of ' + window.currentActiveBank + '</span>';
                        }
                    },
                    onBankCreated: function(name) {
                        const lcdText = document.getElementById('lcd-text');
                        if (lcdText) {
                            lcdText.innerHTML = '<span class="lcd-label">IMPORTED BANK</span><br>'
                                + '<strong class="lcd-color-green">' + parsed.patches.length + ' PATCHES</strong><br>'
                                + '<span class="lcd-sub-sm">' + name.toUpperCase() + '</span>';
                        }
                    }
                });
            }
        };
        reader.readAsArrayBuffer(file);
        loadInput.value = '';
    });

    // ── Export Bank as .syx ──
    const exportBtn = document.getElementById('mngr-export-sysex');
    if (exportBtn) {
        exportBtn.addEventListener('click', () => {
            const patches = window.loadedBanks[window.currentActiveBank];
            const outputBytes = window._buildBankSysex(patches);
            const blob = new Blob([outputBytes], { type: 'application/octet-stream' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = window.currentActiveBank + '.syx';
            link.click();
            setTimeout(() => URL.revokeObjectURL(link.href), 5000);
        });
    }

    window._exportCurrentBankAsSyx = function() {
        const exportBtn = document.getElementById('mngr-export-sysex');
        if (exportBtn) {exportBtn.click();}
    };
};

/**
 * @purpose Bank loading logic extracted from browser_io.js.
 * Contains loadAllFactoryBanksNatively() — loads 8 factory banks (A-H),
 * user banks from localStorage, and injects the Developer Calibration bank.
 *
 * @depends browser_persistence.js (createEmptyBank, _loadUserBanksFromStorage)
 * @depends browser_io_parse.js (parseSysexText, parseSysexBytes)
 */

/**
 * Load all 8 factory banks (A-H) from JUCE native file system or HTTP fetch fallback.
 * Then load user banks from localStorage and inject the Factory Dev Calib bank.
 */
async function loadAllFactoryBanksNatively() {
    if (window.dualMidiBridge && typeof window.dualMidiBridge.waitForReady === 'function') {
        await window.dualMidiBridge.waitForReady(2000);
    }
    const letters = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];

    const loadSingleBank = async (letter) => {
        const bankName = 'Factory Bank ' + letter;
        window.loadedBanks[bankName] = window.createEmptyBank();

        let bytes = null;
        if (window.dualMidiBridge && window.dualMidiBridge.isJuce) {
            try {
                const hexStr = await window.dualMidiBridge.readFactoryBankFile(letter);
                if (hexStr && typeof hexStr === 'string' && hexStr.length > 0) {
                    const cleanHex = hexStr.replace(/\s/g, '');
                    bytes = new Uint8Array(cleanHex.match(/.{1,2}/g).map(function(byte) { return parseInt(byte, 16); }));
                }
            } catch (err) {
                Logger.warn('[BankManager] Error cargando banco nativo ' + letter + ', intentando fetch...', err);
            }
        }

        if (!bytes) {
            try {
                const response = await fetch('./resources/Banks/Factory%20Banks%20V1.1.2/Synth%20Bank%20' + letter + '.syx');
                if (response.ok) {
                    const arrayBuffer = await response.arrayBuffer();
                    bytes = new Uint8Array(arrayBuffer);
                }
            } catch (err) {
                Logger.error('[BankManager] Error en fetch de banco de fabrica ' + letter, err);
            }
        }

        if (bytes && bytes.length >= 291) {
            const patchSize = 291;
            const numPatches = Math.floor(bytes.length / patchSize);
            for (let i = 0; i < Math.min(128, numPatches); i++) {
                const offset = i * patchSize;
                const packedPayload = bytes.slice(offset + 10, offset + 288);
                const unpackedBytes = window.unpack7to8(packedPayload);

                const patchName = window.extractNameFromRawSysex(bytes, offset) || ('Factory Patch ' + (i + 1));
                window.loadedBanks[bankName][i] = {
                    index: i,
                    name: patchName,
                    unpackedBytes: unpackedBytes,
                    meta: window.createDefaultMeta()
                };
            }
        } else {
            Logger.error('[BankManager] Error: No hay bytes de datos válidos para el banco ' + bankName + '. Total bytes:', bytes ? bytes.length : 0);
        }
    };

    // 1. Cargar Banco A inmediatamente para mostrar la interfaz sin retardo
    await loadSingleBank('A');
    if (typeof window.updateLocalBanksDropdown === 'function') {
        window.updateLocalBanksDropdown();
    }

    // 2. Cargar Bancos B-H en paralelo en segundo plano
    Promise.all(letters.slice(1).map(loadSingleBank)).then(() => {
        if (typeof window.updateLocalBanksDropdown === 'function') {
            window.updateLocalBanksDropdown();
        }
    });

    const userBanksLoaded = window._loadUserBanksFromStorage();
    if (!userBanksLoaded) {
        window.loadedBanks['User Bank 1'] = window.createEmptyBank();
    }

    // ── Inject Developer Calibration Bank ──
    const calibBankName = 'Factory Dev Calib';
    window.loadedBanks[calibBankName] = window.createEmptyBank();

    const createCalibTemplate = function(name) {
        const b = new Uint8Array(242);
        const paddedName = name.padEnd(16, ' ');
        for (let ci = 0; ci < 16; ci++) {
            b[ci] = paddedName.charCodeAt(ci);
        }
        b[14] = 1;   // osc1_range = 8'
        b[19] = 1;   // osc1_saw_enable = true
        b[39] = 255; // vcf_cutoff = 100% open
        b[53] = 1;   // env1_attack = flat/immediate
        b[54] = 255; // env1_decay = max
        b[55] = 255; // env1_sustain = 100%
        b[56] = 20;  // env1_release = short natural
        b[62] = 1;   // env2_attack = flat
        b[63] = 255; // env2_decay = max
        b[64] = 255; // env2_sustain = 100%
        b[65] = 20;  // env2_release = short natural
        b[80] = 204; // vca_level = 80%
        return b;
    };

    const calibPresets = [
        { name: 'CALIB_OSC1_SAW',   setup: function(b) {} },
        { name: 'CALIB_OSC1_SQR',   setup: function(b) { b[19] = 0; b[18] = 1; } },
        { name: 'CALIB_OSC2_SQR',   setup: function(b) { b[19] = 0; b[26] = 255; b[28] = 128; } },
        { name: 'CALIB_OSC_DUAL',   setup: function(b) { b[19] = 1; b[26] = 192; } },
        { name: 'CALIB_OSC_SYNC',   setup: function(b) { b[19] = 1; b[26] = 192; b[20] = 1; } },
        { name: 'CALIB_LPF_25',     setup: function(b) { b[39] = 64; } },
        { name: 'CALIB_LPF_RES',    setup: function(b) { b[39] = 128; b[41] = 179; } },
        { name: 'CALIB_HPF_50',     setup: function(b) { b[40] = 128; } },
        { name: 'CALIB_HPF_BOOST',  setup: function(b) { b[40] = 0; b[52] = 1; } },
        { name: 'CALIB_ENV_AMP',    setup: function(b) { b[53] = 10; b[54] = 128; b[55] = 76; b[56] = 128; } },
        { name: 'CALIB_ENV_FLT',    setup: function(b) { b[39] = 64; b[42] = 128; b[62] = 10; b[63] = 180; b[64] = 0; b[65] = 128; } },
        { name: 'CALIB_VCA_BALLS',  setup: function(b) { b[80] = 255; } }
    ];

    for (let pi = 0; pi < 128; pi++) {
let presetBytes;
let presetName;
        if (pi < calibPresets.length) {
            presetName = calibPresets[pi].name;
            presetBytes = createCalibTemplate(presetName);
            calibPresets[pi].setup(presetBytes);
        } else {
            presetName = 'Init Patch ' + (pi + 1);
            presetBytes = createCalibTemplate(presetName);
            presetBytes[19] = 0;
        }
        window.loadedBanks[calibBankName][pi] = {
            index: pi,
            name: presetName,
            unpackedBytes: presetBytes,
            meta: window.createDefaultMeta()
        };
    }

    window.currentActiveBank = 'Factory Bank A';
