        helpers.setSelectedPatch('A', bankName, firstValid.index);
      } else {
        window.calibrationStore.setSelectedPatchA(null);
      }
    };
  }

  if (slotAEl) {
    slotAEl.onchange = () => {
      helpers.setSelectedPatch('A', bankAEl.value, Number(slotAEl.value));
    };
  }

  if (bankBEl) {
    bankBEl.onchange = () => {
      const bankName = bankBEl.value;
      const slotOptions = helpers.buildSlotOptions(bankName);
      const firstValid = slotOptions.find((x) => !x.disabled);
      if (firstValid) {
        helpers.setSelectedPatch('B', bankName, firstValid.index);
      } else {
        window.calibrationStore.setSelectedPatchB(null);
      }
    };
  }

  if (slotBEl) {
    slotBEl.onchange = () => {
      helpers.setSelectedPatch('B', bankBEl.value, Number(slotBEl.value));
    };
  }

  if (useCurrentAEl) {
    useCurrentAEl.onclick = () => helpers.setFromCurrent('A');
  }

  if (useCurrentBEl) {
    useCurrentBEl.onclick = () => helpers.setFromCurrent('B');
  }

  const swapBtn = this.querySelector('#cal-swap-ab');
  if (swapBtn) {
    swapBtn.onclick = () => {
      window.calibrationStore?.swapPatches();
    };
  }
};

CalibrationLabPage.prototype.applySharedFilters = function (rows, projector) {
  const store = window.calibrationStore;
  const state = store.getState();
  const search = (state.filters.search || '').trim().toLowerCase();

  return rows.filter((row) => {
    if (state.filters.showOnlyDifferences && !row.changed) {return false;}
    if (!search) {return true;}
    const hay = projector(row).toLowerCase();
    return hay.includes(search);
  });
};

/**
 * @purpose Calibration Lab render orchestrator and export button updater.
 * Extracted from calibration_lab_page.js render() and _updateExportButtons().
 * Takes pageEl (CalibrationLabPage instance) as first parameter.
 */

window._renderCalibrationLab = function(pageEl) {
    const store = window.calibrationStore;
    if (!store || !pageEl.panelEl) {return;}

    const state = store.getState();

    pageEl.tabButtons.forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.calTab === state.activeTab);
    });

    if (pageEl.voiceSelectEl) {
      pageEl.voiceSelectEl.value = String(state.selectedVoiceIndex ?? 0);
    }

    if (pageEl.searchInputEl && pageEl.searchInputEl.value !== state.filters.search) {
      pageEl.searchInputEl.value = state.filters.search || '';
    }

    if (pageEl.filterDiffEl) {pageEl.filterDiffEl.checked = !!state.filters.showOnlyDifferences;}
    if (pageEl.filterCriticalEl) {pageEl.filterCriticalEl.checked = !!state.filters.showOnlyCritical;}
    if (pageEl.filterAliasesEl) {pageEl.filterAliasesEl.checked = !!state.filters.showOnlyAliases;}

    if (pageEl.statusEl) {
      pageEl.statusEl.textContent =
        state.snapshotStatus === 'ready'
          ? `Snapshot ready · ${state.lastUpdatedAt || 'n/a'}`
          : state.snapshotStatus === 'loading'
          ? 'Loading diagnostic snapshot...'
          : state.snapshotStatus === 'error'
          ? `Error: ${state.snapshotError || 'unknown'}`
          : 'Idle';
    }

    if (pageEl.pickerMountEl && window.CalibrationPatchPickerHelpers) {
      pageEl.pickerMountEl.innerHTML = pageEl.renderPatchPickerBar();
      pageEl.bindPatchPickerEvents();
    }

    // CL-03: Summary cards — siempre visibles, reflejan patch A/B activos
    if (pageEl.summaryMountEl) {
      pageEl.summaryMountEl.innerHTML = renderSummaryCards(store);
    }

    let tabHtml;
    if (state.activeTab === 'patchdiff') {
      tabHtml = pageEl.renderPatchDiffTab(store);
    } else if (state.activeTab === 'raw') {
      tabHtml = pageEl.renderRawTab(store);
    } else if (state.activeTab === 'semantic') {
      tabHtml = pageEl.renderSemanticTab(store);
    } else if (state.activeTab === 'engine') {
      tabHtml = pageEl.renderEngineTab(store);
    } else if (state.activeTab === 'audio-ab') {
      tabHtml = pageEl.renderAudioABTab(store);
    } else if (state.activeTab === 'roundtrip') {
      tabHtml = pageEl.renderRoundTripTab(store);
    } else if (state.activeTab === 'live') {
      tabHtml = pageEl.renderLiveValidationTab(store);
    } else {
      tabHtml = pageEl.renderEffectiveTab(store);
    }

    // CL-07: Panel dividido tabla + drawer cuando hay fila seleccionada
    const drawerHtml = state.selectedRowKey ? pageEl.renderDrawer(store) : '';
    pageEl.panelEl.innerHTML = `
      <div class="cal-panel-split${state.selectedRowKey ? ' has-drawer' : ''}">
        <div class="cal-panel-main">${tabHtml}</div>
        ${drawerHtml ? `<div class="cal-panel-drawer">${drawerHtml}</div>` : ''}
      </div>
    `;
    pageEl.bindDrawerEvents();

    if (state.activeTab === 'audio-ab') {
      pageEl.bindAudioABEvents();
    } else if (state.activeTab === 'roundtrip') {
      pageEl.bindRoundTripEvents();
    } else if (state.activeTab === 'live') {
      pageEl.bindLiveValidationEvents();
    }

    // CL-08d: Bank Run list
    if (pageEl.runListMountEl) {
      pageEl.runListMountEl.innerHTML = pageEl.renderBankRunList(store);
      pageEl.bindBankRunListEvents();
    }

    // CL-09: Workflow drawer
    if (pageEl.workflowMountEl) {
      pageEl.workflowMountEl.innerHTML = pageEl.renderWorkflowDrawer(store);
      pageEl.bindWorkflowEvents();
    }

    // CL-10: Export buttons enabled/disabled
    if (typeof window._updateCalibrationExportButtons === 'function') {
      window._updateCalibrationExportButtons(pageEl, state);
    }
};

window._updateCalibrationExportButtons = function(pageEl, state) {
    const hasRun = state.bankRunItems && state.bankRunItems.length > 0;
    if (pageEl.exportJsonBtn) {pageEl.exportJsonBtn.disabled = !hasRun;}
    if (pageEl.exportCsvBtn) {pageEl.exportCsvBtn.disabled = !hasRun;}
    if (pageEl.exportPdfBtn) {pageEl.exportPdfBtn.disabled = !hasRun;}
    if (pageEl.exportSyxBtn) {
      const store = window.calibrationStore;
      const item = store ? store.getCurrentWorkflowItem() : null;
      pageEl.exportSyxBtn.disabled = !item || !Array.isArray(item?.patchRef?.unpackedBytes);
    }
};

/**
 * @purpose Facade for Audio A/B Validation tab. Actual implementation in:
 *          - calibration_lab_tab_audioab_render.js  (renderAudioABTab)
 *          - calibration_lab_tab_audioab_events.js  (bindAudioABEvents)
 * @classification Module/Calibration/Tab/Facade
 */

// CalibrationLabPage prototype methods are attached by the sub-module files above.
// This facade ensures the namespace exists and maintains backward compatibility.

/**
 * @purpose Audio A/B Validation tab event handlers: binds click handlers for
 *          Start, Render, Finish, Compare, and Abort buttons.
 * @classification Module/Calibration/Tab
 * @dependencies calibration_lab_page.js (defines CalibrationLabPage)
 */

CalibrationLabPage.prototype.bindAudioABEvents = function () {
  const self = this;
  const startBtn = this.querySelector('#audio-btn-start');
  const renderBtn = this.querySelector('#audio-btn-render');
  const finishBtn = this.querySelector('#audio-btn-finish');
  const compareBtn = this.querySelector('#audio-btn-compare');
  const abortBtn = this.querySelector('#audio-btn-abort');

  function addLog(msg) {
    const time = new Date().toTimeString().split(' ')[0];
    self._audioLogs = self._audioLogs || [];
    self._audioLogs.push({ time: time, msg: msg });
    const state = window.calibrationStore;
    if (state) { self.render(); }
  }

  if (startBtn) {
    startBtn.onclick = async function () {
      const store = window.calibrationStore;
      if (!store) { return; }
      const st = store.getState();
      const patchName = (st.selectedPatchA && st.selectedPatchA.name) || 'Active Patch';

      const config = {
        runId: 'audio-ab-' + Date.now(),
        patchName: patchName,
        midiNote: parseInt((self.querySelector('#audio-note-input') && self.querySelector('#audio-note-input').value) || '48', 10),
        velocity: parseInt((self.querySelector('#audio-vel-input') && self.querySelector('#audio-vel-input').value) || '100', 10),
        noteDurationSec: parseFloat((self.querySelector('#audio-dur-input') && self.querySelector('#audio-dur-input').value) || '2.0'),
        tailDurationSec: 0.5,
        sampleRate: 44100.0,
        bitDepth: 24,
        numChannels: 2
      };

      const patchSnapshotJson = JSON.stringify(st.selectedPatchA || {});

      addLog('Iniciando Audio A/B Run: ' + config.runId);
      const res = window.dualMidiBridge && (await window.dualMidiBridge.startAudioABRun(JSON.stringify(config), patchSnapshotJson));
      if (res && res.ok) {
        self._audioStatus = 'running';
        self._comparisonResult = null;
        addLog('Grabador de hardware activo. Capturando se\u00f1al de audio f\u00edsica...');
      } else {
        self._audioStatus = 'error';
        addLog('Error al iniciar run: ' + ((res && res.error) || 'unknown'));
      }
    };
  }

  if (renderBtn) {
    renderBtn.onclick = async function () {
      addLog('Renderizando referencia software del SynthEngine...');
      const res = window.dualMidiBridge && (await window.dualMidiBridge.renderAudioABSoftwareReference());
      if (res && res.ok) {
        addLog('Referencia de software renderizada correctamente en buffer local.');
      } else {
        addLog('Error al renderizar software: ' + ((res && res.error) || 'unknown'));
      }
    };
  }

  if (finishBtn) {
    finishBtn.onclick = async function () {
      addLog('Finalizando run y exportando archivos a disco...');
      const res = window.dualMidiBridge && (await window.dualMidiBridge.finishAudioABRun());
      if (res && res.ok) {
        self._audioStatus = 'finished';
        self._hwWavPath = res.hwWavPath;
        self._swWavPath = res.swWavPath;
        self._lastRunId = res.runId;
        addLog('Run finalizado con \u00e9xito: ' + res.runId);
        addLog('Manifest: ' + res.manifestPath);
        addLog('WAV Hardware: ' + res.hwWavPath + ' (Peak: ' + res.hwPeak + 'dB, RMS: ' + res.hwRms + 'dB)');
        addLog('WAV Software: ' + res.swWavPath + ' (Peak: ' + res.swPeak + 'dB, RMS: ' + res.swRms + 'dB)');
      } else {
        self._audioStatus = 'error';
        addLog('Error al finalizar run: ' + ((res && res.error) || 'unknown'));
      }
    };
  }

  if (compareBtn) {
    compareBtn.onclick = async function () {
      addLog('Ejecutando algoritmo de alineaci\u00f3n y comparaci\u00f3n ac\u00fastica...');

      const store = window.calibrationStore;
      const st = store && store.getState();
      const patchName = (st && st.selectedPatchA && st.selectedPatchA.name) || 'Active Patch';

      const configJson = JSON.stringify({
        trimLeadingSilence: true,
        trimTrailingSilence: true,
        silenceThresholdDb: -72.0,
        normalizeGain: false,
        forceMonoForAnalysis: true,
        enableCrossCorrelation: true,
        maxAlignmentOffsetSamples: 8192,
        fftSize: 1024
      });

      const contextJson = JSON.stringify({
        runId: self._lastRunId || ('audio-ab-' + Date.now()),
        presetId: (st && st.selectedPatchA && st.selectedPatchA.uuid) || 'active',
        presetName: patchName
      });

      const res = window.dualMidiBridge && (await window.dualMidiBridge.compareAudioABRun(
        self._swWavPath || '',
        self._hwWavPath || '',
        configJson,
        contextJson
      ));

      if (res) {
        self._comparisonResult = res;
        if (res.status === 'error') {
          self._audioStatus = 'error';
          addLog('Error contractual en comparador: ' + res.reason_code);
        } else {
          const level = (res.verdict && res.verdict.level) || 'unknown';
          self._audioStatus = level === 'pass' ? 'passed' : 'failed';
          addLog('Comparaci\u00f3n ac\u00fastica finalizada. Veredicto: ' + level.toUpperCase());
          if (res.verdict && res.verdict.triggered_rules && res.verdict.triggered_rules.length) {
            res.verdict.triggered_rules.forEach(function (rule) { addLog(' Regla disparada: ' + rule); });
          }
        }
      } else {
        addLog('Error cr\u00edtico al despachar compareAudioABRun nativo.');
      }
    };
  }

  if (abortBtn) {
    abortBtn.onclick = async function () {
      addLog('Abortando run actual...');
      if (window.dualMidiBridge) { await window.dualMidiBridge.abortAudioABRun(); }
      self._audioStatus = 'idle';
      self._comparisonResult = null;
      addLog('Run abortado.');
    };
  }
};

/**
 * @purpose Audio A/B Validation tab renderer: generates HTML for the Audio A/B
 *          calibration tab including inputs, buttons, status, and comparison verdict.
 * @classification Module/Calibration/Tab
 * @dependencies calibration_lab_page.js (defines CalibrationLabPage)
 */

CalibrationLabPage.prototype.renderAudioABTab = function (store) {
  const state = store.getState();
  const patchName = (state.selectedPatchA && state.selectedPatchA.name) || 'Active Patch';

  this._audioStatus = this._audioStatus || 'idle';
  this._audioLogs = this._audioLogs || [];
  this._comparisonResult = this._comparisonResult || null;

  const formatLogs = function () {
    return this._audioLogs.map(function (l) { return '[' + l.time + '] ' + l.msg; }).join('\n');
  }.bind(this);

  let comparisonHtml = '';
  if (this._comparisonResult) {
    const comp = this._comparisonResult;
    const isErr = comp.status === 'error';
    const level = (comp.verdict && comp.verdict.level) || 'unknown';
    const levelColor = level === 'pass' ? '#2ecc71' : level === 'warn' ? '#f1c40f' : '#e74c3c';

    if (isErr) {
      comparisonHtml = '<div class="cal-audio-error">' +
        '<div class="cal-audio-error-title">COMPARISON ERROR</div>' +
        '<div class="cal-audio-error-reason">Reason: ' + comp.reason_code + '</div>' +
        '<div class="cal-audio-error-list">' +
        (comp.errors || []).map(function (e) { return '\u2022 ' + e; }).join('<br/>') +
        '</div></div>';
    } else {
      comparisonHtml = _buildComparisonVerdictHtml(comp, level, levelColor);
    }
  }

  return [
    '<div class="cal-audio-tab">',
    '  <h4 class="cal-audio-title">Audio A/B Validation (Fase 5C)</h4>',
    '  <p class="cal-audio-desc">Esta pestaña permite disparar la calibración acústica nativa. Configura los parámetros del tono de prueba, inicia el grabador para capturar la entrada física del hardware y renderiza el motor software de referencia.</p>',
    '  <div class="cal-audio-inputs">',
    '    <div class="cal-audio-input-group">',
    '      <label class="cal-audio-label">Midi Note</label>',
    '      <input id="audio-note-input" class="modal-input cal-input-full" type="number" value="48" min="0" max="127" />',
    '    </div>',
    '    <div class="cal-audio-input-group">',
    '      <label class="cal-audio-label">Velocity</label>',
    '      <input id="audio-vel-input" class="modal-input cal-input-full" type="number" value="100" min="1" max="127" />',
    '    </div>',
    '    <div class="cal-audio-input-group">',
    '      <label class="cal-audio-label">Duration (Sec)</label>',
    '      <input id="audio-dur-input" class="modal-input cal-input-full" type="number" value="2.0" step="0.5" min="0.5" />',
    '    </div>',
    '  </div>',
    '  <div class="cal-audio-buttons">',
    '    <button id="audio-btn-start" class="manager-btn btn-solid" type="button" ' + (this._audioStatus === 'running' ? 'disabled' : '') + '>1. Start Capturing Hardware</button>',
    '    <button id="audio-btn-render" class="manager-btn" type="button" ' + (this._audioStatus !== 'running' ? 'disabled' : '') + '>2. Render Software Reference</button>',
    '    <button id="audio-btn-finish" class="manager-btn" type="button" ' + (this._audioStatus !== 'running' ? 'disabled' : '') + '>3. Finish &amp; Export Run</button>',
    '    <button id="audio-btn-compare" class="manager-btn btn-accent" type="button" ' + ((this._audioStatus !== 'finished' && this._audioStatus !== 'compared' && this._audioStatus !== 'failed' && this._audioStatus !== 'passed') ? 'disabled' : '') + '>4. Run Acoustical Comparison</button>',
    '    <button id="audio-btn-abort" class="manager-btn ' + (this._audioStatus === 'running' ? '' : 'hidden') + '" type="button" ' + (this._audioStatus !== 'running' ? 'disabled' : '') + '>Abort</button>',
    '  </div>',
    '  <div class="cal-audio-status-col">',
    '    <div class="cal-audio-status-row">',
    '      <span>Current Status: <strong class="text-accent text-uppercase">' + this._audioStatus + '</strong></span>',
    '      <span>Target Patch: <strong class="text-primary">' + escapeHtml(patchName) + '</strong></span>',
    '    </div>',
    comparisonHtml,
    '    <label class="cal-audio-logs-label">Console Logs / Export manifest details</label>',
    '    <textarea readonly class="modal-input cal-audio-logs" rows="7">' + (escapeHtml(formatLogs()) || 'Idle - Awaiting run') + '</textarea>',
    '  </div>',
    '</div>'
  ].join('\n');
};

/** @private Builds comparison verdict HTML block */
function _buildComparisonVerdictHtml(comp, level, levelColor) {
  let html = '<div class="cal-audio-verdict">';
  html += '<div class="cal-audio-verdict-header">';
  html += '<span class="cal-audio-verdict-title">Acoustical Verdict</span>';
  html += '<span class="cal-audio-verdict-badge" style="--cal-badge-bg: ' + levelColor + ';">';
  html += level + ' (' + (comp.verdict.reason_code || 'n/a') + ')';
  html += '</span></div>';

  if (comp.verdict.triggered_rules && comp.verdict.triggered_rules.length) {
    html += '<div class="cal-audio-warning-box"><strong>Triggered Warnings/Failures:</strong><br/>';
    html += comp.verdict.triggered_rules.map(function (r) { return '\u2022 ' + r; }).join('<br/>');
    html += '</div>';
  }

  html += '<div class="cal-audio-metrics">';
  html += '<div class="cal-audio-metric-col">';
  html += '<strong class="cal-audio-section-label">Temporal Metrics</strong><br/>';
  html += 'Peak Delta: <strong>' + _fmtDb(comp.time_metrics, 'peak_delta_db') + ' dB</strong><br/>';
  html += 'RMS Delta: <strong>' + _fmtDb(comp.time_metrics, 'rms_delta_db') + ' dB</strong><br/>';
  html += 'Residual RMS: <strong>' + _fmtDbfs(comp.time_metrics, 'residual_rms_dbfs') + ' dBFS</strong><br/>';
  html += 'RMSE: <strong>' + _fmtNum(comp.time_metrics, 'rmse', 4) + '</strong>';
  html += '</div>';
  html += '<div class="cal-audio-metric-col">';
  html += '<strong class="cal-audio-section-label">Alignment</strong><br/>';
  html += 'Offset: <strong>' + (comp.alignment ? comp.alignment.sample_offset : '?') + ' samples</strong> (' + _fmtMs(comp.alignment) + ' ms)<br/>';
  html += 'Correlation Peak: <strong>' + _fmtNum(comp.alignment, 'correlation_peak', 4) + '</strong><br/>';
  html += 'Overlap Ratio: <strong>' + _fmtPct(comp.alignment) + '%</strong>';
  html += '</div></div>';

  html += '<div class="cal-audio-spectral">';
  html += '<strong class="cal-audio-section-label">Spectral Magnitude Delta</strong><br/>';
  html += 'Mean Abs Diff: <strong>' + _fmtDb(comp.spectral_metrics, 'log_mag_mean_abs_diff_db') + ' dB</strong><br/>';
  html += '<span class="cal-audio-spectral-dim">';
  html += 'Low: <strong>' + _fmtDb(comp.spectral_metrics, 'low_band_delta_db') + ' dB</strong> | ';
  html += 'Mid: <strong>' + _fmtDb(comp.spectral_metrics, 'mid_band_delta_db') + ' dB</strong> | ';
  html += 'High: <strong>' + _fmtDb(comp.spectral_metrics, 'high_band_delta_db') + ' dB</strong>';
  html += '</span></div></div>';

  return html;
}

/** @private */
function _fmtDb(obj, key) {
  return (obj && obj[key] != null) ? obj[key].toFixed(2) : '?';
}
/** @private */
function _fmtDbfs(obj, key) {
  return (obj && obj[key] != null) ? obj[key].toFixed(1) : '?';
}
/** @private */
function _fmtNum(obj, key, decimals) {
  return (obj && obj[key] != null) ? obj[key].toFixed(decimals || 2) : '?';
}
/** @private */
function _fmtMs(alignment) {
  return (alignment && alignment.time_offset_ms != null) ? alignment.time_offset_ms.toFixed(2) : '?';
}
/** @private */
function _fmtPct(alignment) {
  return (alignment && alignment.overlap_ratio != null) ? (alignment.overlap_ratio * 100).toFixed(1) : '?';
}

// WebUI/js/calibration_lab_tab_diff.js — PatchDiff, Raw, Semantic comparison tabs for CalibrationLabPage
// Extracted from calibration_lab_tabs.js

CalibrationLabPage.prototype.renderPatchDiffTab = function (store) {
  const state = store.getState();
  let rows = collectPatchDiffRows(store);

  if (state.filters.showOnlyAliases) {
    rows = rows.filter(r => r.isAlias);
  }

  if (state.filters.showOnlyDifferences) {
    rows = rows.filter(r => r.changed);
  }

  const search = (state.filters.search || '').trim().toLowerCase();
  if (search) {
    rows = rows.filter(r =>
      String(r.offset).includes(search) ||
      r.region.toLowerCase().includes(search) ||
      r.paramIds.some(p => p.toLowerCase().includes(search))
    );
  }

  const html = rows.map(row => {
    const rowKey = 'pd-' + row.offset;
    const isSelected = state.selectedRowKey === rowKey;
    return `
      <tr class="cal-row cal-row-cursor${row.changed ? ' is-changed' : ''}${isSelected ? ' is-selected' : ''}" data-row-key="${rowKey}">
        <td><span class="cal-badge cal-badge-region">${escapeHtml(row.region)}</span></td>
        <td class="mono">${row.offset}</td>
        <td class="mono cal-rt-table-param">${escapeHtml(row.paramIds.join(', ') || '—')}</td>
        <td class="mono${row.changed ? ' is-delta' : ''}">${fmt(row.rawA, 0)}</td>
        <td class="mono${row.changed ? ' is-delta' : ''}">${fmt(row.rawB, 0)}</td>
        <td class="mono${row.delta !== 0 ? ' is-delta' : ''}">${row.delta !== null ? (row.delta > 0 ? '+' : '') + row.delta : '—'}</td>
        <td class="cal-patchdiff-semantic">${escapeHtml(row.semanticA)}</td>
        <td class="cal-patchdiff-semantic">${escapeHtml(row.semanticB)}</td>
        <td>${renderBadge(row.badge)}</td>
      </tr>
    `;
  }).join('');

  const headers = ['Region', 'Offset', 'Param IDs', 'Raw A', 'Raw B', 'Δ', 'Semantic A', 'Semantic B', 'Badge'];
  return `
    <div class="cal-note">
      Unified byte + semantic diff — sorted by offset.
    </div>
    ${renderRowsTable(headers, html)}
  `;
};

CalibrationLabPage.prototype.renderRawTab = function (store) {
  const state = store.getState();
  const rows = this.applySharedFilters(
    collectRawRows(store),
    (row) => `${row.offset} ${row.paramIds.join(' ')} ${row.rawA} ${row.rawB}`
  );

  const html = rows.map((row) => {
    const firstParam = row.paramIds[0] || null;
    const badge = firstParam
      ? store.classifyRow(firstParam, row.rawA, row.rawB)
      : (row.changed ? 'mismatch' : 'exact');
    const rowKey = `raw-${row.offset}`;
    const isSelected = state.selectedRowKey === rowKey;
    return `
      <tr class="cal-row cal-row-cursor${row.changed ? ' is-changed' : ''}${isSelected ? ' is-selected' : ''}" data-row-key="${rowKey}">
        <td class="mono">${row.offset}</td>
        <td class="mono">${escapeHtml(row.paramIds.join(', ') || '—')}</td>
        <td class="mono">${fmt(row.rawA, 0)}</td>
        <td class="mono">${fmt(row.rawB, 0)}</td>
        <td>${renderBadge(badge)}</td>
      </tr>
    `;
  }).join('');

  return renderRowsTable(['Offset', 'Param IDs', 'Patch A', 'Patch B', 'Badge'], html);
};

CalibrationLabPage.prototype.renderSemanticTab = function (store) {
  const CRITICAL = new Set(['vcfcutoff','vcfresonance','vcfenvdepth','hpfcutoff','vcfpolemode','voicedrift','oscdrift']);
  const state = store.getState();

  let rows = collectSemanticRows(store);

  if (state.filters.showOnlyCritical) {
    rows = rows.filter((row) => CRITICAL.has(row.paramId));
  }

  rows = this.applySharedFilters(
    rows,
    (row) => `${row.paramId} ${row.offset} ${row.cc ?? ''} ${row.rawA} ${row.rawB}`
  );

  const html = rows.map((row) => {
