// ────────────────────────────────────────────────────────────
// Param trace selector
// ────────────────────────────────────────────────────────────

function buildParamTrace(paramId, state, paramVoiceMap, _classifyRowFn) {
  const paramIdLower = (paramId || '').toLowerCase().replace(/[^a-z0-9_]/g, '');
  const mapping = (paramVoiceMap || {})[paramIdLower];
  const voice = getSelectedVoiceSnapshot(state);
  const engine = state.diagnosticSnapshot?.engine || {};

  const trace = {
    paramId: paramIdLower,
    label: mapping?.label || paramIdLower,
    module: mapping?.module || null,
    intermediate: mapping?.intermediate || false,
    patchValue: null,
    liveValue: null,
    liveVoice: voice ? { ...voice } : null,
    engineState: engine,
    derivedContributions: [],
  };

  if (mapping?.voiceField && voice) {
    trace.liveValue = voice[mapping.voiceField];
  }

  if (paramIdLower === 'vcfenvdepth' && voice) {
    trace.liveValue = voice.env1Value;
    trace.derivedContributions.push(
      { key: 'cutoffFromEnv', value: voice.cutoffFromEnv, unit: 'Hz' },
      { key: 'cutoffFromLfo', value: voice.cutoffFromLfo, unit: 'Hz' },
      { key: 'cutoffFromDrift', value: voice.cutoffFromDrift, unit: 'Hz' },
      { key: 'cutoffFromKeytrack', value: voice.cutoffFromKeytrack, unit: 'Hz' },
    );
  }

  if (paramIdLower === 'vcfpolemode' && voice) {
    trace.liveValue = voice.resonance !== null ? '4-pole (default)' : 'n/a';
  }

  return trace;
}

// ────────────────────────────────────────────────────────────
// Validation summary selector
// ────────────────────────────────────────────────────────────

function buildValidationSummary(state, maps, critParams, classifyRowFn) {
  const patchA = state.selectedPatchA;
  const patchB = state.selectedPatchB;

  const empty = {
    total: 0,
    exact: 0,
    aliasShared: 0,
    stub: 0,
    mismatch: 0,
    info: 0,
    criticalWarnings: [],
  };

  if (!patchA || !patchB) {return empty;}

  const bytesA = Array.isArray(patchA.unpackedBytes) ? patchA.unpackedBytes : [];
  const bytesB = Array.isArray(patchB.unpackedBytes) ? patchB.unpackedBytes : [];
  const paramToByteOffset = maps?.paramToByteOffset || {};
  const byteOffsetToParamIds = maps?.byteOffsetToParamIds || {};

  const summary = { ...empty };
  const seenOffsets = new Set();

  Object.entries(paramToByteOffset).forEach(([paramId, offset]) => {
    if (seenOffsets.has(offset)) {return;}
    seenOffsets.add(offset);

    const rawA = Number.isFinite(bytesA[offset]) ? bytesA[offset] : null;
    const rawB = Number.isFinite(bytesB[offset]) ? bytesB[offset] : null;
    const classifyFn = typeof classifyRowFn === 'function' ? classifyRowFn : (typeof window._classifyPatchDiffRow === 'function' ? window._classifyPatchDiffRow : () => 'exact');
    const badge = classifyFn(paramId, rawA, rawB);
    summary.total++;
    if (badge === 'exact') {summary.exact++;}
    else if (badge === 'alias-shared') {summary.aliasShared++;}
    else if (badge === 'stub') {summary.stub++;}
    else if (badge === 'mismatch') {summary.mismatch++;}
    else {summary.info++;}

    if ((badge === 'stub' || badge === 'mismatch') && (critParams || new Set()).has(paramId)) {
      summary.criticalWarnings.push({
        paramId,
        offset,
        badge,
        rawA,
        rawB,
      });
    }
  });

  return summary;
}

// Export to globalThis for cross-file access (browser <script> + Node.js/Vitest)
globalThis.getSelectedVoiceSnapshot = getSelectedVoiceSnapshot;
globalThis.getCurrentWorkflowItem = getCurrentWorkflowItem;
globalThis.buildEngineRows = buildEngineRows;
globalThis.buildEffectiveRows = buildEffectiveRows;
globalThis.buildVoiceSummaryRows = buildVoiceSummaryRows;
globalThis.buildParamTrace = buildParamTrace;
globalThis.buildValidationSummary = buildValidationSummary;

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    getSelectedVoiceSnapshot,
    getCurrentWorkflowItem,
    buildEngineRows,
    buildEffectiveRows,
    buildVoiceSummaryRows,
    buildParamTrace,
    buildValidationSummary,
  };
}

// WebUI/js/calibration_store_selectors_bank.js
// Bank run & workflow selector functions extracted from calibration_store_selectors.js
// Each function takes state (or specific data) and returns derived data — no side effects, no closure.
// Depends on: calibration_store_utils.js (for deepClone, nowIso)

/* eslint-disable no-unused-vars */

/* global deepClone, nowIso */

// ────────────────────────────────────────────────────────────
// Bank run selectors
// ────────────────────────────────────────────────────────────

function buildAllCandidatePatches(loadedBanks) {
  const banks = loadedBanks || {};
  const candidates = [];
  Object.entries(banks).forEach(([bankName, patchList]) => {
    if (!Array.isArray(patchList)) {return;}
    patchList.forEach((patch, patchIndex) => {
      if (!patch || !patch.unpackedBytes) {return;}
      candidates.push({
        bankName,
        patchIndex,
        patchName: (patch.name || `Patch ${patchIndex + 1}`).trim(),
        patchRef: patch,
        meta: patch.meta || {},
      });
    });
  });
  return candidates;
}

function buildStratifiedRunItems(state, maps, critParams, seededShuffleFn, filterCandidateFn) {
  const cfg = { ...state.bankRunConfig };
  const runId = `run-${Date.now()}-${cfg.seed}`;

  let candidates = buildAllCandidatePatches(
    (typeof window !== 'undefined' && window.loadedBanks) || {}
  );
  candidates = filterCandidateFn(candidates, cfg);

  const shuffled = seededShuffleFn(candidates, cfg.seed);
  const size = Math.max(0, Math.min(shuffled.length, cfg.sampleSize));
  const selected = shuffled.slice(0, size);

  const paramToByteOffset = maps?.paramToByteOffset || {};

  return selected.map((c, index) => {
    const bytes = c.patchRef.unpackedBytes;
    const criticalCandidate = [...critParams].some((paramId) => {
      const off = paramToByteOffset[paramId];
      return Number.isFinite(off) && Number.isFinite(bytes[off]) && bytes[off] !== 0;
    });

    return {
      runId,
      index,
      bankName: c.bankName,
      patchIndex: c.patchIndex,
      patchName: c.patchName,
      patchRef: c.patchRef,
      meta: deepClone(c.meta),
      criticalCandidate,
      status: 'pending',
      notes: '',
    };
  });
}

function buildWorkflowProgress(state) {
  const total = state.bankRunItems.length;
  if (total === 0) {return { total: 0, reviewed: 0, pct: 0 };}
  const statuses = state.workflowSession.itemStatuses;
  const reviewed = Object.values(statuses)
    .filter(s => s !== 'pending').length;
  return {
    total,
    reviewed,
    pct: Math.round((reviewed / total) * 100),
    currentIndex: state.workflowSession.currentIndex,
  };
}

function buildWorkflowReportSnapshot(state) {
  const cfg = deepClone(state.bankRunConfig);
  const session = deepClone(state.workflowSession);
  const items = state.bankRunItems.map((item) => ({
    runId: item.runId,
    index: item.index,
    bankName: item.bankName,
    patchIndex: item.patchIndex,
    patchName: item.patchName,
    meta: deepClone(item.meta),
    criticalCandidate: item.criticalCandidate,
    status: state.workflowSession.itemStatuses[String(item.index)] || item.status,
    notes: state.workflowSession.itemNotes[String(item.index)] || item.notes,
    hasSysexData: Array.isArray(item.patchRef?.unpackedBytes) && item.patchRef.unpackedBytes.length > 0,
  }));

  const progress = buildWorkflowProgress(state);
  const counts = items.reduce((acc, item) => {
    acc[item.status] = (acc[item.status] || 0) + 1;
    return acc;
  }, {});

  return {
    exportedAt: nowIso(),
    schemaVersion: 1,
    schema_version: '1.0.0',
    runId: state.bankRunId,
    config: cfg,
    session,
    progress,
    statusCounts: counts,
    items,
  };
}

function buildReportRows(snapshot) {
  if (!snapshot || !Array.isArray(snapshot.items)) {return [];}
  return snapshot.items.map((item) => ({
    schema_version: snapshot.schema_version,
    runId: item.runId,
    index: item.index,
    bankName: item.bankName,
    patchIndex: item.patchIndex,
    patchName: item.patchName,
    category: item.meta.category || '',
    favorite: item.meta.favorite ? 'true' : 'false',
    status: item.status,
    criticalCandidate: item.criticalCandidate ? 'true' : 'false',
    latestBadge: '',
    notes: item.notes,
  }));
}

// Export to globalThis for cross-file access (browser <script> + Node.js/Vitest)
globalThis.buildAllCandidatePatches = buildAllCandidatePatches;
globalThis.buildStratifiedRunItems = buildStratifiedRunItems;
globalThis.buildWorkflowProgress = buildWorkflowProgress;
globalThis.buildWorkflowReportSnapshot = buildWorkflowReportSnapshot;
globalThis.buildReportRows = buildReportRows;

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    buildAllCandidatePatches,
    buildStratifiedRunItems,
    buildWorkflowProgress,
    buildWorkflowReportSnapshot,
    buildReportRows,
  };
}

// WebUI/js/calibration_store_utils.js
// Core utility functions for Calibration Store — reduced version.
// Data constants → calibration_store_data.js
// Snapshot normalization → calibration_store_normalize.js
// Validation/compliance → calibration_store_validation.js

/* eslint-disable no-unused-vars */

function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}

function nowIso() {
  return new Date().toISOString();
}

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Deterministic shuffle using mulberry32 PRNG.
 * @param {Array} items
 * @param {number} seed
 * @returns {Array}
 */
function seededShuffle(items, seed) {
  const arr = [].concat(items);
  let s = (seed >>> 0) + 0x6d2b79f5;
  function next() {
    s = Math.imul(s ^ (s >>> 15), s | 1);
    s ^= s + Math.imul(s ^ (s >>> 7), s | 61);
    return ((s ^ (s >>> 14)) >>> 0) / 0x100000000;
  }
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(next() * (i + 1));
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }
  return arr;
}

/**
 * Filters candidate patches by bank name, category, and favorites.
 * @param {Array} candidates
 * @param {{bankNames: string[], categoryFilter: string, favoritesOnly: boolean}} config
 * @returns {Array}
 */
function filterCandidatePatches(candidates, config) {
  const bankNames = config.bankNames;
  const categoryFilter = config.categoryFilter;
  const favoritesOnly = config.favoritesOnly;
  return candidates.filter(function(c) {
    if (bankNames.length > 0 && bankNames.indexOf(c.bankName) === -1) { return false; }
    if (favoritesOnly && !c.meta.favorite) { return false; }
    if (categoryFilter) {
      const cat = (c.meta.category || '').toLowerCase();
      if (cat.indexOf(categoryFilter.toLowerCase()) === -1) { return false; }
    }
    return true;
  });
}

// ── Exports ──
globalThis.deepClone = deepClone;
globalThis.nowIso = nowIso;
globalThis.isObject = isObject;
globalThis.seededShuffle = seededShuffle;
globalThis.filterCandidatePatches = filterCandidatePatches;

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    deepClone: deepClone,
    nowIso: nowIso,
    isObject: isObject,
    seededShuffle: seededShuffle,
    filterCandidatePatches: filterCandidatePatches,
  };
}

// WebUI/js/calibration_store_validation.js
// Validation and compliance functions — extracted from calibration_store_utils.js
// Depends on: calibration_store_data.js (DEFAULT_CALIBRATION_SPEC, CRITICAL_PARAM_IDS)
// Depends on: calibration_store_utils.js (isObject)
// Depends on: calibration_store_normalize.js (normalizeSnapshot) — via resolveSpec

/* global isObject, DEFAULT_CALIBRATION_SPEC */

/* eslint-disable no-unused-vars */

/**
 * Classifies a param comparison into a badge type.
 * @param {string} paramId
 * @param {number|null} rawA
 * @param {number|null} rawB
 * @returns {'exact'|'alias-shared'|'stub'|'mismatch'|'info'}
 */
function classifyRow(paramId, rawA, rawB) {
  const STUB_PARAMS = new Set(['vcfpolemode', 'vcf_pole_mode']);
  const ALIAS_PARAMS = new Set(['voicedrift', 'oscdrift', 'voice_drift', 'osc_drift']);

  if (STUB_PARAMS.has(paramId)) { return 'stub'; }
  if (ALIAS_PARAMS.has(paramId)) { return 'alias-shared'; }
  if (rawA === null || rawB === null) { return 'info'; }
  if (rawA === rawB) { return 'exact'; }
  return 'mismatch';
}

function resolveSpec(spec) {
  if (isObject(spec) && isObject(spec.voice)) { return spec; }
  return DEFAULT_CALIBRATION_SPEC;
}

function validateLiveCompliance(snapshot, spec) {
  if (!isObject(snapshot) || !Array.isArray(snapshot.voices)) {
    return { compliant: false, voiceResults: [], totalCompliant: 0 };
  }
  const s = resolveSpec(spec);
  const sv = s.voice;
  const pitchRange = sv.staticPitchCentsRange / 2;
  const cutoffRange = sv.staticCutoffNormRange / 2;
  const resRange = sv.staticResNormRange / 2;
  const envRange = sv.staticEnvTimeNormRange / 2;

  const voiceResults = snapshot.voices.map(function(v, idx) {
    const checks = [];

    if (Number.isFinite(v.driftOsc1Pitch)) {
      checks.push({
        param: 'driftOsc1Pitch', label: 'OSC1 Pitch Drift',
        value: v.driftOsc1Pitch, specLimit: pitchRange, unit: 'cents',
        passed: Math.abs(v.driftOsc1Pitch) <= pitchRange,
      });
    }
    if (Number.isFinite(v.driftOsc2Pitch)) {
      checks.push({
        param: 'driftOsc2Pitch', label: 'OSC2 Pitch Drift',
        value: v.driftOsc2Pitch, specLimit: pitchRange, unit: 'cents',
        passed: Math.abs(v.driftOsc2Pitch) <= pitchRange,
      });
    }
    if (Number.isFinite(v.driftVcfCutoff)) {
      checks.push({
        param: 'driftVcfCutoff', label: 'VCF Cutoff Drift',
        value: v.driftVcfCutoff, specLimit: cutoffRange, unit: 'norm',
        passed: Math.abs(v.driftVcfCutoff) <= cutoffRange,
      });
    }
    if (Number.isFinite(v.driftVcfResonance)) {
      checks.push({
        param: 'driftVcfResonance', label: 'VCF Resonance Drift',
        value: v.driftVcfResonance, specLimit: resRange, unit: 'norm',
        passed: Math.abs(v.driftVcfResonance) <= resRange,
      });
    }
    if (Number.isFinite(v.driftEnvTime)) {
      checks.push({
        param: 'driftEnvTime', label: 'Env Time Drift',
        value: v.driftEnvTime, specLimit: envRange, unit: 'norm',
        passed: Math.abs(v.driftEnvTime) <= envRange,
      });
    }

    const active = v.active === true;
    const failedChecks = checks.filter(function(c) { return !c.passed; });
    const passed = !active || failedChecks.length === 0;

    return {
      voiceIndex: idx,
      active: active,
      midiNote: v.midiNote,
      velocity: v.velocity,
      passed: passed,
      checks: checks,
      failedCount: failedChecks.length,
    };
  });

  const totalCompliant = voiceResults.filter(function(r) { return r.passed; }).length;
  return {
    compliant: totalCompliant === voiceResults.length,
    voiceResults: voiceResults,
    totalCompliant: totalCompliant,
  };
}

// ── Exports ──
globalThis.classifyRow = classifyRow;
globalThis.resolveSpec = resolveSpec;
globalThis.validateLiveCompliance = validateLiveCompliance;

if (typeof window !== 'undefined') {
  window.validateLiveCompliance = validateLiveCompliance;
}

if (typeof module !== 'undefined' && module.exports) {
