/**
 * @module ctrl-tooltip_render
 * @purpose Render layer for CtrlTooltip: generates rich HTML tooltip content.
 *   Extracted from ctrl-tooltip.js for SRP.
 * @classification UI Renderer
 */
(function () {
    'use strict';

    const TOOLTIP_CLASS = 'ctrl-tooltip-container';

    /** Ensure tooltip DOM element exists */
    window.ensureTooltipEl = function () {
        let el = document.querySelector('.' + TOOLTIP_CLASS);
        if (el) {return el;}
        el = document.createElement('div');
        el.className = TOOLTIP_CLASS;
        el.setAttribute('role', 'tooltip');
        document.body.appendChild(el);
        return el;
    };

    /**
     * Render rich HTML content for a parameter or custom tooltip.
     * @param {string} paramId - Parameter ID (or custom store key)
     * @param {object} paramMeta - Cached metadata from buildTooltipParamMeta()
     * @param {object} customTextStore - Map of custom tooltip entries
     * @returns {string} HTML string
     */
    window.renderTooltipContent = function (paramId, paramMeta, customTextStore) {
        if (!paramMeta) {return '';}

        const info = paramMeta[paramId];

        // Check custom text store for programmer / non-param controls
        if (!info && customTextStore && customTextStore[paramId]) {
            const data = customTextStore[paramId];
            return _renderCustomTooltip(data);
        }

        if (!info) {
            // Fallback: humanize paramId
            const label = paramId
                .replace(/_/g, ' ')
                .replace(/\b\w/g, function (c) { return c.toUpperCase(); });
            return _renderHeader(label);
        }

        return _renderParamTooltip(info, paramId, paramMeta);
    };

    /* ── Internal render helpers ── */

    function _renderCustomTooltip(data) {
        let html = _renderHeader(data.name);
        if (data.desc) {
            html += _renderDivider();
            html += '<div style="color:var(--text-secondary,#c5c6c7);font-size:var(--text-2xs,8px);font-style:italic;line-height:1.4">' +
                data.desc +
                '</div>';
        }
        return html;
    }

    function _renderHeader(label) {
        return '<div class="ctrl-tt-header" style="color:var(--accent-primary,#ff9900);font-weight:700;font-size:var(--text-sm,9px);text-transform:uppercase;margin-bottom:4px">' +
            label +
            '</div>';
    }

    function _renderDivider() {
        return '<div class="ctrl-tt-divider" style="border-top:1px solid var(--border-dim,#1f2228);margin:3px 0"></div>';
    }

    function _renderParamTooltip(info, paramId, paramMeta) {
        const nameDisplay = info.name.replace(/_/g, ' ');
        let html = _renderHeader(nameDisplay);

        html += _renderDivider();

        // NRPN
        html += _renderRow('NRPN', info.nrpn, 'var(--accent-blue,#00ccff)', true);

        // SysEx byte offset
        html += _renderRow('SysEx Byte', 'b[' + info.byteOffset + ']', 'var(--accent-green,#00ff66)', true);

        // Region
        html += _renderRow('Region', info.region, 'var(--text-secondary,#c5c6c7)');

        // Type
        const typeLabel = info.type.charAt(0).toUpperCase() + info.type.slice(1);
        html += _renderRow('Type', typeLabel, 'var(--text-secondary,#c5c6c7)');

        // Enum labels — show current resolved value + full list
        if (info.enumLabels && info.enumLabels.length > 0) {
            html += _renderEnumSection(info, paramId);
        }

        // Description
        if (info.desc) {
            html += '<div class="ctrl-tt-divider" style="border-top:1px solid var(--border-dim,#1f2228);margin:3px 0;padding-top:3px">' +
                '<span style="color:var(--text-faint,#555);font-style:italic;font-size:var(--text-2xs,7px)">' +
                info.desc +
                '</span>' +
                '</div>';
        }

        return html;
    }

    function _renderRow(label, value, color, isMono) {
        const fontFamily = isMono ? 'font-family:\'Share Tech Mono\',monospace' : '';
        return '<div class="ctrl-tt-row" style="display:flex;justify-content:space-between;gap:10px">' +
            '<span style="color:var(--text-dim,#888)">' + label + '</span>' +
            '<span style="color:' + color + ';' + fontFamily + '">' +
            value +
            '</span>' +
            '</div>';
    }

    function _renderEnumSection(info, paramId) {
        // Look up current value from parameter cache
        let currentIdx = 0;
        try {
            const cache = window.dualMidiBridge && window.dualMidiBridge.parameterCache;
            if (cache && typeof cache[paramId] === 'number') {
                currentIdx = Math.round(cache[paramId] * (info.enumLabels.length - 1));
                currentIdx = Math.max(0, Math.min(currentIdx, info.enumLabels.length - 1));
            }
        } catch (e) {}

        const currentLabel = info.enumLabels[currentIdx];
        const allLabels = info.enumLabels.join(', ');

        return _renderRow('Current', currentLabel, 'var(--accent-primary,#ff9900)') +
            '<div class="ctrl-tt-row" style="display:flex;justify-content:space-between;gap:10px;border-top:1px solid var(--border-dim,#1f2228);padding-top:2px;margin-top:1px">' +
            '<span style="color:var(--text-faint,#555)">Options</span>' +
            '<span style="color:var(--text-faint,#555);font-size:var(--text-2xs,7px);text-align:right;max-width:160px;line-height:1.3">' +
            allLabels +
            '</span>' +
            '</div>';
    }
})();

/**
 * @purpose Handles voice modes mappings, note conversions, and theoretical unison parameters detune stack calculator.
 * @purpose_en Debug panel voice constants and theoretical parameters calculator.
 */

window.DEBUG_VOICE_MODE_NAMES = [
    'Poly', 'Uni2', 'Uni3', 'Uni4', 'Uni6', 'Uni12',
    'Mono', 'Mono2', 'Mono3', 'Mono4', 'Mono6',
    'Poly6', 'Poly8'
];

window.DEBUG_VOICES_PER_MODE = [1, 2, 3, 4, 6, 12, 1, 2, 3, 4, 6, 1, 1];

const DEBUG_NOTE_NAMES = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
window.DEBUG_CHORD_TYPE_NAMES = ['Memory','Major','Minor','Maj7','Min7','Dom7','Sus4','Power','Aug','Dim','Sus2','7th'];

window.debugMidiNoteToName = function(note) {
    if (note < 0 || note > 127) {return '—';}
    const octave = Math.floor(note / 12) - 1;
    return DEBUG_NOTE_NAMES[note % 12] + octave;
};

window.calculateUnisonParams = function(voiceMode, unisonDetune, vcaPanSpread) {
    const totalVoices = window.DEBUG_VOICES_PER_MODE[voiceMode] || 1;
    if (totalVoices <= 1) {return [];}

    const maxDetuneCents = unisonDetune * 50.0;
    const results = [];

    for (let v = 0; v < totalVoices; v++) {
        let detuneCents;

        if (totalVoices === 2) {
            detuneCents = v === 0 ? -maxDetuneCents : maxDetuneCents;
        } else {
            const step = 2.0 * maxDetuneCents / (totalVoices - 1);
            detuneCents = -maxDetuneCents + v * step;
        }

        const panPos = totalVoices === 2 ? (v === 0 ? 0.0 : 1.0) : v / (totalVoices - 1);
        const basePan = 0.5 + (panPos - 0.5) * vcaPanSpread;

        results.push({ voiceIndex: v, detuneCents, panRaw: panPos, panOutput: basePan, active: false, midiNote: -1 });
    }
    return results;
};

/**
 * @component debug-modal
 * @purpose Modal overlay for monitoring real voice state from C++ DSP engine (facade)
 * Voice state reading extracted to debug-panel_voice.js
 * UI rendering extracted to debug-panel_state.js
 * @classification UI Component
 */
(function () {
    class DebugModal extends HTMLElement {
        constructor() {
            super();
            this._updateInterval = null;
            this._boundUpdate = function () { _updateFromCache.call(this); }.bind(this);
            this._vuSmoothed = 0.0;
            this._vuLastTime = Date.now();
            this._vuClipState = {};
            this._updating = false;
        }

        connectedCallback() {
            if (this.children.length === 0) {
                this.innerHTML = window.DEBUG_PANEL_TEMPLATE || '';
            }
            const closeBtn = this.querySelector('#debug-close-btn');
            if (closeBtn) {
                closeBtn.addEventListener('click', function () { this.hide(); }.bind(this));
            }
            const backdrop = this.querySelector('#debug-modal-backdrop');
            if (backdrop) {
                backdrop.addEventListener('click', function (e) {
                    if (e.target === backdrop) { this.hide(); }
                }.bind(this));
            }
            this._escHandler = function (e) { if (e.key === 'Escape') { this.hide(); } }.bind(this);
            document.addEventListener('keydown', this._escHandler);
            this._updateInterval = setInterval(this._boundUpdate, 250);
        }

        disconnectedCallback() {
            if (this._updateInterval) {
                clearInterval(this._updateInterval);
                this._updateInterval = null;
            }
            if (this._escHandler) {
                document.removeEventListener('keydown', this._escHandler);
            }
        }

        show() {
            const backdrop = this.querySelector('#debug-modal-backdrop');
            if (backdrop) { backdrop.style.display = 'flex'; }
            _updateFromCache.call(this);
        }

        hide() {
            const backdrop = this.querySelector('#debug-modal-backdrop');
            if (backdrop) { backdrop.style.display = 'none'; }
        }
    }

    async function _updateFromCache() {
        if (this._updating) { return; }
        this._updating = true;
        try {
            const backdrop = this.querySelector('#debug-modal-backdrop');
            if (!backdrop || backdrop.style.display === 'none') { return; }
            if (!window.dualMidiBridge) { return; }

            const bridge = window.dualMidiBridge;
            const cache = bridge.parameterCache || {};
            let raw = null;

            if (bridge.isJuce && typeof bridge.getVoiceState === 'function') {
                raw = await bridge.getVoiceState().catch(function () { return null; });
            }

            // Read voice state using extracted module
            const state = window.debugReadVoiceState(bridge, cache, raw);
            if (!state) { return; }

            // Update basic info
            window.debugSetText('debug-mode-name', state.voiceModeName);
            window.debugSetText('debug-stack-count', state.voicesPerNote + (state.voicesPerNote === 1 ? ' voice' : ' voices'));
            window.debugSetText('debug-detune-val', state.detuneVal);
            window.debugSetText('debug-pan-val', state.panVal);
            window.debugSetText('debug-data-source', state.dataSource);
            window.debugSetText('debug-active-count', String(state.activeCount) + '/' + String(state.voiceCount));

            // Chord / poly-chord status
            if (state.chordOn || state.polyChordOn) {
                window.debugSetHtml('debug-chord-status', state.chordStatus);
                window.debugSetHtml('debug-polychord-status', state.polyChordStatus);
            } else {
                window.debugSetText('debug-chord-status', '—');
                window.debugSetText('debug-polychord-status', '—');
            }

            // VU meter
            const vuResult = window.debugSmoothVU(state.peakLevel, this._vuSmoothed, this._vuLastTime);
            this._vuSmoothed = vuResult.smoothed;
            this._vuLastTime = vuResult.lastTime;
            this._vuClipState = window.debugRenderVU(this._vuSmoothed, state.peakLevel, this._vuClipState);

            // Controller bars
            window.debugRenderControllers({
                ctrlPitchBend: state.ctrlPitchBend,
                ctrlModWheel: state.ctrlModWheel,
                ctrlAftertouch: state.ctrlAftertouch,
                ctrlSustainPedal: state.ctrlSustainPedal
            });

            // Voice grid
            window.debugRenderVoiceGrid(state.voices, state.voiceMode);

        } catch (e) {
            // Silently handle errors during update
        } finally {
            this._updating = false;
        }
    }

    if (!customElements.get('debug-modal')) {
        customElements.define('debug-modal', DebugModal);
    }
})();

/**
 * @purpose Debug panel: UI rendering helpers for VU meter, controllers, and voice grid.
 * Extracted from debug-panel.js for modularization.
