/**
 * dsp-processor.js — AudioWorkletProcessor for ABDEep WASM DSP Engine.
 * 
 * Runs in the browser's high-priority audio thread.
 * Loads the WebAssembly DSP module and processes audio blocks in real-time.
 */

// Import the Emscripten-generated JS wrapper
import '../wasm/abdeep_dsp.js';

class ABDEepWasmProcessor extends AudioWorkletProcessor {
    constructor(options) {
        super();

        this.wasmModule = null;
        this.dsp = null; // C++ functions bound via cwrap
        this.sampleRate = options.processorOptions?.sampleRate || 44100;
        this.blockSize = 128; // Web Audio API standard block size

        // Pre-allocate WebAssembly heap buffers for outL and outR
        this.outLPtr = 0;
        this.outRPtr = 0;
        this.outLBuffer = null;
        this.outRBuffer = null;
        this.isWasmReady = false;

        // Listen for MIDI events and parameters from the main UI thread
        this.port.onmessage = this.handleMessage.bind(this);

        this.initWasm();
    }

    async initWasm() {
        try {
            // Instanciar el módulo de Emscripten
            const module = await ABDEepDSP({
                locateFile: (path) => {
                    // Cargar el archivo .wasm desde el directorio /wasm/ relativo al servidor
                    if (path.endsWith('.wasm')) {return 'wasm/' + path;}
                    return path;
                }
            });

            this.wasmModule = module;

            // Enlazar las funciones exportadas de C++ con cwrap/ccall
            this.dsp = {
                init: module.cwrap('wasm_init_engine', 'void', ['number', 'number']),
                process: module.cwrap('wasm_process_audio', 'void', ['number', 'number', 'number']),
                setParameter: module.cwrap('wasm_set_parameter', 'void', ['string', 'number']),
                noteOn: module.cwrap('wasm_note_on', 'void', ['number', 'number']),
                noteOff: module.cwrap('wasm_note_off', 'void', ['number']),
                pitchBend: module.cwrap('wasm_pitch_bend', 'void', ['number']),
                panic: module.cwrap('wasm_panic', 'void', [])
            };

            // Inicializar el motor DSP de C++ (sampleRate, blockSize)
            this.dsp.init(this.sampleRate, this.blockSize);

            // Reservar memoria en el HEAP de WASM para los 2 canales de salida (float * 128 samples)
            const numBytes = this.blockSize * 4; // 128 * sizeof(float)
            this.outLPtr = module._malloc(numBytes);
            this.outRPtr = module._malloc(numBytes);

            // Crear vistas Float32Array mapeadas sobre el HEAP de Emscripten
            this.outLBuffer = new Float32Array(module.HEAPF32.buffer, this.outLPtr, this.blockSize);
            this.outRBuffer = new Float32Array(module.HEAPF32.buffer, this.outRPtr, this.blockSize);

            this.isWasmReady = true;
            this.port.postMessage({ type: 'status', ready: true });
            console.log('[WasmProcessor] Motor DSP C++ inicializado correctamente en AudioWorklet.');
        } catch (e) {
            console.error('[WasmProcessor] Error inicializando motor WebAssembly:', e);
        }
    }

    handleMessage(event) {
        if (!this.isWasmReady || !this.dsp) {return;}

        const data = event.data;
        switch (data.type) {
            case 'note_on':
                this.dsp.noteOn(data.note, data.velocity || 0.8);
                break;
            case 'note_off':
                this.dsp.noteOff(data.note);
                break;
            case 'set_param':
                this.dsp.setParameter(data.paramId, data.value);
                break;
            case 'pitch_bend':
                this.dsp.pitchBend(data.value);
                break;
            case 'panic':
                this.dsp.panic();
                break;
        }
    }

    process(inputs, outputs, parameters) {
        if (!this.isWasmReady || !this.dsp) {
            // Si el motor WASM no está listo, emitimos silencio
            return true; 
        }

        const output = outputs[0];
        const outputChannelL = output[0];
        const outputChannelR = output[1];

        // Re-crear vistas de buffer si la memoria WASM creció o se desenganchó el buffer
        if (!this.outLBuffer || this.outLBuffer.buffer.byteLength === 0) {
            this.outLBuffer = new Float32Array(this.wasmModule.HEAPF32.buffer, this.outLPtr, this.blockSize);
            this.outRBuffer = new Float32Array(this.wasmModule.HEAPF32.buffer, this.outRPtr, this.blockSize);
        }

        // Procesar un bloque de audio llamando a C++
        // Esto escribe los resultados en outLPtr y outRPtr
        this.dsp.process(this.outLPtr, this.outRPtr, this.blockSize);

        // Copiar las muestras calculadas por el motor C++ a los buffers de salida del navegador
        if (outputChannelL) {outputChannelL.set(this.outLBuffer);}
        if (outputChannelR) {outputChannelR.set(this.outRBuffer);}

        return true;
    }
}

registerProcessor('abdeep-dsp-processor', ABDEepWasmProcessor);

/**
 * @purpose Gestión del historial de edición Undo/Redo, acciones de Copiar/Pegar presets, almacenamiento (Save / Save As) y atajos de teclado globales.
 * @purpose_en Manages Undo/Redo history stack, Copy/Paste presets buffer, patch persistence (Save / Save As), and global key shortcuts.
 */

function initEditActions() {
    let globalClipboardBytes = null;
    let globalClipboardName = '';

    if (typeof window.initEditHistory === 'function') {
        window.initEditHistory();
    }
    if (typeof window.initEditPersistence === 'function') {
        window.initEditPersistence();
    }

    // Delegación de eventos para la barra de navegación superior (mitiga race conditions de carga)
    document.addEventListener('click', (e) => {
        // Undo
        if (e.target.closest('#menu-undo')) {
            e.preventDefault();
            if (typeof window.triggerUndo === 'function') {window.triggerUndo();}
        }

        // Redo
        if (e.target.closest('#menu-redo')) {
            e.preventDefault();
            if (typeof window.triggerRedo === 'function') {window.triggerRedo();}
        }

        // Copy
        if (e.target.closest('#menu-copy-preset')) {
            e.preventDefault();
            const activeBank = window.loadedBanks[window.currentActiveBank];
            if (!activeBank || window.currentActivePatchIndex === -1) {
                alert('Selecciona primero un preset del Bank Manager para copiar.');
                return;
            }
            const patch = activeBank[window.currentActivePatchIndex];
            if (patch && patch.unpackedBytes) {
                globalClipboardBytes = new Uint8Array(patch.unpackedBytes);
                globalClipboardName = patch.name;
                const lcdText = document.getElementById('lcd-text');
                if (lcdText) {lcdText.innerHTML = `<strong>COPIED</strong><br><span style="font-size:11px;">${patch.name.toUpperCase()}</span>`;}
            }
        }

        // Paste
        if (e.target.closest('#menu-paste-preset')) {
            e.preventDefault();
            if (!globalClipboardBytes) {
                alert('El portapapeles está vacío. Copia un preset primero.');
                return;
            }
            const activeBank = window.loadedBanks[window.currentActiveBank];
            if (!activeBank || window.currentActivePatchIndex === -1) {
                alert('Selecciona un slot de destino en el Bank Manager.');
                return;
            }

            const FACTORY_BANKS = [
                'Factory Bank A', 'Factory Bank B', 'Factory Bank C', 'Factory Bank D',
                'Factory Bank E', 'Factory Bank F', 'Factory Bank G', 'Factory Bank H'
            ];
            if (FACTORY_BANKS.includes(window.currentActiveBank)) {
                alert('No está permitido modificar o pegar presets en los bancos de fábrica.');
                return;
            }

            const patch = activeBank[window.currentActivePatchIndex];
            if (patch) {
                patch.unpackedBytes = new Uint8Array(globalClipboardBytes);
                patch.name = globalClipboardName;

                for (let k = 0; k < 15; k++) {
                    patch.unpackedBytes[224 + k] = k < patch.name.length ? patch.name.charCodeAt(k) : 0x20;
                }

                if (window.triggerMidiDump) {window.triggerMidiDump(patch);}
                if (typeof window.renderPatchesForBank === 'function') {window.renderPatchesForBank(window.currentActiveBank);}

                if (typeof window._saveUserBanksToStorage === 'function') {
                    window._saveUserBanksToStorage();
                }
            }
        }
    });

    window.addEventListener('keydown', (e) => {
        if (e.ctrlKey || e.metaKey) {
            switch (e.key.toLowerCase()) {
                case 'z':
                    e.preventDefault();
                    if (typeof window.triggerUndo === 'function') {window.triggerUndo();}
                    break;
                case 'y':
                    e.preventDefault();
                    if (typeof window.triggerRedo === 'function') {window.triggerRedo();}
                    break;
                case 'c':
                    if (window.getSelection().toString() === '') {
                        e.preventDefault();
                        const copyBtn = document.getElementById('menu-copy-preset');
                        if (copyBtn) {copyBtn.click();}
                    }
                    break;
                case 'v':
                    if (document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'SELECT') {
                        e.preventDefault();
                        const pasteBtn = document.getElementById('menu-paste-preset');
                        if (pasteBtn) {pasteBtn.click();}
                    }
                    break;
            }
        }
    });
}

window.initEditActions = initEditActions;

/**
 * @purpose Maps parameter cache values back into raw unpacked Behringer DeepMind 12 SysEx payload bytes.
 * Iterates over CACHE_MAP data array (defined in edit_cache_mapper_data.js).
 * @purpose_en Parameter Cache to SysEx bytes mapper (data-driven).
 */

window.updateUnpackedBytesFromCache = function(unpackedBytes) {
    if (!window.dualMidiBridge) { return; }
    if (!window.CACHE_MAP) { return; }
    const cache = window.dualMidiBridge.parameterCache;

    const set = function(idx, val) {
        if (val !== undefined && val !== null && !isNaN(val)) {
            unpackedBytes[idx] = Math.round(Math.max(0, Math.min(255, val)));
        }
    };

    // Hardware DeepMind 12 only understands FX types 0-35 (36 standard types).
    // The UI keeps 57 names for advanced types, so clamp anything above
    // the hardware range to 56 before writing the SysEx byte.
    const fxTypeToHardwareByte = function(val) { return Math.min(val, 1.0) * 56; };

    for (let i = 0; i < window.CACHE_MAP.length; i++) {
        const entry = window.CACHE_MAP[i];
        const raw = cache[entry.param];

        if (raw === undefined && entry.default !== undefined) {
            set(entry.byte, entry.default);
        } else if (entry.bipolar) {
            // Bipolar depth: normalized 0..1 → SysEx bipolar 1..255 (center=128)
            set(entry.byte, ((raw * 2 - 1) * 127) + 128);
        } else if (entry.formula === 'fxType') {
            // FX type: clamp UI range (0..56) to hardware byte
            set(entry.byte, fxTypeToHardwareByte(raw));
        } else {
            set(entry.byte, raw * (entry.scale || 255));
        }
    }
};

/**
 * @purpose Manages Undo/Redo stack history, state snapshot capture/restore, and parameter debounced history registration.
 * @purpose_en Undo/Redo history stack service.
 */

const undoStack = [];
window.undoStack = undoStack;
const redoStack = [];
window.redoStack = redoStack;
const maxHistory = 50;
let isHistoryAction = false;
window.isHistoryAction = isHistoryAction;

function captureParamSnapshot() {
    if (!window.dualMidiBridge) {return null;}
    return JSON.stringify(window.dualMidiBridge.parameterCache);
}
window.captureParamSnapshot = captureParamSnapshot;

function restoreParamSnapshot(snapshotStr) {
    if (!snapshotStr || !window.dualMidiBridge) {return;}
    window.isHistoryAction = true;
    isHistoryAction = true;

    const cache = JSON.parse(snapshotStr);
    Object.keys(cache).forEach(paramId => {
        const val = cache[paramId];
        window.dualMidiBridge.setParameter(paramId, val);
        window.dualMidiBridge.handleParameterChangeFromBackend(paramId, val);
    });

    if (typeof window.updateLfoSlidersFromCurrentPreset === 'function') {window.updateLfoSlidersFromCurrentPreset();}
    if (typeof window.updateEnvSlidersFromCurrentPreset === 'function') {window.updateEnvSlidersFromCurrentPreset();}
    if (typeof window.updateOscSlidersFromCurrentPreset === 'function') {window.updateOscSlidersFromCurrentPreset();}

    window.isHistoryAction = false;
    isHistoryAction = false;

    const lcdText = document.getElementById('lcd-text');
    if (lcdText) {
        lcdText.innerHTML = '<span class="lcd-label">EDIT HISTORY</span><br><strong>STATE RESTORED</strong>';
    }
}
window.restoreParamSnapshot = restoreParamSnapshot;

window.initEditHistory = function() {
    if (window.dualMidiBridge) {
        let changeTimeout = null;
        window.dualMidiBridge.onParameterChanged((_paramId, _val) => {
            if (window.isHistoryAction || isHistoryAction) {return;}

            clearTimeout(changeTimeout);
            changeTimeout = setTimeout(() => {
                const snap = captureParamSnapshot();
                if (snap) {
                    if (undoStack.length === 0 || undoStack[undoStack.length - 1] !== snap) {
                        undoStack.push(snap);
                        if (undoStack.length > maxHistory) {undoStack.shift();}
                        redoStack.length = 0; // Clear redo
                    }
                }
            }, 400);
        });
    }
};

window.triggerUndo = function() {
    if (undoStack.length <= 1) {
        alert('No hay más cambios que deshacer.');
        return;
    }
    const current = undoStack.pop();
    redoStack.push(current);

    const previous = undoStack[undoStack.length - 1];
    restoreParamSnapshot(previous);
};

window.triggerRedo = function() {
    if (redoStack.length === 0) {
        alert('No hay cambios para rehacer.');
        return;
    }
    const nextState = redoStack.pop();
    undoStack.push(nextState);
    restoreParamSnapshot(nextState);
};

/**
 * @purpose Manages saving current patch modifications and rendering the interactive "Save As" selection slots.
 * @purpose_en Patch persistence and Save As modal manager.
 */

window.initEditPersistence = function() {
    const menuSave = document.getElementById('menu-save');
    if (menuSave) {
        menuSave.addEventListener('click', () => {
            const activeBank = window.loadedBanks[window.currentActiveBank];
            if (!activeBank || window.currentActivePatchIndex === -1) {
                alert('Por favor, selecciona un preset de la librería local del Bank Manager para guardar.');
                return;
            }
            const FACTORY_BANKS = [
                'Factory Bank A', 'Factory Bank B', 'Factory Bank C', 'Factory Bank D',
                'Factory Bank E', 'Factory Bank F', 'Factory Bank G', 'Factory Bank H'
            ];
            if (FACTORY_BANKS.includes(window.currentActiveBank)) {
                alert("No puedes modificar los bancos de fábrica. Usa 'Save Patch As' para guardarlo en un banco de usuario.");
                return;
            }

            const patch = activeBank[window.currentActivePatchIndex];
            if (patch && window.dualMidiBridge) {
                if (typeof window.updateUnpackedBytesFromCache === 'function') {
                    window.updateUnpackedBytesFromCache(patch.unpackedBytes);
                }
                for (let k = 0; k < 15; k++) {
                    patch.unpackedBytes[224 + k] = k < patch.name.length ? patch.name.charCodeAt(k) : 0x20;
                }
                if (typeof updateSysExMonitor === 'function') {updateSysExMonitor(patch.unpackedBytes);}

                if (typeof window._saveUserBanksToStorage === 'function') {
                    window._saveUserBanksToStorage();
                }

                const lcdText = document.getElementById('lcd-text');
                if (lcdText) {
                    const html = `<span class="lcd-label">SAVED</span><br><strong style="color:var(--accent-green);">${patch.name.toUpperCase()}</strong><br><span style="font-size:9px; color:var(--text-dim);">${window.currentActiveBank} › Slot ${window.currentActivePatchIndex + 1}</span>`;
                    window.lcdSafeUpdate(lcdText, html);
                }
                if (typeof window.renderPatchesForBank === 'function') {window.renderPatchesForBank(window.currentActiveBank);}
            }
        });
    }

    const menuSaveAs = document.getElementById('menu-save-as');
    const saveAsModal = document.getElementById('saveas-modal-backdrop');
    const saveAsCloseBtn = document.getElementById('saveas-close-btn');
    const saveAsCancelBtn = document.getElementById('saveas-btn-cancel');
    const saveAsConfirmBtn = document.getElementById('saveas-btn-confirm');

    let saveAsSelectedBank = '';
    let saveAsSelectedSlotIdx = -1;

    if (menuSaveAs && saveAsModal) {
        menuSaveAs.addEventListener('click', () => {
            saveAsModal.style.display = 'flex';

            const userBanks = Object.keys(window.loadedBanks).filter(b => !b.startsWith('Factory Bank'));
            saveAsSelectedBank = userBanks.includes(window.currentActiveBank) ? window.currentActiveBank : (userBanks[0] || '');
            saveAsSelectedSlotIdx = window.currentActivePatchIndex >= 0 ? window.currentActivePatchIndex : 0;

            const activeBank = window.loadedBanks[window.currentActiveBank];
            const activeName = (activeBank && activeBank[window.currentActivePatchIndex]) ? activeBank[window.currentActivePatchIndex].name : 'My Custom Patch';
            document.getElementById('saveas-preset-name').value = activeName;

            renderSaveAsBanks();
            renderSaveAsSlots();
        });

        const closeSaveAs = () => { saveAsModal.style.display = 'none'; };
        if (saveAsCloseBtn) {saveAsCloseBtn.addEventListener('click', closeSaveAs);}
        if (saveAsCancelBtn) {saveAsCancelBtn.addEventListener('click', closeSaveAs);}
        saveAsModal.addEventListener('click', (e) => {
            if (e.target === saveAsModal) {closeSaveAs();}
        });

        function renderSaveAsBanks() {
            const listContainer = document.getElementById('saveas-banks-list');
            if (!listContainer) {return;}
            listContainer.innerHTML = '';

            Object.keys(window.loadedBanks).forEach(bankName => {
                const isFactory = bankName.startsWith('Factory Bank');
                const item = document.createElement('div');
                item.className = 'saveas-bank-item' + (isFactory ? ' is-factory' : ' is-user');

                if (isFactory) {
                    item.innerHTML = `<span>${bankName}</span><span class="saveas-lock-badge">Lock</span>`;
                } else {
                    const isSelected = bankName === saveAsSelectedBank;
                    if (isSelected) {item.classList.add('is-selected');}
                    item.innerText = bankName;

                    item.addEventListener('click', () => {
                        saveAsSelectedBank = bankName;
                        renderSaveAsBanks();
                        renderSaveAsSlots();
                    });
                }
                listContainer.appendChild(item);
            });
        }

        function renderSaveAsSlots() {
            const gridContainer = document.getElementById('saveas-slots-grid');
            if (!gridContainer) {return;}
            gridContainer.innerHTML = '';

            const patches = window.loadedBanks[saveAsSelectedBank] || [];
            for (let i = 0; i < 128; i++) {
                const patch = patches[i] || { name: `[Empty Slot ${i+1}]` };
                const isSelected = i === saveAsSelectedSlotIdx;
                const isEmpty = patch.name.startsWith('INIT PATCH') || patch.name.startsWith('[Empty');

                const item = document.createElement('div');
                item.className = 'saveas-slot-item';
                if (isSelected) {item.classList.add('is-selected');}
                else if (isEmpty) {item.classList.add('is-empty');}
                else {item.classList.add('is-occupied');}
                item.innerText = `${(i+1).toString().padStart(3, '0')}: ${patch.name}`;

                item.addEventListener('click', () => {
                    saveAsSelectedSlotIdx = i;
                    renderSaveAsSlots();
                });
                gridContainer.appendChild(item);
            }
        }

        if (saveAsConfirmBtn) {
            saveAsConfirmBtn.addEventListener('click', () => {
                if (!saveAsSelectedBank) {
                    alert('Por favor, selecciona un banco de usuario válido.');
                    return;
                }
                if (saveAsSelectedSlotIdx < 0 || saveAsSelectedSlotIdx >= 128) {
                    alert('Por favor, selecciona un slot de destino.');
                    return;
                }

                const newName = document.getElementById('saveas-preset-name').value.trim();
                if (!newName) {
                    alert('Por favor, escribe un nombre para el preset.');
                    return;
                }

                const bank = window.loadedBanks[saveAsSelectedBank];
                if (!bank || !bank[saveAsSelectedSlotIdx]) {
                    alert('Error: el slot seleccionado no existe.');
                    return;
                }
                const targetPatch = bank[saveAsSelectedSlotIdx];

                if (!targetPatch) {
                    alert('Error interno: slot vacío. Intenta crear un nuevo banco.');
                    return;
                }

                const isOccupied = targetPatch && !targetPatch.name.startsWith('INIT PATCH') && !targetPatch.name.startsWith('[Empty');

                if (isOccupied) {
                    const confirmOverwrite = confirm(`¿Estás seguro de que deseas sobrescribir el preset existente "${targetPatch.name}" en el Slot ${saveAsSelectedSlotIdx + 1}?`);
                    if (!confirmOverwrite) {return;}
                }

                targetPatch.name = newName;
                for (let k = 0; k < 15; k++) {
                    targetPatch.unpackedBytes[224 + k] = k < targetPatch.name.length ? targetPatch.name.charCodeAt(k) : 0x20;
                }
                if (typeof window.updateUnpackedBytesFromCache === 'function') {
                    window.updateUnpackedBytesFromCache(targetPatch.unpackedBytes);
                }
                if (typeof updateSysExMonitor === 'function') {updateSysExMonitor(targetPatch.unpackedBytes);}

                window.currentActiveBank = saveAsSelectedBank;
                window.currentActivePatchIndex = saveAsSelectedSlotIdx;

                const localSelect = document.getElementById('local-bank-select');
                if (localSelect) {localSelect.value = saveAsSelectedBank;}
                if (typeof window.renderPatchesForBank === 'function') {window.renderPatchesForBank(saveAsSelectedBank);}

                if (window.triggerMidiDump) {window.triggerMidiDump(targetPatch);}

                if (typeof window._saveUserBanksToStorage === 'function') {
                    window._saveUserBanksToStorage();
                }

                const lcdText = document.getElementById('lcd-text');
                if (lcdText) {
                    const html = `<span class="lcd-label">SAVED AS</span><br><strong style="color:var(--accent-green);">${newName.toUpperCase()}</strong><br><span style="font-size:9px; color:var(--text-dim);">${saveAsSelectedBank} › Slot ${saveAsSelectedSlotIdx + 1}</span>`;
                    window.lcdSafeUpdate(lcdText, html);
                }
                closeSaveAs();
            });
        }
    }
};

/**
 * @purpose Controlador del módulo de efectos (Effects Engine Rack) central (fachada).
 * La lógica se ha extraído a:
 *   - effects_data.js       — FX_TYPE_NAMES estático
 *   - effects_controls.js   — controles del modal (apertura, slots, tipos, routing, páginas, modos)
 *   - effects_sliders.js    — sliders de envío y parámetros de slot
 *   - effects_modal_sync.js — sincronización de la UI del modal
 *   - effects_presets.js    — gestión de presets de efectos (guardar/cargar/eliminar)
 *   - effects_templates.js  — plantillas HTML + renderizado de parámetros activos
 * @purpose_en Central Effects Engine Rack controller (facade).
 */

/* global initEffectsControls, initEffectsSliders */

document.addEventListener('DOMContentLoaded', () => {
    initEffectsModal();
});

function initEffectsModal() {
    const backdrop = document.getElementById('fx-modal-backdrop');
    const dynamicArea = document.getElementById('fx-dynamic-editor-area');

    if (!backdrop || !dynamicArea) {return;}

    window._selectedFxSlot = 1;
    window._activeFxPage = 1;

    // Inicializar submódulos
    initEffectsControls();
    initEffectsSliders();

    // Sync UI (delegado a effects_modal_sync.js)
    if (typeof window.syncFxModalUIFromState === 'function') {
        window.syncFxModalUIFromState();
    }
    if (typeof window.syncFxModalUI === 'function') {
        window.syncFxModalUI();
    }

    // Bridge parameter listener
    if (window.dualMidiBridge && typeof window.dualMidiBridge.onParameterChanged === 'function') {
        window.dualMidiBridge.onParameterChanged(function(paramId) {
            if (backdrop.style.display === 'none') {return;}
            if (paramId.startsWith('fx')) {
                if (paramId.endsWith('_type')) {
                    if (typeof window.syncFxModalUI === 'function') {window.syncFxModalUI();}
                } else {
                    const slotPrefix = 'fx' + window._selectedFxSlot;
                    if (paramId.startsWith(slotPrefix)) {
                        if (typeof window.renderActiveEffectParams === 'function') {
                            window.renderActiveEffectParams();
                        }
                    }
                }
            }
        });
    }
}

window.fxPresetManager = {
    load: function(presetIndex, slot) {
        if (typeof window.applyFxPreset === 'function' && typeof window._loadAllFxPresets === 'function') {
            const allPresets = window._loadAllFxPresets();
            if (allPresets[presetIndex]) {
                window.applyFxPreset(allPresets[presetIndex], slot);
            }
        }
    },
    save: function(presetName, slot) {
        if (typeof window.saveFxPreset === 'function') {
            window.saveFxPreset(presetName, slot);
        }
    },
    delete: function(presetName) {
        if (typeof window.deleteFxPreset === 'function') {
            window.deleteFxPreset(presetName);
        }
    },
    getAll: function() {
        if (typeof window._loadAllFxPresets === 'function') {
            return window._loadAllFxPresets();
        }
        return [];
    }
};

/**
 * @purpose Modal controls for the FX editor: open/close, slot selection, type selectors, routing, pages, mode buttons.
 * @purpose_en FX modal interactive controls for managing all 4 FX slots and global routing/mode.
 */

// eslint-disable-next-line no-unused-vars -- called from initEffectsModal
function initEffectsControls() {
    const backdrop = document.getElementById('fx-modal-backdrop');
    const fxBtn = document.getElementById('programmer-fx-btn');
    const closeBtn = document.getElementById('fx-modal-close-btn');

    if (!fxBtn || !backdrop || !closeBtn) {return;}

    // Modal open
    fxBtn.addEventListener('click', (e) => {
        e.preventDefault();
        backdrop.style.display = 'flex';
        if (typeof window.syncFxModalUI === 'function') {window.syncFxModalUI();}
    });

    // Modal close
    closeBtn.addEventListener('click', () => {
        backdrop.style.display = 'none';
    });

    // Click outside to close
    backdrop.addEventListener('click', (e) => {
        if (e.target === backdrop) {
            backdrop.style.display = 'none';
        }
    });

    // Slot column selection
    for (let i = 1; i <= 4; i++) {
        const slotCol = document.getElementById(`fx-slot-${i}`);
        if (slotCol) {
            slotCol.addEventListener('click', (e) => {
                if (e.target.tagName === 'SELECT') {return;}

                document.querySelectorAll('.fx-slot-column').forEach(c => c.style.borderColor = 'var(--bg-hover)');
                slotCol.style.borderColor = 'var(--brand-accent)';
                window._selectedFxSlot = i;

                if (typeof window.renderActiveEffectParams === 'function') {
                    window.renderActiveEffectParams();
                }
            });
        }
    }

    // FX type select change
    document.querySelectorAll('.fx-type-select').forEach(sel => {
        sel.addEventListener('change', () => {
            const slot = sel.getAttribute('data-slot');
            const val = parseInt(sel.value);
            const displayEl = document.getElementById(`fx${slot}-type-mini-display`);
            if (displayEl) {displayEl.innerText = window.FX_TYPE_NAMES[val];}

            if (window.dualMidiBridge) {
                window.dualMidiBridge.setParameter(`fx${slot}_type`, val / 56.0);
            }
            if (parseInt(slot) === window._selectedFxSlot) {
                if (typeof window.renderActiveEffectParams === 'function') {
                    window.renderActiveEffectParams();
                }
            }
            // Notify vocoder mic module of FX type change
            if (typeof window._onFxTypeChanged === 'function') {
                window._onFxTypeChanged();
            }
        });
    });

    // Routing select
    const routingSelect = document.getElementById('fx-routing-select');
    if (routingSelect) {
        routingSelect.addEventListener('change', () => {
            if (window.dualMidiBridge) {
                window.dualMidiBridge.setParameter('fx_routing', parseInt(routingSelect.value) / 9.0);
            }
        });
    }

    // Page buttons
    const page1Btn = document.getElementById('fx-page-1-btn');
    const page2Btn = document.getElementById('fx-page-2-btn');
    if (page1Btn && page2Btn) {
        page1Btn.addEventListener('click', () => {
            page1Btn.classList.add('active');
            page2Btn.classList.remove('active');
            window._activeFxPage = 1;
            if (typeof window.renderActiveEffectParams === 'function') {
                window.renderActiveEffectParams();
            }
        });
        page2Btn.addEventListener('click', () => {
            page2Btn.classList.add('active');
            page1Btn.classList.remove('active');
            window._activeFxPage = 2;
            if (typeof window.renderActiveEffectParams === 'function') {
                window.renderActiveEffectParams();
            }
        });
    }

    // Mode buttons (Insert / Send / Bypass)
    const modeIns = document.getElementById('fx-mode-ins-btn');
    const modeSend = document.getElementById('fx-mode-send-btn');
    const modeByp = document.getElementById('fx-mode-bypass-btn');
    const sendLevelArea = document.getElementById('fx-send-level-area');

    const setSendLevelVisibility = (modeVal) => {
        if (!sendLevelArea) {return;}
        sendLevelArea.style.display = (modeVal === 1) ? 'flex' : 'none';
    };

    if (modeIns && modeSend && modeByp) {
        modeIns.addEventListener('click', () => {
            modeIns.classList.add('active');
            [modeSend, modeByp].forEach(b => b.classList.remove('active'));
            setSendLevelVisibility(0);
            if (window.dualMidiBridge) {window.dualMidiBridge.setParameter('fx_mode', 0.0);}
        });
        modeSend.addEventListener('click', () => {
            modeSend.classList.add('active');
            [modeIns, modeByp].forEach(b => b.classList.remove('active'));
            setSendLevelVisibility(1);
            if (window.dualMidiBridge) {window.dualMidiBridge.setParameter('fx_mode', 0.5);}
        });
        modeByp.addEventListener('click', () => {
            modeByp.classList.add('active');
            [modeIns, modeSend].forEach(b => b.classList.remove('active'));
            setSendLevelVisibility(2);
            if (window.dualMidiBridge) {window.dualMidiBridge.setParameter('fx_mode', 1.0);}
        });
    }
}

/**
 * @purpose Static definition of effect type names for all 56 FX types.
 * @purpose_en Maps numeric FX type indices to human-readable display names.
 */

const FX_TYPE_NAMES = ['Bypass', 'Ambience', 'tcDeepVerb', 'RoomRev', 'VintageRoom', 'HallReverb', 'ChamberRev', 'Plate Reverb', 'Rich Plate', 'Gated Reverb', 'Reverse Reverb', 'ChorusRev', 'DelayRev', 'FlangerRev', 'MidasEQ', 'Enhancer', 'FairComp', 'MBDistortion', 'RackAmp', 'Edison', 'AutoPan/Trem', 'NoiseGate', 'Delay', '3Tap Delay', '4Tap Delay', 'T-RayDelay', 'DecimatorDelay', 'ModDlyRev', 'Stereo Chorus', 'Chorus-D', 'Stereo Flanger', 'Stereo Phaser', 'Mood Filter', 'Dual Pitch', 'Vintage Pitch', 'Rotary Speaker', 'BBD Chorus', 'Solina Ens', 'Ring Mod', 'Space Echo', 'Tape Delay', 'Shimmer Dly', 'Granular Dly', 'Pattern Frz', 'Duck Delay', 'Spectral Dly', 'Freq Shifter', 'HarmonicReso', 'Combulator', 'MB Vocoder', 'OS Distortion', 'WaveShaper', 'FDN Reverb', 'Zita Reverb', 'Nimbus', 'Bonsai', 'TreeMonster'];
window.FX_TYPE_NAMES = FX_TYPE_NAMES;

/**
 * @purpose Sincronización de la UI del modal de efectos: lectura de parámetros y actualización de controles.
 * Extraído de effects.js como parte de la modularización.
 * @purpose_en FX modal UI sync: reads parameters and updates controls.
 */

/**
 * Set a gain slider position from a param value read from cache or patch bytes.
 * @param {string} paramId - Parameter identifier (e.g., 'fx1_gain')
 * @param {number} fallbackByte - Byte offset in unpacked bytes array
 */
function _setGainSliderPos(paramId, fallbackByte) {
    if (typeof window._readFxParamValue !== 'function') {return;}
    const val = window._readFxParamValue(paramId, fallbackByte, 1.0);
    const slider = document.querySelector('[data-param="' + paramId + '"] .v-slider');
    if (!slider) {return;}
    const handle = slider.querySelector('.handle');
    if (!handle) {return;}
    const handleHeight = 12;
    const limit = slider.getBoundingClientRect().height - handleHeight;
    if (limit > 0) {
        handle.style.top = ((1.0 - val) * limit) + 'px';
    }
}
window._setGainSliderPos = _setGainSliderPos;

/**
 * Sync all modal UI controls from the current patch/bridge state.
 */
// eslint-disable-next-line no-unused-vars -- called from effects.js
function syncFxModalUI() {
    const routingSelect = document.getElementById('fx-routing-select');
    const modeIns = document.getElementById('fx-mode-ins-btn');
    const modeSend = document.getElementById('fx-mode-send-btn');
    const modeByp = document.getElementById('fx-mode-bypass-btn');
    const sendLevelArea = document.getElementById('fx-send-level-area');
    const FX_TYPE_NAMES = window.FX_TYPE_NAMES || [];

    function setSendLevelVisibility(modeVal) {
        if (!sendLevelArea) {return;}
        sendLevelArea.style.display = (modeVal === 1) ? 'flex' : 'none';
    }

    for (let i = 1; i <= 4; i++) {
        if (typeof window._readFxParamValue !== 'function') {continue;}
        const offsetType = i === 1 ? 166 : (i === 2 ? 179 : (i === 3 ? 192 : 205));
        const typeValNormalized = window._readFxParamValue('fx' + i + '_type', offsetType, 0.0);
        const typeVal = Math.round(typeValNormalized * 56.0);

        const selectEl = document.querySelector('.fx-type-select[data-slot="' + i + '"]');
        if (selectEl) {selectEl.value = typeVal;}

        const offsetGain = i === 1 ? 218 : (i === 2 ? 219 : (i === 3 ? 220 : 221));
        _setGainSliderPos('fx' + i + '_gain', offsetGain);

        const offsetParam = i === 1 ? 167 : (i === 2 ? 180 : (i === 3 ? 193 : 206));
        const params = [];
        for (let p = 1; p <= 12; p++) {
            params.push(window._readFxParamValue('fx' + i + '_param' + p, offsetParam + p - 1, 0.5));
        }
        const gainVal = window._readFxParamValue('fx' + i + '_gain', offsetGain, 1.0);

        let displayName = FX_TYPE_NAMES[typeVal] || 'Bypass';
        if (typeVal > 0 && typeof window.findMatchingFxPresetName === 'function') {
            const matchedName = window.findMatchingFxPresetName(typeValNormalized, gainVal, params);
            if (matchedName) {
                displayName = matchedName;
            }
        }

        const displayEl = document.getElementById('fx' + i + '-type-mini-display');
        if (displayEl) {
            displayEl.innerText = displayName;
            displayEl.title = displayName;
        }
    }

    if (typeof window.syncFxPresetDropdowns === 'function') {
        window.syncFxPresetDropdowns();
    }

    if (typeof window._readFxParamValue === 'function') {
        const routeVal = Math.round(window._readFxParamValue('fx_routing', 165, 0.0) * 9.0);
        if (routingSelect) {routingSelect.value = routeVal;}

        const modeVal = Math.round(window._readFxParamValue('fx_mode', 222, 0.0) * 2.0);
        if (modeIns && modeSend && modeByp) {
            [modeIns, modeSend, modeByp].forEach(function(b) { b.classList.remove('active'); });
            if (modeVal === 0) {modeIns.classList.add('active');}
            else if (modeVal === 1) {modeSend.classList.add('active');}
            else {modeByp.classList.add('active');}
        }
        setSendLevelVisibility(modeVal);

        const sendLevel = window._readFxParamValue('fx_send_level', 225, 0.5);
        const sendLevelSliderEl = document.getElementById('fx-send-level-slider');
        if (sendLevelSliderEl) {
            const handle = sendLevelSliderEl.querySelector('.handle');
            if (handle) {
                const handleHeight = 12;
                const limit = sendLevelSliderEl.getBoundingClientRect().height - handleHeight;
                if (limit > 0) {
                    handle.style.top = ((1.0 - sendLevel) * limit) + 'px';
                }
            }
        }
    }

    if (typeof window.renderActiveEffectParams === 'function') {
        window.renderActiveEffectParams();
    }
}

/**
 * Sync FX modal UI from external state (called from panel_controls_binder.js).
 */
window.syncFxModalUIFromState = function() {
    const backdrop = document.getElementById('fx-modal-backdrop');
    if (backdrop && backdrop.style.display !== 'none') {
        syncFxModalUI();
    }
};

// eslint-disable-next-line no-var
var Logger = globalThis.Logger || console;

/**
 * @purpose Facade for FX presets library. Actual implementation in:
 *          - effects_presets_storage.js     (_loadAllFxPresets)
 *          - effects_presets_apply.js       (applyFxPreset)
 *          - effects_presets_bank_extract.js (extractAndSaveNewPresetsFromBank)
 *          - effects_presets_data.js        (DEFAULT_FX_PRESETS, escapeHtml)
 *          - effects_presets_render.js      (_renderFxPresetList, findMatchingFxPresetName)
 *          - effects_presets_filter.js      (filtering helpers)
 * @purpose_en FX presets library service — facade.
 */

window.saveFxPreset = function (presetName, slotNumber) {
  if (!presetName || presetName.trim() === '') { return; }
  presetName = presetName.trim().replace(/[<>"'&]/g, '');
  if (!presetName) { return; }
  slotNumber = slotNumber || window._selectedFxSlot || 1;
  const bridge = window.dualMidiBridge;
  if (!bridge || !bridge.parameterCache) { return; }

  const preset = {
    name: presetName.trim(),
    slot: slotNumber,
    type: _readFxParam('fx' + slotNumber + '_type', slotNumber === 1 ? 166 : (slotNumber === 2 ? 179 : (slotNumber === 3 ? 192 : 205)), 0.0),
    params: [],
    created: Date.now()
  };
  for (let i = 1; i <= 12; i++) {
    const offsetStart = slotNumber === 1 ? 167 : (slotNumber === 2 ? 180 : (slotNumber === 3 ? 193 : 206));
    preset.params.push(_readFxParam('fx' + slotNumber + '_param' + i, offsetStart + i - 1, 0.5));
  }
  preset.gain = _readFxParam('fx' + slotNumber + '_gain', slotNumber === 1 ? 218 : (slotNumber === 2 ? 219 : (slotNumber === 3 ? 220 : 221)), 1.0);

  const allPresets = _loadAllFxPresets();
  let existingIdx = -1;
  for (let j = 0; j < allPresets.length; j++) {
    if (allPresets[j].name === preset.name) { existingIdx = j; break; }
  }
  if (existingIdx >= 0) {
    allPresets[existingIdx] = preset;
  } else {
    allPresets.push(preset);
  }

  try {
    localStorage.setItem('abd-eep-fx-presets', JSON.stringify(allPresets));
  } catch (e) {
    Logger.warn('[FX Presets] Error saving to localStorage:', e);
  }

  if (typeof window._renderFxPresetList === 'function') { window._renderFxPresetList(); }
  if (typeof window.syncFxPresetDropdowns === 'function') { window.syncFxPresetDropdowns(); }
  if (typeof window.lcdSafeUpdate === 'function') {
    const lcd = document.getElementById('lcd-screen-main');
    if (lcd) { window.lcdSafeUpdate(lcd, 'FX Preset Saved: ' + preset.name, null, { useQueue: false }); }
  }
};

/** @private Reads an FX param value from the bridge parameterCache */
function _readFxParam(paramId, defaultOffset, fallback) {
  const bridge = window.dualMidiBridge;
  if (!bridge || !bridge.parameterCache) { return fallback; }
  const val = bridge.parameterCache[paramId];
  return (val !== undefined && val !== null) ? val : fallback;
}

window.deleteFxPreset = function (presetName) {
  const allPresets = _loadAllFxPresets();
  const filtered = [];
  for (let i = 0; i < allPresets.length; i++) {
    if (allPresets[i].name !== presetName) {
      filtered.push(allPresets[i]);
    }
  }
  if (filtered.length !== allPresets.length) {
    try {
      localStorage.setItem('abd-eep-fx-presets', JSON.stringify(filtered));
    } catch (e) { /* ignore */ }
    if (typeof window._renderFxPresetList === 'function') { window._renderFxPresetList(); }
    if (typeof window.syncFxPresetDropdowns === 'function') { window.syncFxPresetDropdowns(); }
  }
};

// Fallback stubs (loaded before effects_presets_render.js in index.html)
window._renderFxPresetList = window._renderFxPresetList || function () {};
window.findMatchingFxPresetName = window.findMatchingFxPresetName || function () { return null; };

/**
 * @purpose FX preset application: applies a saved preset to the bridge and updates UI.
 * @classification Module/Effects/Presets/Apply
 */

window.applyFxPreset = function (presetData, slotNumber) {
  slotNumber = slotNumber || window._selectedFxSlot || 1;
  const bridge = window.dualMidiBridge;
  if (!bridge) { return; }

  bridge.setParameter('fx' + slotNumber + '_type', presetData.type);

  for (let i = 0; i < 12 && i < presetData.params.length; i++) {
    bridge.setParameter('fx' + slotNumber + '_param' + (i + 1), presetData.params[i]);
  }

  if (presetData.gain !== undefined) {
    bridge.setParameter('fx' + slotNumber + '_gain', presetData.gain);
  }

  const selectEl = document.querySelector('.fx-type-select[data-slot="' + slotNumber + '"]');
  if (selectEl) {
    const typeVal = Math.round(presetData.type * 56.0);
    selectEl.value = typeVal;
    const displayEl = document.getElementById('fx' + slotNumber + '-type-mini-display');
    if (displayEl) {
      displayEl.innerText = (window.FX_TYPE_NAMES && window.FX_TYPE_NAMES[typeVal]) || 'Bypass';
    }
  }

  if (typeof window._setGainSliderPos === 'function') {
    const offsetMap = { 1: 218, 2: 219, 3: 220, 4: 221 };
    window._setGainSliderPos('fx' + slotNumber + '_gain', offsetMap[slotNumber] || 221);
  }

  if (slotNumber === window._selectedFxSlot) {
    if (typeof window.renderActiveEffectParams === 'function') {
      window.renderActiveEffectParams();
    }
  }

  if (typeof window.lcdSafeUpdate === 'function') {
    const lcd = document.getElementById('lcd-screen-main');
    if (lcd) {
      window.lcdSafeUpdate(lcd, 'FX Preset Loaded: ' + presetData.name + ' \u2192 FX' + slotNumber, null, { useQueue: false });
    }
  }
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { applyFxPreset: window.applyFxPreset };
}

/**
 * @purpose FX preset bank extraction: scans patches from a bank dump and extracts
 *          new FX and sequencer presets that don't already exist.
 * @classification Module/Effects/Presets/BankExtract
 */

var Logger = globalThis.Logger || console;

window.extractAndSaveNewPresetsFromBank = function (bankName, patches) {
  if (!Array.isArray(patches)) { return; }

  const userFxPresets = (typeof window._loadAllFxPresets === 'function') ? window._loadAllFxPresets() : [];
  const userSeqPresets = (typeof window._loadUserSeqPresets === 'function') ? window._loadUserSeqPresets() : [];
  let newFxCount = 0;
  let newSeqCount = 0;

  const fxSlotConfigs = [
    { id: 1, typeByte: 166, paramStart: 167, gainByte: 218 },
    { id: 2, typeByte: 179, paramStart: 180, gainByte: 219 },
    { id: 3, typeByte: 192, paramStart: 193, gainByte: 220 },
    { id: 4, typeByte: 205, paramStart: 206, gainByte: 221 }
  ];

  for (let pi = 0; pi < patches.length; pi++) {
    const patch = patches[pi];
    if (!patch || !patch.unpackedBytes) { continue; }
    const b = patch.unpackedBytes;

    // Scan FX slots
    for (let si = 0; si < fxSlotConfigs.length; si++) {
      const slot = fxSlotConfigs[si];
      const typeVal = b[slot.typeByte];
      const typeNames = window.FX_TYPE_NAMES;
      if (typeVal > 0 && typeNames && typeVal < typeNames.length) {
        const typeName = typeNames[typeVal];
        const typeValNorm = typeVal / 56.0;
        const gain = b[slot.gainByte] / 255.0;
        const params = [];
        for (let p = 0; p < 12; p++) {
          params.push(b[slot.paramStart + p] / 255.0);
        }

        const alreadyExists = (typeof window._isFxPresetDuplicate === 'function')
          ? window._isFxPresetDuplicate(typeVal, gain, params, userFxPresets)
          : false;

        if (!alreadyExists) {
          userFxPresets.push({
            name: typeName + ' (' + patch.name + ')',
            slot: slot.id,
            type: typeValNorm,
            gain: gain,
            params: params,
            created: Date.now()
          });
          newFxCount++;
        }
      }
    }

    // Scan sequencer steps
    const steps = [];
    let max = 0;
    let min = 255;
    let isZero = true;
    for (let s = 0; s < 32; s++) {
      const val = b[123 + s];
      steps.push(val);
      if (val !== 128) { isZero = false; }
      if (val > max) { max = val; }
      if (val < min) { min = val; }
    }

    if (!isZero && (max - min) >= 15) {
      const seqExists = (typeof window._isSeqPresetDuplicate === 'function')
        ? window._isSeqPresetDuplicate(steps, userSeqPresets)
        : false;

      if (!seqExists) {
        userSeqPresets.push({ name: patch.name + ' Seq', steps: steps });
        newSeqCount++;
      }
    }
  }

  if (newFxCount > 0) {
    try { localStorage.setItem('abd-eep-fx-presets', JSON.stringify(userFxPresets)); } catch (e) { /* ignore */ }
    if (typeof window._renderFxPresetList === 'function') { window._renderFxPresetList(); }
  }
  if (newSeqCount > 0) {
    try { localStorage.setItem('abd-eep-seq-presets', JSON.stringify(userSeqPresets)); } catch (e) { /* ignore */ }
    if (typeof window.initSequencerPresets === 'function') { window.initSequencerPresets(); }
  }

  if (newFxCount > 0 || newSeqCount > 0) {
    Logger.log('[AutoExtractor] Extracted from bank \'' + bankName + '\': ' + newFxCount + ' new FX presets and ' + newSeqCount + ' new Sequence presets.');
  }
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { extractAndSaveNewPresetsFromBank: window.extractAndSaveNewPresetsFromBank };
}

/**
 * @purpose FX Presets filtering logic: duplicate detection, matching.
 * Extracted from effects_presets.js for modularization.
 * @classification Module/Effects/Presets
 */

/**
 * Check if an FX preset configuration already exists in a given preset list.
 * Compares by type (rounded), gain (within 0.03 tolerance), and 12 params (within 0.03 tolerance).
 * @param {number} typeVal - Raw FX type value (0-56)
 * @param {number} gain - Gain value (0-1)
 * @param {number[]} params - Array of 12 param values (0-1)
 * @param {object[]} presetList - Array of preset objects with type, gain, params
 * @returns {boolean} true if matching preset found
 */
window._findMatchingFxPreset = function(typeVal, gain, params, presetList) {
    if (!Array.isArray(presetList)) { return false; }
    for (let i = 0; i < presetList.length; i++) {
        const p = presetList[i];
        if (Math.round(p.type * 56) === typeVal) {
            if (Math.abs(p.gain - gain) > 0.03) { continue; }
            let match = true;
            for (let j = 0; j < 12; j++) {
                if (Math.abs(p.params[j] - params[j]) > 0.03) {
                    match = false;
                    break;
                }
            }
            if (match) { return true; }
        }
    }
    return false;
};

/**
 * Check if an FX preset config is a duplicate across factory AND user presets.
 * @param {number} typeVal - Raw FX type value
 * @param {number} gain - Gain value
 * @param {number[]} params - Array of 12 param values
 * @param {object[]} userPresets - User FX presets array
 * @returns {boolean} true if already exists in factory or user presets
 */
window._isFxPresetDuplicate = function(typeVal, gain, params, userPresets) {
    // Check factory presets
    if (Array.isArray(window.FACTORY_FX_PRESETS)) {
        if (window._findMatchingFxPreset(typeVal, gain, params, window.FACTORY_FX_PRESETS)) {
            return true;
        }
    }
    // Check user presets
    return window._findMatchingFxPreset(typeVal, gain, params, userPresets);
};

/**
 * Check if a SEQ preset (32 steps) already exists in a given preset list.
 * Compares steps with tolerance of 5.
 * @param {number[]} steps - Array of 32 step values (0-255)
 * @param {object[]} presetList - Array of seq preset objects with steps property
 * @returns {boolean} true if matching preset found
 */
window._findMatchingSeqPreset = function(steps, presetList) {
    if (!Array.isArray(presetList)) { return false; }
    for (let i = 0; i < presetList.length; i++) {
        const p = presetList[i];
        if (!p.steps || p.steps.length < 32) { continue; }
        let match = true;
        for (let j = 0; j < 32; j++) {
            if (Math.abs(p.steps[j] - steps[j]) > 5) {
                match = false;
                break;
            }
        }
        if (match) { return true; }
    }
    return false;
};

/**
 * Check if a SEQ preset config is a duplicate across factory AND user presets.
 * @param {number[]} steps - Array of 32 step values
 * @param {object[]} userSeqPresets - User SEQ presets array
 * @returns {boolean} true if already exists in factory or user presets
 */
window._isSeqPresetDuplicate = function(steps, userSeqPresets) {
    // Check factory presets
    if (window.FACTORY_SEQ_PRESETS) {
        if (window._findMatchingSeqPreset(steps, window.FACTORY_SEQ_PRESETS)) {
            return true;
        }
    }
    // Check user presets
    return window._findMatchingSeqPreset(steps, userSeqPresets);
};

/**
 * @purpose FX preset list rendering and matching logic.
 * Extracted from effects_presets.js — DOM rendering + preset name matching.
 * Depends on: effects_presets_data.js (escapeHtml, DEFAULT_FX_PRESETS), effects_presets.js (_loadAllFxPresets)
 */

function _renderFxPresetList() {
    const listEl = document.getElementById('fx-preset-list');
    if (!listEl) {return;}
    const allPresets = window._loadAllFxPresets();
    if (allPresets.length === 0) {
        listEl.innerHTML = '<div class="fx-preset-empty">No FX presets saved yet</div>';
        return;
    }
    const filterMode = window._fxPresetFilterMode || 'active';
    const slot = window._selectedFxSlot || 1;
    const offsetType = slot === 1 ? 166 : (slot === 2 ? 179 : (slot === 3 ? 192 : 205));
    const activeTypeNorm = (typeof window._readFxParamValue === 'function') ? window._readFxParamValue('fx' + slot + '_type', offsetType, 0.0) : -1;
    const activeType = (activeTypeNorm >= 0) ? Math.round(activeTypeNorm * 56.0) : -1;
    const displayIndices = [];

    if (filterMode === 'active' && activeType >= 0) {
        for (let i = allPresets.length - 1; i >= 0; i--) {
            if (Math.round(allPresets[i].type * 56.0) === activeType) {displayIndices.push(i);}
        }
    } else {
        for (let i = allPresets.length - 1; i >= 0; i--) {displayIndices.push(i);}
    }

    const slotNum = slot;
    const filterLabel = (activeType >= 0) ? (window.FX_TYPE_NAMES[activeType] || ('FX' + slotNum)) : ('FX' + slotNum);

    let html = '<div class="fx-preset-filter-bar">' +
        '<button class="fx-preset-filter-btn' + (filterMode === 'active' ? ' active' : '') + '" data-filter="active">' + (typeof globalThis.escapeHtml === 'function' ? globalThis.escapeHtml(filterLabel) : filterLabel) + '</button>' +
        '<button class="fx-preset-filter-btn' + (filterMode === 'all' ? ' active' : '') + '" data-filter="all">Ver todos</button>' +
    '</div>';

    if (displayIndices.length === 0) {
        html += '<div class="fx-preset-empty">No presets for this FX type</div>';
    } else if (filterMode === 'all') {
        const groups = {};
        displayIndices.forEach(function(idx) {
            const p = allPresets[idx];
            const ti = Math.round(p.type * 56);
            if (!groups[ti]) {groups[ti] = [];}
            groups[ti].push(idx);
        });
        const typeOrder = [];
        displayIndices.forEach(function(idx) {
            const ti = Math.round(allPresets[idx].type * 56);
            if (typeOrder.indexOf(ti) === -1) {typeOrder.push(ti);}
        });
        let firstHeader = true;
        typeOrder.forEach(function(ti) {
            const tn = window.FX_TYPE_NAMES[ti] || '?';
            const cnt = groups[ti].length;
            const hdrClass = 'fx-preset-group-header' + (firstHeader ? '' : ' fx-preset-group-sep');
            html += '<div class="' + hdrClass + '">' + (typeof globalThis.escapeHtml === 'function' ? globalThis.escapeHtml(tn) : tn) + ' <span class="fx-preset-group-count">(' + cnt + ')</span></div>';
            firstHeader = false;
            groups[ti].forEach(function(idx) {
                const name = allPresets[idx].name;
                const safeName = typeof globalThis.escapeHtml === 'function' ? globalThis.escapeHtml(name) : name;
                html += '<div class="fx-preset-item" data-preset-index="' + idx + '">' +
                    '<div title="Apply ' + safeName + ' to FX' + slotNum + '">' +
                        '<span class="fx-preset-name">' + safeName + '</span> ' +
                    '</div>' +
                    '<button class="btn btn-xs fx-preset-delete-btn" data-ctrl-tooltip="Delete preset">\u2715</button>' +
                '</div>';
            });
        });
    } else {
        displayIndices.forEach(function(idx) {
            const name = allPresets[idx].name;
            const safeName = typeof globalThis.escapeHtml === 'function' ? globalThis.escapeHtml(name) : name;
            html += '<div class="fx-preset-item" data-preset-index="' + idx + '">' +
                '<div title="Apply ' + safeName + ' to FX' + slotNum + '">' +
                    '<span class="fx-preset-name">' + safeName + '</span> ' +
                '</div>' +
                '<button class="btn btn-xs fx-preset-delete-btn" data-ctrl-tooltip="Delete preset">\u2715</button>' +
            '</div>';
        });
    }
    listEl.innerHTML = html;

    listEl.querySelectorAll('.fx-preset-item').forEach(function(item) {
        const idx = parseInt(item.getAttribute('data-preset-index'));
        if (isNaN(idx) || idx < 0 || idx >= allPresets.length) {return;}
        item.querySelector('div[title]').addEventListener('click', function() {
            window.applyFxPreset(allPresets[idx], slot);
        });
        const delBtn = item.querySelector('.fx-preset-delete-btn');
        if (delBtn) {
            delBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                window.deleteFxPreset(allPresets[idx].name);
            });
        }
    });

    listEl.querySelectorAll('.fx-preset-filter-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
            window._fxPresetFilterMode = btn.getAttribute('data-filter');
            _renderFxPresetList();
        });
    });
}
window._renderFxPresetList = _renderFxPresetList;

window.findMatchingFxPresetName = function(type, gain, params) {
    if (type === 0.0) {return 'Bypass';}

    // Buscar en presets de usuario primero
    const userPresets = window._loadAllFxPresets();
    for (let i = 0; i < userPresets.length; i++) {
        const p = userPresets[i];
        if (Math.round(p.type * 56) === Math.round(type * 56)) {
            let match = true;
            if (Math.abs(p.gain - gain) > 0.03) {match = false;}
            for (let j = 0; j < 12 && j < p.params.length; j++) {
                if (Math.abs(p.params[j] - params[j]) > 0.03) {
                    match = false;
                    break;
                }
            }
            if (match) {return p.name;}
        }
    }

    // Buscar en presets de fábrica (FACTORY_FX_PRESETS)
    if (window.FACTORY_FX_PRESETS) {
        for (let i = 0; i < window.FACTORY_FX_PRESETS.length; i++) {
            const p = window.FACTORY_FX_PRESETS[i];
if (Math.round(p.type * 56) === Math.round(type * 56)) {
                let match = true;
                if (Math.abs(p.gain - gain) > 0.03) {match = false;}
                for (let j = 0; j < 12 && j < p.params.length; j++) {
                    if (Math.abs(p.params[j] - params[j]) > 0.03) {
                        match = false;
                        break;
                    }
                }
                if (match) {return p.name;}
            }
        }
    }
    return null;
};

/**
 * @purpose FX presets storage: loads presets from localStorage and merges with
 *          DEFAULT_FX_PRESETS and FACTORY_FX_PRESETS.
 * @classification Module/Effects/Presets/Storage
 */

var Logger = globalThis.Logger || console;

function _loadAllFxPresets() {
  let userPresets = [];
  try {
    const raw = localStorage.getItem('abd-eep-fx-presets');
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) { userPresets = parsed; }
    }
  } catch (e) { /* ignore JSON parse errors */ }

  const list = [].concat(userPresets);
  const existingNames = {};
  for (let ui = 0; ui < userPresets.length; ui++) {
    existingNames[userPresets[ui].name] = true;
  }

  const defaults = globalThis.DEFAULT_FX_PRESETS || [];
  for (let di = 0; di < defaults.length; di++) {
    if (!existingNames[defaults[di].name]) {
      list.push(defaults[di]);
      existingNames[defaults[di].name] = true;
    }
  }

  const factory = (typeof window !== 'undefined' && Array.isArray(window.FACTORY_FX_PRESETS)) ? window.FACTORY_FX_PRESETS : [];
  for (let fi = 0; fi < factory.length; fi++) {
    if (!existingNames[factory[fi].name]) {
      list.push(factory[fi]);
      existingNames[factory[fi].name] = true;
    }
  }

  return list;
}

window._loadAllFxPresets = _loadAllFxPresets;

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { _loadAllFxPresets: _loadAllFxPresets };
}

/**
 * @purpose Effects parameter renderer: reads FX params, generates template HTML, wires interactive controls.
 * Extracted from effects_templates.js.
 */

function renderActiveEffectParams() {
    const dynamicArea = document.getElementById('fx-dynamic-editor-area');
    const activeSlotLabel = document.getElementById('fx-screen-active-slot');
    if (!dynamicArea) {return;}

    const selectedSlot = window._selectedFxSlot || 1;
    const typeSelect = document.querySelector(`.fx-type-select[data-slot="${selectedSlot}"]`);
    if (!typeSelect) {return;}
    const effectType = parseInt(typeSelect.value);

    const offsetStart = selectedSlot === 1 ? 167 : (selectedSlot === 2 ? 180 : (selectedSlot === 3 ? 193 : 206));

    if (activeSlotLabel) {
        const offsetGain = selectedSlot === 1 ? 218 : (selectedSlot === 2 ? 219 : (selectedSlot === 3 ? 220 : 221));
        const gainVal = window._readFxParamValue(`fx${selectedSlot}_gain`, offsetGain, 1.0);
        const paramsAll = [];
        for (let p = 1; p <= 12; p++) {
            paramsAll.push(window._readFxParamValue(`fx${selectedSlot}_param${p}`, offsetStart + p - 1, 0.5));
        }
        let displayName = window.FX_TYPE_NAMES[effectType] || 'Bypass';
        if (effectType > 0 && typeof window.findMatchingFxPresetName === 'function') {
            const matchedName = window.findMatchingFxPresetName(effectType / 56.0, gainVal, paramsAll);
            if (matchedName) {
                displayName = matchedName;
            }
        }
        activeSlotLabel.innerText = `Slot: FX${selectedSlot} (${displayName})`;
    }

    const pVals = Array(8).fill(0.5);
    for (let i = 0; i < 8; i++) {
        pVals[i] = window._readFxParamValue(`fx${selectedSlot}_param${i+1}`, offsetStart + i, 0.5);
    }

    dynamicArea.innerHTML = '';

    if (effectType === 0) { // BYPASS
        dynamicArea.innerHTML = '<span style="color:var(--text-faint); font-size:12px; font-family:\'Share Tech Mono\', monospace; text-transform:uppercase;">Effect Bypassed</span>';
        return;
    }

    const renderer = window._getFXTemplateRenderer(effectType);
    const templateHtml = renderer(pVals, effectType, selectedSlot);
    dynamicArea.innerHTML = templateHtml;

    dynamicArea.querySelectorAll('.v-slider').forEach((slider, idx) => {
        const handle = slider.querySelector('.handle');
        let isDragging = false;

        const updateVal = (clientY) => {
            const rect = slider.getBoundingClientRect();
            const handleHeight = 16;
            const limit = rect.height - handleHeight;
            let y = clientY - rect.top - (handleHeight / 2);
            y = Math.max(0, Math.min(limit, y));
            handle.style.top = y + 'px';

            const val = 1.0 - (y / limit);
            if (window.dualMidiBridge) {
                window.dualMidiBridge.setParameter(`fx${selectedSlot}_param${idx+1}`, val);
            }
        };

        function onSliderMove(e) {
            if (isDragging) {updateVal(e.clientY);}
        }
        function onSliderEnd() {
            isDragging = false;
            window.removeEventListener('mousemove', onSliderMove);
            window.removeEventListener('mouseup', onSliderEnd);
        }
        slider.addEventListener('mousedown', (e) => {
            isDragging = true;
            updateVal(e.clientY);
            e.preventDefault();
            e.stopPropagation();
            window.addEventListener('mousemove', onSliderMove);
            window.addEventListener('mouseup', onSliderEnd);
        });
    });

    dynamicArea.querySelectorAll('.knob-ring').forEach((knob, idx) => {
        const pointer = knob.querySelector('.knob-pointer');
        let isDragging = false;
        let startY = 0;
        let startVal = 0.5;

        if (pVals && pVals[idx] !== undefined) {
            startVal = pVals[idx];
        }

        function onKnobMove(e) {
            if (!isDragging) {return;}
            const dy = startY - e.clientY;
            let val = startVal + (dy / 150.0);
            val = Math.max(0.0, Math.min(1.0, val));

            if (pointer) {
                pointer.style.transform = `translateX(-50%) rotate(${(val * 270) - 135}deg)`;
            }

            if (window.dualMidiBridge) {
                window.dualMidiBridge.setParameter(`fx${selectedSlot}_param${idx+1}`, val);
            }
        }
        function onKnobEnd(e) {
            if (isDragging) {
                isDragging = false;
                const dy = startY - e.clientY;
                const val = startVal + (dy / 150.0);
                startVal = Math.max(0.0, Math.min(1.0, val));
            }
            window.removeEventListener('mousemove', onKnobMove);
            window.removeEventListener('mouseup', onKnobEnd);
        }
        knob.addEventListener('mousedown', (e) => {
            isDragging = true;
            startY = e.clientY;
            e.preventDefault();
            e.stopPropagation();
            window.addEventListener('mousemove', onKnobMove);
            window.addEventListener('mouseup', onKnobEnd);
        });
    });
}
window.renderActiveEffectParams = renderActiveEffectParams;

