/**
 * @purpose Slider drag handlers for the FX modal: send level and slot parameter sliders.
 * @purpose_en Send level and FX slot parameter vertical slider mouse drag interaction.
 */

// eslint-disable-next-line no-unused-vars -- called from initEffectsModal
function initEffectsSliders() {
    // Send level slider
    const sendLevelSlider = document.getElementById('fx-send-level-slider');
    if (sendLevelSlider) {
        const handle = sendLevelSlider.querySelector('.handle');
        if (handle) {
            let isDragging = false;

            const updateSendLevel = (clientY) => {
                const rect = sendLevelSlider.getBoundingClientRect();
                const handleHeight = 12;
                const limit = rect.height - handleHeight;
                let y = clientY - rect.top - (handleHeight / 2);
                y = Math.max(0, Math.min(limit, y));
                handle.style.top = y + 'px';

                const val = 1.0 - (y / limit);
                if (window.dualMidiBridge) {
                    window.dualMidiBridge.setParameter('fx_send_level', val);
                }
            };

            function onSliderMove(e) {
                if (isDragging) {updateSendLevel(e.clientY);}
            }
            function onSliderEnd() {
                isDragging = false;
                window.removeEventListener('mousemove', onSliderMove);
                window.removeEventListener('mouseup', onSliderEnd);
            }
            sendLevelSlider.addEventListener('mousedown', (e) => {
                isDragging = true;
                updateSendLevel(e.clientY);
                e.preventDefault();
                e.stopPropagation();
                window.addEventListener('mousemove', onSliderMove);
                window.addEventListener('mouseup', onSliderEnd);
            });
        }
    }

    // Slot column v-sliders (individual FX parameter sliders in slot columns)
    const backdrop = document.getElementById('fx-modal-backdrop');
    if (backdrop) {
        backdrop.querySelectorAll('.fx-slot-column .v-slider').forEach(slider => {
            const ctrlUnit = slider.closest('[data-param]');
            if (!ctrlUnit) {return;}
            const paramId = ctrlUnit.getAttribute('data-param');
            const handle = slider.querySelector('.handle');

            let isDragging = false;

            const updateSliderPos = (clientY) => {
                const rect = slider.getBoundingClientRect();
                const handleHeight = 12;
                const limit = rect.height - handleHeight;
                let y = clientY - rect.top - (handleHeight / 2);
                y = Math.max(0, Math.min(limit, y));
                handle.style.top = y + 'px';

                const val = 1.0 - (y / limit);
                if (window.dualMidiBridge) {
                    window.dualMidiBridge.setParameter(paramId, val);
                }
            };

            function onSliderMove(e) {
                if (isDragging) {updateSliderPos(e.clientY);}
            }
            function onSliderEnd() {
                isDragging = false;
                window.removeEventListener('mousemove', onSliderMove);
                window.removeEventListener('mouseup', onSliderEnd);
            }
            slider.addEventListener('mousedown', (e) => {
                isDragging = true;
                updateSliderPos(e.clientY);
                e.preventDefault();
                e.stopPropagation();
                window.addEventListener('mousemove', onSliderMove);
                window.addEventListener('mouseup', onSliderEnd);
            });
        });
    }
}

/**
 * @purpose Generates specialized HTML templates for the 35 DeepMind 12 effect types and controls dial drag/rotation logic.
 * @purpose_en Effects HTML template layouts and dial rotation services.
 *
 * Sub-modules extracted to:
 *   effects_theme.js             → FX_THEME_COLORS + _getFxTheme + _fxThemeStyle
 *   effects_render_params.js     → renderActiveEffectParams (with interactive controls)
 */

function _readFxParamValue(paramId, fallbackByte, defaultVal) {
    const bridge = window.dualMidiBridge;
    if (bridge && bridge.parameterCache && bridge.parameterCache[paramId] !== undefined) {
        return bridge.parameterCache[paramId];
    }
    if (typeof window.currentActivePatchIndex !== 'undefined' && window.currentActivePatchIndex !== -1) {
        const activeBank = window.loadedBanks[window.currentActiveBank];
        if (activeBank) {
            const patch = activeBank[window.currentActivePatchIndex];
            if (patch && patch.unpackedBytes && patch.unpackedBytes[fallbackByte] !== undefined) {
                return patch.unpackedBytes[fallbackByte] / 255.0;
            }
        }
    }
    return defaultVal;
}
window._readFxParamValue = _readFxParamValue;

/**
 * @purpose Individual HTML template renderers for each DeepMind 12 effect type.
 * Dispatcher + bypass + fallback kept here.
 * Category-specific renderers extracted to:
 *   effects_renderers_reverbs.js       — Reverbs (types 2, 4, 7, 9, 10, 11, 12, 13)
 *   effects_renderers_eq_dynamics.js   — EQ/Dynamics (types 14, 15, 16, 17)
 *   effects_renderers_modulation.js    — Modulation (types 18, 19, 20, 21, 31, 32)
 *   effects_renderers_delays_pitch.js  — Delays/Pitch (types 22, 23, 24, 25, 33, 34, 35)
 * Each renderer takes (pVals[, effectType][, selectedSlot]) and returns an HTML string.
 */

// ──────────────────────────────────────────────
// Dispatcher
// ──────────────────────────────────────────────

/**
 * Returns the appropriate template renderer function for the given effect type.
 * @param {number} effectType
 * @returns {function}
 */
window._getFXTemplateRenderer = function(effectType) {
    const renderers = {
        0:  window._renderFXBypass,
        2:  window._renderFXTcDeepVerb,
        4:  window._renderFXVintageRoomReverb,
        7:  window._renderFXPlateReverb,
        9:  window._renderFXGatedReverse,
        10: window._renderFXGatedReverse,
        11: window._renderFXDualFX,
        12: window._renderFXDualFX,
        13: window._renderFXDualFX,
        14: window._renderFXMidasEQ,
        15: window._renderFXEnhancer,
        16: window._renderFXFairComp,
        17: window._renderFXMBDistortion,
        18: window._renderFXRackAmp,
        19: window._renderFXEdison,
        20: window._renderFXAutoPan,
        21: window._renderFXNoiseGate,
        22: window._renderFXDelay,
        23: window._renderFXDelay,
        24: window._renderFXDelay,
        25: window._renderFXTRayDelay,
        31: window._renderFXStereoPhaser,
        32: window._renderFXMoodFilter,
        33: window._renderFXPitch,
        34: window._renderFXPitch,
        35: window._renderFXRotarySpeaker
    };
    return renderers[effectType] || window._renderFXFallback;
};

// ──────────────────────────────────────────────
// BYPASS
// ──────────────────────────────────────────────

window._renderFXBypass = function() {
    return '<span style="color:var(--text-faint); font-size:12px; font-family:\'Share Tech Mono\', monospace; text-transform:uppercase;">Effect Bypassed</span>';
};

