        });

        Logger.log('[ChordMemory] Memory mode: transposed by', interval, 'semitones from', baseNote, 'to', rootNote);
    } else {
        const intervals = CHORD_INTERVALS[chordType];
        if (!intervals) {return false;}

        intervals.forEach(function(interval) {
