        Logger.log('[ChordMemory] Generated', typeNames[chordType] || 'Chord', 'at root', rootNote, ':', notesToPlay.join(','));
    }

    if (notesToPlay.length === 0) {return false;}

    notesToPlay.forEach(function(note) {
        bridge._chordActiveNotes.push(note);
