/** Update octave button visual state (color, border, glow) */
window._renderOctaveButtons = function(octUpBtn, octDownBtn, octaveShift) {
    const currentOctVal = octaveShift / 12;

    let activeColor = 'var(--color-env-vca)';
    if (Math.abs(currentOctVal) === 1) {
        activeColor = 'var(--color-env-vcf)';
    } else if (Math.abs(currentOctVal) === 2) {
        activeColor = 'var(--color-env-mod)';
    } else if (Math.abs(currentOctVal) >= 3) {
        activeColor = 'var(--color-oct-3)';
    }

    const isUpActive = currentOctVal > 0;
    const isDownActive = currentOctVal < 0;

    const applyActive = (btn) => {
        btn.style.setProperty('color', activeColor, 'important');
        btn.style.setProperty('border-color', activeColor, 'important');
        btn.style.setProperty('box-shadow', '0 0 8px ' + activeColor, 'important');
    };
    const applyInactive = (btn) => {
        btn.style.setProperty('color', 'var(--brand-accent)', 'important');
        btn.style.setProperty('border-color', 'var(--border-dim)', 'important');
        btn.style.setProperty('box-shadow', 'none', 'important');
    };

    if (octUpBtn) {
        if (isUpActive) { applyActive(octUpBtn); }
        else { applyInactive(octUpBtn); }
    }
    if (octDownBtn) {
        if (isDownActive) { applyActive(octDownBtn); }
        else { applyInactive(octDownBtn); }
    }
};

/** Apply deterministic ivory texture CSS properties to a white key */
window._applyKeyIvoryTexture = function(key, midiNote) {
    const seed = (midiNote * 12345) % 100;
    const hue = 40 + (seed % 6 - 3);
    const sat = 18 + (seed % 6);
    const light = 90 - (seed % 5);
    const dirtStart = 85 + (seed % 10);
    const dirtOpacity = 0.05 + (seed % 12) / 100.0;

    key.style.setProperty('--ivory-base', 'hsl(' + hue + ', ' + sat + '%, ' + light + '%)');
    key.style.setProperty('--ivory-top', 'hsl(' + hue + ', ' + sat + '%, ' + (light + 6) + '%)');
    key.style.setProperty('--ivory-bottom', 'hsl(' + hue + ', ' + sat + '%, ' + (light - 5) + '%)');
    key.style.setProperty('--dirt-color', 'rgba(105, 90, 75, ' + dirtOpacity + ')');
    key.style.setProperty('--dirt-start', dirtStart + '%');
};

/** Resolve key LED color based on arp/seq/chord/polyChord bridge state */
window._resolveKeyLedColor = function(bridge) {
    if (!bridge) { return 'var(--brand-accent)'; }
    const cache = bridge.parameterCache;
    if (!cache) { return 'var(--brand-accent)'; }
    const arpActive = cache['arp_enable'] > 0.5;
    const seqActive = cache['seq_enable'] > 0.5;
    const chordActive = cache['chord_enable'] > 0.5;
    const polyChordActive = cache['poly_chord_enable'] > 0.5;

    if (arpActive) { return '#ff3366'; }
    if (seqActive) { return '#9933ff'; }
    if (polyChordActive) { return '#00ffcc'; }
    if (chordActive) { return '#ffcc00'; }

    if (typeof window._getScopeColors === 'function') {
        return window._getScopeColors().waveform;
    }
    return 'var(--brand-accent)';
};

// ================================================================
// Key Pressure Display — Aftertouch / Mod Wheel / Pitch Bend
// ================================================================

(function() {
    let _atPrevious = 0.0;
    let _mwPrevious = 0.0;
    let _pbPrevious = 0.0;
    let _atFramePending = false;

    /**
     * Update CSS --pressure, --mw-pressure, --pb-offset on pushed keys.
     * Manages its own RAF scheduling. Start once after keybed exists.
     */
    function _updateKeyPressureDisplay() {
        _atFramePending = false;

        const bridge = window.dualMidiBridge;
        if (!bridge) { _scheduleNext(); return; }

        let aftertouch = 0.0;
        let modWheel = 0.0;
        let pitchBend = 0.0;

        if (bridge.isJuce) {
            if (bridge._lastVoiceStateRaw) {
                aftertouch = bridge._lastVoiceStateRaw.aftertouch !== undefined
                    ? bridge._lastVoiceStateRaw.aftertouch : 0.0;
                modWheel = bridge._lastVoiceStateRaw.modWheel !== undefined
                    ? bridge._lastVoiceStateRaw.modWheel : 0.0;
                pitchBend = bridge._lastVoiceStateRaw.pitchBend !== undefined
                    ? bridge._lastVoiceStateRaw.pitchBend : 0.0;
            }
        } else {
            aftertouch = (bridge.parameterCache['aftertouch'] !== undefined)
                ? bridge.parameterCache['aftertouch'] : 0.0;
            modWheel = (bridge.parameterCache['mod_wheel'] !== undefined)
                ? bridge.parameterCache['mod_wheel'] : 0.0;
        }

        aftertouch = Math.max(0, Math.min(1, aftertouch));
        modWheel = Math.max(0, Math.min(1, modWheel));
        pitchBend = Math.max(-1, Math.min(1, pitchBend));

        if (typeof window.applyControllerCurve === 'function') {
            aftertouch = window.applyControllerCurve(aftertouch, window.getControllerCurve('aftertouch'));
            modWheel = window.applyControllerCurve(modWheel, window.getControllerCurve('modwheel'));
        }
        if (typeof window.applyBipolarCurve === 'function') {
            pitchBend = window.applyBipolarCurve(pitchBend, window.getControllerCurve('pitchbend'));
        }

        if (Math.abs(aftertouch - _atPrevious) < 0.01
            && Math.abs(modWheel - _mwPrevious) < 0.01
            && Math.abs(pitchBend - _pbPrevious) < 0.01) {
            _scheduleNext();
            return;
        }
        _atPrevious = aftertouch;
        _mwPrevious = modWheel;
        _pbPrevious = pitchBend;

        const combinedPressure = Math.max(aftertouch, modWheel);
        const hasAnyPressure = combinedPressure > 0.01;
        const pressureCombinedAttr = hasAnyPressure ? combinedPressure.toFixed(3) : null;
        const mwAttr = (modWheel > 0.01) ? modWheel.toFixed(3) : null;
        const pbSensitivity = parseInt(localStorage.getItem('abd-eep-pb-sensitivity') || '6', 10);
        const pbPx = Math.round(pitchBend * pbSensitivity);
        const pbAttr = Math.abs(pitchBend) > 0.01 ? String(pbPx) : null;

        const keybed = document.getElementById('ivory-keys-bed');
        if (!keybed) { _scheduleNext(); return; }
        const pushedKeys = keybed.querySelectorAll('.key.pushed');

        for (const k of pushedKeys) {
            if (pressureCombinedAttr) {
                k.style.setProperty('--pressure', pressureCombinedAttr);
                k.style.setProperty('--mw-pressure', mwAttr || '0');
                k.classList.add('pressured');
            } else {
                k.style.removeProperty('--pressure');
                k.style.removeProperty('--mw-pressure');
                k.classList.remove('pressured');
            }
            if (pbAttr) {
                k.style.setProperty('--pb-offset', pbAttr + 'px');
                k.classList.add('pitch-bent');
            } else {
                k.style.removeProperty('--pb-offset');
                k.classList.remove('pitch-bent');
            }
        }

        _scheduleNext();
    }

    function _scheduleNext() {
        if (_atFramePending) { return; }
        _atFramePending = true;
        requestAnimationFrame(_updateKeyPressureDisplay);
    }

    /** Start the key pressure display loop. Call once after keybed exists. */
    window._startKeyPressureDisplay = function() {
        _scheduleNext();
    };
})();

/**
 * @purpose Core rendering utilities for the virtual piano keybed: key element creation
 * and octave-shift LCD display. Extracted from keyboard.js for modularity.
 * @classification Module/Keyboard/Render
 */

/**
 * Creates a single key DOM element with class, data attributes, and ivory texture/position.
 * Does NOT attach event listeners — those are handled in keyboard.js.
 * @param {Object} noteDef - { type: 'white'|'black', name: 'C'|'C#'|... }
 * @param {number} midiNote - Absolute MIDI note number
 * @param {number} whiteKeyIndex - Sequential white key index (1-based)
 * @returns {HTMLElement} The created key <div>
 */
window._createKeyElement = function(noteDef, midiNote, whiteKeyIndex) {
    const key = document.createElement('div');
    key.classList.add('key', noteDef.type);
    key.setAttribute('data-note', midiNote);

    if (noteDef.type === 'white') {
        if (typeof window._applyKeyIvoryTexture === 'function') {
            window._applyKeyIvoryTexture(key, midiNote);
        }
    } else {
        key.style.left = ((whiteKeyIndex - 0.6) / 28) * 100 + '%';
    }

    return key;
};

/**
 * Updates the LCD text display to show the current octave shift value.
 * @param {number} octaveShift - Current octave shift in semitones
 */
window._updateOctaveLcd = function(octaveShift) {
    const lcdText = document.getElementById('lcd-text');
    if (!lcdText) { return; }

    const sign = octaveShift > 0 ? '+' : '';
    const octaveLabel = (octaveShift / 12).toString();

    lcdText.innerHTML = '<span class=\"lcd-label\">KEYBED</span><br><strong>OCTAVE SHIFT</strong><br>'
        + '<span style=\"font-size:15px; color:var(--brand-accent);\">' + sign + octaveLabel + '</span>';

    if (typeof window.setLcdParamDisplayTimer === 'function') {
        window.setLcdParamDisplayTimer(lcdText);
    }
};

/**
 * @purpose Módulo de control interactivo para potenciómetros giratorios (knobs), incluyendo Data Entry y Performance Knobs (Volume, Portamento).
 * @purpose_en Control module for rotary knobs, including Data Entry and Performance Knobs (Volume, Portamento).
 */

function initKnobs() {
    // CONFIGURAR TODOS LOS KNOBS GENERALES DE PERFORMANCE (Volume y Portamento)
    document.querySelectorAll('.performance-matrix-panel .ctrl-unit').forEach(knobUnit => {
        const paramId = knobUnit.getAttribute('data-param');
        const ring = knobUnit.querySelector('.knob-ring');
        const pointer = knobUnit.querySelector('.knob-pointer');
        if (!ring || !pointer) {return;}

        let isDragging = false;
        let startY = 0;
        let baseValue = 0.0;
        if (paramId === 'global_volume') {baseValue = 0.8;}

        ring.addEventListener('pointerdown', (e) => {
            isDragging = true;
            startY = e.clientY;
            ring.setPointerCapture(e.pointerId);
            e.preventDefault();
        });

        ring.addEventListener('pointermove', (e) => {
            if (!isDragging) {return;}
            const deltaY = startY - e.clientY;
            startY = e.clientY;

            const sensitivity = 0.005;
            baseValue = Math.max(0.0, Math.min(1.0, baseValue + deltaY * sensitivity));
            const rotation = (baseValue * 270) - 135;
            pointer.style.transform = `translateX(-50%) rotate(${rotation}deg)`;

            if (window.dualMidiBridge) {
                window.dualMidiBridge.setParameter(paramId, baseValue);

                const lcdText = document.getElementById('lcd-text');
                if (lcdText) {
                    const displayVal = typeof window.formatParamValue === 'function' ? window.formatParamValue(paramId, baseValue) : baseValue.toFixed(2);
                    lcdText.innerHTML = `<span class="lcd-label">PERFORMANCE</span><br><strong>${paramId.toUpperCase()}</strong><br><span style="font-size:15px; color:var(--color-gold);">${displayVal}</span>`;
                    if (typeof window.setLcdParamDisplayTimer === 'function') {
                        window.setLcdParamDisplayTimer(lcdText);
                    }
                }
            }
        });

        ring.addEventListener('pointerup', () => {
            isDragging = false;
        });

        if (window.dualMidiBridge) {
            window.dualMidiBridge.onParameterChanged((id, val) => {
                if (id === paramId) {
                    baseValue = val;
                    const rotation = (val * 270) - 135;
                    pointer.style.transform = `translateX(-50%) rotate(${rotation}deg)`;
                }
            });
        }
    });
}

// Exportar al ámbito de window
window.initKnobs = initKnobs;

/**
 * @purpose Logger centralizado y condicional para la WebUI.
 * @purpose_en Centralized and conditional logger for the WebUI.
 *
 * Los mensajes solo se imprimen cuando el modo debug está activado
 * mediante `localStorage.setItem('abd-eep-debug-logs', '1')` o
 * `window._ABD_DEBUG = true` antes de cargar este script.
 */

(function() {
    'use strict';

    function _enabled() {
        try {
            if (typeof window === 'undefined') {return false;}
            if (window._ABD_DEBUG === true) {return true;}
            return window.localStorage && window.localStorage.getItem('abd-eep-debug-logs') === '1';
        } catch (e) {
            return false;
        }
    }

    function _noop() {}

    const _debug = (typeof console !== 'undefined' && console.log) ? console.log.bind(console) : _noop;
    const _info = (typeof console !== 'undefined' && console.info) ? console.info.bind(console) : _noop;
    const _warn = (typeof console !== 'undefined' && console.warn) ? console.warn.bind(console) : _noop;
    const _error = (typeof console !== 'undefined' && console.error) ? console.error.bind(console) : _noop;

    const enabled = _enabled();

    /**
     * @namespace Logger
     */
    const Logger = {
        /**
         * Devuelve true si el modo debug está activo.
         * @returns {boolean}
         */
        isEnabled: function() {
            return enabled;
        },

        /**
         * Activa o desactiva el modo debug en runtime.
         * @param {boolean} value
         */
        setDebug: function(value) {
            try {
                if (typeof window !== 'undefined') {
                    window._ABD_DEBUG = !!value;
                    if (window.localStorage) {
                        window.localStorage.setItem('abd-eep-debug-logs', value ? '1' : '0');
                    }
                }
            } catch (e) {
                // localStorage puede estar bloqueado en modo privado/incógnito
            }
        },

        log: enabled ? _debug : _noop,
        info: enabled ? _info : _noop,
        warn: enabled ? _warn : _noop,
        error: enabled ? _error : _noop
    };

    if (typeof window !== 'undefined') {
        window.Logger = Logger;
    }

    if (typeof module !== 'undefined' && module.exports) {
        module.exports = Logger;
    }
})();

/* --- ABDEEP MODULATION MATRIX MANAGEMENT ---
   Gestor interactivo de 8/32 slots de la matriz de modulación (Mod Matrix)
   Depends on: modmatrix_data.js (loaded first)
   UI sync: modmatrix_sync.js (loaded after)
*/

document.addEventListener('DOMContentLoaded', () => {
    initModMatrix();
});

function initModMatrix() {
    // Inicializar modo por defecto en 'advanced' (AbyssMind Pro) si no está configurado
    if (typeof window !== 'undefined') {
        window.appMode = window.appMode || localStorage.getItem('abd-eep-app-mode') || 'advanced';
    }

    const modmatrixBtn = document.getElementById('programmer-mod-matrix-btn');
    const backdrop = document.getElementById('modmatrix-modal-backdrop');
    const closeBtn = document.getElementById('modmatrix-close-btn');
    const gridContainer = document.querySelector('.modmatrix-grid');
    const blockTabsContainer = document.getElementById('mod-block-tabs');
    const compactBtn = document.getElementById('mod-compact-btn');

    if (!modmatrixBtn || !backdrop || !closeBtn || !gridContainer) {return;}

    // Crear Dropdown flotante global reutilizable
    const dropdownList = document.createElement('div');
    dropdownList.className = 'modmatrix-dropdown-list';
    document.body.appendChild(dropdownList);

    // Ocultar dropdown al hacer click fuera
    document.addEventListener('pointerdown', (e) => {
        if (!e.target.closest('.modmatrix-selector-btn') && !e.target.closest('.modmatrix-dropdown-list')) {
            dropdownList.style.display = 'none';
        }
    });

    // Canvas View Toggle
    const toggleBtns = document.querySelectorAll('.modmatrix-toggle-btn');
    const modCanvas = document.querySelector('.modmatrix-canvas');
    const modMatrixCanvas = modCanvas && window.ModMatrixCanvas ? new window.ModMatrixCanvas(modCanvas) : null;

    window._modMatrixCanvasForSync = modMatrixCanvas;

    if (modMatrixCanvas) {
        modMatrixCanvas.setCallbacks(function(slot, mx, _my) {
            const srcBtn = document.getElementById('mod-src-btn-' + (slot + 1));
            const destBtn = document.getElementById('mod-dest-btn-' + (slot + 1));
            const cx = modCanvas.width / 2;
            if (mx < cx) { if (srcBtn) {srcBtn.click();} }
            else { if (destBtn) {destBtn.click();} }
        });
        setTimeout(function() { modMatrixCanvas.resize(); }, 50);
    }

    toggleBtns.forEach(function(btn) {
        btn.addEventListener('click', function() {
            const view = btn.getAttribute('data-view');
            toggleBtns.forEach(function(b) { b.classList.remove('active'); b.style.borderColor = 'var(--border)'; });
            btn.classList.add('active'); btn.style.borderColor = 'var(--accent-blue)';
            if (view === 'graph') {
                document.querySelector('.modmatrix-grid').style.display = 'none';
                if (blockTabsContainer) { blockTabsContainer.style.display = 'none'; }
                modCanvas.style.display = 'block';
                if (modMatrixCanvas) { modMatrixCanvas.resize(); modMatrixCanvas.syncFromCache(window.dualMidiBridge ? window.dualMidiBridge.parameterCache : {}); }
            } else {
                document.querySelector('.modmatrix-grid').style.display = 'grid';
                if (blockTabsContainer && window.appMode !== 'standard') { blockTabsContainer.style.display = 'flex'; }
                modCanvas.style.display = 'none';
            }
        });
    });

    // Generar el HTML de los 32 Slots (8 en Standard, 32 en Pro)
    let html = '';
    const totalSlots = 32;
    for (let slot = 1; slot <= totalSlots; slot++) {
        const nrpnInfo = slot <= 8 ? `${93+(slot-1)*3}/${94+(slot-1)*3}/${95+(slot-1)*3}` : `EXT-${slot}`;
        html += `
            <div class="modmatrix-slot" data-slot="${slot}" style="${slot > 8 ? 'display:none;' : ''}">
                <div class="modmatrix-slot-title">Modulation Slot ${slot}</div>
                <div class="modmatrix-selector-row">
                    <button class="modmatrix-selector-btn" id="mod-src-btn-${slot}" data-type="src">Source: None</button>
                    <button class="modmatrix-selector-btn" id="mod-dest-btn-${slot}" data-type="dest">Dest: None</button>
                </div>
                <div class="modmatrix-flow-arrow" id="mod-flow-arrow-${slot}">
                    <span class="arrow-path">&#x2500;</span><span class="arrow-depth-indicator">&#x2500;</span><span class="arrow-path">&#x2500;</span><span class="arrow-path">&#x25B6;</span>
                </div>
                <div class="modmatrix-depth-row">
                    <span class="label" style="font-size: 7px; color:var(--text-dim);">DEPTH</span>
                    <div class="modmatrix-h-slider" id="mod-depth-slider-${slot}">
                        <div class="track"></div>
                        <div class="fill pos"></div>
                        <div class="fill neg"></div>
                        <div class="handle" style="left: 50%;"></div>
                    </div>
                    <div class="modmatrix-depth-value" id="mod-depth-txt-${slot}">0</div>
                </div>
                <div class="modmatrix-slot-info" style="display:flex;justify-content:space-between;margin-top:2px;gap:4px">
                    <span style="font-size:var(--text-2xs);color:var(--text-faint)">NRPN: ${nrpnInfo}</span>
                    <span class="mod-slot-active-badge" id="mod-active-badge-${slot}" style="font-size:var(--text-2xs);color:var(--text-faint)">OFF</span>
                </div>
            </div>
        `;
    }
    gridContainer.innerHTML = html;

    // Manejo de Bloques de Pestañas (AbyssMind Pro)
    function _updateBlockVisibility(activeBlock) {
        const isAdvanced = (window.appMode !== 'standard');
        if (blockTabsContainer) {
            blockTabsContainer.style.display = isAdvanced ? 'flex' : 'none';
        }
        const banner = document.getElementById('mod-block-banner');
        if (banner) {
            banner.style.display = isAdvanced ? 'flex' : 'none';
            const minSlot = (activeBlock - 1) * 8 + 1;
            const maxSlot = activeBlock * 8;
            const titleSpan = banner.querySelector('span');
            if (titleSpan) {
                titleSpan.innerHTML = `🔷 <strong>BLOCK ${activeBlock}</strong> (SLOTS ${minSlot} TO ${maxSlot})`;
            }
        }
        gridContainer.querySelectorAll('.modmatrix-slot').forEach(slotEl => {
            const slotNum = parseInt(slotEl.dataset.slot);
            if (!isAdvanced) {
                slotEl.style.display = slotNum <= 8 ? 'block' : 'none';
            } else {
                const minSlot = (activeBlock - 1) * 8 + 1;
                const maxSlot = activeBlock * 8;
                slotEl.style.display = (slotNum >= minSlot && slotNum <= maxSlot) ? 'block' : 'none';
            }
        });
    }

    let _currentBlock = 1;
    document.querySelectorAll('.mod-block-tab').forEach(tab => {
        tab.addEventListener('click', () => {
            document.querySelectorAll('.mod-block-tab').forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            _currentBlock = parseInt(tab.dataset.block);
            _updateBlockVisibility(_currentBlock);
        });
    });

    // Botón Compactar
    if (compactBtn) {
        compactBtn.addEventListener('click', () => {
            if (typeof window.compactModMatrix === 'function') {
                const activeCount = window.compactModMatrix(window.deepmindState || (window.dualMidiBridge ? window.dualMidiBridge.parameterCache : {}));
                if (typeof window.syncModMatrixUIFromState === 'function') {
                    window.syncModMatrixUIFromState();
                }
                const lcdUpdate = window.lcdSafeUpdate || function() {};
                lcdUpdate(`MODMATRIX COMPACTED (${activeCount} ACTIVE)`);
            }
        });
    }

    // Abrir Modal
    modmatrixBtn.addEventListener('click', () => {
        backdrop.style.display = 'flex';
        _updateBlockVisibility(_currentBlock);
        if (typeof window.syncModMatrixUIFromState === 'function') {
            window.syncModMatrixUIFromState();
        }
    });

    // Cerrar Modal
    closeBtn.addEventListener('click', () => {
        backdrop.style.display = 'none';
    });

    // Manejar Click en Botones Source/Dest (Desplegar Dropdown)
    gridContainer.querySelectorAll('.modmatrix-selector-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const rect = btn.getBoundingClientRect();
            const isSource = btn.getAttribute('data-type') === 'src';
            const slot = btn.closest('.modmatrix-slot').getAttribute('data-slot');

            dropdownList.style.top = (rect.bottom + window.scrollY) + 'px';
            dropdownList.style.left = (rect.left + window.scrollX) + 'px';
            dropdownList.style.width = rect.width + 'px';
            dropdownList.style.display = 'block';

            const items = isSource ? window.MOD_SOURCES : window.FULL_MOD_DESTINATIONS;
            let listHtml = '';
            items.forEach((itemText, index) => {
                listHtml += `<div class="modmatrix-dropdown-item" data-index="${index}">${itemText}</div>`;
            });
            dropdownList.innerHTML = listHtml;

            dropdownList.querySelectorAll('.modmatrix-dropdown-item').forEach(item => {
                item.addEventListener('click', () => {
                    const selectedIdx = parseInt(item.getAttribute('data-index'));
                    const selectedText = item.innerText;
                    btn.innerText = (isSource ? 'Source: ' : 'Dest: ') + selectedText;
                    dropdownList.style.display = 'none';

                    if (isSource) {
                        window.applyButtonColor(btn, selectedIdx > 0 ? window.getSrcCategoryColor(selectedIdx) : null);
                    } else {
                        window.applyButtonColor(btn, selectedIdx > 0 ? window.getDestCategoryColor(selectedIdx) : null);
                    }

                    const paramId = isSource ? `mod_matrix_slot${slot}_src` : `mod_matrix_slot${slot}_dest`;
                    const maxVal = isSource ? 22.0 : 129.0;

                    if (window.dualMidiBridge) {
                        window.dualMidiBridge.setParameter(paramId, selectedIdx / maxVal);
                    }
                });
            });
        });
    });

    // Configurar los 32 Sliders Horizontales de Profundidad (Bipolar: -1.0 a 1.0)
    for (let slot = 1; slot <= totalSlots; slot++) {
        const slider = document.getElementById(`mod-depth-slider-${slot}`);
        if (!slider) {continue;}
        const handle = slider.querySelector('.handle');
        const txtVal = document.getElementById(`mod-depth-txt-${slot}`);

        let isDragging = false;

        const updateDepth = (clientX) => {
            const rect = slider.getBoundingClientRect();
            let pct = (clientX - rect.left) / rect.width;
            pct = Math.max(0, Math.min(1, pct));

            handle.style.left = (pct * 100) + '%';
            window.updateSliderFill(slider, pct);

            const bipolarVal = (pct * 2.0) - 1.0;
            const scaledInt = Math.round(bipolarVal * 128);
            txtVal.innerText = scaledInt;

            const paramId = `mod_matrix_slot${slot}_depth`;
            if (window.dualMidiBridge) {
                window.dualMidiBridge.setParameter(paramId, pct);
            }
        };

        slider.addEventListener('pointerdown', (e) => {
            isDragging = true;
            slider.setPointerCapture(e.pointerId);
            updateDepth(e.clientX);
        });

        slider.addEventListener('pointermove', (e) => {
            if (isDragging) {updateDepth(e.clientX);}
        });

        slider.addEventListener('pointerup', () => {
            isDragging = false;
        });
    }
}

