const FULL_MOD_DESTINATIONS = (function buildFullDestinations() {
    const arr = [];
    for (let i = 0; i <= 132; i++) {
        if (i < MOD_DESTINATIONS.length) {
            arr.push(MOD_DESTINATIONS[i]);
        } else if (i === 129) {
