 *   - panel_edit_scope.js   — toggles de pantalla/scope + toolbar
 *   - panel_animations.js   — canvas loop + audio polling
 *   - panel_param_handler.js — cambios de parámetros en tiempo real
 *   - panel_controls_binder.js — bindings de sliders + selectores
 *   - panel_graphics.js     — renderizado canvas de formas de onda
 * @purpose_en Facade that initializes all detail panel sub-modules.
 */

/* global initPanelButtons, initPanelScope */

document.addEventListener('DOMContentLoaded', () => {
    initDetailPanel();
});

function initDetailPanel() {
    const panel = document.getElementById('detail-edit-panel');
    const closeBtn = document.getElementById('panel-close-btn');

    if (!panel || !closeBtn) {return;}

    // Initialize sub-modules
    initPanelButtons(panel);
    initPanelScope();

    // Escuchar cambios de parámetros en tiempo real (delegado a panel_param_handler.js)
    if (window.dualMidiBridge) {
        window.dualMidiBridge.onParameterChanged(window._handlePanelParamChange);
    }

    // Observer y animaciones (delegado a panel_animations.js)
    if (typeof window._initPanelObserver === 'function') {
        window._initPanelObserver();
    }
}

/**
 * @purpose Edit button setup for the detail editor panel: mode buttons, chord/polychord, close.
 * @purpose_en Opens panel modes, toggles chord/polychord with bridge, manages close/openSeqPanel.
 */

// eslint-disable-next-line no-unused-vars -- called from initDetailPanel
function initPanelButtons(panel) {
    const state = window.panelEditState;
    const closeBtn = document.getElementById('panel-close-btn');

    if (!panel || !closeBtn) {return false;}

    const lfoEditBtn = document.getElementById('lfo-edit-btn');
    const vcaEditBtn = document.getElementById('vca-edit-btn');
    const envEditBtn = document.getElementById('env-edit-btn');
    const hpfEditBtn = document.getElementById('hpf-edit-btn');
    const vcfEditBtn = document.getElementById('vcf-edit-btn');
    const oscEditBtn = document.getElementById('osc-edit-btn');
    const polyEditBtn = document.getElementById('poly-edit-btn');
    const portaEditBtn = document.getElementById('porta-edit-btn');
    const chordEditBtn = document.getElementById('programmer-chord-btn');
    const polychordEditBtn = document.getElementById('programmer-polychord-btn');

    // Opening modes listeners
    const setupOpenPanel = (btn, mode) => {
        if (!btn) {return;}
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            state.currentPanelMode = mode;
            if (typeof window.syncDetailPanelControls === 'function') {window.syncDetailPanelControls();}
            panel.classList.add('active');
        });
    };

    setupOpenPanel(lfoEditBtn, 'LFO');
    setupOpenPanel(vcaEditBtn, 'VCA');
    setupOpenPanel(envEditBtn, 'ENV');
    setupOpenPanel(hpfEditBtn, 'HPF');
    setupOpenPanel(vcfEditBtn, 'VCF');
    setupOpenPanel(oscEditBtn, 'OSC');
    setupOpenPanel(polyEditBtn, 'POLY');
    setupOpenPanel(portaEditBtn, 'PORTA');

    // Delegación de eventos para asegurar apertura instantánea aunque los Web Components se inicialicen de forma asíncrona
    document.addEventListener('click', (e) => {
        const btn = e.target.closest('#lfo-edit-btn, #vca-edit-btn, #env-edit-btn, #hpf-edit-btn, #vcf-edit-btn, #osc-edit-btn, #poly-edit-btn, #porta-edit-btn');
        if (btn) {
            e.preventDefault();
            e.stopPropagation();
            const modeMap = {
                'lfo-edit-btn': 'LFO',
                'vca-edit-btn': 'VCA',
                'env-edit-btn': 'ENV',
                'hpf-edit-btn': 'HPF',
                'vcf-edit-btn': 'VCF',
                'osc-edit-btn': 'OSC',
                'poly-edit-btn': 'POLY',
                'porta-edit-btn': 'PORTA'
            };
            const mode = modeMap[btn.id];
            if (mode) {
                state.currentPanelMode = mode;
                if (typeof window.syncDetailPanelControls === 'function') {window.syncDetailPanelControls();}
                panel.classList.add('active');
            }
        }
    });

    if (chordEditBtn) {
        chordEditBtn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (window.dualMidiBridge) {
                const active = window.dualMidiBridge.parameterCache['chord_enable'] > 0.5;
                const nextVal = active ? 0.0 : 1.0;
                window.dualMidiBridge.setParameter('chord_enable', nextVal);
                if (nextVal > 0.5) {
                    window.dualMidiBridge.setParameter('poly_chord_enable', 0.0);
                }
            }
            state.currentPanelMode = 'CHORD';
            if (typeof window.syncDetailPanelControls === 'function') {window.syncDetailPanelControls();}
            panel.classList.add('active');
        });
    }

    if (polychordEditBtn) {
        polychordEditBtn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (window.dualMidiBridge) {
                const active = window.dualMidiBridge.parameterCache['poly_chord_enable'] > 0.5;
                const nextVal = active ? 0.0 : 1.0;
                window.dualMidiBridge.setParameter('poly_chord_enable', nextVal);
                if (nextVal > 0.5) {
                    window.dualMidiBridge.setParameter('chord_enable', 0.0);
                }
            }
            state.currentPanelMode = 'POLY_CHORD';
            if (typeof window.syncDetailPanelControls === 'function') {window.syncDetailPanelControls();}
            panel.classList.add('active');
        });
    }

    window.openSeqPanel = function() {
        state.currentPanelMode = 'SEQ';
        if (typeof window.syncDetailPanelControls === 'function') {window.syncDetailPanelControls();}
        panel.classList.add('active');
    };

    closeBtn.addEventListener('click', () => {
        panel.classList.remove('active');
    });

    return true;
}

/**
 * @purpose Scope toolbar and screen/realScope toggle setup for the detail editor panel.
 * @purpose_en Screen collapse/expand, DSP scope toggles, trigger/zoom/color toolbar buttons.
 */

// eslint-disable-next-line no-unused-vars -- called from initDetailPanel
function initPanelScope() {
    const state = window.panelEditState;
    const screenEl = document.getElementById('panel-graphic-screen');
    const screenToggleBtn = document.getElementById('panel-graphic-toggle');
    const realScopeScreenEl = document.getElementById('panel-real-scope-screen');
    const realScopeToggleBtn = document.getElementById('panel-real-scope-toggle');

    if (screenToggleBtn && screenEl) {
        screenToggleBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            state.isScreenCollapsed = !state.isScreenCollapsed;
            window.updateScreenHeight();
        });
    }

    if (realScopeToggleBtn && realScopeScreenEl) {
        realScopeToggleBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            state.isRealScopeCollapsed = !state.isRealScopeCollapsed;
            window.updateRealScopeHeight();
            window._updateAudioWaveformPolling();
            if (!state.isRealScopeCollapsed && typeof window._updateScopeToolbar === 'function') {
                window._updateScopeToolbar();
            }
        });
    }

    // Scope toolbar triggers
    document.addEventListener('click', function _onScopeTrigger(e) {
        const btn = e.target.closest('#scope-trigger-btn');
        if (!btn) {return;}
        state._scopeTriggerMode = (state._scopeTriggerMode + 1) % 3;
        state._scopeLastSamples = null;
        if (typeof window._updateScopeToolbar === 'function') {window._updateScopeToolbar();}
    });

    document.addEventListener('click', function _onScopeZoom(e) {
        const btn = e.target.closest('.scope-zoom-btn');
        if (!btn) {return;}
        const zoom = parseInt(btn.getAttribute('data-zoom'));
        if (zoom >= 1 && zoom <= 4) {
            state._scopeZoom = zoom;
            if (typeof window._updateScopeToolbar === 'function') {window._updateScopeToolbar();}
        }
    });

    document.addEventListener('click', function _onScopeColor(e) {
        const btn = e.target.closest('#scope-color-btn');
        if (!btn) {return;}
        state._scopeColorScheme = (state._scopeColorScheme + 1) % (window.SCOPE_COLORS ? window.SCOPE_COLORS.length : 4);
        if (typeof window._updateScopeToolbar === 'function') {window._updateScopeToolbar();}
    });

    // View mode toggle: WAVE/SPC/DUAL
    document.addEventListener('click', function _onScopeView(e) {
        const btn = e.target.closest('#scope-view-btn');
        if (!btn) {return;}
        const maxMode = (window.SCOPE_VIEW_LABELS ? window.SCOPE_VIEW_LABELS.length : 3) - 1;
        state._scopeViewMode = ((state._scopeViewMode || 0) + 1) % (maxMode + 1);
        if (typeof window._updateScopeToolbar === 'function') {window._updateScopeToolbar();}
    });
}

/**
 * @purpose Orchestrator for theoretical graph rendering on the details panel canvas.
 * Drawing functions extracted to panel_graphics_shapes.js (waveform evaluators + per-section drawers).
 * @purpose_en Graph rendering orchestrator for panel_edit details.
 * @lastUpdated 2026-07-25
 */

window.drawPanelGraphic = function() {
    const canvas = document.getElementById('panel-graphic-canvas');
    if (!canvas) {return;}
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    const state = window.panelEditState || {};
    const currentPanelMode = state.currentPanelMode || 'LFO';

    // Obtener color activo de la marca desde CSS variables de forma segura
    const brandColor = getComputedStyle(document.documentElement).getPropertyValue('--brand-accent').trim() || '#ff9900';

    // Obtener colores del osciloscopio en tiempo real para coherencia visual completa
    let colors = null;
    if (typeof window._getScopeColors === 'function') {
        colors = window._getScopeColors();
    }

    if (!colors) {
        colors = {
            waveform: brandColor,
            grid: window.pgHexToRgba(brandColor, 0.03),
            center: window.pgHexToRgba(brandColor, 0.08),
            text: window.pgHexToRgba(brandColor, 0.4),
            glow: brandColor,
            trigger: window.pgHexToRgba(brandColor, 0.15)
        };
    }

    // Dibujar cuadrícula de fondo retro (CRT) coherente con el osciloscopio
    if (typeof window._drawGraphGrid === 'function') {
        window._drawGraphGrid(ctx, w, h, colors, currentPanelMode);
    }

    if (!window.dualMidiBridge || !window.dualMidiBridge.parameterCache) {return;}
    const cache = window.dualMidiBridge.parameterCache;

    // Delegar a los drawers específicos según el modo de panel activo
    if ((currentPanelMode === 'ENV' || currentPanelMode === 'VCA') && typeof window._drawEnvGraph === 'function') {
        window._drawEnvGraph(ctx, w, h, colors, cache, state);
    } else if (currentPanelMode === 'LFO' && typeof window._drawLfoGraph === 'function') {
        window._drawLfoGraph(ctx, w, h, colors, cache, state);
    } else if ((currentPanelMode === 'VCF' || currentPanelMode === 'HPF') && typeof window._drawVcfGraph === 'function') {
        window._drawVcfGraph(ctx, w, h, colors, cache, state);
    } else if (currentPanelMode === 'OSC' && typeof window._drawOscGraph === 'function') {
        window._drawOscGraph(ctx, w, h, colors, cache, state);
    } else if (currentPanelMode === 'ARP' && typeof window._drawArpGraph === 'function') {
        window._drawArpGraph(ctx, w, h, colors, cache, state);
    }
};

/**
 * @purpose Arpeggiator pattern graph drawer with animated step dots.
 * Extracted from panel_graphics_shapes.js.
 */

/** Draw arpeggiator pattern with step dots */
window._drawArpGraph = function(ctx, w, h, colors, cache, state) {
    const _animTime = state._animTime || 0;

    ctx.strokeStyle = colors.waveform;
    ctx.shadowColor = window.pgHexToRgba(colors.waveform, 0.4);
    ctx.shadowBlur = 4;
    ctx.lineWidth = 2;
    const padding = 10;
    const graphW = w - padding * 2;
    const graphH = h - padding * 2;
    const centerY = h / 2;

    const arpRate = typeof cache['arp_rate'] !== 'undefined' ? cache['arp_rate'] : 0.5;
    const bpm = 20 + arpRate * 220;
    const beatMs = 60000 / bpm;
    const stepDuration = beatMs / 4;
    const stepIndex = Math.floor((_animTime % (stepDuration * 8)) / stepDuration);

    ctx.beginPath();
    const steps = 8;
    const stepW = graphW / steps;
    for (let i = 0; i <= steps; i++) {
        const x = padding + i * stepW;
        const y = centerY + (i % 4 - 2) * (graphH / 4);
        if (i === 0) {ctx.moveTo(x, y);}
        else {ctx.lineTo(x, y);}
    }
    ctx.stroke();

    ctx.shadowBlur = 0;

    // Draw active step dot
    if (stepIndex >= 0 && stepIndex < steps) {
        const dotX = padding + (stepIndex + 0.5) * stepW;
        const dotY = centerY + (stepIndex % 4 - 2) * (graphH / 4);
        ctx.fillStyle = colors.waveform;
        ctx.shadowColor = colors.glow;
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.arc(dotX, dotY, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;
    }
};

/**
 * @purpose Base graphics functions for panel graph canvas: waveform evaluators and grid background.
 * Extracted from panel_graphics_shapes.js.
 */

/** Evaluate LFO waveform shape at a given phase position */
window._evalLfoWaveform = function(shapeVal, pct, phase) {
    const angle = pct * Math.PI * 4 + phase;
    let yVal = 0;
    if (shapeVal === 0) {
        yVal = Math.sin(angle);
    } else if (shapeVal === 1) {
        const mod = angle % (Math.PI * 2);
        if (mod < Math.PI) {
            yVal = 1.0 - (mod / (Math.PI / 2));
        } else {
            yVal = -1.0 + ((mod - Math.PI) / (Math.PI / 2));
        }
    } else if (shapeVal === 2) {
        yVal = (angle % (Math.PI * 2)) < Math.PI ? 1.0 : -1.0;
    } else if (shapeVal === 3) {
        yVal = -1.0 + 2.0 * ((angle % (Math.PI * 2)) / (Math.PI * 2));
    } else if (shapeVal === 4) {
        yVal = 1.0 - 2.0 * ((angle % (Math.PI * 2)) / (Math.PI * 2));
    } else {
        const steps = 8;
        const stepIdx = Math.floor(pct * steps);
        const randVals = [0.2, -0.6, 0.7, -0.2, -0.8, 0.4, -0.1, 0.5];
        yVal = randVals[stepIdx % randVals.length];
        if (shapeVal === 6) {
            const nextVal = randVals[(stepIdx + 1) % randVals.length];
            const interp = (pct * steps) % 1.0;
            yVal = yVal + (nextVal - yVal) * interp;
        }
    }
    return yVal;
};

/** Evaluate oscillator waveform (saw + square mix) at a given phase position */
window._evalOscWaveform = function(sawEn, sqEn, osc2Lvl, osc2Pitch, pct, phase) {
    const angle = pct * Math.PI * 6 + phase;
    let yVal = 0;
    if (sawEn) {yVal += -0.5 + ((angle % (Math.PI * 2)) / (Math.PI * 2));}
    if (sqEn) {yVal += (angle % (Math.PI * 2)) < Math.PI ? 0.35 : -0.35;}
    const osc2Phase = phase + osc2Pitch * Math.PI * 2;
    const a2 = pct * Math.PI * 6 + osc2Phase;
    yVal += osc2Lvl * 0.3 * Math.sin(a2 * 1.5);
    return yVal;
};

/** Draw CRT-style retro grid background on the graph canvas */
window._drawGraphGrid = function(ctx, w, h, colors, currentPanelMode) {
    ctx.strokeStyle = colors.grid;
    ctx.lineWidth = 1;
    for (let x = 0; x < w; x += 15) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, h);
        ctx.stroke();
    }
    for (let y = 0; y < h; y += 15) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
    }
    if (currentPanelMode === 'LFO' || currentPanelMode === 'OSC') {
        ctx.strokeStyle = colors.center;
        ctx.lineWidth = 1;
        ctx.setLineDash([2, 3]);
        ctx.beginPath();
        ctx.moveTo(0, h / 2);
        ctx.lineTo(w, h / 2);
        ctx.stroke();
        ctx.setLineDash([]);
    }
};

/**
 * @purpose ADSR envelope graph drawer (ENV / VCA modes).
 * Extracted from panel_graphics_shapes.js.
 */

/** Draw ADSR envelope curve with VCA mode overlay if applicable */
window._drawEnvGraph = function(ctx, w, h, colors, cache, state) {
    const currentPanelMode = state.currentPanelMode || 'ENV';
    const panelActiveEnv = state.panelActiveEnv || 1;
    const envNum = currentPanelMode === 'VCA' ? 1 : panelActiveEnv;
    const prefix = 'env' + envNum + '_';

    const a = typeof cache[prefix + 'attack'] !== 'undefined' ? cache[prefix + 'attack'] : 0.2;
    const d = typeof cache[prefix + 'decay'] !== 'undefined' ? cache[prefix + 'decay'] : 0.35;
    const s = typeof cache[prefix + 'sustain'] !== 'undefined' ? cache[prefix + 'sustain'] : 0.55;
    const r = typeof cache[prefix + 'release'] !== 'undefined' ? cache[prefix + 'release'] : 0.4;

    const aCurve = typeof cache[prefix + 'attack_curve'] !== 'undefined' ? (cache[prefix + 'attack_curve'] * 2.0 - 1.0) : 0.0;
    const dCurve = typeof cache[prefix + 'decay_curve'] !== 'undefined' ? (cache[prefix + 'decay_curve'] * 2.0 - 1.0) : 0.0;
    const rCurve = typeof cache[prefix + 'release_curve'] !== 'undefined' ? (cache[prefix + 'release_curve'] * 2.0 - 1.0) : 0.0;

    const padding = 10;
    const graphW = w - padding * 2;
    const graphH = h - padding * 2;
    const startX = padding;
    const startY = h - padding;

    let envAmp = 1.0;
    let baseOffset = 0.0;
    let isBallsy = false;

    if (currentPanelMode === 'VCA') {
        const vcaLvl = typeof cache['vca_level'] !== 'undefined' ? cache['vca_level'] : 0.5;
        const vcaEnvDepth = typeof cache['vca_env_depth'] !== 'undefined' ? cache['vca_env_depth'] : 0.5;
        const vcaModeVal = typeof cache['vca_mode'] !== 'undefined' ? cache['vca_mode'] : 0.0;

        envAmp = vcaEnvDepth;
        baseOffset = vcaLvl;
        isBallsy = vcaModeVal > 0.5;
    }

    const getY = (val) => {
        const norm = baseOffset + val * envAmp;
        const clamped = Math.max(0.0, Math.min(1.0, norm));
        return startY - clamped * graphH * 0.9;
    };

    const totalTime = a + d + 0.7 + r;
    const aW = Math.max(4, (a / totalTime) * graphW);
    const dW = Math.max(4, (d / totalTime) * graphW);
    const sW = Math.max(8, (0.7 / totalTime) * graphW);
    const rW = Math.max(4, (r / totalTime) * graphW);

    const p0 = [startX, getY(0.0)];
    const p1 = [startX + aW, getY(1.0)];
    const p2 = [p1[0] + dW, getY(s)];
    const p3 = [p2[0] + sW, p2[1]];
    const p4 = [p3[0] + rW, getY(0.0)];

    // Fill under curve
    ctx.fillStyle = window.pgHexToRgba(colors.waveform, 0.05);
    ctx.beginPath();
    ctx.moveTo(p0[0], p0[1]);
    for (let i = 0; i <= 20; i++) {
        const t = window.pgApplyCurve(i / 20, aCurve);
        ctx.lineTo(p0[0] + (p1[0] - p0[0]) * (i / 20), p0[1] + (p1[1] - p0[1]) * t);
    }
    for (let i = 0; i <= 20; i++) {
        const t = window.pgApplyCurve(i / 20, dCurve);
        ctx.lineTo(p1[0] + (p2[0] - p1[0]) * (i / 20), p1[1] + (p2[1] - p1[1]) * t);
    }
    ctx.lineTo(p3[0], p3[1]);
    for (let i = 0; i <= 20; i++) {
        const t = window.pgApplyCurve(i / 20, rCurve);
        ctx.lineTo(p3[0] + (p4[0] - p3[0]) * (i / 20), p3[1] + (p4[1] - p3[1]) * t);
    }
    ctx.lineTo(startX + graphW, startY);
    ctx.lineTo(startX, startY);
    ctx.fill();

    // Stroke curve
    ctx.strokeStyle = colors.waveform;
    if (currentPanelMode === 'VCA' && isBallsy) {
        ctx.shadowColor = colors.glow;
        ctx.shadowBlur = 8;
        ctx.lineWidth = 3;
    } else {
        ctx.shadowColor = window.pgHexToRgba(colors.waveform, 0.4);
        ctx.shadowBlur = 4;
        ctx.lineWidth = 2;
    }

    ctx.beginPath();
    ctx.moveTo(p0[0], p0[1]);
    for (let i = 0; i <= 20; i++) {
        const t = window.pgApplyCurve(i / 20, aCurve);
        ctx.lineTo(p0[0] + (p1[0] - p0[0]) * (i / 20), p0[1] + (p1[1] - p0[1]) * t);
    }
    for (let i = 0; i <= 20; i++) {
        const t = window.pgApplyCurve(i / 20, dCurve);
        ctx.lineTo(p1[0] + (p2[0] - p1[0]) * (i / 20), p1[1] + (p2[1] - p1[1]) * t);
    }
    ctx.lineTo(p3[0], p3[1]);
    for (let i = 0; i <= 20; i++) {
        const t = window.pgApplyCurve(i / 20, rCurve);
        ctx.lineTo(p3[0] + (p4[0] - p3[0]) * (i / 20), p3[1] + (p4[1] - p3[1]) * t);
    }
    ctx.stroke();

    ctx.shadowBlur = 0;

    // Draw segment markers
    ctx.fillStyle = colors.waveform;
    [p1, p2, p3].forEach(pt => {
        ctx.beginPath();
        ctx.arc(pt[0], pt[1], 3, 0, Math.PI * 2);
        ctx.fill();
    });

    const envLabel = currentPanelMode === 'VCA'
        ? 'ENV 1 (VCA) - ' + (isBallsy ? 'Ballsy' : 'Transparent')
        : ['', 'ENV 1 VCA', 'ENV 2 VCF', 'ENV 3 MOD'][envNum] || 'ENV ' + envNum;
    ctx.fillStyle = colors.text;
    ctx.font = '7px Share Tech Mono, monospace';
    ctx.fillText(envLabel, padding + 2, padding + 8);
};

/**
 * @purpose LFO waveform graph drawer with CRT phosphor ghost trail.
 * Extracted from panel_graphics_shapes.js.
 */

/** Draw LFO waveform with animated phase and ghost (CRT phosphor trail) */
window._drawLfoGraph = function(ctx, w, h, colors, cache, state) {
    const panelActiveLfo = state.panelActiveLfo || 1;
    const prefix = 'lfo' + panelActiveLfo + '_';
    const _animTime = state._animTime || 0;
    const shapeVal = typeof cache[prefix + 'shape'] !== 'undefined' ? Math.round(cache[prefix + 'shape'] * 6) : 1;
    const lfoRate = typeof cache[prefix + 'rate'] !== 'undefined' ? cache[prefix + 'rate'] : 0.5;

    ctx.strokeStyle = colors.waveform;
    ctx.shadowColor = window.pgHexToRgba(colors.waveform, 0.4);
    ctx.shadowBlur = 4;
    ctx.lineWidth = 2;
    ctx.beginPath();

    const padding = 10;
    const graphW = w - padding * 2;
    const graphH = h - padding * 2;
    const centerY = h / 2;

    const freq = 0.5 + lfoRate * 4.0;
    const phaseOffset = (_animTime / 1000) * freq * Math.PI * 2;

    // Main waveform
    for (let x = 0; x < graphW; x++) {
        const pct = x / graphW;
        const yVal = window._evalLfoWaveform(shapeVal, pct, phaseOffset);
        const canvasX = padding + x;
        const canvasY = centerY - yVal * (graphH / 2);
        if (x === 0) {ctx.moveTo(canvasX, canvasY);}
        else {ctx.lineTo(canvasX, canvasY);}
    }
    ctx.stroke();

    // Ghost wave (CRT phosphor trail)
    ctx.shadowBlur = 0;
    ctx.strokeStyle = window.pgHexToRgba(colors.waveform, 0.08);
    ctx.lineWidth = 1;
    ctx.beginPath();
    const ghostPhase = phaseOffset - freq * Math.PI * 0.2;
    for (let x = 0; x < graphW; x++) {
        const pct = x / graphW;
        const yVal = window._evalLfoWaveform(shapeVal, pct, ghostPhase);
        const canvasX = padding + x;
        const canvasY = centerY - yVal * (graphH / 2);
        if (x === 0) {ctx.moveTo(canvasX, canvasY);}
        else {ctx.lineTo(canvasX, canvasY);}
    }
    ctx.stroke();
};

/**
 * @purpose Pure math functions for canvas rendering in panel graphics.
 * Extracted from panel_graphics.js — pure functions, no canvas/DOM dependencies.
 * All functions are deterministic: same inputs → same outputs.
 */

// ──────────────────────────────────────────────
// Color helpers
// ──────────────────────────────────────────────

window.pgHexToRgba = function(hex, alpha) {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return 'rgba(' + r + ', ' + g + ', ' + b + ', ' + alpha + ')';
};

// ──────────────────────────────────────────────
// Envelope curve shaping
// ──────────────────────────────────────────────

window.pgApplyCurve = function(t, curve) {
    if (Math.abs(curve) < 0.01) {return t;}
    const exp = curve < 0 ? 1.0 - curve * 3.0 : 1.0 / (1.0 + curve * 3.0);
    return Math.pow(t, exp);
};

// ──────────────────────────────────────────────
// LFO waveform evaluation
// ──────────────────────────────────────────────

window.pgEvalLfoWaveform = function(shapeVal, pct, phase) {
    const angle = pct * Math.PI * 4 + phase;
    let yVal = 0;
    if (shapeVal === 0) {
        yVal = Math.sin(angle);
    } else if (shapeVal === 1) {
        const mod = angle % (Math.PI * 2);
        if (mod < Math.PI) {
            yVal = 1.0 - (mod / (Math.PI / 2));
        } else {
            yVal = -1.0 + ((mod - Math.PI) / (Math.PI / 2));
        }
    } else if (shapeVal === 2) {
        yVal = (angle % (Math.PI * 2)) < Math.PI ? 1.0 : -1.0;
    } else if (shapeVal === 3) {
        yVal = -1.0 + 2.0 * ((angle % (Math.PI * 2)) / (Math.PI * 2));
    } else if (shapeVal === 4) {
        yVal = 1.0 - 2.0 * ((angle % (Math.PI * 2)) / (Math.PI * 2));
    } else {
        const steps = 8;
        const stepIdx = Math.floor(pct * steps);
        const randVals = [0.2, -0.6, 0.7, -0.2, -0.8, 0.4, -0.1, 0.5];
        yVal = randVals[stepIdx % randVals.length];
        if (shapeVal === 6) {
            const nextVal = randVals[(stepIdx + 1) % randVals.length];
            const interp = (pct * steps) % 1.0;
            yVal = yVal + (nextVal - yVal) * interp;
        }
    }
    return yVal;
};

// ──────────────────────────────────────────────
// Oscillator waveform mixing
// ──────────────────────────────────────────────

window.pgEvalOscWaveform = function(sawEn, sqEn, osc2Lvl, osc2Pitch, pct, phase) {
    const angle = pct * Math.PI * 6 + phase;
    let yVal = 0;
    if (sawEn) {yVal += -0.5 + ((angle % (Math.PI * 2)) / (Math.PI * 2));}
    if (sqEn) {yVal += (angle % (Math.PI * 2)) < Math.PI ? 0.35 : -0.35;}
    const osc2Phase = phase + osc2Pitch * Math.PI * 2;
    const a2 = pct * Math.PI * 6 + osc2Phase;
    yVal += osc2Lvl * 0.3 * Math.sin(a2 * 1.5);
    return yVal;
};

// ──────────────────────────────────────────────
// Envelope ADSR helpers
// ──────────────────────────────────────────────

window.pgCalcEnvelopeWidths = function(a, d, s, r, graphW) {
    const totalTime = a + d + 0.7 + r;
    return {
        aW: Math.max(4, (a / totalTime) * graphW),
        dW: Math.max(4, (d / totalTime) * graphW),
        sW: Math.max(8, (0.7 / totalTime) * graphW),
        rW: Math.max(4, (r / totalTime) * graphW)
    };
};

window.pgCalcEnvelopePoints = function(aW, dW, sW, rW, sustainVal, graphH, startX, startY) {
    const p0 = [startX, startY];
    const p1 = [startX + aW, startY - graphH];
    const p2 = [p1[0] + dW, startY - sustainVal * graphH];
    const p3 = [p2[0] + sW, p2[1]];
    const p4 = [p3[0] + rW, startY];
    return { p0: p0, p1: p1, p2: p2, p3: p3, p4: p4 };
};

// ──────────────────────────────────────────────
// Filter frequency response
// ──────────────────────────────────────────────

window.pgCalcVcfGain = function(freq, cutoff, resonance) {
    if (freq < cutoff) {
        const dist = cutoff - freq;
        if (dist < 0.1) {
            const peak = resonance * 1.8 * (1.0 - dist / 0.1);
            return 1.0 + peak;
        }
        return 1.0;
    } else {
        const dist = freq - cutoff;
        return (1.0 + resonance * 1.8) / (1.0 + (dist * 12.0) * (dist * 12.0));
    }
};

window.pgCalcHpfGain = function(freq, cutoff) {
    if (freq > cutoff) {
        return 1.0;
    } else {
        const dist = cutoff - freq;
        return 1.0 / (1.0 + (dist * 15.0) * (dist * 15.0));
    }
};

// ──────────────────────────────────────────────
// Arpeggiator note position
// ──────────────────────────────────────────────

window.pgCalcArpStepY = function(stepIndex, graphH, centerY) {
    return centerY + (stepIndex % 4 - 2) * (graphH / 4);
};

/**
 * @purpose Oscillator waveform graph drawer (OSC1/OSC2) with CRT ghost trail.
 * Extracted from panel_graphics_shapes.js.
 */

/** Draw oscillator waveform (OSC1 or OSC2) with CRT ghost trail */
window._drawOscGraph = function(ctx, w, h, colors, cache, state) {
    const panelActiveOsc = state.panelActiveOsc || 1;
    const _animTime = state._animTime || 0;

    ctx.strokeStyle = colors.waveform;
    ctx.shadowColor = window.pgHexToRgba(colors.waveform, 0.4);
    ctx.shadowBlur = 4;
    ctx.lineWidth = 2;
    ctx.beginPath();

    const padding = 10;
    const graphW = w - padding * 2;
    const graphH = h - padding * 2;
    const centerY = h / 2;

    const oscPhase = (_animTime / 1000) * Math.PI * 2 * 2.2;

    function drawOscWave(isOsc2) {
        ctx.beginPath();
        for (let x = 0; x < graphW; x++) {
            const pct = x / graphW;
            let yVal = 0;
            if (!isOsc2) {
                const sawEn = typeof cache['osc1_saw_enable'] !== 'undefined' ? cache['osc1_saw_enable'] > 0.5 : true;
                const sqEn = typeof cache['osc1_square_enable'] !== 'undefined' ? cache['osc1_square_enable'] > 0.5 : false;
                const angle = pct * Math.PI * 6 + oscPhase;
                if (sawEn) {yVal += -0.5 + ((angle % (Math.PI * 2)) / (Math.PI * 2));}
                if (sqEn) {yVal += (angle % (Math.PI * 2)) < Math.PI ? 0.35 : -0.35;}
            } else {
                const toneMod = typeof cache['osc2_tone_mod'] !== 'undefined' ? cache['osc2_tone_mod'] : 0.5;
                const angle = pct * Math.PI * 6 + oscPhase;
                const modAngle = angle % (Math.PI * 2);
                const duty = 0.2 + toneMod * 0.6;
                yVal = modAngle < Math.PI * duty ? 0.7 : -0.7;
            }
            const canvasX = padding + x;
            const canvasY = centerY - yVal * (graphH / 2);
            if (x === 0) {ctx.moveTo(canvasX, canvasY);}
            else {ctx.lineTo(canvasX, canvasY);}
        }
        ctx.stroke();
    }

    drawOscWave(panelActiveOsc === 2);

    // Ghost wave
    ctx.shadowBlur = 0;
    const ghostOscPhase = oscPhase - Math.PI * 0.5;
    ctx.strokeStyle = window.pgHexToRgba(colors.waveform, 0.06);
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 0; x < graphW; x++) {
        const pct = x / graphW;
        let yVal = 0;
        if (panelActiveOsc !== 2) {
            const sawEn = typeof cache['osc1_saw_enable'] !== 'undefined' ? cache['osc1_saw_enable'] > 0.5 : true;
            const sqEn = typeof cache['osc1_square_enable'] !== 'undefined' ? cache['osc1_square_enable'] > 0.5 : false;
            const angle = pct * Math.PI * 6 + ghostOscPhase;
            if (sawEn) {yVal += -0.5 + ((angle % (Math.PI * 2)) / (Math.PI * 2));}
            if (sqEn) {yVal += (angle % (Math.PI * 2)) < Math.PI ? 0.35 : -0.35;}
        } else {
            const toneMod = typeof cache['osc2_tone_mod'] !== 'undefined' ? cache['osc2_tone_mod'] : 0.5;
            const angle = pct * Math.PI * 6 + ghostOscPhase;
            const modAngle = angle % (Math.PI * 2);
            const duty = 0.2 + toneMod * 0.6;
            yVal = modAngle < Math.PI * duty ? 0.7 : -0.7;
        }
        const canvasX = padding + x;
        const canvasY = centerY - yVal * (graphH / 2);
        if (x === 0) {ctx.moveTo(canvasX, canvasY);}
        else {ctx.lineTo(canvasX, canvasY);}
    }
    ctx.stroke();
};

/**
 * @purpose VCF/HPF frequency response graph drawer with resonance peak and ghost reference.
 * Extracted from panel_graphics_shapes.js.
 */

/** Draw VCF/HPF frequency response curve with resonance peak and ghost reference */
window._drawVcfGraph = function(ctx, w, h, colors, cache, state) {
    const currentPanelMode = state.currentPanelMode || 'VCF';
    const _animTime = state._animTime || 0;
    let cutoff = 0.5;
    let resonance = 0.0;
    let vcfModel = 0;
    let moogSubMode = 0;
    let korgSubMode = 0;
    let vcfPoleMode = 0;

    if (currentPanelMode === 'VCF') {
        cutoff = typeof cache['vcf_cutoff'] !== 'undefined' ? cache['vcf_cutoff'] : 0.5;
        resonance = typeof cache['vcf_resonance'] !== 'undefined' ? cache['vcf_resonance'] : 0.0;
        vcfModel = typeof cache['vcf_model'] !== 'undefined' ? Math.round(cache['vcf_model'] * 2) : 0;
        moogSubMode = typeof cache['vcf_moog_submode'] !== 'undefined' ? Math.round(cache['vcf_moog_submode'] * 2) : 0;
        korgSubMode = typeof cache['vcf_korg_submode'] !== 'undefined' ? Math.round(cache['vcf_korg_submode'] * 1) : 0;
        vcfPoleMode = typeof cache['vcf_pole_mode'] !== 'undefined' ? cache['vcf_pole_mode'] : 0;
        const lfoDepth = typeof cache['vcf_lfo_depth'] !== 'undefined' ? cache['vcf_lfo_depth'] : 0.0;
        if (lfoDepth > 0.01) {
            const lfoPhase = (_animTime / 1000) * Math.PI * 2 * 1.5;
            const modRange = cutoff * 0.8;
            cutoff += Math.sin(lfoPhase) * modRange * lfoDepth;
            cutoff = Math.max(0.01, Math.min(0.99, cutoff));
        }
    } else {
        cutoff = typeof cache['hpf_cutoff'] !== 'undefined' ? cache['hpf_cutoff'] : 0.2;
        const wobble = 0.02 * Math.sin((_animTime / 1000) * Math.PI * 2 * 0.8);
        cutoff += wobble;
        cutoff = Math.max(0.01, Math.min(0.99, cutoff));
    }

    // Determine effective response type and resonance character
    let responseType = 'LP';
    let resMultiplier = 1.8;
    if (currentPanelMode === 'VCF') {
        if (vcfModel === 1) {
            if (moogSubMode === 1) { responseType = 'BP'; }
            else if (moogSubMode === 2) { responseType = 'HP'; }
            resMultiplier = 2.2;
        } else if (vcfModel === 2) {
            if (korgSubMode === 1) { responseType = 'HP'; }
            resMultiplier = 3.0;
        }
    }

    // Compute gain for a given normalized frequency (0..1)
    function vcfGain(freq) {
        if (currentPanelMode === 'HPF') {
            if (freq > cutoff) { return 1.0; }
const d = cutoff - freq;
            return 1.0 / (1.0 + (d * 15.0) * (d * 15.0));
        }
        const slope = vcfPoleMode === 1 ? 7.0 : 14.0;
        if (responseType === 'LP') {
            if (freq < cutoff) {
const d = cutoff - freq;
                if (d < 0.1) { return 1.0 + resonance * resMultiplier * (1.0 - d / 0.1); }
                return 1.0;
            } else {
const d = freq - cutoff;
                return (1.0 + resonance * resMultiplier) / (1.0 + (d * slope) * (d * slope));
            }
        } else if (responseType === 'BP') {
const d = Math.abs(freq - cutoff);
            return (1.0 + resonance * resMultiplier * 1.5) / (1.0 + (d * 18.0) * (d * 18.0));
        } else {
            // HP
            if (freq > cutoff) {
const d = freq - cutoff;
                if (d < 0.1) { return 1.0 + resonance * resMultiplier * (1.0 - d / 0.1); }
                return 1.0;
            } else {
const d = cutoff - freq;
                return (1.0 + resonance * resMultiplier) / (1.0 + (d * 12.0) * (d * 12.0));
            }
        }
    }

    ctx.strokeStyle = colors.waveform;
    ctx.shadowColor = window.pgHexToRgba(colors.waveform, 0.4);
    ctx.shadowBlur = 4;
    ctx.lineWidth = 2;
    ctx.beginPath();

    const padding = 10;
    const graphW = w - padding * 2;
    const graphH = h - padding * 2;
    const startY = h - padding;

    for (let x = 0; x < graphW; x++) {
        const freq = x / graphW;
        const gain = vcfGain(freq);
        const canvasX = padding + x;
        const canvasY = startY - gain * (graphH * 0.7);
        if (x === 0) { ctx.moveTo(canvasX, canvasY); }
        else { ctx.lineTo(canvasX, canvasY); }
    }
    ctx.stroke();

    // Ghost wave (base cutoff without LFO modulation)
    if (currentPanelMode === 'VCF') {
        const baseCutoff = typeof cache['vcf_cutoff'] !== 'undefined' ? cache['vcf_cutoff'] : 0.5;
        const slope = vcfPoleMode === 1 ? 7.0 : 14.0;
        ctx.shadowBlur = 0;
        ctx.strokeStyle = window.pgHexToRgba(colors.waveform, 0.08);
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let x2 = 0; x2 < graphW; x2++) {
            const freq2 = x2 / graphW;
let d2, gain2;
            if (responseType === 'LP') {
                if (freq2 < baseCutoff) {
                    d2 = baseCutoff - freq2;
                    gain2 = (d2 < 0.1) ? 1.0 + resonance * resMultiplier * (1.0 - d2 / 0.1) : 1.0;
                } else {
                    d2 = freq2 - baseCutoff;
                    gain2 = (1.0 + resonance * resMultiplier) / (1.0 + (d2 * slope) * (d2 * slope));
                }
            } else if (responseType === 'BP') {
                d2 = Math.abs(freq2 - baseCutoff);
                gain2 = (1.0 + resonance * resMultiplier * 1.5) / (1.0 + (d2 * 18.0) * (d2 * 18.0));
            } else {
                if (freq2 > baseCutoff) {
                    d2 = freq2 - baseCutoff;
                    gain2 = (d2 < 0.1) ? 1.0 + resonance * resMultiplier * (1.0 - d2 / 0.1) : 1.0;
                } else {
                    d2 = baseCutoff - freq2;
                    gain2 = (1.0 + resonance * resMultiplier) / (1.0 + (d2 * 12.0) * (d2 * 12.0));
                }
            }
            const canvasX2 = padding + x2;
            const canvasY2 = startY - gain2 * (graphH * 0.7);
            if (x2 === 0) { ctx.moveTo(canvasX2, canvasY2); }
            else { ctx.lineTo(canvasX2, canvasY2); }
        }
        ctx.stroke();
    }
};

/**
 * @purpose Panel layout toggles: screen/scope height controls, audio waveform polling,
 *           and panel mutation observer for auto-start/stop animations.
 * Extraído de panel_animations.js para SRP.
 * @classification Module/Panel/Layout
 */

/* ── Screen & Scope Height Toggles ── */

window.updateScreenHeight = function() {
    const state = window.panelEditState;
    const screenEl = document.getElementById('panel-graphic-screen');
    const screenToggleBtn = document.getElementById('panel-graphic-toggle');
    const noScreenModes = ['POLY', 'PORTA', 'CHORD', 'POLY_CHORD'];
    if (!screenEl || !screenToggleBtn) {return;}
    if (noScreenModes.includes(state.currentPanelMode)) {
        screenEl.style.height = '0px';
        screenEl.style.borderBottomWidth = '0px';
        screenEl.style.display = 'none';
        screenToggleBtn.style.display = 'none';
    } else {
        screenEl.style.display = 'flex';
        screenToggleBtn.style.display = 'block';
        if (state.isScreenCollapsed) {
            screenEl.style.height = '0px';
            screenEl.style.borderBottomWidth = '0px';
            screenToggleBtn.innerHTML = '&#9660; EXPAND &#9660;';
        } else {
            screenEl.style.height = '100px';
            screenEl.style.borderBottomWidth = '1.5px';
            screenToggleBtn.innerHTML = '&#9650; COLLAPSE &#9650;';
        }
    }
};

window.updateRealScopeHeight = function() {
    const state = window.panelEditState;
    const realScopeScreenEl = document.getElementById('panel-real-scope-screen');
    const realScopeToggleBtn = document.getElementById('panel-real-scope-toggle');
    const noScopeModes = ['POLY', 'PORTA', 'CHORD', 'POLY_CHORD', 'ARP'];
    if (!realScopeScreenEl || !realScopeToggleBtn) {return;}
    const isJuce = window.dualMidiBridge && window.dualMidiBridge.isJuce;
    const hasWebAudio = window.wasmBridge && window.wasmBridge.isAudioStarted;
    const toolbar = document.getElementById('scope-toolbar');
    if (noScopeModes.includes(state.currentPanelMode)) {
        realScopeScreenEl.style.display = 'none';
        realScopeToggleBtn.style.display = 'none';
        _stopAudioWaveformPolling();
        return;
    }
    realScopeScreenEl.style.display = 'flex';
    realScopeToggleBtn.style.display = 'block';
    if (state.isRealScopeCollapsed) {
        realScopeScreenEl.style.height = '0px';
        realScopeScreenEl.style.borderBottomWidth = '0px';
        if (isJuce) {
            realScopeToggleBtn.innerHTML = '🔴 DSP SCOPE (off)';
        } else if (hasWebAudio) {
            realScopeToggleBtn.innerHTML = '🔴 WEB SCOPE (off)';
        } else {
            realScopeToggleBtn.innerHTML = '⚫ DSP SCOPE (no engine)';
        }
        if (toolbar) {toolbar.style.display = 'none';}
    } else {
        realScopeScreenEl.style.height = '113px';
        realScopeScreenEl.style.borderBottomWidth = '1.5px';
        if (isJuce) {
            realScopeToggleBtn.innerHTML = '🟢 DSP SCOPE (live)';
        } else if (hasWebAudio) {
            realScopeToggleBtn.innerHTML = '🟢 WEB SCOPE (live)';
        } else {
            realScopeToggleBtn.innerHTML = '⚫ DSP SCOPE (no engine)';
        }
        if (toolbar) {toolbar.style.display = 'flex';}
    }
};

/* ── Audio Waveform Polling ── */

let _audioWaveformTimer = null;

function _startAudioWaveformPolling() {
    if (_audioWaveformTimer) {return;}
    _audioWaveformTimer = setInterval(function() {
        const bridge = window.dualMidiBridge;
        if (!bridge || !bridge.isJuce) {return;}
        bridge.getAudioWaveform().catch(function() {});
    }, 33);
}

function _stopAudioWaveformPolling() {
    if (_audioWaveformTimer) {
        clearInterval(_audioWaveformTimer);
        _audioWaveformTimer = null;
    }
}

window._updateAudioWaveformPolling = function() {
    const hasBridge = window.dualMidiBridge;
    const isJuce = hasBridge && hasBridge.isJuce;
    const progToggle = window.programmerDisplayToggle;
    const isProgScopeActive = progToggle && progToggle.mode !== 'sysex';
    const panel = document.getElementById('detail-edit-panel');
    const state = window.panelEditState || {};
    const isSidePanelScopeActive = panel && panel.classList.contains('active') && !state.isRealScopeCollapsed;

    const shouldPoll = isJuce && (isProgScopeActive || isSidePanelScopeActive);
    if (shouldPoll) {
        _startAudioWaveformPolling();
    } else {
        _stopAudioWaveformPolling();
    }
};

/* ── Panel Mutation Observer ── */

window._initPanelObserver = function() {
    const panel = document.getElementById('detail-edit-panel');
    const state = window.panelEditState;
    const noScreenModes = ['POLY', 'PORTA', 'CHORD', 'POLY_CHORD'];
    if (!panel) {return;}

    const observer = new MutationObserver(function() {
        if (panel.classList.contains('active') && !noScreenModes.includes(state.currentPanelMode)) {
            if (typeof window._startCanvasAnimation === 'function') {
                window._startCanvasAnimation();
            }
            window._updateAudioWaveformPolling();
        } else if (!panel.classList.contains('active')) {
            window._updateAudioWaveformPolling();
        }
    });
    observer.observe(panel, { attributes: true, attributeFilter: ['class'] });
};

/**
 * @purpose Renders the real-time audio oscilloscope (DSP engine waveform + FFT spectrum)
 * on the details panel. Supports 3 view modes: WAVE (waveform only), SPC (spectrum only),
 * DUAL (split view). Core helpers in panel_oscilloscope_core.js.
 * FFT spectrum, filter overlay, and filter math extracted to
 * panel_oscilloscope_spectrum.js.
 * Waveform rendering extracted to panel_oscilloscope_waveform.js.
 * @purpose_en Real-time DSP oscilloscope + spectrum analyzer.
 */

/* global _getScopeColors, _findTriggerPoint, SCOPE_COLORS, hexToRgba, _drawWaveform, _drawPlaceholder */

window.drawRealScope = function(targetCanvasId) {
    const canvas = document.getElementById(targetCanvasId || 'programmer-scope-canvas') || document.getElementById('panel-real-scope-canvas');
    if (!canvas) {return;}

    if (canvas.clientWidth && canvas.clientHeight && (canvas.width !== canvas.clientWidth || canvas.height !== canvas.clientHeight)) {
        canvas.width = canvas.clientWidth;
        canvas.height = canvas.clientHeight;
    }

    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    const bridge = window.dualMidiBridge;
    const isJuce = bridge && bridge.isJuce;
    const colors = typeof window._getScopeColors === 'function' ? window._getScopeColors()
        : { grid: 'rgba(51,51,51,0.2)', center: 'rgba(102,102,102,0.3)', trigger: 'rgba(255,200,0,0.5)', waveform: '#00ffcc', text: 'rgba(200,200,200,0.7)' };
    const state = window.panelEditState || {};
    const viewMode = state._scopeViewMode || 0; // 0=DUAL, 1=WAVE, 2=SPC

    // ── Grid ──
    ctx.strokeStyle = colors.grid;
    ctx.lineWidth = 1;
    for (let gx = 0; gx < w; gx += 15) { ctx.beginPath(); ctx.moveTo(gx, 0); ctx.lineTo(gx, h); ctx.stroke(); }
    for (let gy = 0; gy < h; gy += 15) { ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(w, gy); ctx.stroke(); }

    // ── Divider line for DUAL mode ──
    if (viewMode === 0) {
        const splitY = Math.round(h * 0.5);
        ctx.strokeStyle = colors.center;
        ctx.lineWidth = 1;
        ctx.setLineDash([2, 3]);
        ctx.beginPath(); ctx.moveTo(0, splitY); ctx.lineTo(w, splitY); ctx.stroke();
        ctx.setLineDash([]);
    }

    const hasWaveData = bridge && bridge._lastAudioWaveform && Array.isArray(bridge._lastAudioWaveform);
    const hasFreqData = bridge && bridge._lastAudioFrequencyData && Array.isArray(bridge._lastAudioFrequencyData);
    const hasAudioEngine = isJuce || (window.wasmBridge && window.wasmBridge.isAudioStarted);

    // ── Determine drawing regions ──
    let waveTop, waveBot, specTop, specBot;
    const padding = 3;

    if (viewMode === 0) {
        // DUAL: top 50% waveform, bottom 50% spectrum, 1px gap for divider at center
        const sY = Math.round(h * 0.5);
        waveTop = padding;
        waveBot = sY - 1;
        specTop = sY + 2;
        specBot = h - padding;
    } else if (viewMode === 1) {
        // WAVE only: full canvas
        waveTop = padding;
        waveBot = h - padding;
        specTop = h;
        specBot = h;
    } else {
        // SPC only: full canvas
        waveTop = h;
        waveBot = h;
        specTop = padding;
        specBot = h - padding;
    }

    // ── Draw waveform (top half or full) ──
    if (viewMode !== 2 && hasWaveData) {
        window._drawWaveform(ctx, bridge._lastAudioWaveform, waveTop, waveBot, w, colors, state, padding);
    } else if (viewMode !== 2 && hasAudioEngine) {
        window._drawPlaceholder(ctx, w, h, colors, 'WAITING FOR AUDIO...', 'Play notes to see waveform');
    }

    // ── Draw spectrum (bottom half or full) ──
    if (viewMode !== 1 && hasFreqData && typeof window._drawSpectrum === 'function') {
        window._drawSpectrum(ctx, bridge._lastAudioFrequencyData, specTop, specBot, w, colors);
    } else if (viewMode !== 1 && hasAudioEngine && !hasFreqData) {
        if (viewMode !== 0) {
            window._drawPlaceholder(ctx, w, h, colors, 'WAITING FOR AUDIO...', 'Play notes to see spectrum');
        }
    }

    // ── No engine at all ──
    if (!hasWaveData && !hasFreqData && !hasAudioEngine) {
        window._drawPlaceholder(ctx, w, h, { text: 'rgba(102,102,102,0.5)' }, 'NO DSP ENGINE', '(MIDI controller mode)');
    }
};

