/**
 * SCOPE_COLORS — 4 color schemes for the oscilloscope display.
 * Each scheme: { waveform, grid, center, text, glow, trigger, name }
 */
window.SCOPE_COLORS = [
    { waveform: '#ff9900',  grid: 'rgba(255,153,0,0.03)',  center: 'rgba(255,153,0,0.08)',  text: 'rgba(255,153,0,0.4)',  glow: '#ff9900',  trigger: 'rgba(255,153,0,0.15)', name: 'Brand' },
    { waveform: '#00ff66',  grid: 'rgba(0,255,102,0.03)',  center: 'rgba(0,255,102,0.08)',  text: 'rgba(0,255,102,0.4)',  glow: '#00ff66',  trigger: 'rgba(0,255,102,0.15)', name: 'CRT Green' },
    { waveform: '#00ccff',  grid: 'rgba(0,204,255,0.03)',  center: 'rgba(0,204,255,0.08)',  text: 'rgba(0,204,255,0.4)',  glow: '#00ccff',  trigger: 'rgba(0,204,255,0.15)', name: 'Blue' },
    { waveform: '#ffb000',  grid: 'rgba(255,176,0,0.03)',  center: 'rgba(255,176,0,0.08)',  text: 'rgba(255,176,0,0.4)',  glow: '#ffb000',  trigger: 'rgba(255,176,0,0.15)', name: 'Amber' },
];

/**
 * Finds the first zero-crossing trigger point in a waveform sample buffer.
 * @param {number[]} samples  Audio sample buffer
 * @param {number}   mode     0=free-run, 1=auto, 2=normal
 * @param {number}   edge     0=rising (neg→pos), 1=falling (pos→neg)
 * @returns {number}          Sample index of trigger point, 0 for free-run, -1 if not found
 */
window._findTriggerPoint = function(samples, mode, edge) {
    if (mode === 0 || !samples || samples.length < 4) {return 0;}
    const threshold = 0.0;
    const searchStart = Math.floor(samples.length * 0.1);
    const searchEnd = Math.floor(samples.length * 0.8);
    for (let i = searchStart; i < searchEnd; i++) {
        const prev = samples[i - 1];
        const curr = samples[i];
        if (typeof prev !== 'number' || typeof curr !== 'number') {continue;}
        if (edge === 0) {
            if (prev <= threshold && curr > threshold) {return i;}
        } else {
            if (prev >= threshold && curr < threshold) {return i;}
        }
    }
    return -1;
};

/**
 * Returns the current oscilloscope color scheme from panelEditState.
 * @returns {object} Color scheme object with waveform, grid, center, text, glow, trigger, name
 */
window._getScopeColors = function() {
    const state = window.panelEditState || {};
    const idx = Math.max(0, Math.min(window.SCOPE_COLORS.length - 1, state._scopeColorScheme || 0));
    return window.SCOPE_COLORS[idx];
};

/**
 * View mode labels and names for the scope view toggle.
 * 0=DUAL, 1=WAVE, 2=SPC
 */
window.SCOPE_VIEW_LABELS = ['DUAL', 'WAVE', 'SPC'];
window.SCOPE_VIEW_NAMES = ['Dual Waveform + Spectrum', 'Waveform only', 'Spectrum only'];

/**
 * Updates the oscilloscope toolbar UI elements (trigger mode button, zoom buttons,
 * color button, and view mode button).
 * Reads state from window.panelEditState.
 */
window._updateScopeToolbar = function() {
    const state = window.panelEditState || {};
    const triggerBtn = document.getElementById('scope-trigger-btn');
    if (triggerBtn) {
        const labels = ['FR', 'AT', 'NM'];
        const names = ['Free', 'Auto', 'Normal'];
        triggerBtn.textContent = labels[state._scopeTriggerMode || 0];
        triggerBtn.title = 'Trigger: ' + names[state._scopeTriggerMode || 0];
    }
    document.querySelectorAll('.scope-zoom-btn').forEach(function(btn) {
        const z = parseInt(btn.getAttribute('data-zoom'));
        btn.classList.toggle('active', z === (state._scopeZoom || 1));
    });
    const colorBtn = document.getElementById('scope-color-btn');
    if (colorBtn) {
        const colors = window._getScopeColors();
        const indicator = document.getElementById('scope-color-indicator');
        if (indicator) {
            indicator.style.color = colors.waveform;
            indicator.style.textShadow = '0 0 4px ' + colors.glow;
        }
        colorBtn.title = 'Color: ' + colors.name;
    }
    // View mode toggle
    const viewBtn = document.getElementById('scope-view-btn');
    if (viewBtn) {
        const vMode = state._scopeViewMode || 0;
        viewBtn.textContent = window.SCOPE_VIEW_LABELS[vMode];
        viewBtn.title = 'View: ' + window.SCOPE_VIEW_NAMES[vMode];
        viewBtn.style.color = vMode === 0 ? 'var(--accent-green,#00ffcc)' :
            vMode === 1 ? 'var(--accent-blue,#00ccff)' : 'var(--accent-pink,#ff66aa)';
    }
};

/**
 * @purpose FFT spectrum rendering and VCF filter overlay for the real-time oscilloscope.
 * Extracted from panel_oscilloscope.js for SRP.
 * Contains: _drawSpectrum (frequency-domain bars), _drawFilterOverlay (LP/HP/BP curve),
 * _calcFilterResponse (filter math).
 * @classification Module/Oscilloscope/Spectrum
 */

/* global hexToRgba */

/**
 * Draws the frequency-domain spectrum bars (FFT).
 * @param {CanvasRenderingContext2D} ctx
 * @param {number[]} freqData  Frequency magnitude data (0-255 per bin)
 * @param {number} top  Top Y of spectrum region
 * @param {number} bot  Bottom Y of spectrum region
 * @param {number} w  Canvas width
 * @param {object} colors  Color scheme
 */
window._drawSpectrum = function(ctx, freqData, top, bot, w, colors) {
    const graphH = bot - top;
    if (graphH < 4) {return;}

    const state = window.panelEditState || {};
    const padding = 3;
    const graphW = w - padding * 2;

    // Downsample 256 bins to ~40 bars with log-like spacing
    const numBars = 40;
    const barSpacing = 1;
    const barW = Math.max(2, Math.floor((graphW - barSpacing * (numBars - 1)) / numBars));
    const totalBarWidth = numBars * barW + (numBars - 1) * barSpacing;
    const offsetX = padding + Math.floor((graphW - totalBarWidth) / 2);

    // Peak hold per bin (slowly decays)
    if (!state._specPeakDecay) {state._specPeakDecay = new Array(numBars).fill(0);}

    for (let i = 0; i < numBars; i++) {
        // Map bar index to frequency bin index (logarithmic-like distribution)
        const binIdx = Math.floor(Math.pow(i / numBars, 0.8) * freqData.length);
        const rawVal = freqData[Math.min(binIdx, freqData.length - 1)];

        // Normalize 0-255 to 0-1 with perceptual curve for small view visibility
        const norm = Math.min(1, rawVal / 255.0);
        const boostedNorm = Math.min(1, Math.pow(norm, 0.5) * 1.5);
        const barHeight = Math.max(1, boostedNorm * (graphH - 2));
        const x = offsetX + i * (barW + barSpacing);
        const y = bot - barHeight;

        // Color gradient: low freq = warm, high freq = cool
        const t = i / numBars;
        const r = Math.round(50 + 205 * (1 - t));
        const g = Math.round(80 + 175 * t);
        const b = Math.round(200 * t + 60 * (1 - t));
        const alpha = 0.6 + boostedNorm * 0.4;

        ctx.fillStyle = 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
        ctx.fillRect(x, y, barW, barHeight);

        // Peak hold line: slowly decays
        state._specPeakDecay[i] = Math.max(boostedNorm, state._specPeakDecay[i] * 0.85);

        if (state._specPeakDecay[i] > 0.02) {
            const holdY = bot - state._specPeakDecay[i] * (graphH - 2);
            ctx.fillStyle = 'rgba(255,255,255,0.45)';
            ctx.fillRect(x, holdY, barW, 1);
        }
    }

    // VCF filter overlay (LP/HP/BP) on the spectrum
    window._drawFilterOverlay(ctx, padding, w, top, bot, graphH, graphW);

    // Frequency labels
    ctx.fillStyle = colors.text;
    ctx.font = '6px Share Tech Mono, monospace';
    ctx.textAlign = 'left';
    ctx.fillText('20Hz', padding + 1, bot - 1);
    ctx.textAlign = 'center';
    ctx.fillText('1kHz', w / 2, bot - 1);
    ctx.textAlign = 'right';
    ctx.fillText('20kHz', w - padding, bot - 1);
    ctx.textAlign = 'left';
};

/**
 * Draws the VCF filter overlay (LP/HP/BP curve, cutoff line, resonance peak)
 * on top of the spectrum display.
 * Reads vcf_cutoff, vcf_resonance, vcf_model and submode from bridge parameterCache.
 * @param {CanvasRenderingContext2D} ctx
 * @param {number} padding  Canvas padding
 * @param {number} w  Canvas width
 * @param {number} top  Top Y of spectrum region
 * @param {number} bot  Bottom Y of spectrum region
 * @param {number} graphH  Height of spectrum region
 * @param {number} graphW  Width of spectrum region (excl. padding)
 */
window._drawFilterOverlay = function(ctx, padding, w, top, bot, graphH, graphW) {
    const cache = window.dualMidiBridge ? window.dualMidiBridge.parameterCache : null;
    if (!cache) {return;}

    const rawCutoff = cache['vcf_cutoff'];
    if (rawCutoff === undefined || rawCutoff === null) {return;}
    const vcfCutoff = Math.max(0, Math.min(1, rawCutoff));
    const vcfRes = cache['vcf_resonance'] !== undefined ? Math.max(0, Math.min(1, cache['vcf_resonance'])) : 0;
    const vcfModel = cache['vcf_model'] !== undefined ? Math.round(cache['vcf_model']) : 0;

    // Determinar tipo de filtro según modelo
    let filterType = 0; // 0=LP, 1=BP, 2=HP
    let filterName = '';
    if (vcfModel === 0) {
        filterType = 0; // DM12 OTA = Lowpass
        filterName = 'OTA LP';
    } else if (vcfModel === 1) {
        const moogSub = cache['vcf_moog_submode'] !== undefined ? Math.round(cache['vcf_moog_submode']) : 0;
        filterType = moogSub; // 0=LP, 1=BP, 2=HP
        filterName = 'Moog ' + (moogSub === 0 ? 'LP' : moogSub === 1 ? 'BP' : 'HP');
    } else if (vcfModel === 2) {
        const korgSub = cache['vcf_korg_submode'] !== undefined ? Math.round(cache['vcf_korg_submode']) : 0;
        filterType = korgSub === 0 ? 0 : 2; // 0=LP, 1=HP
        filterName = 'MS-20 ' + (korgSub === 0 ? 'LP' : 'HP');
    }

    // Pole mode: 0=24dB, 1=12dB
    const poleMode = cache['vcf_pole_mode'] !== undefined ? Math.round(cache['vcf_pole_mode']) : 0;
    if (filterName) {
        filterName += ' ' + (poleMode === 0 ? '24dB' : '12dB');
    }

    // Mapear cutoff (0-1) a Hz: escala logarítmica 20Hz - 20kHz
    const cutoffHz = 20 * Math.pow(1000, vcfCutoff);

    // Mapear Hz a posición X en el canvas (log scale: 20Hz->left, 20kHz->right)
    const normX = Math.log(cutoffHz / 20) / Math.log(20000 / 20); // 0..1
    const cutoffX = padding + Math.round(normX * graphW);

    // ---- Lines de corte vertical ----
    ctx.strokeStyle = 'rgba(0, 255, 200, 0.5)';
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 3]);
    ctx.beginPath();
    ctx.moveTo(cutoffX, top);
    ctx.lineTo(cutoffX, bot);
    ctx.stroke();
    ctx.setLineDash([]);

    // ---- Zona atenuada (sombra semitransparente) ----
    const shadowColor = 'rgba(0, 100, 180, 0.12)';
    if (filterType === 0) {
        // LP: atenuado a la derecha del cutoff
        ctx.fillStyle = shadowColor;
        ctx.fillRect(cutoffX, top, w - cutoffX, bot - top);
    } else if (filterType === 2) {
        // HP: atenuado a la izquierda del cutoff
        ctx.fillStyle = shadowColor;
        ctx.fillRect(padding, top, cutoffX - padding, bot - top);
    } else {
        // BP: atenuado a ambos lados, menos atenuado cerca del cutoff
        ctx.fillStyle = shadowColor;
        ctx.fillRect(padding, top, cutoffX - padding, bot - top);
        ctx.fillRect(cutoffX, top, w - padding - cutoffX, bot - top);
    }

    // ---- Curva de respuesta del filtro ----
    // Dibujar una curva suave que muestra la atenuación
    ctx.strokeStyle = 'rgba(0, 255, 200, 0.35)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();

    const steps = 60;
    const responsePeakX = cutoffX;
    const responsePeakY = top + 2; // Pico en la parte superior

    for (let si = 0; si <= steps; si++) {
        const t = si / steps;
        const x = padding + t * graphW;

        // Calcular frecuencia en Hz en esta posición X
        const freqHz = 20 * Math.pow(20000 / 20, t);

        // Calcular respuesta del filtro (0=totalmente atenuado, 1=sin atenuación)
        const response = _calcFilterResponseLocal(freqHz, cutoffHz, vcfRes, filterType, poleMode);

        // Y: desde la parte superior (sin atenuación) hacia abajo (atenuado)
        const regionH = graphH * 0.8;
        const y = top + (1 - response) * regionH;

        if (si === 0) {ctx.moveTo(x, y);}
        else {ctx.lineTo(x, y);}
    }
    ctx.stroke();

    // ---- Pico de resonancia ----
    if (vcfRes > 0.05) {
        const peakBoost = vcfRes * 8; // Altura del pico (proporcional a la resonancia)
        const peakH = Math.min(graphH * 0.6, 4 + peakBoost * 3);
        const peakTopY = top + 2; // El pico sube hasta arriba (más resonancia = más alto)
        const peakSpread = Math.max(2, 6 + vcfRes * 20); // Ancho del pico (px)

        ctx.fillStyle = 'rgba(255, 200, 50, ' + (0.3 + vcfRes * 0.4) + ')';
        ctx.beginPath();
        // Media elipse superior (counterclockwise=true: de π a 0 por arriba)
        ctx.ellipse(cutoffX, peakTopY + peakH - 2, peakSpread, peakH, 0, Math.PI, 0, true);
        ctx.fill();
    }

    // ---- Etiqueta del filtro (solo en vista alta o zoom) ----
    if (filterName && graphH > 60) {
        ctx.fillStyle = 'rgba(0, 255, 200, 0.6)';
        ctx.font = '6.5px Share Tech Mono, monospace';
        ctx.textAlign = 'left';
        const labelX = padding + 4;
        const labelY = top + 10;
        ctx.fillText(filterName, labelX, labelY);

        // Frecuencia de corte
        const freqLabel = cutoffHz < 1000 ? Math.round(cutoffHz) + 'Hz' : (cutoffHz / 1000).toFixed(1) + 'kHz';
        ctx.fillStyle = 'rgba(0, 255, 200, 0.45)';
        ctx.font = '6px Share Tech Mono, monospace';
        ctx.fillText(freqLabel, labelX, labelY + 10);
        ctx.textAlign = 'left';
    }
};

/**
 * Calcula la respuesta del filtro para una frecuencia dada (uso interno).
 * @param {number} freqHz  Frecuencia a evaluar
 * @param {number} cutoffHz  Frecuencia de corte
 * @param {number} res  Resonancia (0-1)
 * @param {number} type  0=LP, 1=BP, 2=HP
 * @param {number} poles 0=24dB/4pole, 1=12dB/2pole
 * @returns {number} 0 (total atenuado) a 1 (sin atenuación)
 */
function _calcFilterResponseLocal(freqHz, cutoffHz, res, type, poles) {
    if (cutoffHz <= 0) {return (type === 2) ? 1 : 0;}

    const ratio = freqHz / cutoffHz;
    const slope = (poles === 0) ? 4 : 2; // 24dB = 4th order, 12dB = 2nd order

    let response;
    if (type === 0) {
        // Low Pass: 1 / (1 + (ratio)^(2*slope))
        response = 1 / (1 + Math.pow(ratio, 2 * slope));
    } else if (type === 2) {
        // High Pass: 1 / (1 + (1/ratio)^(2*slope))
        response = 1 / (1 + Math.pow(1 / Math.max(ratio, 0.001), 2 * slope));
    } else {
        // Band Pass: 2*ratio / (1 + ratio^2) — peaks at 1.0 at center frequency
        response = Math.max(0, 2 * ratio / (1 + ratio * ratio));
    }

    // Resonance peak at cutoff
    if (res > 0.01 && type !== 1) {
        const peakWidth = 1 + res * 5;
        const peakGain = 1 + res * 2.5;
        const peak = peakGain / (1 + Math.pow((freqHz / cutoffHz - 1) * peakWidth, 2));
        response = Math.min(1, response + (peak - 1) * res * 0.6);
    }

    return Math.max(0, Math.min(1, response));
}

/**
 * @purpose Waveform rendering for the real-time audio oscilloscope.
 * Extracted from panel_oscilloscope.js.
 * @purpose_en Real-time oscilloscope waveform drawing + helpers.
 */

/* global _getScopeColors, _findTriggerPoint, SCOPE_COLORS */
/* exported hexToRgba, _drawWaveform, _drawPlaceholder */

/**
 * Converts hex color string to rgba with given alpha.
 * @param {string} hex  Hex color (#ff9900)
 * @param {number} alpha  Alpha (0-1)
 * @returns {string} rgba string
 */
function hexToRgba(hex, alpha) {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
}

/** Draws the time-domain waveform */
function _drawWaveform(ctx, rawSamples, top, bot, w, colors, state, padding) {
    const graphH = bot - top;
    if (graphH < 4) {return;}
    const centerY = top + graphH / 2;

    // Center line (dashed) at waveform region center
    ctx.strokeStyle = colors.center;
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 3]);
    ctx.beginPath(); ctx.moveTo(0, centerY); ctx.lineTo(w, centerY); ctx.stroke();
    ctx.setLineDash([]);

    // Trigger level line (only in Auto/Normal modes)
    if ((state._scopeTriggerMode || 0) > 0) {
        ctx.strokeStyle = colors.trigger;
        ctx.lineWidth = 1;
        ctx.setLineDash([1, 4]);
        ctx.beginPath(); ctx.moveTo(0, centerY); ctx.lineTo(w, centerY); ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = colors.trigger;
        ctx.font = '6px Share Tech Mono, monospace';
        ctx.fillText('\u25B6', 1, centerY - 1);
    }

    let displaySamples = rawSamples;
    let triggerIdx = 0;

    if ((state._scopeTriggerMode || 0) > 0) {
        triggerIdx = window._findTriggerPoint(rawSamples, state._scopeTriggerMode || 0, 0);
        if (triggerIdx < 0 && (state._scopeTriggerMode || 0) === 1) {
            const now = Date.now();
            if (now - (state._scopeAutoTriggerTime || 0) > 500) {
                state._scopeAutoTriggerTime = now;
                triggerIdx = 0;
            } else { triggerIdx = 0; }
        } else if (triggerIdx < 0 && (state._scopeTriggerMode || 0) === 2) {
            if (state._scopeLastSamples) {displaySamples = state._scopeLastSamples;}
            triggerIdx = 0;
        } else if (triggerIdx >= 0) {
            state._scopeAutoTriggerTime = Date.now();
        }
    }

    const zoom = Math.max(1, Math.min(4, state._scopeZoom || 1));
    const zoomLen = Math.max(32, Math.floor(displaySamples.length / zoom));
    const startIdx = Math.max(0, triggerIdx - Math.floor(zoomLen * 0.1));
    let subSamples = displaySamples.slice(startIdx, startIdx + zoomLen);
    if (subSamples.length < 4) {subSamples = rawSamples.slice(0, zoomLen);}
    state._scopeLastSamples = subSamples.slice();

    ctx.shadowColor = hexToRgba(colors.waveform, 0.4);
    ctx.shadowBlur = 4;
    ctx.strokeStyle = hexToRgba(colors.waveform, 0.85);
    ctx.lineWidth = 1.5;
    ctx.beginPath();

    const graphW = w - padding * 2;
    const len = subSamples.length;
    let firstDrawn = false;

    for (let x = 0; x < graphW; x++) {
        const sampleIdx = Math.floor((x / graphW) * len);
        const val = typeof subSamples[sampleIdx] === 'number' ? subSamples[sampleIdx] : 0;
        const clamped = Math.max(-1, Math.min(1, val));
        const canvasX = padding + x;
        const canvasY = centerY - clamped * (graphH / 2);
        if (!firstDrawn) { ctx.moveTo(canvasX, canvasY); firstDrawn = true; }
        else { ctx.lineTo(canvasX, canvasY); }
    }
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Trigger marker
    if ((state._scopeTriggerMode || 0) > 0 && triggerIdx > 0) {
        const trigPct = (triggerIdx - startIdx) / len;
        if (trigPct >= 0 && trigPct <= 1) {
            const trigX = padding + trigPct * graphW;
            ctx.fillStyle = hexToRgba(colors.waveform, 0.5);
            ctx.beginPath(); ctx.arc(trigX, centerY, 3, 0, Math.PI * 2); ctx.fill();
        }
    }

    // Peak + dB meter + labels
    let peak = 0;
    for (let i = 0; i < subSamples.length; i++) {
        const s = Math.abs(subSamples[i]);
        if (s > peak) {peak = s;}
    }
    const db = peak < 0.0001 ? '-\u221E' : (20.0 * Math.log10(peak)).toFixed(1) + ' dB';
    ctx.fillStyle = colors.text;
    ctx.font = '7px Share Tech Mono, monospace';
    ctx.textAlign = 'right';
    ctx.fillText('PK ' + db, w - padding, top + 8);

    // Mini dB bar
    const barW = 5;
    const barX = w - padding - barW - 2;
    const barTop = top + 14;
    const barBot = bot - 1;
    const barH = barBot - barTop;

    if (state._scopeSmoothPeak === undefined) {state._scopeSmoothPeak = 0;}
    state._scopeSmoothPeak += (peak - state._scopeSmoothPeak) * 0.3;
    const smoothPeak = Math.min(1, Math.max(0, state._scopeSmoothPeak));

    ctx.fillStyle = 'rgba(102,102,102,0.15)';
    ctx.fillRect(barX, barTop, barW, barH);

    const fillH = smoothPeak * barH;
    const fillY = barBot - fillH;
    const barColor = smoothPeak < 0.3 ? hexToRgba(colors.waveform, 0.7)
        : smoothPeak < 0.6 ? 'rgba(255,200,0,0.8)'
        : smoothPeak < 0.85 ? 'rgba(255,120,0,0.8)'
        : 'rgba(255,30,30,0.85)';
    ctx.fillStyle = barColor;
    ctx.fillRect(barX, fillY, barW, fillH);

    // Tick marks
    const drawDbLine = function(dbVal) {
        const ratio = Math.pow(10, dbVal / 20);
        const lineY = barBot - ratio * barH;
        if (lineY > barTop && lineY < barBot) {
            ctx.strokeStyle = 'rgba(102,102,102,0.25)';
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(barX - 1, lineY); ctx.lineTo(barX + barW + 1, lineY); ctx.stroke();
        }
    };
    drawDbLine(-12);
    drawDbLine(-6);

    // Clip
    const isClipping = smoothPeak >= 0.98;
    if (!state._scopeClipTimer) {state._scopeClipTimer = 0;}
    if (isClipping) {state._scopeClipTimer = 30;}
    else if (state._scopeClipTimer > 0) {state._scopeClipTimer--;}
    if (state._scopeClipTimer > 0) {
        const blink = state._scopeClipTimer % 6 < 3;
        ctx.fillStyle = blink ? 'rgba(255,0,0,0.9)' : 'rgba(255,0,0,0.3)';
        ctx.font = 'bold 6px Share Tech Mono, monospace';
        ctx.textAlign = 'right';
        ctx.fillText('CLIP', w - padding, barTop - 1);
    }

    ctx.textAlign = 'left';
    const sampleRate = 44100;
    const timeMs = (subSamples.length / sampleRate) * 1000;
    const triggerLabel = ['FR', 'AT', 'NM'][state._scopeTriggerMode || 0];
    ctx.fillStyle = colors.text;
    ctx.font = '7px Share Tech Mono, monospace';
    ctx.fillText(triggerLabel + ' ' + zoom + 'x ' + subSamples.length + 's ' + timeMs.toFixed(1) + 'ms', padding + 2, bot - 2);
}

/** Draws centered placeholder text */
function _drawPlaceholder(ctx, w, h, colors, line1, line2) {
    ctx.fillStyle = colors.text;
    ctx.font = '8px Share Tech Mono, monospace';
    ctx.textAlign = 'center';
    ctx.fillText(line1, w / 2, h / 2 - 4);
    ctx.font = '6px Share Tech Mono, monospace';
    ctx.fillText(line2, w / 2, h / 2 + 10);
    ctx.textAlign = 'left';
}

