 * @purpose Editor interactivo de pasos del secuenciador — visual sync.
 * DOM builder (initPanelSeqEditor) está en panel_seq_editor_builder.js.
 * Extraído de panel_controls_arp_seq_mod.js como parte de la modularización.
 */

// ── Global State (shared with panel_controls_arp_seq_mod.js) ──
window._panelSeqValues = new Array(32).fill(0);
window._panelSeqRaw = new Array(32).fill(128);
window._panelLastSeqStep = 0;

/**
 * Update the visual state of a single step element (fill bar, skip badge, label).
 * @param {number} idx - Step index (0-31)
 */
function _updatePanelStepVisual(idx) {
    const stepsContainer = document.getElementById('panel-seq-steps-container');
    const wraps = stepsContainer ? stepsContainer.children : [];
    if (idx < 0 || idx >= wraps.length) {return;}
    const wrap = wraps[idx];
    const val = window._panelSeqValues[idx];
    const raw = window._panelSeqRaw[idx];
    if (val === undefined || raw === undefined) {return;}
    const fillBar = wrap.querySelector('.panel-seq-fill');
    const skipBadge = wrap.querySelector('.panel-seq-skip');
    const numLabel = wrap.querySelector('.panel-seq-num');
    const lenSel = document.getElementById('panel-seq-length-select');
    const activeLen = lenSel ? (parseInt(lenSel.value) + 2) : 16;
    const isActive = idx < activeLen;
    const isSkip = raw === 0;

    const signStr = val >= 0 ? '+' : '';
    wrap.title = isSkip
        ? 'Step ' + (idx + 1) + ': SKIP (raw: ' + raw + ')'
        : 'Step ' + (idx + 1) + ': ' + signStr + val + ' (raw: ' + raw + ')';

    if (skipBadge) {skipBadge.classList.toggle('visible', isSkip);}
    if (numLabel) {
        numLabel.classList.toggle('is-active', isActive);
        numLabel.classList.toggle('is-inactive', !isActive);
    }
    wrap.classList.toggle('is-active', isActive);
    wrap.classList.toggle('is-inactive', !isActive);

    if (fillBar) {
        fillBar.classList.remove('is-skip', 'is-positive', 'is-negative');
        if (isSkip) {
            fillBar.style.height = '0%';
            fillBar.style.bottom = '50%';
            fillBar.classList.add('is-skip');
        } else if (val >= 0) {
            const pct = Math.min(50, (val / 127) * 50);
            fillBar.style.bottom = '50%';
            fillBar.style.height = pct + '%';
            fillBar.classList.add('is-positive');
        } else {
            const pct = Math.min(50, (Math.abs(val) / 128) * 50);
            fillBar.style.bottom = (50 - pct) + '%';
            fillBar.style.height = pct + '%';
            fillBar.classList.add('is-negative');
        }
    }
}
window._updatePanelStepVisual = _updatePanelStepVisual;

/**
 * Sync the panel step state from the bridge's parameter cache.
 * Called after initialization and on external parameter changes.
 */
function _syncPanelSeqFromCache() {
    const bridge = window.dualMidiBridge;
    if (!bridge) {return;}
    for (let si = 0; si < 32; si++) {
        const paramId = 'seq_step_' + (si + 1);
        const norm = bridge.parameterCache[paramId];
        if (norm !== undefined) {
            const rawByte = Math.round(norm * 255);
            window._panelSeqRaw[si] = rawByte;
            window._panelSeqValues[si] = rawByte === 0 ? 0 : rawByte - 128;
            window._updatePanelStepVisual(si);
        }
    }
}
window._syncPanelSeqFromCache = _syncPanelSeqFromCache;
// initPanelSeqEditor is called from panel_controls_arp_seq_mod.js via window.initPanelSeqEditor

/**
 * @purpose Interactive SEQ step editor DOM builder — creates 32 step elements
 * with mouse/touch drag, dblclick reset, and hover LCD preview.
 * Visual sync helpers (_updatePanelStepVisual, _syncPanelSeqFromCache) are
 * in panel_seq_editor.js.
 */

/**
 * Initialize the interactive SEQ step editor in the given container.
 * Creates 32 step elements with mouse drag, touch drag, dblclick reset,
 * and hover LCD preview.
 * @param {HTMLElement} stepsContainer - The container element for the step elements
 */
// eslint-disable-next-line no-unused-vars
function initPanelSeqEditor(stepsContainer) {
    if (!stepsContainer) {return;}

    stepsContainer.innerHTML = '';
    for (let psi = 0; psi < 32; psi++) {
        (function(stepIdx) {
            const stepWrap = document.createElement('div');
            stepWrap.className = 'seq-step-wrap';
            if (stepIdx >= 16) {stepWrap.classList.add('row-2');}

            const zLine = document.createElement('div');
            zLine.className = 'seq-zero-line';
            stepWrap.appendChild(zLine);

            const fillBar = document.createElement('div');
            fillBar.className = 'panel-seq-fill seq-fill-bar';
            stepWrap.appendChild(fillBar);

            const skipBadge = document.createElement('div');
            skipBadge.className = 'panel-seq-skip seq-skip-badge';
            skipBadge.textContent = 'SKIP';
            stepWrap.appendChild(skipBadge);

            const numLabel = document.createElement('div');
            numLabel.className = 'panel-seq-num seq-num-label';
            numLabel.textContent = String(stepIdx + 1);
            stepWrap.appendChild(numLabel);

            let _isEditing = false;

            stepWrap.addEventListener('dblclick', function(e) {
                const idx = stepIdx;
                window._panelLastSeqStep = idx;
                window._panelSeqValues[idx] = 0;
                window._panelSeqRaw[idx] = 128;
                if (window.dualMidiBridge) {
                    window.dualMidiBridge.setParameter('seq_step_' + (idx + 1), 0.5);
                }
                if (typeof window._updatePanelStepVisual === 'function') {
                    window._updatePanelStepVisual(idx);
                }
                e.preventDefault();
                e.stopPropagation();
            });

            stepWrap.addEventListener('mousedown', function(e) {
                _isEditing = true;
                window._panelLastSeqStep = stepIdx;

                function _doEdit(clientY) {
                    const idx = stepIdx;
                    const wraps = stepsContainer ? stepsContainer.children : [];
                    if (idx < 0 || idx >= wraps.length) {return;}
                    const wrap = wraps[idx];
                    const rect = wrap.getBoundingClientRect();
                    const h = rect.height;
                    if (h <= 0) {return;}
                    let relY = 1.0 - (clientY - rect.top) / h;
                    relY = Math.max(0, Math.min(1, relY));
                    let bipolar = Math.round((relY * 255) - 128);
                    if (Math.abs(bipolar) <= 2) {bipolar = 0;}
                    window._panelSeqValues[idx] = bipolar;
                    const rawByte = Math.max(0, Math.min(255, bipolar + 128));
                    window._panelSeqRaw[idx] = rawByte;
                    const normalized = Math.max(0, Math.min(1, rawByte / 255.0));
                    if (window.dualMidiBridge) {
                        window.dualMidiBridge.setParameter('seq_step_' + (idx + 1), normalized);
                    }
                    if (typeof window._updatePanelStepVisual === 'function') {
                        window._updatePanelStepVisual(idx);
                    }
                }

                _doEdit(e.clientY);
                e.preventDefault();

                function _onMove(ev) {
                    if (!_isEditing) {return;}
                    _doEdit(ev.clientY);
                }
                function _onUp() {
                    _isEditing = false;
                    document.removeEventListener('mousemove', _onMove);
                    document.removeEventListener('mouseup', _onUp);
                }
                document.addEventListener('mousemove', _onMove);
                document.addEventListener('mouseup', _onUp);
            });

            let _touchId = null;
            stepWrap.addEventListener('touchstart', function(e) {
                if (e.touches.length !== 1) {return;}
                const touch = e.changedTouches[0];
                _touchId = touch.identifier;
                _isEditing = true;

                function _doTouchEdit(touchY) {
                    const idx = stepIdx;
                    const wraps = stepsContainer ? stepsContainer.children : [];
                    if (idx < 0 || idx >= wraps.length) {return;}
                    const wrap = wraps[idx];
                    const rect = wrap.getBoundingClientRect();
                    const h = rect.height;
                    if (h <= 0) {return;}
                    let relY = 1.0 - (touchY - rect.top) / h;
                    relY = Math.max(0, Math.min(1, relY));
                    let bipolar = Math.round((relY * 255) - 128);
                    if (Math.abs(bipolar) <= 2) {bipolar = 0;}
                    window._panelSeqValues[idx] = bipolar;
                    const rawByte = Math.max(0, Math.min(255, bipolar + 128));
                    window._panelSeqRaw[idx] = rawByte;
                    const normalized = Math.max(0, Math.min(1, rawByte / 255.0));
                    if (window.dualMidiBridge) {
                        window.dualMidiBridge.setParameter('seq_step_' + (idx + 1), normalized);
                    }
                    if (typeof window._updatePanelStepVisual === 'function') {
                        window._updatePanelStepVisual(idx);
                    }
                }

                _doTouchEdit(touch.clientY);

                function _onTouchMove(ev) {
                    if (!_isEditing) {return;}
                    let foundTouch = null;
                    for (let ti = 0; ti < ev.touches.length; ti++) {
                        if (ev.touches[ti].identifier === _touchId) {
                            foundTouch = ev.touches[ti];
                            break;
                        }
                    }
                    if (!foundTouch) {return;}
                    _doTouchEdit(foundTouch.clientY);
                    ev.preventDefault();
                }
                function _onTouchEnd() {
                    _isEditing = false;
                    _touchId = null;
                    document.removeEventListener('touchmove', _onTouchMove);
                    document.removeEventListener('touchend', _onTouchEnd);
                }
                document.addEventListener('touchmove', _onTouchMove, { passive: false });
                document.addEventListener('touchend', _onTouchEnd, { passive: false });
            }, { passive: false });

            stepWrap.addEventListener('mouseenter', (function(idx) {
                return function() {
                    const lcdText = document.getElementById('lcd-text');
                    if (!lcdText) {return;}
                    const v = window._panelSeqValues ? window._panelSeqValues[idx] : 0;
                    const r = window._panelSeqRaw ? window._panelSeqRaw[idx] : 128;
                    const isSkip = r === 0;
                    const sign = v >= 0 ? '+' : '';
                    const valStr = isSkip ? 'SKIP' : sign + v;
                    lcdText.innerHTML = '<span class=\"lcd-label\">CONTROL SEQ PANEL</span><br>'
                        + '<strong>STEP ' + (idx + 1) + ' VALUE</strong><br>'
                        + '<span class=\"seq-lcd-value\">' + valStr + ' (raw:' + r + ')</span>';
                    if (typeof window.setLcdParamDisplayTimer === 'function') {
                        window.setLcdParamDisplayTimer(lcdText);
                    }
                };
            })(stepIdx));

            stepsContainer.appendChild(stepWrap);
        })(psi);
    }
}

