// eslint-disable-next-line no-unused-vars -- called from script.js via window.*
function initBlinkLoop() {
    const arpBtnEl = document.getElementById('programmer-arp-btn');
    if (arpBtnEl) { arpBtnEl.classList.add('panel-btn', 'accent-primary'); }
    const seqBtnEl = document.getElementById('programmer-seq-btn');
    if (seqBtnEl) { seqBtnEl.classList.add('panel-btn', 'accent-pink', 'seq-btn'); }
    const chordBtnEl = document.getElementById('programmer-chord-btn');
    if (chordBtnEl) { chordBtnEl.classList.add('panel-btn', 'accent-green'); }
    const polychordBtnEl = document.getElementById('programmer-polychord-btn');
    if (polychordBtnEl) { polychordBtnEl.classList.add('panel-btn', 'accent-blue'); }

    function setButtonInactive(el, _mixColor, _accentColor) {
        if (!el) {return;}
        el.classList.remove('is-active', 'blink-on', 'blink-off', 'is-pulse', 'is-running', 'is-idle');
        el.classList.add('is-inactive');
    }

    function runBlinkLoop(timestamp) {
        let isArpOn = false;
        let isSeqOn = false;
        let isChordMemOn = false;
        let isPolyChordOn = false;

        if (window.dualMidiBridge && window.dualMidiBridge.parameterCache) {
            isArpOn = window.dualMidiBridge.parameterCache['arp_enable'] > 0.5;
            isSeqOn = window.dualMidiBridge.parameterCache['seq_enable'] > 0.5;
            isChordMemOn = window.dualMidiBridge.parameterCache['chord_enable'] > 0.5;
            isPolyChordOn = window.dualMidiBridge.parameterCache['poly_chord_enable'] > 0.5;
        }

        if (!isArpOn && !isSeqOn && !isChordMemOn && !isPolyChordOn) {
            setButtonInactive(arpBtnEl);
            setButtonInactive(seqBtnEl);
            setButtonInactive(chordBtnEl);
            setButtonInactive(polychordBtnEl);
            requestAnimationFrame(runBlinkLoop);
            return;
        }

        let bpm = 120;
        if (window.dualMidiBridge && window.dualMidiBridge.parameterCache) {
            const arpRateVal = window.dualMidiBridge.parameterCache['arp_rate'];
            if (typeof arpRateVal !== 'undefined') {
                bpm = 20 + arpRateVal * 220;
            }
        }

        const periodMs = 60000 / bpm;
        const blinkStateSlow = Math.floor(timestamp / (periodMs / 2)) % 2 === 0;

        if (arpBtnEl) {
            if (isArpOn) {
                arpBtnEl.classList.remove('is-inactive');
                arpBtnEl.classList.add('is-active', blinkStateSlow ? 'blink-on' : 'blink-off');
            } else {
                setButtonInactive(arpBtnEl);
            }
        }

        if (seqBtnEl) {
            if (isSeqOn) {
                if (window._lastSeqStep === undefined) {window._lastSeqStep = -1;}
                const currentSeqStep = window.dualMidiBridge && window.dualMidiBridge.parameterCache
                    ? window.dualMidiBridge.parameterCache['seq_current_step']
                    : undefined;
                const seqStepChanged = currentSeqStep !== undefined && currentSeqStep !== window._lastSeqStep;
                if (seqStepChanged) {
                    window._lastSeqStep = currentSeqStep;
                    window._seqPulseTime = timestamp;
                }

                const seqPulseAge = timestamp - (window._seqPulseTime || 0);
                const seqStepPulseMs = 200;
                const isEngRunning = window.dualMidiBridge && window.dualMidiBridge._seqEngine
                    ? window.dualMidiBridge._seqEngine.running
                    : false;

                seqBtnEl.classList.remove('is-inactive');
                if (seqPulseAge < seqStepPulseMs && isEngRunning) {
                    const pulseFade = seqPulseAge / seqStepPulseMs;
                    const brightness = 60 - pulseFade * 35;
                    const glowSize = 14 - pulseFade * 10;
                    seqBtnEl.style.setProperty('--seq-brightness', brightness.toFixed(0) + '%');
                    seqBtnEl.style.setProperty('--seq-glow', glowSize.toFixed(1) + 'px');
                    seqBtnEl.classList.remove('is-running', 'is-idle');
                    seqBtnEl.classList.add('is-pulse');
                } else if (isEngRunning) {
                    seqBtnEl.classList.remove('is-pulse', 'is-idle');
                    seqBtnEl.classList.add('is-running');
                } else {
                    seqBtnEl.classList.remove('is-pulse', 'is-running');
                    seqBtnEl.classList.add('is-idle');
                }
            } else {
                setButtonInactive(seqBtnEl);
            }
        }

        if (chordBtnEl) {
            if (isChordMemOn) {
                chordBtnEl.classList.remove('is-inactive');
                chordBtnEl.classList.add('is-active', blinkStateSlow ? 'blink-on' : 'blink-off');
            } else {
                setButtonInactive(chordBtnEl);
            }
        }

        if (polychordBtnEl) {
            if (isPolyChordOn) {
                polychordBtnEl.classList.remove('is-inactive');
                polychordBtnEl.classList.add('is-active', blinkStateSlow ? 'blink-on' : 'blink-off');
            } else {
                setButtonInactive(polychordBtnEl);
            }
        }

        requestAnimationFrame(runBlinkLoop);
    }
    requestAnimationFrame(runBlinkLoop);
}

/**
 * @purpose Wheels/pressure/VU telemetry overlay controller — orchestration RAF loop.
 * Wheel overlays → script_controllers_wheels.js
 * LED pulse → script_controllers_leds.js
 * LCD core (LcdQueue, fade timing, lcdFadeUpdate, lcdSafeUpdate) → script_lcd_core.js
 * @lastUpdated 2026-07-25
 */

// Global telemetry loop coordinator
document.addEventListener('DOMContentLoaded', () => {
    const _ctrlEls = {};
    function _getCtrlEl(id) {
        if (!_ctrlEls[id]) {_ctrlEls[id] = document.getElementById(id);}
        return _ctrlEls[id];
    }

    // Typewriter animation state for patch name display
    window._twText = null;
    window._twBank = '';
    let _twStart = 0;
    let _twActive = false;
    const _TW_CHAR_MS = 65;

    // Crossfade state for SEQ step transitions on LCD
    let _seqPrevStep = -1;
    let _seqFadeOldHtml = '';
    let _seqFadeStart = 0;
    let _seqFadeActive = false;

    function _updateCtrlOverlay(_timestamp) {
        const bridge = window.dualMidiBridge;
        if (!bridge) {
            requestAnimationFrame(_updateCtrlOverlay);
            return;
        }

        let pb = 0.0, mw = 0.0, at = 0.0;

        if (bridge.isJuce && bridge._lastVoiceStateRaw) {
            pb = bridge._lastVoiceStateRaw.pitchBend !== undefined ? bridge._lastVoiceStateRaw.pitchBend : 0.0;
            mw = bridge._lastVoiceStateRaw.modWheel !== undefined ? bridge._lastVoiceStateRaw.modWheel : 0.0;
            at = bridge._lastVoiceStateRaw.aftertouch !== undefined ? bridge._lastVoiceStateRaw.aftertouch : 0.0;
        }

        pb = Math.max(-1, Math.min(1, pb));
        mw = Math.max(0, Math.min(1, mw));
        at = Math.max(0, Math.min(1, at));

        if (typeof window.applyControllerCurve === 'function') {
            at = window.applyControllerCurve(at, window.getControllerCurve('aftertouch'));
            mw = window.applyControllerCurve(mw, window.getControllerCurve('modwheel'));
            pb = typeof window.applyBipolarCurve === 'function'
                ? window.applyBipolarCurve(pb, window.getControllerCurve('pitchbend'))
                : pb;
        }

        // Update wheel overlays (Pitch Bend, Mod Wheel, Aftertouch fill bars)
        if (typeof window._updateWheelOverlays === 'function') {
            window._updateWheelOverlays(pb, mw, at);
        }

        // VU Meter
        const rawPeak = bridge.isJuce && bridge._lastVoiceStateRaw
            ? (bridge._lastVoiceStateRaw.peakLevel !== undefined ? bridge._lastVoiceStateRaw.peakLevel : 0.0)
            : 0.0;
        const peakLevel = typeof window._updateVuMeter === 'function'
            ? window._updateVuMeter(rawPeak)
            : 0.0;

        // ── LCD Telemetry ──
        const lcdText = _getCtrlEl('lcd-text');
        if (lcdText) {
            const queueMsg = window.LcdQueue.getActive();
            if (queueMsg && queueMsg.priority < 2 && !lcdText._lcdFading) {
                lcdText._ctrlLcdRestore = null;
                lcdText.style.removeProperty('transition');
                lcdText.style.opacity = '1';
                if (lcdText.innerHTML !== queueMsg.content) {
                    lcdText.innerHTML = queueMsg.content;
                }
            } else {
                const hasPb = Math.abs(pb) > 0.01;
                const hasAt = at > 0.01;
                const hasMw = mw > 0.01;
                const isSeqRunning = !hasPb && !hasAt && !hasMw && (bridge.parameterCache['seq_enable'] || 0) > 0.5 && typeof bridge.parameterCache['seq_current_step'] !== 'undefined';
                const hasVu = !hasPb && !hasAt && !hasMw && !isSeqRunning && peakLevel > 0.001;

                if (hasPb || hasAt || hasMw) {
                    if (lcdText._ctrlLcdFadeTimer) {
                        clearTimeout(lcdText._ctrlLcdFadeTimer);
                        lcdText._ctrlLcdFadeTimer = null;
                    }
                    lcdText.style.removeProperty('transition');
                    lcdText.style.opacity = '1';
                    if (!lcdText._ctrlLcdRestore) {
                        lcdText._ctrlLcdRestore = lcdText.innerHTML;
                    }
                    if (typeof window._buildWheelLcdHtml === 'function') {
                        lcdText.innerHTML = window._buildWheelLcdHtml(pb, mw, at);
                    }
                } else if (hasVu) {
                    if (lcdText._ctrlLcdFadeTimer) {
                        clearTimeout(lcdText._ctrlLcdFadeTimer);
                        lcdText._ctrlLcdFadeTimer = null;
                    }
                    lcdText.style.removeProperty('transition');
                    lcdText.style.opacity = '1';
                    if (!lcdText._ctrlLcdRestore) {
                        lcdText._ctrlLcdRestore = lcdText.innerHTML;
                    }
                    if (typeof window._buildVuLcdHtml === 'function') {
                        lcdText.innerHTML = window._buildVuLcdHtml(peakLevel);
                    }
                } else if (isSeqRunning) {
                    if (lcdText._ctrlLcdFadeTimer) {
                        clearTimeout(lcdText._ctrlLcdFadeTimer);
                        lcdText._ctrlLcdFadeTimer = null;
                    }
                    if (!lcdText._ctrlLcdRestore) {
                        lcdText._ctrlLcdRestore = lcdText.innerHTML;
                    }

                    // Track SEQ step changes for crossfade
                    const _currentSeqStep_ = bridge.parameterCache['seq_current_step'];
                    if (_currentSeqStep_ !== _seqPrevStep && _seqPrevStep !== -1) {
                        _seqFadeOldHtml = lcdText.innerHTML;
                        _seqFadeStart = Date.now();
                        _seqFadeActive = true;
                    }
                    _seqPrevStep = _currentSeqStep_;

                    let seqHtml;
                    if (window._seqDebugMode) {
                        if (typeof window._buildSeqDebugLcdHtml === 'function') {
                            seqHtml = window._buildSeqDebugLcdHtml(bridge);
                        } else {
                            seqHtml = '';
                        }
                    } else {
                        const seqModeBadge = typeof window._resolveSeqModeBadge === 'function'
                            ? window._resolveSeqModeBadge(bridge)
                            : '';
                        if (typeof window._buildSeqLcdHtml === 'function') {
                            seqHtml = window._buildSeqLcdHtml(bridge, seqModeBadge);
                        } else {
                            seqHtml = '';
                        }
                    }

                    if (_seqFadeActive) {
                        const fadeElapsed_ = Date.now() - _seqFadeStart;
                        const fadeHalf_ = 0;
                        if (fadeElapsed_ < fadeHalf_) {
                            const fadeOutOp_ = 1.0 - (fadeElapsed_ / fadeHalf_);
                            lcdText.innerHTML = _seqFadeOldHtml;
                            lcdText.style.opacity = String(Math.max(0, fadeOutOp_));
                        } else if (fadeElapsed_ < fadeHalf_ * 2) {
                            const fadeInOp_ = (fadeElapsed_ - fadeHalf_) / fadeHalf_;
                            lcdText.innerHTML = seqHtml;
                            lcdText.style.opacity = String(Math.min(1, fadeInOp_));
                        } else {
                            _seqFadeActive = false;
                            lcdText.innerHTML = seqHtml;
                            lcdText.style.removeProperty('transition');
                            lcdText.style.opacity = '1';
                        }
                    } else {
                        lcdText.style.removeProperty('transition');
                        lcdText.style.opacity = '1';
                        lcdText.innerHTML = seqHtml;
                    }
                } else if (lcdText._ctrlLcdRestore) {
                    if (typeof window._handleLcdFadeRestore === 'function') {
                        window._handleLcdFadeRestore(lcdText);
                    }
                } else {
                    if (typeof window._buildPatchNameLcdHtml === 'function') {
                        const pnResult = window._buildPatchNameLcdHtml(window._seqDebugMode || false);
                        if (pnResult.type === 'typewriter') {
                            // Typewriter animation: RAF-per-frame character reveal
                            if (!_twActive) {
                                _twActive = true;
                                _twStart = Date.now();
                            }
                            const elapsed_ = Date.now() - _twStart;
                            const charsToShow_ = Math.min(pnResult.twText.length, Math.max(1, Math.floor(elapsed_ / _TW_CHAR_MS)));
                            const revealed_ = pnResult.twText.substring(0, charsToShow_);
                            const isDone_ = charsToShow_ >= pnResult.twText.length;

                            if (isDone_) {
                                window._twText = null;
                                _twActive = false;
                                window._twBank = '';
                            }

                            const cursor_ = isDone_ ? '' : '<span class="lcd-cursor">_</span>';
                            lcdText.innerHTML = '<span class="lcd-text-xl">' + revealed_ + cursor_ + '</span>' + pnResult.debugBadge + '<br><span class="lcd-text-sub">' + pnResult.twBank.toUpperCase() + '</span>';
                        } else {
                            lcdText.innerHTML = pnResult.html;
                        }
                    }
                }
            }
        }

        // Update LCD glow pulse on SEQ step changes
        if (typeof window._updateLcdGlowPulse === 'function') {
            window._updateLcdGlowPulse(bridge);
        }

        requestAnimationFrame(_updateCtrlOverlay);
    }
    requestAnimationFrame(_updateCtrlOverlay);
});

/**
 * @purpose LCD content builders for the telemetry overlay (Wheel/VU/PatchName/Fade).
 * SEQ builders extracted to script_controllers_lcd_seq.js.
 * @classification Module/Controllers/LCD
 * @lastUpdated 2026-07-29
 */

/** Build LCD HTML for Pitch Bend, Aftertouch, Mod Wheel display */
window._buildWheelLcdHtml = function(pb, mw, at) {
    let lcdContent = '';
    if (Math.abs(pb) > 0.01) {
        const st = (pb * 2.0).toFixed(2);
        const pbClass = pb >= 0 ? 'lcd-color-green' : 'lcd-color-pink';
        const pbRaw = Math.round((pb + 1) * 8191.5);
        const center = 10;
        const fillLen = Math.round(Math.abs(pb) * center);
        const leftBar = pb >= 0
            ? window._genFillBar(0, center)
            : window._genFillBar(fillLen, center);
        const rightBar = pb < 0
            ? window._genFillBar(0, center)
            : window._genFillBar(fillLen, center);
        const centerMarker = '\u2502';
        lcdContent += '<span class="lcd-label">WHEEL</span><br>'
            + '<strong class="' + pbClass + '">PITCH BEND</strong><br>'
            + '<span class="lcd-text-xl ' + pbClass + '">' + (pb >= 0 ? '+' : '') + st + ' st</span><br>'
            + window._genBarHtml(leftBar + centerMarker + rightBar, { letterSpacing: '0', suffix: '<span class="lcd-text-sub"> ' + pbRaw + '</span>' });
    }
    if (Math.abs(pb) > 0.01 && (at > 0.01 || mw > 0.01)) {
        lcdContent += '<br>';
    }
    if (at > 0.01) {
        const atPct = Math.round(at * 100);
        const barLen = Math.round(at * 20);
        lcdContent += '<span class="lcd-label">CHANNEL PRESSURE</span><br>'
            + '<strong class="lcd-color-orange">AFTERTOUCH</strong><br>'
            + '<span class="lcd-text-xl lcd-color-orange">' + atPct + '%</span><br>'
            + window._genBarHtml(window._genFillBar(barLen, 20));
    }
    if ((Math.abs(pb) > 0.01 || at > 0.01) && mw > 0.01) {
        lcdContent += '<br>';
    }
    if (mw > 0.01) {
        const mwPct = Math.round(mw * 100);
        const barLen = Math.round(mw * 20);
        lcdContent += '<span class="lcd-label">MODULATION</span><br>'
            + '<strong class="lcd-color-blue">MOD WHEEL</strong><br>'
            + '<span class="lcd-text-xl lcd-color-blue">' + mwPct + '%</span><br>'
            + window._genBarHtml(window._genFillBar(barLen, 20));
    }
    return lcdContent;
};

/** Build LCD HTML for VU meter display */
window._buildVuLcdHtml = function(peakLevel) {
    let vuColor = 'var(--text-faint)';
    let vuClass = 'lcd-color-faint';
    if (peakLevel < 0.001) {vuColor = 'var(--text-faint)'; vuClass = 'lcd-color-faint';}
    else if (peakLevel < 0.06) {vuColor = 'var(--accent-green)'; vuClass = 'lcd-color-green';}
    else if (peakLevel < 0.5) {vuColor = 'var(--accent-yellow)'; vuClass = 'lcd-color-yellow';}
    else if (peakLevel < 0.7) {vuColor = 'var(--accent-orange)'; vuClass = 'lcd-color-orange';}
    else {vuColor = 'var(--color-danger)'; vuClass = 'lcd-color-red';}
    const db = peakLevel < 0.0001 ? '-\u221E' : (20.0 * Math.log10(peakLevel)).toFixed(1);
    const barLen = Math.round(peakLevel * 24);
    return '<span class="lcd-label">OUTPUT LEVEL</span><br>'
        + '<span class="lcd-text-lg ' + vuClass + '">' + db + ' dB</span><br>'
        + window._genBarHtml(window._genFillBar(barLen, 24), { color: vuColor })
        + (peakLevel > 0.9 ? '<br><span class="lcd-clip-badge">CLIP!</span>' : '');
};

/** Delegate SEQ LCD builders to extracted module */
// Functions _buildSeqDebugLcdHtml, _buildSeqLcdHtml, _resolveSeqModeBadge
// have been extracted to script_controllers_lcd_seq.js (loaded before this file).

/** Build LCD HTML for patch name display (with typewriter animation support) */
window._buildPatchNameLcdHtml = function(seqDebugMode) {
    const activeBank = window.loadedBanks && window.loadedBanks[window.currentActiveBank];
    const activePatch = activeBank && activeBank[window.currentActivePatchIndex];
    const bridge = window.dualMidiBridge;
    const basePatchName_ = activePatch ? activePatch.name
        : (bridge && bridge.parameterCache && bridge.parameterCache['patch_name']
            ? bridge.parameterCache['patch_name'] : 'INITIAL PATCH');
    const baseBankName_ = window.currentActiveBank || '';
    const debugBadge_ = seqDebugMode ? '<span class="lcd-dbg-badge">DBG</span>' : '';

    if (window._twText) {
        return { type: 'typewriter', html: '', twText: window._twText, twBank: window._twBank, debugBadge: debugBadge_ };
    } else {
        let _pnHtml_;
        const _pnUpper_ = basePatchName_.toUpperCase();
        if (basePatchName_.length > 10) {
            const _scrollDur_ = Math.max(4, basePatchName_.length * 0.5);
            _pnHtml_ = '<div class="lcd-scroll-container"><span class="lcd-scroll-text animate" style="animation-duration:' + _scrollDur_.toFixed(1) + 's;">' + _pnUpper_ + '</span></div>';
        } else {
            _pnHtml_ = '<span class="lcd-text-xl">' + _pnUpper_ + '</span>';
        }
        return { type: 'static', html: _pnHtml_ + debugBadge_ + '<br><span class="lcd-text-sub">' + baseBankName_.toUpperCase() + '</span>' };
    }
};

/** Handle LCD fade restore with timer management */
window._handleLcdFadeRestore = function(lcdText) {
    const restoreHtml = lcdText._ctrlLcdRestore;
    lcdText._ctrlLcdRestore = null;
    if (lcdText._ctrlLcdFadeTimer) {
        clearTimeout(lcdText._ctrlLcdFadeTimer);
    }
    const rt = window.getLcdFadeTiming();
    if (rt.outR === 0) {
        if (lcdText._ctrlLcdFadeTimer) {clearTimeout(lcdText._ctrlLcdFadeTimer);}
        lcdText._ctrlLcdFadeTimer = null;
        lcdText.innerHTML = restoreHtml;
        lcdText.style.removeProperty('transition');
        lcdText.style.opacity = '1';
    } else {
        lcdText.style.transition = 'opacity ' + rt.outR + 'ms ' + window._LCD_FADE_OUT_EASING;
        lcdText.style.opacity = '0';
        lcdText._ctrlLcdFadeTimer = setTimeout(() => {
            lcdText._ctrlLcdFadeTimer = null;
            if (lcdText._ctrlLcdRestore !== null) {return;}
            lcdText.innerHTML = restoreHtml;
            lcdText.style.transition = 'opacity ' + rt.inR + 'ms ' + window._LCD_FADE_IN_EASING;
            lcdText.style.opacity = '1';
            setTimeout(() => {
                lcdText.style.removeProperty('transition');
                lcdText.style.removeProperty('opacity');
            }, rt.cleanupR);
        }, rt.swapR);
    }
};

/**
 * @purpose LCD content builders for SEQ telemetry overlay (debug + normal + mode badge).
 * Extracted from script_controllers_lcd.js LCD SEQ section.
 * @classification Module/Controllers/LCD/SEQ
 * @lastUpdated 2026-07-29
 */

/* global FULL_MOD_DESTINATIONS */

/** Build LCD HTML for SEQ debug mode */
window._buildSeqDebugLcdHtml = function(bridge) {
    let seqDebugHtml = '<span class=\"lcd-seq-debug-header\">SEQ DEBUG <span class=\"lcd-color-red\">\u25CF</span></span><br>';
    const _clockNames_ = ['1/2', '3/8', '1/3', '1/4', '3/16', '1/6', '1/8', '1/12', '1/16', '1/24', '1/32', '1/48', '1/64', '1/96', '1/128', '1/192'];
    const _clockVal_ = Math.round((bridge.parameterCache['seq_clock'] || 0) * 15);
    const _clockLabel_ = _clockNames_[_clockVal_] || '1/8';
    const _bpm_ = 20 + (bridge.parameterCache['arp_rate'] || 0.5) * 220;
    const _divider_ = [2, 8/3, 3, 4, 16/3, 6, 8, 12, 16, 24, 32, 48, 64, 96, 128, 192][_clockVal_] || 4;
    const _baseMs_ = (60000 / _bpm_) / _divider_;
    const _swingNorm_ = bridge.parameterCache['seq_swing'] || 0;
    const _swingFactor_ = _swingNorm_ * 0.5;
    const _evenMs_ = Math.round(_baseMs_ * (1 + _swingFactor_));
    const _oddMs_ = Math.round(_baseMs_ * (1 - _swingFactor_));
    let _seqDestName_ = '';
    try {
        for (let _ms_ = 1; _ms_ <= 8; _ms_++) {
            const _src_ = bridge.parameterCache['mod_matrix_slot' + _ms_ + '_src'];
            if (_src_ !== undefined && Math.round(_src_ * 22) === 14) {
                const _dest_ = bridge.parameterCache['mod_matrix_slot' + _ms_ + '_dest'];
                if (_dest_ !== undefined) {
                    const _destIdx_ = Math.round(_dest_ * 129);
                    _seqDestName_ = (typeof FULL_MOD_DESTINATIONS !== 'undefined' && FULL_MOD_DESTINATIONS[_destIdx_])
                        ? FULL_MOD_DESTINATIONS[_destIdx_]
                        : 'Dest ' + _destIdx_;
                }
                break;
            }
        }
    } catch(e) {}
    seqDebugHtml += '<span class=\"lcd-seq-debug-info\">'
        + '<span class=\"lcd-color-pink\">' + _clockLabel_ + '</span> '
        + Math.round(_bpm_) + ' BPM '
        + '<span class=\"op-60\">|</span> ' + Math.round(_baseMs_) + 'ms/step'
        + (_swingNorm_ > 0.001 ? ' <span class=\"op-50\">(even:</span><span class=\"lcd-color-yellow op-80\">' + _evenMs_ + '</span><span class=\"op-50\"> odd:</span><span class=\"lcd-color-cyan op-80\">' + _oddMs_ + '</span><span class=\"op-50\">ms)</span>' : '')
        + (_seqDestName_ ? ' <span class=\"op-60\">|</span> <span class=\"lcd-color-pink op-80\">\u2192</span><span class=\"lcd-color-cyan text-bold op-90\">' + _seqDestName_ + '</span>' : '')
        + '</span>';
    const _slewNorm_ = bridge.parameterCache['seq_slew_rate'] || 0;
    if (_slewNorm_ > 0.001) {
        const _slewPct_ = Math.round(_slewNorm_ * 100);
        const _slewRaw_ = Math.round(_slewNorm_ * 255);
        const _slewK_ = _slewNorm_ * 0.5;
        const _slewSteps_ = _slewK_ > 0.01 ? Math.round(Math.log(0.1) / Math.log(1 - _slewK_)) : 0;
        const _slewMs_ = Math.round(_slewSteps_ * _baseMs_);
        seqDebugHtml += '<span class=\"lcd-seq-slew-info\">'
            + 'Slew: <span class=\"lcd-color-orange\">' + _slewPct_ + '%</span>'
            + ' <span class=\"op-40\">(raw:' + _slewRaw_ + ')</span>'
            + ' <span class=\"op-60\">|</span> <span class=\"op-50\">smoothing:</span><span class=\"lcd-color-yellow op-80\">~' + _slewMs_ + 'ms</span>'
            + ' <span class=\"op-40\">(' + _slewSteps_ + ' steps to 90%)</span>'
            + '</span>';
    }
    const _debugSeqLen_ = Math.round((bridge.parameterCache['seq_length'] || 0) * 31) + 2;
    seqDebugHtml += '<span class=\"lcd-seq-debug-grid\">';
    const _activeStep_ = bridge.parameterCache['seq_current_step'];
    for (let di = 0; di < _debugSeqLen_; di++) {
        const isActiveCell_ = _activeStep_ !== undefined && di === _activeStep_;
        const paramId = 'seq_step_' + (di + 1);
        const norm = bridge.parameterCache[paramId];
        const raw = norm !== undefined ? Math.round(norm * 255) : 128;
        const bip = raw === 0 ? -128 : raw - 128;
        const num = (di + 1) < 10 ? '0' + (di + 1) : '' + (di + 1);
        const isSkip = raw === 0;
        const valStr = isSkip ? '<span class=\"lcd-color-red\">SKIP</span>' : (bip >= 0 ? '+' + bip : '' + bip);
        const colorClass = isSkip ? 'lcd-color-red' : (bip > 0 ? 'lcd-color-pink' : (bip < 0 ? 'text-dim' : 'text-faint'));
        const rawStr = isSkip ? '000' : (raw < 100 ? '0' : '') + (raw < 10 ? '0' : '') + raw;
        const ccVal = norm !== undefined ? Math.round(norm * 127) : 64;
        const ccStr = isSkip ? '00' : (ccVal < 100 ? '0' : '') + (ccVal < 10 ? '0' : '') + ccVal;
        let ccColorClass = colorClass;
        let ccTitle = '';
        if (!isSkip) {
            if (ccVal >= 127) { ccColorClass = 'lcd-color-red'; ccTitle = ' title=\"\u26A0 SATURATION\"'; }
            else if (ccVal >= 125) { ccColorClass = 'lcd-color-orange'; ccTitle = ' title=\"\u26A0 Near saturation\"'; }
            else if (ccVal >= 120) { ccColorClass = 'lcd-color-yellow'; ccTitle = ' title=\"\u26A0 Approaching saturation\"'; }
        }
        if (isActiveCell_) {
            seqDebugHtml += '<span class=\"lcd-seq-debug-cell-active\">\u25B6' + num + ':' + valStr + '(' + rawStr + '/<span class=\"' + ccColorClass + '\"' + ccTitle + '>' + ccStr + '</span>)</span>';
        } else {
            seqDebugHtml += '<span class=\"' + colorClass + '\">' + num + ':' + valStr + '(' + rawStr + '/<span class=\"' + ccColorClass + '\"' + ccTitle + '>' + ccStr + '</span>)</span>';
        }
    }
    seqDebugHtml += '</span>';
    return seqDebugHtml;
};

/** Build LCD HTML for normal SEQ (non-debug) step display */
window._buildSeqLcdHtml = function(bridge, seqModeBadge) {
    const seqStep = bridge.parameterCache['seq_current_step'];
    const seqVal = bridge.parameterCache['seq_current_value'] || 0.5;
    const seqLen = Math.round((bridge.parameterCache['seq_length'] || 0) * 31) + 2;
    const seqEn = (bridge.parameterCache['seq_enable'] || 0) > 0.5;
    const seqSkip = (bridge.parameterCache['seq_current_step_skip'] || 0) > 0.5;
    const bipVal = (seqVal * 2.0) - 1.0;
    const barHalf = 12;
    const fillLen = Math.round(Math.abs(bipVal) * barHalf);
    const leftBar = bipVal >= 0
        ? window._genFillBar(0, barHalf)
        : window._genFillBar(fillLen, barHalf);
    const rightBar = bipVal < 0
        ? window._genFillBar(0, barHalf)
        : window._genFillBar(fillLen, barHalf);
    const centerMarker = '\u2502';
    const stepBarLen = Math.min(seqLen, 24);
    const stepDot = seqStep < stepBarLen ? seqStep : (seqStep % stepBarLen);
    const stepBar = window._genPosBar(stepDot, stepBarLen);
    const seqColor = 'var(--accent-pink)';
    const seqRawVal = Math.round(seqVal * 255);
    if (seqSkip) {
        const centerBar = '\u2591'.repeat(12) + '\u2502' + '\u2591'.repeat(12);
        return '<span class=\"lcd-label\">CONTROL SEQ ' + (seqEn ? '\u25B6' : '\u25A0') + seqModeBadge + '</span><br>'
            + '<strong class=\"lcd-color-pink\">STEP ' + (seqStep + 1) + ' / ' + seqLen + ' <span class=\"lcd-seq-skip-text\">SKIP</span></strong><br>'
            + window._genBarHtml(centerBar, { letterSpacing: '0' })
            + '<span class=\"lcd-seq-val-skip\"> -- (raw:' + seqRawVal + ')</span><br>'
            + window._genBarHtml(stepBar, { color: seqColor });
    } else {
        const seqExactVal = Math.round(bipVal * 127);
        const seqValStr = seqExactVal >= 0 ? '+' + seqExactVal : String(seqExactVal);
        return '<span class=\"lcd-label\">CONTROL SEQ ' + (seqEn ? '\u25B6' : '\u25A0') + seqModeBadge + '</span><br>'
            + '<strong class=\"lcd-color-pink\">STEP ' + (seqStep + 1) + ' / ' + seqLen + '</strong><br>'
            + '<span class=\"lcd-seq-bars\">' + leftBar + centerMarker + rightBar + '</span>'
            + '<span class=\"lcd-seq-val-norm\"> ' + seqValStr + ' (raw:' + seqRawVal + ')</span><br>'
            + window._genBarHtml(stepBar, { color: seqColor });
    }
};

/** Resolve SEQ mode badge string based on key loop mode */
window._resolveSeqModeBadge = function(bridge) {
    const _seqKeyLoopVal = Math.round((bridge.parameterCache['seq_key_loop'] || 0) * 2);
    if (bridge._seqEngine && bridge._seqEngine._forcedFreeRunning) {
        return ' <span class=\"lcd-seq-mode-badge-free-forced\" title=\"Key Sync desactivado autom\u00E1ticamente \u2014 no hab\u00EDa teclas presionadas al activar SEQ\">FREE*</span>';
    } else if (_seqKeyLoopVal === 0) {
        return ' <span class=\"lcd-seq-mode-badge-free\">FREE</span>';
    } else if (_seqKeyLoopVal === 1) {
        return ' <span class=\"lcd-seq-mode-badge-key\">KEY</span>';
    } else if (_seqKeyLoopVal === 2) {
        return ' <span class=\"lcd-seq-mode-badge-loop\">LOOP</span>';
    }
    return '';
};

/**
 * @purpose LCD glow pulse animation on SEQ step changes.
 * Extracted from script_controllers.js RAF loop for modularity.
 * @classification Module/Controllers/LEDs
 * @lastUpdated 2026-07-25
 */

(function() {
    // Glow pulse state (persistent across frames)
    window._seqGlowPulse = 0;
    window._seqGlowLastStep = -1;

    /**
     * Update LCD glow pulse effect when SEQ step changes.
     * Called every RAF frame from script_controllers.js
     */
    window._updateLcdGlowPulse = function(bridge) {
        const glowEl = document.getElementById('lcd-glow-pulse');
        if (!glowEl) {return;}

        const seqEn = bridge.parameterCache && (bridge.parameterCache['seq_enable'] || 0) > 0.5;
        const curStep = bridge.parameterCache ? bridge.parameterCache['seq_current_step'] : undefined;
        const stepChanged = curStep !== undefined && curStep !== window._seqGlowLastStep;

        if (stepChanged) {
            window._seqGlowLastStep = curStep;
            window._seqGlowPulse = Date.now();
        }

        if (seqEn && curStep !== undefined) {
            const age = Date.now() - window._seqGlowPulse;
            const duration = 400;
            if (age < duration) {
                const intensity = 1.0 - (age / duration);
                const size = 2 + intensity * 4;
                glowEl.style.boxShadow = '0 0 ' + size.toFixed(1) + 'px color-mix(in srgb, var(--accent-pink) 40%, transparent)';
            } else if (glowEl.style.boxShadow) {
                glowEl.style.boxShadow = '';
            }
        } else if (glowEl.style.boxShadow) {
            glowEl.style.boxShadow = '';
        }
    };
})();

/**
 * @purpose Wheel overlay updaters (Pitch Bend, Mod Wheel, Aftertouch) + VU Meter.
 * Extracted from script_controllers.js RAF loop for modularity.
 * @classification Module/Controllers/Wheels
 * @lastUpdated 2026-07-25
 */

(function() {
    // VU ballistics state (persistent across frames)
    window._vuSmoothed = 0.0;
    window._vuLastTime = Date.now();

    /**
     * Update Pitch Bend, Mod Wheel, and Aftertouch overlay bars.
     * Called every RAF frame from script_controllers.js
     */
    window._updateWheelOverlays = function(pb, mw, at) {
        // ── Pitch Bend ──
        const pbFill = document.getElementById('ctrl-o-pb-fill');
        const pbVal = document.getElementById('ctrl-o-pb-val');
        if (pbFill) {
            const center = 50;
            const left = pb >= 0 ? center : center + pb * 50;
            const width = Math.abs(pb) * 50;
            pbFill.style.left = left + '%';
            pbFill.style.width = width + '%';
            pbFill.style.background = pb >= 0 ? 'var(--accent-green)' : 'var(--accent-pink)';
        }
        if (pbVal) {
            const st = pb * 2.0;
            pbVal.textContent = (st >= 0 ? '+' : '') + st.toFixed(2);
            pbVal.style.color = pb >= 0 ? 'var(--accent-green)' : 'var(--accent-pink)';
        }

        // ── Mod Wheel ──
        const mwFill = document.getElementById('ctrl-o-mw-fill');
        const mwVal = document.getElementById('ctrl-o-mw-val');
        if (mwFill) {
            mwFill.style.width = Math.round(mw * 100) + '%';
            mwFill.style.background = mw > 0.01 ? 'var(--accent-blue)' : 'var(--text-faint)';
        }
        if (mwVal) {
            mwVal.textContent = Math.round(mw * 100) + '%';
            mwVal.style.color = mw > 0.01 ? 'var(--accent-blue)' : 'var(--text-faint)';
        }

        // ── Aftertouch ──
        const atFill = document.getElementById('ctrl-o-at-fill');
        const atVal = document.getElementById('ctrl-o-at-val');
        if (atFill) {
            atFill.style.width = Math.round(at * 100) + '%';
            atFill.style.background = at > 0.01 ? 'var(--accent-orange)' : 'var(--text-faint)';
        }
        if (atVal) {
            atVal.textContent = Math.round(at * 100) + '%';
            atVal.style.color = at > 0.01 ? 'var(--accent-orange)' : 'var(--text-faint)';
        }
    };

    /**
     * Update VU meter with ballistic smoothing (attack/release).
     * Called every RAF frame from script_controllers.js
     * @returns {number} smoothed peak level (0..1)
     */
    window._updateVuMeter = function(rawPeak) {
        rawPeak = Math.max(0, Math.min(1, rawPeak));

        const VU_ATTACK_MS = 5;
        const VU_RELEASE_MS = 300;
        const now = Date.now();
        const dt = Math.min(100, Math.max(1, now - window._vuLastTime));
        window._vuLastTime = now;

        if (rawPeak > window._vuSmoothed) {
            const attackCoeff = Math.exp(-dt / VU_ATTACK_MS);
            window._vuSmoothed = window._vuSmoothed * attackCoeff + rawPeak * (1 - attackCoeff);
        } else {
            const releaseCoeff = Math.exp(-dt / VU_RELEASE_MS);
            window._vuSmoothed = rawPeak + (window._vuSmoothed - rawPeak) * releaseCoeff;
        }
        if (window._vuSmoothed < 0.001) {window._vuSmoothed = 0.0;}

        return window._vuSmoothed;
    };
})();

/**
 * @purpose Evaluates and handles response curves for hardware controllers.
 * @purpose_en Controller Response Curves and piecewise custom curve editor support.
 */

function _evalCustomCurve(x, points) {
    if (!points || points.length < 2) {return x;}
    for (let i = 0; i < points.length - 1; i++) {
        const a = points[i], b = points[i + 1];
        if (x >= a.x && x <= b.x) {
            const t = (x - a.x) / (b.x - a.x || 1);
            return a.y + (b.y - a.y) * t;
        }
    }
    return points[points.length - 1].y;
}

window.applyControllerCurve = function(value, curveType) {
    if (curveType === 'linear' || !curveType) {return value;}
    if (curveType === 'custom') {
        const atSel = document.getElementById('settings-curve-aftertouch');
        const mwSel = document.getElementById('settings-curve-modwheel');
        const pbSel = document.getElementById('settings-curve-pitchbend');
        let ctrlName = 'aftertouch';
        if (atSel && atSel.value === 'custom') {ctrlName = 'aftertouch';}
        else if (mwSel && mwSel.value === 'custom') {ctrlName = 'modwheel';}
        else if (pbSel && pbSel.value === 'custom') {ctrlName = 'pitchbend';}
        const points = window.getCustomCurvePoints(ctrlName);
        const v = Math.max(0, Math.min(1, value));
        return _evalCustomCurve(v, points);
    }
    const v = Math.max(0, Math.min(1, value));
    switch (curveType) {
        case 'expo2':    return v * v;
        case 'expo3':    return v * v * v;
        case 'log':      return Math.sqrt(v);
        case 's-curve':  return v * v * (3 - 2 * v);
        default:         return v;
    }
};

window.getControllerCurve = function(ctrlName) {
    const key = 'abd-eep-curve-' + ctrlName;
    const saved = localStorage.getItem(key);
    return saved || 'linear';
};

window.setControllerCurve = function(ctrlName, curveType) {
    const key = 'abd-eep-curve-' + ctrlName;
    localStorage.setItem(key, curveType);
};

window.applyBipolarCurve = function(value, curveType) {
    if (curveType === 'linear' || !curveType) {return value;}
    if (curveType === 'custom') {
        const points = window.getCustomCurvePoints('pitchbend');
        const abs = Math.max(0, Math.min(1, Math.abs(value)));
        const sign = value >= 0 ? 1 : -1;
        return sign * _evalCustomCurve(abs, points);
    }
    const abs = Math.max(0, Math.min(1, Math.abs(value)));
    const sign = value >= 0 ? 1 : -1;
    switch (curveType) {
        case 'expo2':    return sign * abs * abs;
        case 'expo3':    return sign * abs * abs * abs;
        case 'log':      return sign * Math.sqrt(abs);
        case 's-curve':  return sign * (abs * abs * (3 - 2 * abs));
        default:         return value;
    }
};

window.getCustomCurvePoints = function(ctrlName) {
    const key = 'abd-eep-custom-curve-' + ctrlName;
    const raw = localStorage.getItem(key);
    let intermediates = [];
    if (raw) {
        try { intermediates = JSON.parse(raw); } catch(e) { intermediates = []; }
    }
    const all = [{x:0, y:0}, ...intermediates, {x:1, y:1}];
    all.sort((a, b) => a.x - b.x);
    return all;
};

window.setCustomCurvePoints = function(ctrlName, intermediates) {
    const key = 'abd-eep-custom-curve-' + ctrlName;
    const filtered = intermediates.filter(p => p.x > 0.001 && p.x < 0.999);
    const limited = filtered.slice(0, 5);
    localStorage.setItem(key, JSON.stringify(limited));
};

/**
 * @purpose LCD priority queue, fade animations, and safe update helpers.
 * Extracted from script_controllers.js to reduce monolithic size.
 */

// LCD Priority Queue
window.LcdQueue = {
    _messages: {},
    _expiryTimers: {},

    push: function(id, content, priority, options) {
        options = options || {};
        this._messages[id] = {
            content: content,
            priority: priority,
            timestamp: Date.now()
        };
        if (this._expiryTimers[id]) {
            clearTimeout(this._expiryTimers[id]);
        }
        const duration = (options.duration !== undefined) ? options.duration : 2000;
        if (duration !== null) {
            const self = this;
            this._expiryTimers[id] = setTimeout(function() {
                delete self._messages[id];
                delete self._expiryTimers[id];
            }, duration);
        }
    },

    getActive: function() {
        let best = null;
        for (const id in this._messages) {
            const m = this._messages[id];
            if (!best || m.priority < best.priority) {
                best = m;
            }
        }
        return best;
    },

    clear: function() {
        for (const id in this._expiryTimers) {
            clearTimeout(this._expiryTimers[id]);
        }
        this._messages = {};
        this._expiryTimers = {};
    }
};

window._LCD_FADE_OUT_EASING = 'cubic-bezier(0.4, 0.0, 1.0, 1.0)';
window._LCD_FADE_IN_EASING = 'cubic-bezier(0.0, 0.0, 0.2, 1.0)';

window.getLcdFadeTiming = function() {
    const speed = localStorage.getItem('abd-eep-fade-speed') || 'normal';
    switch (speed) {
        case 'off':    return { out:0, swap:0, in:0, cleanup:0, outR:0, swapR:0, inR:0, cleanupR:0 };
        case 'fast':   return { out:60, swap:70, in:60, cleanup:80, outR:80, swapR:90, inR:80, cleanupR:100 };
        case 'normal': return { out:100, swap:110, in:100, cleanup:130, outR:150, swapR:160, inR:150, cleanupR:180 };
        case 'slow':   return { out:220, swap:230, in:220, cleanup:250, outR:300, swapR:320, inR:300, cleanupR:350 };
        default:       return { out:100, swap:110, in:100, cleanup:130, outR:150, swapR:160, inR:150, cleanupR:180 };
    }
};

let _lcdLastParam = null;

window.lcdFadeUpdate = function(lcdEl, html, paramId) {
    if (!lcdEl) {return;}
    if (lcdEl._ctrlLcdFadeTimer) {
        clearTimeout(lcdEl._ctrlLcdFadeTimer);
        lcdEl._ctrlLcdFadeTimer = null;
    }
    const contentId = 'param_' + (paramId || 'generic');

    // Read user timeout preference
    const saved = localStorage.getItem('abd-eep-lcd-timeout');
    let timeoutMs = 2000;
    if (saved !== null) {
        timeoutMs = saved === 'off' ? null : (parseInt(saved, 10) || 2000);
    }

    if (paramId && paramId === _lcdLastParam) {
        if (lcdEl._ctrlLcdFadeTimer) {
            clearTimeout(lcdEl._ctrlLcdFadeTimer);
            lcdEl._ctrlLcdFadeTimer = null;
        }
        lcdEl._lcdFading = false;
        lcdEl.style.removeProperty('transition');
        lcdEl.style.opacity = '1';
        window.LcdQueue.push(contentId, html, 0, {
            duration: timeoutMs !== null ? timeoutMs : null
        });
        return;
    }
    _lcdLastParam = paramId;
    lcdEl._lcdFading = true;
    window.LcdQueue.push(contentId, html, 0, {
        duration: timeoutMs !== null ? timeoutMs : null
    });
    const t = window.getLcdFadeTiming();
    if (t.out === 0) {
        lcdEl._lcdFading = false;
        lcdEl.style.removeProperty('transition');
        lcdEl.style.opacity = '1';
        lcdEl.innerHTML = html;
        return;
    }
    lcdEl.style.transition = 'opacity ' + t.out + 'ms ' + window._LCD_FADE_OUT_EASING;
    lcdEl.style.opacity = '0';
    lcdEl._ctrlLcdFadeTimer = setTimeout(() => {
        if (lcdEl._ctrlLcdFadeTimer === null) {return;}
        lcdEl._ctrlLcdFadeTimer = null;
        lcdEl.innerHTML = html;
        lcdEl.style.transition = 'opacity ' + t.in + 'ms ' + window._LCD_FADE_IN_EASING;
        lcdEl.style.opacity = '1';
        lcdEl._lcdFading = false;
        setTimeout(() => {
            lcdEl.style.removeProperty('transition');
            lcdEl.style.removeProperty('opacity');
        }, t.cleanup);
    }, t.swap);
};

window.lcdSafeUpdate = function(lcdEl, html, paramId, options) {
    if (!lcdEl) {return;}
    options = options || {};
    if (typeof window.lcdFadeUpdate === 'function' && options.useQueue !== false) {
        window.lcdFadeUpdate(lcdEl, html, paramId);
    } else {
        if (lcdEl._ctrlLcdFadeTimer) {
            clearTimeout(lcdEl._ctrlLcdFadeTimer);
            lcdEl._ctrlLcdFadeTimer = null;
        }
        lcdEl._lcdFading = false;
        lcdEl.style.removeProperty('transition');
        lcdEl.style.opacity = '1';
        lcdEl.innerHTML = html;
    }
};

/**
 * @purpose PANIC (All Notes Off) button, REQUEST FROM HW button, and reset timing counters.
 * @purpose_en Panic handler with SEQ/ARP reset, edit buffer request, and elapsed-time tooltips.
 */

// eslint-disable-next-line no-var
var Logger = globalThis.Logger || console;

// ── RESET COUNTERS ──
window._seqResetCount = 0;
window._arpResetCount = 0;
window._arpLastResetTime = null;
window._seqLastResetTime = null;

window._formatElapsedTime = function (timestamp) {
    if (timestamp === null) {return null;}
    const elapsed = Math.floor((Date.now() - timestamp) / 1000);
    if (elapsed < 2) {return 'Just now';}
    if (elapsed < 60) {return elapsed + 's ago';}
    let mins = Math.floor(elapsed / 60);
    const secs = elapsed % 60;
    if (mins < 60) {return mins + 'm ' + secs + 's ago';}
    const hours = Math.floor(mins / 60);
    mins = mins % 60;
    return hours + 'h ' + mins + 'm ago';
};

window._updateResetTooltips = function () {
    const arpBtn = document.getElementById('modal-arp-reset-btn');
    const seqBtn = document.getElementById('modal-seq-reset-btn');
    const arpRel = window._formatElapsedTime(window._arpLastResetTime);
    const seqRel = window._formatElapsedTime(window._seqLastResetTime);
    if (arpBtn) {
        arpBtn.title = arpRel !== null
            ? 'Reset ARP engine \u2014 ' + arpRel + ' (#' + window._arpResetCount + ')'
            : 'Reset arpeggiator engine \u2014 stop, rewind to step 0, clear held notes';
    }
    if (seqBtn) {
        seqBtn.title = seqRel !== null
            ? 'Reset SEQ engine \u2014 ' + seqRel + ' (#' + window._seqResetCount + ')'
            : 'Reset sequencer engine \u2014 stop, rewind to step 0, clear held notes';
    }
};
setInterval(window._updateResetTooltips, 2000);

// ── INIT PANIC BUTTON ──
// eslint-disable-next-line no-unused-vars -- called from script.js via window.*
function initPanicButton() {
    const panicBtn = document.getElementById('programmer-panic-btn');
    if (!panicBtn) {return;}

    panicBtn.addEventListener('click', function () {
        if (typeof window.playKeyLedAnimation === 'function') {
            window.playKeyLedAnimation('panic');
        }
        const _pBtn_ = this;
        _pBtn_.classList.add('btn-panic', 'is-flashing');
        setTimeout(function () {
            _pBtn_.classList.remove('is-flashing');
        }, 380);

        const bridge = window.dualMidiBridge;
        if (!bridge) {
            alert('Bridge not initialized.');
            return;
        }

        let msgCount = 0;

        if (bridge.isJuce) {
            bridge.panic();
            msgCount = 1;
        } else if (bridge.midiOutput) {
            bridge._signalMidiActivity();
            for (let ch = 0; ch < 16; ch++) {
                const status = 0xB0 | ch;
                bridge.midiOutput.send([status, 123, 0]); // All Notes Off
                bridge.midiOutput.send([status, 120, 0]); // All Sound Off
                msgCount += 2;
            }
        }

        Logger.log('[Panic] Triggered panic routine. Sent ' + msgCount + ' messages/actions to stop notes.');

        let seqResetMsg = '';
        if (bridge._seqEngine) {
            const seqWasRunning = bridge._seqEngine.running;
            bridge._seqEngine.stop();
            bridge._seqEngine.stepIndex = 0;
            for (let si = 0; si < bridge._seqEngine.previousValues.length; si++) {
                bridge._seqEngine.previousValues[si] = 0;
            }
            bridge._seqEngine.heldNotes = [];
            if (seqWasRunning || (bridge.parameterCache['seq_enable'] || 0) > 0.5) {
                bridge._updateSeqEngine();
                const _seqNotesHeld_ = bridge._seqEngine.heldNotes.length;
                const _seqStepIdx_ = bridge._seqEngine.stepIndex;
                const _seqLen_ = Math.round((bridge.parameterCache['seq_length'] || 0) * 31) + 2;
                window._seqLastResetTime = Date.now();
                window._seqResetCount++;
                const _seqBar_ = window._genPosBar(Math.round((_seqStepIdx_ / Math.max(_seqLen_ - 1, 1)) * 18), 18);
                seqResetMsg = '<br>' + window._genLcdBarHtml('seq', {
                    decorated: true,
                    header: '\u2500\u2500\u2500 SEQ RESET #' + window._seqResetCount + ' \u2500\u2500\u2500',
                    stepInfo: 'Step ' + _seqStepIdx_ + ' \u00B7 ' + _seqNotesHeld_ + ' notes \u00B7 ' + _seqLen_ + ' steps',
                    bar: _seqBar_
                });
            }
        }

        let arpResetMsg = '';
        if (bridge._arpEngine) {
            const arpWasRunning = bridge._arpEngine.running;
            bridge._arpEngine.stop();
            bridge._arpEngine.stepIndex = 0;
            bridge._arpEngine.heldNotes = [];
            bridge._arpEngine.currentDirection = 1;
            bridge._arpActiveNotes = [];
            if (arpWasRunning || (bridge.parameterCache['arp_enable'] || 0) > 0.5) {
                const _arpNotesHeld_ = bridge._arpEngine.heldNotes.length;
                const _arpStepIdx_ = bridge._arpEngine.stepIndex;
                window._arpLastResetTime = Date.now();
                window._arpResetCount++;
                const _arpBar_ = window._genFillBar(Math.round((_arpNotesHeld_ / 12) * 18), 18);
                arpResetMsg = '<br>' + window._genLcdBarHtml('arp', {
                    decorated: true,
                    header: '\u2500\u2500\u2500 ARP RESET #' + window._arpResetCount + ' \u2500\u2500\u2500',
                    stepInfo: 'Step ' + _arpStepIdx_ + ' \u00B7 ' + _arpNotesHeld_ + ' notes held',
                    bar: _arpBar_
                });
            }
        }

        const lcdText = document.getElementById('lcd-text');
        if (lcdText) {
            const panicHtml = '<span class="lcd-label">\u26A0\uFE0F PANIC</span><br><strong class="lcd-color-danger">ALL NOTES OFF</strong><br><span class="lcd-sub">' + msgCount + ' MIDI messages sent</span>' + seqResetMsg + arpResetMsg;
            window.lcdSafeUpdate(lcdText, panicHtml);
        }
    });
}

// ── INIT REQUEST FROM HW ──
// eslint-disable-next-line no-unused-vars -- called from script.js via window.*
function initRequestHwButton() {
    const requestHwBtn = document.getElementById('programmer-request-hw-btn');
    if (!requestHwBtn) {return;}

    requestHwBtn.addEventListener('click', function () {
        const bridge = window.dualMidiBridge;
        if (!bridge) {
            alert('Bridge not initialized.');
            return;
        }
        const lcdText = document.getElementById('lcd-text');
        if (lcdText) {
            const html = '<span class="lcd-label">REQUESTING...</span><br><strong>EDIT BUFFER</strong>';
            window.lcdSafeUpdate(lcdText, html);
        }
        bridge.requestMidiDump('edit', 4000).then(function (response) {
            if (response) {
                Logger.log('[RequestHW] Edit buffer received:', response.length, 'bytes');
                if (lcdText) {
                    const okHtml = '<span class="lcd-color-green text-bold">\u2705 DUMP RECEIVED</span>';
                    window.lcdSafeUpdate(lcdText, okHtml);
                }
            } else {
                Logger.warn('[RequestHW] No response from hardware');
                if (lcdText) {
                    const failHtml = '<span class="lcd-color-danger text-bold">\u274C NO RESPONSE</span>';
                    window.lcdSafeUpdate(lcdText, failHtml);
                }
            }
        });
    });
}

// eslint-disable-next-line no-var
var Logger = globalThis.Logger || console;

/**
 * @purpose Manages keyboard shortcuts configuration, metadata, and mapping checks.
 * @purpose_en Keyboard Shortcut Configuration System.
 */

window.ShortcutConfig = {
    STORAGE_KEY: 'abd-eep-keyboard-shortcuts',

    _defaults: {
        'midi-learn':     { ctrl: true,  shift: false, alt: false, meta: false, key: 'l' },
        'panic':          { ctrl: true,  shift: true,  alt: false, meta: false, key: 'P' },
        'seq-quickstart': { ctrl: true,  shift: true,  alt: false, meta: false, key: 'S' },
        'seq-debug':      { ctrl: true,  shift: true,  alt: false, meta: false, key: 'D' },
    },

    _meta: {
        'midi-learn':     { label: 'MIDI Learn',     description: 'Toggle Learn mode',                           group: 'global',     color: '--accent-cyan' },
        'panic':          { label: 'PANIC',           description: 'All Notes Off + reset engines',                group: 'global',     color: '--accent-cyan' },
        'seq-quickstart': { label: 'SEQ Quick-Start', description: 'Open panel + enable SEQ',                     group: 'sequencer',  color: '--accent-pink' },
        'seq-debug':      { label: 'SEQ Debug',       description: 'Toggle debug mode',                           group: 'sequencer',  color: '--accent-pink' },
    },

    load: function() {
        let saved = {};
        try {
            const raw = localStorage.getItem(this.STORAGE_KEY);
            if (raw) {saved = JSON.parse(raw);}
        } catch(e) {}
        const result = {};
        for (const id in this._defaults) {
            result[id] = saved[id] ? this._deepClone(saved[id]) : this._deepClone(this._defaults[id]);
        }
        return result;
    },

    save: function(config) {
        try {
            localStorage.setItem(this.STORAGE_KEY, JSON.stringify(config));
        } catch(e) {}
    },

    get: function(id) {
        const all = this.load();
        return all[id] || this._deepClone(this._defaults[id]) || {};
    },

    set: function(id, combo) {
        const all = this.load();
        all[id] = this._deepClone(combo);
        this.save(all);
    },

    reset: function(id) {
        const all = this.load();
        delete all[id];
        this.save(all);
    },

    resetAll: function() {
        try {
            localStorage.removeItem(this.STORAGE_KEY);
        } catch(e) {}
    },

    formatCombo: function(combo) {
        if (!combo) {return '';}
        const parts = [];
        if (combo.ctrl)  {parts.push('Ctrl');}
        if (combo.shift) {parts.push('Shift');}
        if (combo.alt)   {parts.push('Alt');}
        if (combo.meta)  {parts.push('Meta');}
        if (combo.key)   {parts.push(combo.key.length === 1 ? combo.key.toUpperCase() : combo.key);}
        return parts.join(' + ');
    },

    getMeta: function(id) {
        return this._meta[id] || { label: id, description: '', group: 'other', color: '--text-dim' };
    },

    getAllIds: function() {
        return Object.keys(this._defaults);
    },

    matches: function(e, combo) {
        if (!combo) {return false;}
        if (!!e.ctrlKey  !== !!combo.ctrl)  {return false;}
        if (!!e.shiftKey !== !!combo.shift) {return false;}
        if (!!e.altKey   !== !!combo.alt)   {return false;}
        if (!!e.metaKey  !== !!combo.meta)  {return false;}
        const eventKey = e.key;
        if (combo.key && combo.key.length === 1 && eventKey.length === 1) {
            return eventKey.toLowerCase() === combo.key.toLowerCase();
        }
        return eventKey === combo.key;
    },

    _deepClone: function(obj) {
        return JSON.parse(JSON.stringify(obj));
    }
};

window.initKeyboardShortcuts = function() {
    document.addEventListener('keydown', function (e) {
        if (window._shortcutCaptureActive) {return;}

        const shortcuts = window.ShortcutConfig.load();

        // MIDI Learn
        if (window.ShortcutConfig.matches(e, shortcuts['midi-learn'])) {
            e.preventDefault();
            const bridge = window.dualMidiBridge;
            if (bridge && typeof bridge.toggleMidiLearn === 'function') {
                bridge.toggleMidiLearn();
            }
            return;
        }

        // SEQ Quick-Start
        if (window.ShortcutConfig.matches(e, shortcuts['seq-quickstart'])) {
            e.preventDefault();
            const bridge = window.dualMidiBridge;
            if (!bridge) {return;}
            const seqBtn = document.getElementById('programmer-seq-btn');
            if (seqBtn) {seqBtn.click();}
            const currentSeqEn = bridge.parameterCache['seq_enable'] || 0;
            if (currentSeqEn < 0.5) {
                bridge.setParameter('seq_enable', 1.0);
                Logger.log('[SeqSim] Started sequencer via shortcut');
            }
            return;
        }

        // SEQ Debug
        if (window.ShortcutConfig.matches(e, shortcuts['seq-debug'])) {
            e.preventDefault();
            window._seqDebugMode = !window._seqDebugMode;
            Logger.log('[SeqDebug] Debug mode:', window._seqDebugMode ? 'ON' : 'OFF');
            const lcdText = document.getElementById('lcd-text');
            if (lcdText && window._seqDebugMode) {
                lcdText.innerHTML = '<span class="lcd-label">SEQ DEBUG</span><br><strong style="color:var(--accent-pink);">MODE ACTIVE</strong><br><span style="font-size:7px; color:var(--text-dim);">Start sequencer to view steps</span>';
            }
            return;
        }

        // PANIC
        if (window.ShortcutConfig.matches(e, shortcuts['panic'])) {
            e.preventDefault();
            const panicBtn = document.getElementById('programmer-panic-btn');
            if (panicBtn) {
                panicBtn.click();
            }
            return;
        }
    });
};

document.addEventListener('DOMContentLoaded', () => {
    window.initKeyboardShortcuts();
});

