document.addEventListener('DOMContentLoaded', () => {
    initSequencerModal();
});

window.openSeqModal = function() {
    const backdrop = document.getElementById('seq-modal-backdrop');
    if (!backdrop) {return;}
    backdrop.style.display = 'flex';
    backdrop.classList.add('visible-flex');
    if (typeof window._updateSeqModalModeBadge === 'function') {
        window._updateSeqModalModeBadge();
    }
    if (typeof window.syncSeqModalUI === 'function') {
        window.syncSeqModalUI();
    }
    if (typeof window.syncSeqModalUIFromState === 'function') {
        window.syncSeqModalUIFromState();
    }
    if (window.dualMidiBridge) {
        const curStep = window.dualMidiBridge.parameterCache['seq_current_step'];
        if (curStep !== undefined) {
            window._modalActiveStep = Math.round(curStep);
            window._modalActiveSkip = (window.dualMidiBridge.parameterCache['seq_current_step_skip'] || 0) > 0.5;
            if (typeof window.updateStepVisual === 'function') {window.updateStepVisual(window._modalActiveStep);}
        }
    }
};

document.addEventListener('click', function(e) {
    const btn = e.target.closest('#programmer-seq-btn, #panel-seq-open-modal-btn');
    if (btn) {
        e.preventDefault();
        window.openSeqModal();
    } else if (e.target.closest('#seq-modal-close-btn') || e.target.id === 'seq-modal-backdrop') {
        if (typeof window._hideSeqModal === 'function') {
            window._hideSeqModal();
        }
    }
});

function initSequencerModal() {
    const backdrop = document.getElementById('seq-modal-backdrop');
    if (!backdrop) {return;}

    // Init sub-modules
    if (typeof window.initSequencerEditor === 'function') {window.initSequencerEditor();}
    if (typeof window.initSequencerPresets === 'function') {window.initSequencerPresets();}
    if (typeof window.initSequencerCanvas === 'function') {window.initSequencerCanvas();}

    // ── Canvas Toggle ──
    document.querySelectorAll('.seq-toggle-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
            const view = btn.getAttribute('data-view');
            if (typeof window._toggleSeqCanvasView === 'function') {
                window._toggleSeqCanvasView(view);
            }
        });
    });

    const seqBtn = document.getElementById('programmer-seq-btn');
    if (seqBtn) {
        seqBtn.addEventListener('click', function(e) {
            e.preventDefault();
            window.openSeqModal();
        });
    }

    const closeBtn = document.getElementById('seq-modal-close-btn');
    if (closeBtn) {
        closeBtn.addEventListener('click', window._hideSeqModal);
    }
    backdrop.addEventListener('click', function(e) { if (e.target === backdrop) { window._hideSeqModal(); } });

    // ── Select Handlers ──
    const seqBox = document.getElementById('modal-seq-enable-box');
    if (seqBox) {
        seqBox.addEventListener('click', function() {
            const active = seqBox.classList.contains('active');
            if (window.dualMidiBridge) {window.dualMidiBridge.setParameter('seq_enable', active ? 0.0 : 1.0);}
        });
    }

    const selectClock = document.getElementById('modal-seq-clock-select');
    if (selectClock) {
        selectClock.addEventListener('change', function() {
            if (window.dualMidiBridge) {window.dualMidiBridge.setParameter('seq_clock', parseInt(selectClock.value) / 15.0);}
        });
    }

    const selectLength = document.getElementById('modal-seq-length-select');
    if (selectLength) {
        selectLength.addEventListener('change', function() {
            if (window.dualMidiBridge) {window.dualMidiBridge.setParameter('seq_length', parseInt(selectLength.value) / 31.0);}
            for (let i = 0; i < 32; i++) {
                if (typeof window.updateStepVisual === 'function') {window.updateStepVisual(i);}
            }
        });
    }

    const selectKeyLoop = document.getElementById('modal-seq-keyloop-select');
    if (selectKeyLoop) {
        selectKeyLoop.addEventListener('change', function() {
            if (window.dualMidiBridge) {window.dualMidiBridge.setParameter('seq_key_loop', parseInt(selectKeyLoop.value) / 2.0);}
        });
    }

    // ── V-Slider Handlers ──
    backdrop.querySelectorAll('.v-slider').forEach(function(slider) {
        const ctrlUnit = slider.closest('[data-param]');
        if (!ctrlUnit) {return;}
        const paramId = ctrlUnit.getAttribute('data-param');
        const handle = slider.querySelector('.handle');
        let isDragging = false;

        function updateSliderPos(clientY) {
            const rect = slider.getBoundingClientRect();
            const handleHeight = 16;
            const limit = rect.height - handleHeight;
            let y = clientY - rect.top - (handleHeight / 2);
            y = Math.max(0, Math.min(limit, y));
            handle.style.top = y + 'px';
            const val = 1.0 - (y / limit);
            if (window.dualMidiBridge) {window.dualMidiBridge.setParameter(paramId, val);}
        }

        function onSliderMove(e) {
            if (isDragging) {updateSliderPos(e.clientY);}
        }

        function onSliderEnd() {
            isDragging = false;
            window.removeEventListener('mousemove', onSliderMove);
            window.removeEventListener('mouseup', onSliderEnd);
        }

        slider.addEventListener('mousedown', function(e) {
            isDragging = true;
            updateSliderPos(e.clientY);
            e.preventDefault();
            window.addEventListener('mousemove', onSliderMove);
            window.addEventListener('mouseup', onSliderEnd);
        });
    });

    // ── Open Panel ──
    const openPanelBtn = document.getElementById('modal-seq-open-panel-btn');
    if (openPanelBtn) {
        openPanelBtn.addEventListener('click', function(e) {
            e.preventDefault(); e.stopPropagation();
            if (typeof window.openSeqPanel === 'function') { window.openSeqPanel(); }
        });
    }

    // ── Reset Button ──
    const resetBtn = document.getElementById('modal-seq-reset-btn');
    if (resetBtn) {
        resetBtn.addEventListener('click', function() {
            const bridge = window.dualMidiBridge;
            if (!bridge || !bridge._seqEngine) {return;}
            if (typeof window._renderSeqResetFeedback === 'function') {
                window._renderSeqResetFeedback(resetBtn, bridge);
            }
        });
    }

    // ── Observer (delegated) ──
    if (typeof window._initSeqModalObserver === 'function') {
        window._initSeqModalObserver();
    }

    // ── Real-time parameter changes ──
    if (window.dualMidiBridge) {
        window.dualMidiBridge.onParameterChanged(function(paramId, val) {
            if (typeof window._handleSeqParamChange === 'function') {
                window._handleSeqParamChange(paramId, val, backdrop);
            }
        });
    }
}

/**
 * @purpose Generates 32-step grid sliders and manages updates to control values.
 * @purpose_en Control Sequencer interactive step editor.
 *
 * updateStepVisual() extraído a sequencer_editor_render.js
 */

const seqStepsValues = Array(32).fill(0);
window.seqStepsValues = seqStepsValues;
const seqStepsRaw = Array(32).fill(0);
window.seqStepsRaw = seqStepsRaw;

window.initSequencerEditor = function() {
    const stepsGrid = document.querySelector('.seq-steps-grid');
    const stepsLabels = document.querySelector('.seq-steps-labels');
    if (!stepsGrid || !stepsLabels) {return;}

    stepsGrid.innerHTML = '';
    stepsLabels.innerHTML = '';

    for (let i = 0; i < 32; i++) {
        const stepUnit = document.createElement('div');
        stepUnit.className = 'seq-editor-step';

        const numIndicator = document.createElement('div');
        numIndicator.className = 'seq-step-val';
        numIndicator.innerText = '0';
        stepUnit.appendChild(numIndicator);

        const rawIndicator = document.createElement('div');
        rawIndicator.className = 'seq-step-raw';
        rawIndicator.innerText = '128';
        stepUnit.appendChild(rawIndicator);

        const barContainer = document.createElement('div');
        barContainer.className = 'seq-step-bar-container';

        const zeroLine = document.createElement('div');
        zeroLine.className = 'seq-step-zero-line';
        barContainer.appendChild(zeroLine);

        const fillBar = document.createElement('div');
        fillBar.className = 'seq-step-fill-bar';
        barContainer.appendChild(fillBar);
        stepUnit.appendChild(barContainer);

        stepUnit.addEventListener('dblclick', (function(idx) {
            return function(e) {
                seqStepsValues[idx] = 0;
                seqStepsRaw[idx] = 128;
                const activeBank = window.loadedBanks[window.currentActiveBank];
                if (activeBank && window.currentActivePatchIndex !== -1) {
                    const patch = activeBank[window.currentActivePatchIndex];
                    if (patch && patch.unpackedBytes) {
                        patch.unpackedBytes[123 + idx] = 128;
                    }
                }
                if (window.dualMidiBridge) {
                    window.dualMidiBridge.setParameter('seq_step_' + (idx + 1), 0.5);
                }
                window.updateStepVisual(idx);
                e.preventDefault();
                e.stopPropagation();
            };
        })(i));

        let isEditing = false;

        const updateValFromY = (clientY) => {
            const rect = barContainer.getBoundingClientRect();
            const height = rect.height;
            let relY = (clientY - rect.top) / height;
            relY = Math.max(0, Math.min(1, relY));
            const normVal = 1.0 - relY;
            let bipolarVal = Math.round((normVal * 255) - 128);

            if (Math.abs(bipolarVal) <= 2) {bipolarVal = 0;}

            seqStepsValues[i] = bipolarVal;
            const rawByte = bipolarVal + 128;
            seqStepsRaw[i] = Math.max(0, Math.min(255, rawByte));

            const activeBank = window.loadedBanks[window.currentActiveBank];
            if (activeBank && window.currentActivePatchIndex !== -1) {
                const patch = activeBank[window.currentActivePatchIndex];
                if (patch && patch.unpackedBytes) {
                    patch.unpackedBytes[123 + i] = seqStepsRaw[i];
                }
            }

            const normalized = Math.max(0, Math.min(1, seqStepsRaw[i] / 255.0));
            if (window.dualMidiBridge) {
                window.dualMidiBridge.setParameter(`seq_step_${i + 1}`, normalized);
            }

            window.updateStepVisual(i);

            const lcdText = document.getElementById('lcd-text');
            if (lcdText) {
                lcdText.innerHTML = `<span class="lcd-label">CONTROL SEQ</span><br><strong>STEP ${i+1} VALUE</strong><br><span class="seq-lcd-value">${bipolarVal}</span>`;
                if (typeof window.setLcdParamDisplayTimer === 'function') {window.setLcdParamDisplayTimer(lcdText);}
            }
        };

        function onStepMove(e) {
            if (isEditing) {updateValFromY(e.clientY);}
        }
        function onStepEnd() {
            isEditing = false;
            window.removeEventListener('mousemove', onStepMove);
            window.removeEventListener('mouseup', onStepEnd);
        }
        stepUnit.addEventListener('mouseenter', (function(idx) {
            return function() {
                const lcdText = document.getElementById('lcd-text');
                if (!lcdText) {return;}
                const v = seqStepsValues[idx];
                const r = seqStepsRaw[idx];
                const isSkip = r === 0;
                const sign = v >= 0 ? '+' : '';
                const valStr = isSkip ? 'SKIP' : sign + v;
                lcdText.innerHTML = '<span class="lcd-label">CONTROL SEQ MODAL</span><br>'
                    + '<strong>STEP ' + (idx + 1) + ' VALUE</strong><br>'
                    + '<span class="seq-lcd-value">' + valStr + ' (raw:' + r + ')</span>';
                if (typeof window.setLcdParamDisplayTimer === 'function') {window.setLcdParamDisplayTimer(lcdText);}
            };
        })(i));

        stepUnit.addEventListener('mousedown', (e) => {
            isEditing = true;
            updateValFromY(e.clientY);
            e.preventDefault();
            window.addEventListener('mousemove', onStepMove);
            window.addEventListener('mouseup', onStepEnd);
        });

        stepsGrid.appendChild(stepUnit);

        const label = document.createElement('span');
        label.innerText = i + 1;
        stepsLabels.appendChild(label);
    }
};

window.initSequencerCanvas = function() {
    const canvas = document.querySelector('.seq-steps-canvas');
    if (!canvas || !window.SequencerStepsCanvas) {return;}
    if (canvas._seqStepsCanvas) { canvas._seqStepsCanvas.resize(); return; }
    canvas._seqStepsCanvas = new window.SequencerStepsCanvas(canvas);
    if (typeof canvas._seqStepsCanvas.setOnChange === 'function') {
        canvas._seqStepsCanvas.setOnChange(function(stepIdx, rawVal) {
            window.seqStepsRaw[stepIdx] = rawVal;
            window.seqStepsValues[stepIdx] = rawVal === 0 ? 0 : rawVal - 128;
            if (typeof window.updateStepVisual === 'function') {window.updateStepVisual(stepIdx);}
            const bridge = window.dualMidiBridge;
            if (bridge) {
                const paramId = 'seq_step_' + (stepIdx + 1);
                bridge.setParameter(paramId, rawVal / 255.0);
            }
        });
    }
    window.syncSeqCanvasFromValues = function() {
        if (canvas._seqStepsCanvas) {canvas._seqStepsCanvas.syncFromValues();}
    };
    canvas._seqStepsCanvas.syncFromValues();
};

window.syncSeqCanvasFromValues = function() {
    const canvas = document.querySelector('.seq-steps-canvas');
    if (canvas && canvas._seqStepsCanvas) {canvas._seqStepsCanvas.syncFromValues();}
};

// Wrap updateStepVisual to also sync the canvas widget
const _origUpdateStepVisual = window.updateStepVisual;
window.updateStepVisual = function(idx) {
    if (typeof _origUpdateStepVisual === 'function') {_origUpdateStepVisual(idx);}
    const canvas = document.querySelector('.seq-steps-canvas');
    if (canvas && canvas._seqStepsCanvas) {
        canvas._seqStepsCanvas.syncFromValues();
    }
};

/**
 * @purpose Sequencer Editor DOM Rendering — updates step visuals (values, bars, colors).
 * Extracted from sequencer_editor.js for SRP separation.
 */

/**
 * Actualiza la apariencia visual de un paso individual del secuenciador.
 * @param {number} index - Índice del paso (0-31)
 */
window.updateStepVisual = function(index) {
    const stepsGrid = document.querySelector('.seq-steps-grid');
    if (!stepsGrid) { return; }
    const stepUnit = stepsGrid.children[index];
    if (!stepUnit) { return; }
    const numIndicator = stepUnit.querySelector('.seq-step-val');
    const rawIndicator = stepUnit.querySelector('.seq-step-raw');
    const fillBar = stepUnit.querySelector('.seq-step-fill-bar');
    const barContainer = stepUnit.querySelector('.seq-step-bar-container');
    const val = window.seqStepsValues[index];
    const rawVal = window.seqStepsRaw[index];

    const selectLength = document.getElementById('modal-seq-length-select');
    const activeLength = selectLength ? (parseInt(selectLength.value) + 2) : 16;
    const isActive = index < activeLength;

    const rawForSkip = window.seqStepsRaw[index];
    const isSkip = (rawForSkip === 0);

    const signStr = val >= 0 ? '+' : '';
    stepUnit.title = isSkip
        ? 'Step ' + (index + 1) + ': SKIP (raw: ' + rawForSkip + ')'
        : 'Step ' + (index + 1) + ': ' + signStr + val + ' (raw: ' + rawForSkip + ')';

    if (numIndicator) {
        if (isSkip) {
            numIndicator.innerText = 'SKIP';
            numIndicator.style.color = 'var(--text-faint)';
            numIndicator.style.fontSize = '6px';
        } else if (val === 0) {
            numIndicator.innerText = '0';
            numIndicator.style.color = 'var(--text-dim)';
            numIndicator.style.fontSize = 'var(--text-xs)';
        } else {
            numIndicator.innerText = val > 0 ? '+' + val : String(val);
            numIndicator.style.color = isActive ? 'var(--brand-accent)' : 'var(--text-faint)';
            numIndicator.style.fontSize = 'var(--text-xs)';
        }
        numIndicator.style.background = isActive ? 'var(--bg-header)' : 'var(--bg-surface)';
        numIndicator.style.borderColor = isActive ? (isSkip ? 'var(--color-danger)' : 'var(--brand-accent)') : 'var(--border-dim)';
        numIndicator.style.opacity = isActive ? '1.0' : '0.4';
    }

    if (rawIndicator) {
        rawIndicator.innerText = isSkip ? '--' : String(rawVal);
        rawIndicator.style.color = isSkip ? 'var(--color-danger)' : (isActive ? 'var(--text-dim)' : 'var(--text-faint)');
        rawIndicator.style.opacity = isActive ? '0.8' : '0.3';
    }

    if (stepUnit) {
        stepUnit.style.background = isSkip ? 'rgba(255,0,0,0.05)' : (isActive ? 'var(--bg-surface)' : 'var(--bg-deepest)');
    }

    if (index === window._modalActiveStep) {
        stepUnit.style.outline = window._modalActiveSkip
            ? '1px dashed var(--color-danger)'
            : '1.5px solid var(--accent-pink)';
        stepUnit.style.boxShadow = window._modalActiveSkip
            ? '0 0 4px rgba(255,0,0,0.3)'
            : '0 0 8px color-mix(in srgb, var(--accent-pink) 40%, transparent)';
        if (numIndicator) {
            numIndicator.style.borderColor = window._modalActiveSkip ? 'var(--color-danger)' : 'var(--accent-pink)';
            numIndicator.style.boxShadow = '0 0 4px var(--accent-pink)';
        }
    } else {
        stepUnit.style.outline = '';
        stepUnit.style.boxShadow = '';
        if (numIndicator) { numIndicator.style.boxShadow = ''; }
    }

    if (barContainer) {
        barContainer.style.background = isActive ? 'var(--bg-header)' : 'var(--bg-surface)';
    }

    if (fillBar) {
        if (isSkip) {
            fillBar.style.bottom = '50%';
            fillBar.style.height = '0%';
            fillBar.style.background = 'transparent';
            fillBar.style.borderLeft = 'none';
            fillBar.style.borderTop = 'none';
            fillBar.style.outline = '1px dashed var(--color-danger)';
        } else if (val >= 0) {
            const pctUp = (val / 127) * 50;
            fillBar.style.bottom = '50%';
            fillBar.style.height = Math.max(3, pctUp) + '%';
            fillBar.style.background = isActive ? 'var(--accent-pink)' : 'color-mix(in srgb, var(--accent-pink) 20%, transparent)';
            fillBar.style.borderTop = isActive ? '2px solid #ffffff' : '2px solid var(--accent-pink)';
            fillBar.style.boxShadow = isActive ? '0 -1px 3px var(--accent-pink)' : 'none';
            fillBar.style.outline = 'none';
        } else {
            const pctDown = (Math.abs(val) / 128) * 50;
            fillBar.style.bottom = (50 - pctDown) + '%';
            fillBar.style.height = Math.max(3, pctDown) + '%';
            fillBar.style.background = isActive ? 'color-mix(in srgb, var(--accent-pink) 60%, #000)' : 'color-mix(in srgb, var(--accent-pink) 20%, #000)';
            fillBar.style.borderTop = isActive ? '2px solid var(--accent-pink)' : '1px solid var(--border)';
            fillBar.style.boxShadow = isActive ? '0 0 3px var(--accent-pink)' : 'none';
            fillBar.style.outline = 'none';
        }
    }
};

/**
 * @purpose Polling timer y MutationObserver para el modal del secuenciador.
 * Extraído de sequencer_modal_state.js como parte de la modularización.
 * @purpose_en Sequencer modal polling and observer logic.
 */

// ── Modal Polling ──
let _modalPollTimer = null;

window._startModalPolling = function() {
    window._stopModalPolling();
    const backdrop = document.getElementById('seq-modal-backdrop');
    const stepsGrid = document.querySelector('.seq-steps-grid');
    if (!backdrop || !stepsGrid) {return;}

    _modalPollTimer = setInterval(function() {
        if (backdrop.style.display === 'none') {
            window._stopModalPolling();
            return;
        }
        const bridge = window.dualMidiBridge;
        if (!bridge) {return;}

        const currentStep = bridge.parameterCache['seq_current_step'];
        const seqEn = bridge.parameterCache['seq_enable'] || 0;

        if (seqEn < 0.5) {
            if (window._modalActiveStep !== -1) {
                window._clearModalActiveHighlight();
            }
            window._modalLastPolledStep = -1;
            return;
        }

        if (currentStep === undefined || currentStep === null) {
            if (window._modalActiveStep !== -1) {
                window._clearModalActiveHighlight();
            }
            window._modalLastPolledStep = -1;
            return;
        }

        window._updateSeqModalModeBadge();

        const stepIdx = Math.round(currentStep);
        const isSkip = (bridge.parameterCache['seq_current_step_skip'] || 0) > 0.5;

        if (stepIdx !== window._modalLastPolledStep || isSkip !== window._modalActiveSkip) {
            if (window._modalActiveStep >= 0 && window._modalActiveStep < 32) {
                const prevEl = stepsGrid.children[window._modalActiveStep];
                if (prevEl) {
                    prevEl.style.outline = '';
                    prevEl.style.boxShadow = '';
                    const prevNum = prevEl.querySelector('.seq-step-val');
                    if (prevNum) {prevNum.style.boxShadow = '';}
                }
            }
            window._modalActiveStep = stepIdx;
            window._modalActiveSkip = isSkip;
            window._modalLastPolledStep = stepIdx;
            if (typeof window.updateStepVisual === 'function') {window.updateStepVisual(stepIdx);}
        }
    }, 100);
};

window._stopModalPolling = function() {
    if (_modalPollTimer) {
        clearInterval(_modalPollTimer);
        _modalPollTimer = null;
    }
};

window.addEventListener('beforeunload', window._stopModalPolling);

// ── Modal Observer ──
window._initSeqModalObserver = function() {
    const backdrop = document.getElementById('seq-modal-backdrop');
    if (!backdrop) {return;}
    const observer = new MutationObserver(function() {
        if (backdrop.style.display === 'flex') {
            window._clearModalActiveHighlight();
            window._startModalPolling();
        } else if (backdrop.style.display === 'none') {
            window._stopModalPolling();
            window._clearModalActiveHighlight();
        }
    });
    observer.observe(backdrop, { attributes: true, attributeFilter: ['style'] });
};

/**
 * @purpose Estado, sync UI y observer del modal del secuenciador.
 * Polling extraído a sequencer_modal_polling.js.
 * Extraído de sequencer.js como parte de la modularización.
 * @purpose_en Sequencer modal state management and UI sync.
 */

// ── Shared State ──
let _modalActiveStep = -1;
window._modalActiveStep = _modalActiveStep;
const _modalActiveSkip = false;
window._modalActiveSkip = _modalActiveSkip;
let _modalLastPolledStep = -1;
window._modalLastPolledStep = _modalLastPolledStep;

// ── Hide Modal ──
window._hideSeqModal = function() {
    const backdrop = document.getElementById('seq-modal-backdrop');
    if (!backdrop) {return;}
    backdrop.style.display = 'none';
    backdrop.classList.remove('visible-flex');
    window._stopModalPolling();
    window._clearModalActiveHighlight();
};

// ── Clear Active Highlight ──
window._clearModalActiveHighlight = function() {
    const stepsGrid = document.querySelector('.seq-steps-grid');
    if (!stepsGrid) {return;}
    for (let ci = 0; ci < 32; ci++) {
        const child = stepsGrid.children[ci];
        if (child) {
            child.style.outline = '';
            child.style.boxShadow = '';
            const numEl = child.querySelector('.seq-step-val');
            if (numEl) {numEl.style.boxShadow = '';}
            const rawEl = child.querySelector('.seq-step-raw');
            if (rawEl) {rawEl.style.color = '';}
        }
    }
    _modalActiveStep = -1;
    window._modalActiveStep = -1;
    _modalLastPolledStep = -1;
    window._modalLastPolledStep = -1;
};

// ── Sync Modal UI ──
window.syncSeqModalUI = function() {
    if (typeof window.currentActivePatchIndex === 'undefined' || window.currentActivePatchIndex === -1) {return;}
    const activeBank = window.loadedBanks && window.loadedBanks[window.currentActiveBank];
    if (!activeBank) {return;}
    const patch = activeBank[window.currentActivePatchIndex];
    if (!patch || !patch.unpackedBytes) {return;}

    const seqBox = document.getElementById('modal-seq-enable-box');
    const selectClock = document.getElementById('modal-seq-clock-select');
    const selectLength = document.getElementById('modal-seq-length-select');
    const selectKeyLoop = document.getElementById('modal-seq-keyloop-select');

    const seqEn = patch.unpackedBytes[117] > 0.5;
    const clockVal = patch.unpackedBytes[118] || 0;
    const lengthVal = patch.unpackedBytes[119] || 0;
    const keyloopVal = patch.unpackedBytes[121] || 0;

    if (seqBox) {seqBox.classList.toggle('active', seqEn);}
    if (selectClock) {selectClock.value = Math.round(clockVal);}
    if (selectLength) {selectLength.value = Math.round(lengthVal);}
    if (selectKeyLoop) {selectKeyLoop.value = Math.round(keyloopVal);}

    const sliders = [
        { id: 'seq_swing', val: patch.unpackedBytes[120] / 25.0 },
        { id: 'seq_slew_rate', val: patch.unpackedBytes[122] / 255.0 }
    ];

    sliders.forEach(function(sliderInfo) {
        if (sliderInfo.id === 'seq_swing') {
            const txt = document.getElementById('modal-seq-swing-val');
            if (txt) {txt.innerText = Math.round(50 + sliderInfo.val * 9);}
        } else if (sliderInfo.id === 'seq_slew_rate') {
            const txt = document.getElementById('modal-seq-slew-val');
            if (txt) {txt.innerText = Math.round(sliderInfo.val * 255);}
        }

        const backdrop = document.getElementById('seq-modal-backdrop');
        if (!backdrop) {return;}
        const sliderEl = backdrop.querySelector('[data-param="' + sliderInfo.id + '"] .v-slider');
        if (sliderEl) {
            const handle = sliderEl.querySelector('.handle');
            const pos = function() {
                const rect = sliderEl.getBoundingClientRect();
                if (rect.height > 0) {
                    const handleHeight = 16;
                    const posY = (1.0 - sliderInfo.val) * (rect.height - handleHeight);
                    handle.style.top = posY + 'px';
                } else {
                    setTimeout(pos, 100);
                }
            };
            pos();
        }
    });

    for (let i = 0; i < 32; i++) {
        const rawByte = patch.unpackedBytes[123 + i];
        window.seqStepsRaw[i] = rawByte;
        window.seqStepsValues[i] = rawByte === 0 ? 0 : rawByte - 128;
        if (typeof window.updateStepVisual === 'function') {window.updateStepVisual(i);}
    }
};

// ── Update Seq Modal Mode Badge ──
window._updateSeqModalModeBadge = function() {
    const badgeEl = document.getElementById('modal-seq-mode-badge');
    if (!badgeEl) {return;}
    const bridge = window.dualMidiBridge;
    if (!bridge) {return;}
    const keyLoopNorm = bridge.parameterCache['seq_key_loop'] || 0;
    const keyLoopVal = Math.round(keyLoopNorm * 2);
    const forcedMode = bridge._seqEngine && bridge._seqEngine._forcedFreeRunning;
    let label = '', color = '';
    if (forcedMode) {
        label = 'FREE*';
        color = 'var(--accent-yellow)';
    } else if (keyLoopVal === 0) {
        label = 'FREE';
        color = 'var(--accent-green)';
    } else if (keyLoopVal === 1) {
        label = 'KEY';
        color = 'var(--accent-blue)';
    } else {
        label = 'LOOP';
        color = 'var(--accent-teal)';
    }
    let tooltip = '';
    if (label === 'FREE*') {
        tooltip = ' title="Key Sync desactivado automáticamente — no había teclas presionadas al activar SEQ"';
    }
    const cursorStyle = label === 'FREE*' ? ';cursor:help' : '';
    badgeEl.innerHTML = '<span style="color:' + color + ';font-weight:bold;border:1px solid ' + color + ';padding:0 6px;border-radius:3px;font-size:10px' + cursorStyle + '"' + tooltip + '>' + label + '</span>';
};

// ── Sync State From External ──
window.syncSeqModalUIFromState = function() {
    const backdrop = document.getElementById('seq-modal-backdrop');
    if (backdrop && backdrop.style.display !== 'none') {
        window.syncSeqModalUI();
    }
};

/**
 * @purpose Handles loading, applying, and saving Control Sequencer presets.
 * @purpose_en Control Sequencer presets service.
 */

const DEFAULT_SEQ_PRESETS = [
    {
        name: 'Staircase',
        steps: Array(32).fill(0).map((_, i) => Math.round((i / 31) * 255))
    },
    {
        name: 'Triangle Wave',
        steps: Array(32).fill(0).map((_, i) => {
            const phase = (i / 16) % 2.0;
            const val = phase < 1.0 ? phase : 2.0 - phase;
            return Math.round(val * 255);
        })
    },
    {
        name: 'Random Walk',
        steps: Array(32).fill(0).map(() => Math.round(Math.random() * 255))
    }
];

function _loadUserSeqPresets() {
    try {
        const raw = localStorage.getItem('abd-eep-seq-presets');
        if (raw) {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed) && parsed.length > 0) {
                let allValid = true;
                const sanitized = parsed.map(p => {
                    if (!p || !Array.isArray(p.steps) || p.steps.length !== 32) {
                        allValid = false;
                        const match = DEFAULT_SEQ_PRESETS.find(d => d.name === (p && p.name));
                        return match ? { name: p.name, steps: match.steps } : { name: (p && p.name) || 'Preset', steps: Array(32).fill(0).map((_, i) => Math.round((i / 31) * 255)) };
                    }
                    return p;
                });
                if (!allValid) {
                    localStorage.setItem('abd-eep-seq-presets', JSON.stringify(sanitized));
                }
                return sanitized;
            }
        }
    } catch (e) {}
    localStorage.setItem('abd-eep-seq-presets', JSON.stringify(DEFAULT_SEQ_PRESETS));
    return DEFAULT_SEQ_PRESETS;
}
window._loadUserSeqPresets = _loadUserSeqPresets;

window.initSequencerPresets = function() {
    const presetsList = document.getElementById('modal-seq-presets-list');
    const loadPresetBtn = document.getElementById('modal-seq-load-preset');
    const savePresetBtn = document.getElementById('modal-seq-save-preset');

    function renderPresetsList() {
        if (!presetsList) {return;}
        presetsList.innerHTML = '';

        // Render User Presets
        const userPresets = _loadUserSeqPresets();
        userPresets.forEach((p, _idx) => {
            const item = document.createElement('div');
            item.className = 'preset-item seq-preset-list-item text-sm text-primary';
            item.innerHTML = `<span style="font-weight:bold;color:var(--accent-pink)">${p.name}</span>` +
                             '<span class="delete-seq-preset-btn" style="color:var(--text-faint);font-size:10px;cursor:pointer;padding:0 4px;">✕</span>';

            item.addEventListener('click', (e) => {
                if (e.target.classList.contains('delete-seq-preset-btn')) {return;}
                selectItem(item, p);
            });
            item.addEventListener('dblclick', (e) => {
                if (e.target.classList.contains('delete-seq-preset-btn')) {return;}
                selectItem(item, p);
                if (loadPresetBtn) {loadPresetBtn.click();}
            });

            const delBtn = item.querySelector('.delete-seq-preset-btn');
            if (delBtn) {
                delBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    deleteSeqPreset(p.name);
                });
            }

            presetsList.appendChild(item);
        });

        // Render Factory Presets (from factory_seq_presets.js)
        if (window.FACTORY_SEQ_PRESETS) {
            window.FACTORY_SEQ_PRESETS.forEach(p => {
                const item = document.createElement('div');
                item.className = 'preset-item seq-preset-list-item text-sm text-primary';
                item.innerHTML = `<span style="color:var(--text-dim)">${p.name}</span> <span style="font-size:8px;color:var(--text-faint)">Factory</span>`;

                item.addEventListener('click', () => {
                    selectItem(item, p);
                });
                item.addEventListener('dblclick', () => {
                    selectItem(item, p);
                    if (loadPresetBtn) {loadPresetBtn.click();}
                });

                presetsList.appendChild(item);
            });
        }
    }

    let selectedPreset = null;

    function applyPreset(presetObj) {
        if (!presetObj) {return;}
        let steps = presetObj.steps;
        if (!Array.isArray(steps) || steps.length !== 32) {
            const match = DEFAULT_SEQ_PRESETS.find(d => d.name === presetObj.name);
            steps = match ? match.steps : Array(32).fill(0).map((_, i) => Math.round((i / 31) * 255));
        }

        for (let i = 0; i < 32; i++) {
            const rawByte = Math.max(0, Math.min(255, steps[i]));
            window.seqStepsRaw[i] = rawByte;
            window.seqStepsValues[i] = rawByte === 0 ? 0 : rawByte - 128;

            const activeBank = (window.loadedBanks && window.currentActiveBank) ? window.loadedBanks[window.currentActiveBank] : null;
            const patch = (activeBank && window.currentActivePatchIndex !== -1) ? activeBank[window.currentActivePatchIndex] : null;
            if (patch && patch.unpackedBytes) {
                patch.unpackedBytes[123 + i] = rawByte;
            }

            const normalized = rawByte / 255.0;
            if (window.dualMidiBridge) {
                window.dualMidiBridge.setParameter(`seq_step_${i + 1}`, normalized);
            }
            if (typeof window.updateStepVisual === 'function') {
                window.updateStepVisual(i);
            }
        }
        if (typeof window.syncSeqCanvasFromValues === 'function') {
            window.syncSeqCanvasFromValues();
        }

        const _presetName_ = presetObj.name;
        const _lcd_ = document.getElementById('lcd-text');
        if (_lcd_) {
            let _sum_ = 0, _count_ = 0;
            for (let _pi_ = 0; _pi_ < 32; _pi_++) {
                const _abs_ = Math.abs(window.seqStepsValues[_pi_]);
                if (_abs_ > 5) { _sum_ += _pi_; _count_++; }
            }
            const _avgPos_ = _count_ > 0 ? Math.round(_sum_ / _count_) : 16;
            const _bar_ = (typeof window._genPosBar === 'function') ? window._genPosBar(_avgPos_, 18) : '';
            const _presetHtml_ = (typeof window._genLcdBarHtml === 'function') ? window._genLcdBarHtml('seq_preset', {
                header: 'SEQ PRESET LOADED',
                presetName: _presetName_,
                bar: _bar_,
                meta: '32 steps \u00B7 avg pos: ' + _avgPos_
            }) : 'SEQ PRESET: ' + _presetName_;
            if (typeof window.lcdSafeUpdate === 'function') {
                window.lcdSafeUpdate(_lcd_, _presetHtml_, 'seq_preset');
            }
        }
    }

    function selectItem(itemEl, presetObj) {
        presetsList.querySelectorAll('.preset-item').forEach(i => {
            i.style.background = 'transparent';
            i.classList.remove('selected');
        });
        itemEl.style.background = 'color-mix(in srgb, var(--accent-pink) 20%, transparent)';
        itemEl.classList.add('selected');
        selectedPreset = presetObj;
        applyPreset(presetObj);
    }

    function deleteSeqPreset(name) {
        let userPresets = _loadUserSeqPresets();
        userPresets = userPresets.filter(p => p.name !== name);
        localStorage.setItem('abd-eep-seq-presets', JSON.stringify(userPresets));
        renderPresetsList();
    }

    renderPresetsList();

    if (loadPresetBtn) {
        loadPresetBtn.addEventListener('click', () => {
            if (selectedPreset) {
                applyPreset(selectedPreset);
            }
        });
    }

    if (savePresetBtn) {
        savePresetBtn.addEventListener('click', () => {
            if (window.currentActiveBank && window.currentActiveBank.startsWith('Factory Bank')) {
                alert('Cannot save sequences on factory patches. Please copy this patch to a User Bank first.');
                return;
            }
            const name = prompt('Enter a name for the new sequence preset:');
            if (name && name.trim()) {
                const cleanName = name.trim().replace(/[<>"'&]/g, '');
                if (!cleanName) {return;}

                const currentSteps = [];
                for (let i = 0; i < 32; i++) {
                    currentSteps.push(window.seqStepsRaw[i] !== undefined ? window.seqStepsRaw[i] : 128);
                }

                const userPresets = _loadUserSeqPresets();
                const existingIdx = userPresets.findIndex(p => p.name === cleanName);
                const newPreset = { name: cleanName, steps: currentSteps };

                if (existingIdx >= 0) {
                    userPresets[existingIdx] = newPreset;
                } else {
                    userPresets.push(newPreset);
                }

                localStorage.setItem('abd-eep-seq-presets', JSON.stringify(userPresets));
                renderPresetsList();
            }
        });
    }
};

/**
 * @purpose Sequencer render/UI sync functions — extracted from sequencer.js.
 * Handles: canvas view toggle, reset button feedback animation, real-time parameter change UI sync.
 */

/** Toggle between canvas and grid view for sequencer steps */
window._toggleSeqCanvasView = function(view) {
    const toggleBtns = document.querySelectorAll('.seq-toggle-btn');
    const seqCanvas = document.querySelector('.seq-steps-canvas');
    toggleBtns.forEach(function(b) { b.classList.remove('active'); b.style.borderColor = 'var(--border)'; });
    const activeBtn = document.querySelector('.seq-toggle-btn[data-view="' + view + '"]');
    if (activeBtn) { activeBtn.classList.add('active'); activeBtn.style.borderColor = 'var(--accent-teal)'; }
    if (view === 'canvas') {
        const grid = document.querySelector('.seq-steps-grid');
        const labels = document.querySelector('.seq-steps-labels');
        if (grid) { grid.style.display = 'none'; }
        if (labels) { labels.style.display = 'none'; }
        if (seqCanvas) {
            seqCanvas.style.display = 'block';
            if (seqCanvas._seqStepsCanvas) {
                seqCanvas._seqStepsCanvas.resize();
                seqCanvas._seqStepsCanvas.syncFromValues();
            }
        }
    } else {
        const grid = document.querySelector('.seq-steps-grid');
        const labels = document.querySelector('.seq-steps-labels');
        if (grid) { grid.style.display = 'flex'; }
        if (labels) { labels.style.display = 'flex'; }
        if (seqCanvas) { seqCanvas.style.display = 'none'; }
    }
};

/** Render reset button flash feedback animation and LCD update */
window._renderSeqResetFeedback = function(resetBtn, bridge) {
    if (!resetBtn || !bridge) {return;}
    const wasRunning = bridge._seqEngine.running;
    bridge._seqEngine.stop();
    bridge._seqEngine.stepIndex = 0;
    bridge._seqEngine.heldNotes = [];
    bridge._seqEngine._forcedFreeRunning = false;
    for (let si = 0; si < bridge._seqEngine.previousValues.length; si++) {
        bridge._seqEngine.previousValues[si] = 0;
    }
    window._clearModalActiveHighlight();

    if (wasRunning || (bridge.parameterCache['seq_enable'] || 0) > 0.5) {
        bridge._updateSeqEngine();
    }

    window._seqLastResetTime = Date.now();
    window._seqResetCount++;
    const _sNotes_ = bridge._seqEngine.heldNotes.length;
    const _sStep_ = bridge._seqEngine.stepIndex;
    const _sLen_ = Math.round((bridge.parameterCache['seq_length'] || 0) * 31) + 2;
    const _sBar_ = window._genPosBar(Math.round((_sStep_ / Math.max(_sLen_ - 1, 1)) * 18), 18);
    const _lcdText_ = document.getElementById('lcd-text');
    if (_lcdText_) {
        const _seqHtml_ = window._genLcdBarHtml('seq', {
            header: 'SEQUENCER RESET (manual) #' + window._seqResetCount,
            stepInfo: 'Step ' + _sStep_ + ' \u00B7 ' + _sNotes_ + ' notes \u00B7 ' + _sLen_ + ' steps',
            bar: _sBar_
        });
        window.lcdSafeUpdate(_lcdText_, _seqHtml_, 'seq_reset');
    }

    // Button flash animation
    resetBtn.style.transition = 'background 60ms ease-out, box-shadow 60ms ease-out';
    resetBtn.style.background = 'color-mix(in srgb, var(--color-danger) 70%, transparent)';
    resetBtn.style.boxShadow = '0 0 16px var(--color-danger)';
    resetBtn.style.borderColor = 'var(--color-danger)';
    resetBtn.style.color = 'var(--color-danger)';
    setTimeout(function() {
        resetBtn.style.transition = 'background 300ms ease-out, box-shadow 300ms ease-out, border-color 300ms ease-out, color 300ms ease-out';
        resetBtn.style.background = '';
        resetBtn.style.boxShadow = '';
        resetBtn.style.borderColor = '';
        resetBtn.style.color = '';
        setTimeout(function() { resetBtn.style.transition = ''; }, 320);
    }, 60);
};

/** Handle real-time sequencer parameter changes — UI sync only */
window._handleSeqParamChange = function(paramId, val, backdrop) {
    if (!backdrop || backdrop.style.display === 'none') {return;}

    const seqBox = document.getElementById('modal-seq-enable-box');
    const selectClock = document.getElementById('modal-seq-clock-select');
    const selectLength = document.getElementById('modal-seq-length-select');
    const selectKeyLoop = document.getElementById('modal-seq-keyloop-select');

    if (paramId === 'seq_enable' && seqBox) {
        seqBox.classList.toggle('active', val > 0.5);
        if (val < 0.5) { window._clearModalActiveHighlight(); }
        if (val > 0.5 && window.dualMidiBridge && window.dualMidiBridge._seqEngine) {
            const _sNotes_ = window.dualMidiBridge._seqEngine.heldNotes.length;
            const _sStep_ = window.dualMidiBridge._seqEngine.stepIndex;
            const _sLen_ = Math.round((window.dualMidiBridge.parameterCache['seq_length'] || 0) * 31) + 2;
            window._seqLastResetTime = Date.now();
            window._seqResetCount++;
            const _sBar_ = window._genPosBar(Math.round((_sStep_ / Math.max(_sLen_ - 1, 1)) * 18), 18);
            const _lcdText_ = document.getElementById('lcd-text');
            if (_lcdText_) {
                const _seqHtml_ = window._genLcdBarHtml('seq', {
                    header: 'SEQUENCER RESET #' + window._seqResetCount,
                    stepInfo: 'Step ' + _sStep_ + ' \u00B7 ' + _sNotes_ + ' notes \u00B7 ' + _sLen_ + ' steps',
                    bar: _sBar_
                });
                window.lcdSafeUpdate(_lcdText_, _seqHtml_, 'seq_enable');
            }
        }
    }
    if (paramId === 'seq_clock' && selectClock) {selectClock.value = Math.round(val * 15.0);}
    if (paramId === 'seq_length' && selectLength) {
        selectLength.value = Math.round(val * 31.0);
        for (let i = 0; i < 32; i++) {
            if (typeof window.updateStepVisual === 'function') {window.updateStepVisual(i);}
        }
    }
    if (paramId === 'seq_key_loop' && selectKeyLoop) {selectKeyLoop.value = Math.round(val * 2.0);}
    if (paramId && paramId.startsWith('seq_step_')) {
        const stepIdx = parseInt(paramId.split('_')[2]) - 1;
        if (stepIdx >= 0 && stepIdx < 32) {
            const rawByte = Math.round(val * 255);
            window.seqStepsRaw[stepIdx] = rawByte;
            window.seqStepsValues[stepIdx] = rawByte === 0 ? 0 : rawByte - 128;
            if (typeof window.updateStepVisual === 'function') {window.updateStepVisual(stepIdx);}
        }
        return;
    }

    if (paramId === 'seq_swing' || paramId === 'seq_slew_rate') {
        if (paramId === 'seq_swing') {
            const txt = document.getElementById('modal-seq-swing-val');
            if (txt) {txt.innerText = Math.round(50 + val * 9);}
        } else if (paramId === 'seq_slew_rate') {
            const txt = document.getElementById('modal-seq-slew-val');
            if (txt) {txt.innerText = Math.round(val * 255);}
        }
        const sliderEl = backdrop.querySelector('[data-param="' + paramId + '"] .v-slider');
        if (sliderEl) {
            const handle = sliderEl.querySelector('.handle');
            const rect = sliderEl.getBoundingClientRect();
            if (rect.height > 0) {
                const handleHeight = 16;
                const pos = (1.0 - val) * (rect.height - handleHeight);
                handle.style.top = pos + 'px';
            }
        }
    }
};

