/**
 * @purpose Custom curve canvas drag/drop interaction for the response curve editor.
 * Canvas drawing extraído a settings_curves_draw.js.
 */

(function() {
    window._lastCurveType = 'linear';
    window._lastCurveIsBipolar = false;

    function _getActiveCustomCtrlName() {
        const atSel = document.getElementById('settings-curve-aftertouch');
        const mwSel = document.getElementById('settings-curve-modwheel');
        const pbSel = document.getElementById('settings-curve-pitchbend');
        if (atSel && atSel.value === 'custom') {return 'aftertouch';}
        if (mwSel && mwSel.value === 'custom') {return 'modwheel';}
        if (pbSel && pbSel.value === 'custom') {return 'pitchbend';}
        return null;
    }

    window._setupCustomCurveCanvas = function() {
        const canvas = document.getElementById('curve-preview-canvas');
        if (!canvas || canvas._customCurveSetupDone) {return;}
        canvas._customCurveSetupDone = true;

        let dragState = null;

        function canvasXToCurve(cvX) {
            const pad = 8, graphW = canvas.width - 16;
            return (cvX - pad) / graphW;
        }
        function canvasYToCurve(cvY, bipolar) {
            const pad = 8, graphH = canvas.height - 16;
            if (bipolar) {
                const centerY = pad + graphH / 2;
                return (centerY - cvY) / (graphH / 2);
            }
            return 1.0 - (cvY - pad) / graphH;
        }
        function curveToCanvasX(x) {
            const pad = 8, graphW = canvas.width - 16;
            return pad + x * graphW;
        }
        function curveToCanvasY(y, bipolar) {
            const pad = 8, graphH = canvas.height - 16;
            if (bipolar) {
                const centerY = pad + graphH / 2;
                return centerY - y * (graphH / 2);
            }
            return pad + (1 - y) * graphH;
        }

        function hitTest(cvX, cvY, points, bipolar) {
            for (let i = 0; i < points.length; i++) {
                const px = curveToCanvasX(points[i].x);
                const py = curveToCanvasY(points[i].y, bipolar);
                const dx = cvX - px, dy = cvY - py;
                if (dx * dx + dy * dy < 100) {return i;}
            }
            return -1;
        }

        function addPoint(cvX, cvY, ctrlName, bipolar) {
            const nx = Math.max(0.01, Math.min(0.99, canvasXToCurve(cvX)));
            let ny = Math.max(0, Math.min(1, canvasYToCurve(cvY, bipolar)));
            if (bipolar) {ny = Math.max(-1, Math.min(1, ny));}
            const points = window.getCustomCurvePoints(ctrlName);
            const intermediates = points.filter(p => p.x > 0.001 && p.x < 0.999);
            if (intermediates.length >= 5) {return;}
            intermediates.push({x: nx, y: ny});
            intermediates.sort((a, b) => a.x - b.x);
            window.setCustomCurvePoints(ctrlName, intermediates);
            _redrawCustom();
        }

        function deletePoint(idx, points, ctrlName) {
            if (idx <= 0 || idx >= points.length - 1) {return;}
            const intermediates = points.filter(p => p.x > 0.001 && p.x < 0.999);
            intermediates.splice(idx - 1, 1);
            window.setCustomCurvePoints(ctrlName, intermediates);
            _redrawCustom();
        }

        function _redrawCustom() {
            if (typeof window.drawCurvePreview === 'function') {
                window.drawCurvePreview('custom', window._lastCurveIsBipolar);
            }
        }

        canvas.addEventListener('pointerdown', (e) => {
            const ctrlName = _getActiveCustomCtrlName();
            if (!ctrlName) {return;}
            if (window._lastCurveType !== 'custom') {return;}
            const rect = canvas.getBoundingClientRect();
            const cvX = e.clientX - rect.left;
            const cvY = e.clientY - rect.top;
            const points = window.getCustomCurvePoints(ctrlName);
            const hit = hitTest(cvX, cvY, points, window._lastCurveIsBipolar);
            if (hit >= 0) {
                dragState = {
                    idx: hit,
                    ctrlName: ctrlName,
                    offsetX: cvX - curveToCanvasX(points[hit].x),
                    offsetY: cvY - curveToCanvasY(points[hit].y, window._lastCurveIsBipolar)
                };
                canvas.setPointerCapture(e.pointerId);
                e.preventDefault();
            } else {
                addPoint(cvX, cvY, ctrlName, window._lastCurveIsBipolar);
            }
        });

        canvas.addEventListener('pointermove', (e) => {
            if (!dragState) {return;}
            const rect = canvas.getBoundingClientRect();
            const cvX = e.clientX - rect.left;
            const cvY = e.clientY - rect.top;
            const points = window.getCustomCurvePoints(dragState.ctrlName);
            if (dragState.idx < 0 || dragState.idx >= points.length) {return;}
            let nx = Math.max(0, Math.min(1, canvasXToCurve(cvX - dragState.offsetX)));
            let ny = Math.max(0, Math.min(1, canvasYToCurve(cvY - dragState.offsetY, window._lastCurveIsBipolar)));
            if (window._lastCurveIsBipolar) {ny = Math.max(-1, Math.min(1, ny));}

            if (dragState.idx === 0) { nx = 0; ny = 0; }
            if (dragState.idx === points.length - 1) { nx = 1; ny = 1; }

            if (dragState.idx > 0) {nx = Math.max(nx, points[dragState.idx - 1].x + 0.01);}
            if (dragState.idx < points.length - 1) {nx = Math.min(nx, points[dragState.idx + 1].x - 0.01);}
            points[dragState.idx].x = nx;
            points[dragState.idx].y = ny;

            const intermediates = points.filter(p => p.x > 0.001 && p.x < 0.999);
            window.setCustomCurvePoints(dragState.ctrlName, intermediates);
            _redrawCustom();
            e.preventDefault();
        });

        canvas.addEventListener('pointerup', () => {
            dragState = null;
        });

        canvas.addEventListener('pointercancel', () => {
            dragState = null;
        });

        canvas.addEventListener('contextmenu', (e) => {
            const ctrlName = _getActiveCustomCtrlName();
            if (!ctrlName || window._lastCurveType !== 'custom') {return;}
            const rect = canvas.getBoundingClientRect();
            const cvX = e.clientX - rect.left;
            const cvY = e.clientY - rect.top;
            const points = window.getCustomCurvePoints(ctrlName);
            const hit = hitTest(cvX, cvY, points, window._lastCurveIsBipolar);
            if (hit >= 0) {
                deletePoint(hit, points, ctrlName);
                e.preventDefault();
            }
        });
    };
})();

/**
 * @purpose Curve preview canvas drawing and custom curve interpolation.
 * Extraído de settings_curves.js.
 */

(function() {
    const _customCurveState = null;

    function _evalCustomCurve(x, points) {
        if (!points || points.length < 2) {return x;}
        for (let i = 0; i < points.length - 1; i++) {
            const a = points[i], b = points[i + 1];
            if (x >= a.x && x <= b.x) {
                const t = (x - a.x) / (b.x - a.x || 1);
                return a.y + (b.y - a.y) * t;
            }
        }
        return points[points.length - 1].y;
    }

    function _getActiveCustomCtrlName() {
        const atSel = document.getElementById('settings-curve-aftertouch');
        const mwSel = document.getElementById('settings-curve-modwheel');
        const pbSel = document.getElementById('settings-curve-pitchbend');
        if (atSel && atSel.value === 'custom') {return 'aftertouch';}
        if (mwSel && mwSel.value === 'custom') {return 'modwheel';}
        if (pbSel && pbSel.value === 'custom') {return 'pitchbend';}
        return null;
    }

    window.drawCurvePreview = function(curveType, bipolar) {
        if (bipolar === undefined) {bipolar = false;}
        window._lastCurveType = curveType;
        window._lastCurveIsBipolar = bipolar;
        const canvas = document.getElementById('curve-preview-canvas');
        if (!canvas) {return;}
        const ctx = canvas.getContext('2d');
        const w = canvas.width;
        const h = canvas.height;
        const pad = 8;
        const graphW = w - pad * 2;
        const graphH = h - pad * 2;
        const centerY = pad + graphH / 2;

        ctx.clearRect(0, 0, w, h);

        // Grid lines
        ctx.strokeStyle = 'rgba(255,255,255,0.06)';
        ctx.lineWidth = 1;
        for (let i = 0; i <= 4; i++) {
            const x = pad + (i / 4) * graphW;
            const y = pad + (1 - i / 4) * graphH;
            ctx.beginPath(); ctx.moveTo(x, pad); ctx.lineTo(x, pad + graphH); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(pad, y); ctx.lineTo(pad + graphW, y); ctx.stroke();
        }

        // Center line for bipolar
        if (bipolar) {
            ctx.strokeStyle = 'rgba(255,255,255,0.15)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(pad, centerY);
            ctx.lineTo(pad + graphW, centerY);
            ctx.stroke();
        }

        // Diagonal reference
        ctx.strokeStyle = 'rgba(255,255,255,0.12)';
        ctx.lineWidth = 1;
        ctx.setLineDash([2, 3]);
        ctx.beginPath();
        ctx.moveTo(pad, pad + graphH);
        ctx.lineTo(pad + graphW, pad);
        ctx.stroke();
        ctx.setLineDash([]);

        // Curve line
        const brandColor = getComputedStyle(document.documentElement).getPropertyValue('--brand-accent').trim() || '#ff9900';
        ctx.strokeStyle = brandColor;
        ctx.lineWidth = 2;
        ctx.beginPath();

        let customPoints = null;
        if (curveType === 'custom') {
            const ctrlName = _getActiveCustomCtrlName();
            if (ctrlName) {customPoints = window.getCustomCurvePoints(ctrlName);}
        }

        for (let px = 0; px <= graphW; px++) {
            const t = px / graphW;
            let canvasY;

            if (bipolar) {
                const input = t * 2 - 1;
                let output;
                if (curveType === 'custom' && customPoints) {
                    const abs = Math.abs(input);
                    const sign = input >= 0 ? 1 : -1;
                    output = sign * _evalCustomCurve(abs, customPoints);
                } else {
                    output = typeof window.applyBipolarCurve === 'function'
                        ? window.applyBipolarCurve(input, curveType)
                        : input;
                }
                canvasY = centerY - output * (graphH / 2);
            } else {
                let y;
                if (curveType === 'custom' && customPoints) {
                    y = _evalCustomCurve(t, customPoints);
                } else {
                    y = typeof window.applyControllerCurve === 'function'
                        ? window.applyControllerCurve(t, curveType)
                        : t;
                }
                canvasY = pad + graphH - y * graphH;
            }

            const canvasX = pad + px;
            if (px === 0) {ctx.moveTo(canvasX, canvasY);}
            else {ctx.lineTo(canvasX, canvasY);}
        }
        ctx.stroke();

        // Label
        const CURVE_LABELS = {
            'linear': 'Linear',
            'expo2':  'Quadratic',
            'expo3':  'Cubic',
            'log':    'Log',
            's-curve':'S-Curve',
            'custom': 'Custom'
        };
        const label = (bipolar ? 'Bipolar ' : '') + (CURVE_LABELS[curveType] || curveType);
        ctx.fillStyle = brandColor;
        ctx.font = 'bold 8px Share Tech Mono, monospace';
        ctx.textAlign = 'right';
        ctx.fillText(label, pad + graphW, pad + 9);
        ctx.textAlign = 'start';

        // Axis labels
        ctx.fillStyle = 'rgba(255,255,255,0.3)';
        ctx.font = '7px Share Tech Mono, monospace';
        if (bipolar) {
            ctx.fillText('-1', pad, pad + graphH + 7);
            ctx.fillText('0', pad + graphW / 2 - 3, pad + graphH + 7);
            ctx.fillText('+1', pad + graphW - 7, pad + graphH + 7);
        } else {
            ctx.fillText('0', pad, pad + graphH + 7);
            ctx.fillText('1', pad + graphW - 5, pad + graphH + 7);
        }

        // Custom curve nodes
        if (curveType === 'custom') {
            const ctrlName = _getActiveCustomCtrlName();
            if (ctrlName) {
                const points = window.getCustomCurvePoints(ctrlName);
                for (let i = 0; i < points.length; i++) {
                    let cx, cy;
                    if (bipolar) {
                        const input = points[i].x * 2 - 1;
                        const output = points[i].y;
                        cx = pad + (input + 1) / 2 * graphW;
                        cy = centerY - output * (graphH / 2);
                    } else {
                        cx = pad + points[i].x * graphW;
                        cy = pad + graphH - points[i].y * graphH;
                    }
                    const isEndpoint = (i === 0 || i === points.length - 1);
                    const isSelected = _customCurveState && _customCurveState.selIdx === i;
                    const radius = isEndpoint ? 3 : 4;

                    ctx.beginPath();
                    ctx.arc(cx, cy, radius + 2, 0, Math.PI * 2);
                    ctx.fillStyle = isSelected ? brandColor : 'rgba(255,255,255,0.5)';
                    ctx.fill();

                    ctx.beginPath();
                    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
                    ctx.fillStyle = isEndpoint ? 'rgba(255,255,255,0.3)' : brandColor;
                    ctx.fill();

                    if (isEndpoint) {
                        ctx.strokeStyle = 'rgba(255,255,255,0.4)';
                        ctx.lineWidth = 1;
                        ctx.beginPath();
                        ctx.moveTo(cx - 3, cy - 3); ctx.lineTo(cx + 3, cy + 3);
                        ctx.moveTo(cx + 3, cy - 3); ctx.lineTo(cx - 3, cy + 3);
                        ctx.stroke();
                    }
                }
            }
        }
    };
})();

/**
 * @purpose Renders unpacked hardware SysEx bytes as an interactive hex grid
 * with tooltips, region highlight overlays, and search filtering.
 * Data helpers (DUMP_REGION_COLORS, getRegionColor, formatTooltip) are in
 * settings_dump_viewer_data.js; event wiring is in settings_dump_viewer_events.js.
 * @purpose_en SysEx decoded dump viewer — hex grid renderer.
 */

function renderDumpView(bytes) {
  const grid = document.getElementById('dump-byte-grid');
  const summary = document.getElementById('dump-byte-summary');
  const nameEl = document.getElementById('dump-patch-name');
  const searchInput = document.getElementById('dump-search-input');
  if (!grid) {return;}

  if (!bytes || bytes.length < 242) {
    grid.innerHTML = '<div class="text-dim text-center" style="padding:40px">No data loaded. Load a preset or click Refresh.</div>';
    if (summary) {summary.textContent = 'No bytes loaded';}
    return;
  }

  const searchTerm = searchInput ? searchInput.value.toLowerCase().trim() : '';
  const bm = window.BYTE_MAP || [];

  if (nameEl) {
    if (window._lastPresetName) {
      nameEl.textContent = window._lastPresetName;
    } else {
      nameEl.textContent = '—';
    }
  }

  let html = '';
  const rows = Math.ceil(bytes.length / 16);

  for (let row = 0; row < rows; row++) {
    const rowStart = row * 16;
    const rowEnd = Math.min(rowStart + 16, bytes.length);

    html += '<span style="color:var(--text-dim);margin-right:6px;opacity:0.5">' + rowStart.toString(16).toUpperCase().padStart(3,'0') + '0</span>';

    for (let i = rowStart; i < rowEnd; i++) {
      const val = bytes[i];
      const info = bm[i] || null;
      const region = info ? info.region : '?';
      const colors = getRegionColor(region);
      const tooltip = info
        ? formatTooltip(info, val)
        : 'Byte ' + i + ' — No mapping\nValue: ' + val + ' (0x' + val.toString(16).toUpperCase().padStart(2,'0') + ')';

      const matchesSearch = !searchTerm ||
        (info && info.param.toLowerCase().includes(searchTerm)) ||
        info && info.region.toLowerCase().includes(searchTerm) ||
        String(i).includes(searchTerm) ||
        val.toString(16).toUpperCase().padStart(2,'0').includes(searchTerm) ||
        val.toString().includes(searchTerm);

      const isReserved = (region === '?');
      const reservedStyle = isReserved ? ';border:1px dotted #555;' : '';
      const displayVal = isReserved
        ? '•' + val.toString(16).toUpperCase().padStart(2,'0')
        : val.toString(16).toUpperCase().padStart(2,'0');

      if (searchTerm && !matchesSearch) {
        html += '<span style="opacity:0.15;color:' + colors.fg + ';background:' + colors.bg + ';padding:1px 3px;margin:1px;border-radius:2px;cursor:default;font-size:9px' + reservedStyle + '" title="' + tooltip + '">' + displayVal + '</span>';
      } else {
        const highlight = searchTerm && matchesSearch ? ';outline:1px solid var(--accent-primary);outline-offset:0px' : '';
        html += '<span class="dump-byte" data-idx="' + i + '" style="color:' + colors.fg + ';background:' + colors.bg + ';padding:1px 3px;margin:1px;border-radius:2px;cursor:help;font-size:9px' + highlight + reservedStyle + '" title="' + tooltip + '">' + displayVal + '</span>';
      }
    }
    html += '<br>\n';
  }

  grid.innerHTML = html;

  const active = bytes.filter(function(b) { return b > 0; }).length;
  const zero = bytes.filter(function(b) { return b === 0; }).length;
  const total = bytes.length;
  const reservedCount = bytes.filter(function(_, i) {
    const info = bm[i] || null;
    return info && info.region === '?';
  }).length;

  if (summary) {
    const parts = [total + ' bytes', active + ' active', zero + ' zero'];
    if (reservedCount > 0) { parts.push('🟦 ' + reservedCount + ' reserved'); }
    summary.textContent = parts.join(' | ');
  }

  const byteEls = grid.querySelectorAll('.dump-byte');
  byteEls.forEach(function(el) {
    el.addEventListener('click', function() {
      const idx = parseInt(el.dataset.idx);
      const infoEl = document.getElementById('dump-selection-info');
      if (infoEl) {
        const val = bytes[idx];
        const info = bm[idx] || null;
        if (info) {
          infoEl.textContent = 'Selected: b[' + idx + '] ' + info.param + ' = ' + val + ' (0x' + val.toString(16).toUpperCase().padStart(2,'0') + ') [' + info.region + ']';
        } else {
          infoEl.textContent = 'Selected: b[' + idx + '] = ' + val + ' (0x' + val.toString(16).toUpperCase().padStart(2,'0') + ') [unmapped]';
        }
        el.style.outline = '2px solid var(--accent-primary)';
        setTimeout(function() { el.style.outline = ''; }, 1500);
      }
    });
  });
}

window.renderDumpView = renderDumpView;

