const DEFAULT_REGION_COLOR = {bg:'#111', fg:'#888'};

function getRegionColor(region) {
  return DUMP_REGION_COLORS[region] || DEFAULT_REGION_COLOR;
}

function formatTooltip(info, val) {
  const pct = (val / 255 * 100).toFixed(1);
  const lines = ['Byte ' + info.idx + ' \u2014 ' + info.param];
  lines.push('Region: ' + info.region + ' | Type: ' + info.type);
  lines.push('Value: ' + val + ' (0x' + val.toString(16).toUpperCase().padStart(2,'0') + ') [' + pct + '%]');

  if (info.type === 'toggle') {
    lines.push('\u2192 ' + (val > 0 ? 'ON (1)' : 'OFF (0)'));
  } else if (info.type === 'enum' && info.enumLabels) {
    const idx = Math.min(val, info.enumLabels.length - 1);
    lines.push('\u2192 ' + info.enumLabels[idx] + ' (index ' + idx + ')');
  } else if (info.type === 'bipolar') {
    const bipolar = val - 128;
    lines.push('\u2192 Bipolar: ' + bipolar + ' (center=0, range -128..+127)');
    if (val === 128) {lines.push('\u2192 Center (no modulation)');}
    else if (val === 0) {lines.push('\u2192 Skip step (seq) or min');}
  } else if (info.type === 'time') {
    const secs = (val / 255 * 10).toFixed(3);
    lines.push('\u2192 ' + secs + 's');
  } else if (info.type === 'ascii') {
    const ch = val >= 32 && val < 127 ? String.fromCharCode(val) : '\u00b7';
    lines.push('\u2192 \'' + ch + '\'');
  }

  if (info.desc) {lines.push('Note: ' + info.desc);}

  return lines.join('\n');
}

// eslint-disable-next-line no-var
var Logger = globalThis.Logger || console;

/**
 * @purpose Event wiring for the SysEx dump viewer: refresh, request HW, global dump, search.
 * @purpose_en Dump viewer button event handlers.
 */

function initDumpView() {
  const dumpBtn = document.querySelector('.btn[data-tab="dump"]');
  if (!dumpBtn) {return;}

  const refreshBtn = document.getElementById('dump-refresh-btn');
  const requestHwBtn = document.getElementById('dump-request-hw-btn');
  const searchInput = document.getElementById('dump-search-input');

  function refreshDump() {
    const bytes = window._lastUnpackedBytes;
    if (typeof window.renderDumpView === 'function') {
      window.renderDumpView(bytes);
    }
  }

  const requestGlobalBtn = document.getElementById('dump-request-global-btn');
  if (requestGlobalBtn) {
    requestGlobalBtn.addEventListener('click', async () => {
      const bridge = window.dualMidiBridge;
      if (!bridge) {
        alert('Bridge not initialized.');
        return;
      }
      requestGlobalBtn.disabled = true;
      requestGlobalBtn.textContent = '\u23f3 Requesting...';
      requestGlobalBtn.classList.add('btn-loading');
      try {
        const response = await bridge.requestMidiDump('global', 4000, 2);
        if (response && response.length >= 30) {
          Logger.log('[GlobalDump] \u2705 Global dump received:', response.length, 'bytes');
          if (typeof window.unpack7to8 === 'function') {
            window._lastUnpackedBytes = response;
            window._lastPresetName = 'GLOBAL SETTINGS DUMP';
            if (typeof window.renderDumpView === 'function') {
              window.renderDumpView(response);
            }
          }
        } else {
          Logger.warn('[GlobalDump] No response from hardware');
        }
      } catch (err) {
        Logger.error('[GlobalDump] Error:', err);
      } finally {
        requestGlobalBtn.disabled = false;
        requestGlobalBtn.textContent = '\ud83c\udf10 Global Dump';
        requestGlobalBtn.classList.remove('btn-loading');
      }
    });
  }

  if (requestHwBtn) {
    requestHwBtn.addEventListener('click', async () => {
      const bridge = window.dualMidiBridge;
      if (!bridge) {
        alert('Bridge not initialized.');
        return;
      }
      requestHwBtn.disabled = true;
      requestHwBtn.textContent = '\u23f3 Requesting...';
      requestHwBtn.classList.add('btn-loading');
      try {
        const response = await bridge.requestMidiDump('edit', 4000, 2);
        if (response && response.length >= 291) {
          const packedPayload = response.slice(8, 286);
          if (typeof window.unpack7to8 === 'function') {
            const unpackedBytes = window.unpack7to8(packedPayload);
            const name = (typeof window.extractNameFromRawSysex === 'function'
                ? window.extractNameFromRawSysex(response)
                : undefined) || 'EDIT BUFFER';
            window._lastUnpackedBytes = unpackedBytes;
            window._lastPresetName = name;
            if (typeof window.renderDumpView === 'function') {
              window.renderDumpView(unpackedBytes);
            }
            Logger.log('[DumpView] \u2705 Dump received and decoded:', name);
          }
        } else {
          Logger.warn('[DumpView] No response from hardware');
        }
      } catch (err) {
        Logger.error('[DumpView] Error requesting dump:', err);
      } finally {
        requestHwBtn.disabled = false;
        requestHwBtn.textContent = '\u2b07 Request from HW';
        requestHwBtn.classList.remove('btn-loading');
      }
    });
  }

  dumpBtn.addEventListener('click', () => {
    setTimeout(refreshDump, 50);
  });

  if (refreshBtn) {
    refreshBtn.addEventListener('click', refreshDump);
  }

  if (searchInput) {
    let debounceTimer;
    searchInput.addEventListener('input', () => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(refreshDump, 150);
    });
  }
}

window.initDumpView = initDumpView;

// WebUI/js/settings_fx_presets.js — FX presets export/import/clear settings
// Extracted from settings.js (initFxPresetsSetting)

function initFxPresetsSetting() {
    const countEl = document.getElementById('settings-fx-preset-count');
    const sizeEl = document.getElementById('settings-fx-preset-size');
    const exportBtn = document.getElementById('settings-fx-preset-export-btn');
    const importBtn = document.getElementById('settings-fx-preset-import-btn');
    const fileInput = document.getElementById('settings-fx-preset-file-input');
    const clearBtn = document.getElementById('settings-fx-preset-clear-btn');
    const statusEl = document.getElementById('settings-fx-preset-status');
    if (!countEl) { return; }

    const FX_KEY = 'abd-eep-fx-presets';

    function refreshStats() {
        try {
            const raw = localStorage.getItem(FX_KEY);
            if (raw) {
                const arr = JSON.parse(raw);
                if (Array.isArray(arr)) {
                    countEl.textContent = arr.length + ' preset' + (arr.length !== 1 ? 's' : '');
                    const bytes = new Blob([raw]).size;
                    sizeEl.textContent = bytes > 1024 ? (bytes / 1024).toFixed(1) + ' KB' : bytes + ' B';
                    return;
                }
            }
        } catch (e) { /* ignore */ }
        countEl.textContent = '0 presets';
        sizeEl.textContent = '\u2014';
    }

    function setStatus(msg, ms) {
        if (!statusEl) { return; }
        statusEl.textContent = msg;
        if (ms) { setTimeout(function() { statusEl.textContent = ''; }, ms); }
    }

    if (exportBtn) {
        exportBtn.addEventListener('click', function() {
            try {
                const raw = localStorage.getItem(FX_KEY);
                const arr = raw ? JSON.parse(raw) : [];
                if (!Array.isArray(arr) || arr.length === 0) {
                    setStatus('No presets to export', 3000);
                    return;
                }
                const blob = new Blob([JSON.stringify(arr, null, 2)], { type: 'application/json' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'abdeep_fx_presets_' + new Date().toISOString().slice(0, 10) + '.json';
                a.click();
                URL.revokeObjectURL(url);
                setStatus('Exported ' + arr.length + ' presets', 3000);
            } catch (e) {
                setStatus('Export failed', 3000);
            }
        });
    }

    if (importBtn && fileInput) {
        importBtn.addEventListener('click', function() { fileInput.click(); });
        fileInput.addEventListener('change', function() {
            const file = fileInput.files[0];
            if (!file) { return; }
            const reader = new FileReader();
            reader.onload = function(e) {
                try {
                    const imported = JSON.parse(e.target.result);
                    if (!Array.isArray(imported)) {
                        setStatus('Invalid file format', 3000);
                        return;
                    }
                    const existing = [];
                    try {
                        const raw = localStorage.getItem(FX_KEY);
                        if (raw) {
                            const parsed = JSON.parse(raw);
                            if (Array.isArray(parsed)) { existing.push(...parsed); }
                        }
                    } catch (ex) { /* ignore */ }

                    let added = 0;
                    imported.forEach(function(p) {
                        if (p && p.name && typeof p.type === 'number') {
                            let found = -1;
                            for (let i = 0; i < existing.length; i++) {
                                if (existing[i].name === p.name && existing[i].slot === p.slot) {
                                    found = i;
                                    break;
                                }
                            }
                            if (found >= 0) { existing[found] = p; }
                            else { existing.push(p); }
                            added++;
                        }
                    });

                    localStorage.setItem(FX_KEY, JSON.stringify(existing));
                    refreshStats();
                    setStatus('Imported ' + added + ' presets (' + imported.length + ' in file)', 3000);
                } catch (ex) {
                    setStatus('Import failed: invalid JSON', 3000);
                }
                fileInput.value = '';
            };
            reader.readAsText(file);
        });
    }

    if (clearBtn) {
        clearBtn.addEventListener('click', function() {
            const raw = localStorage.getItem(FX_KEY);
            let count = 0;
            try {
                if (raw) {
                    const arr = JSON.parse(raw);
                    if (Array.isArray(arr)) { count = arr.length; }
                }
            } catch (e) { /* ignore */ }
            if (count === 0) {
                setStatus('No presets to clear', 3000);
                return;
            }
            if (!confirm('Delete all ' + count + ' FX presets? This cannot be undone.')) { return; }
            localStorage.removeItem(FX_KEY);
            refreshStats();
            setStatus('Cleared ' + count + ' presets', 3000);
        });
    }

    refreshStats();
    window._syncFxPresetsSettingsUI = refreshStats;
}

