window.initVelocityCurveSetting = initVelocityCurveSetting;
window.drawVelocityCurvePreview = drawVelocityCurvePreview;

/**
 * @purpose Fachada del monitor SysEx. Funciones de renderizado extraídas a
 * sysex_monitor_render.js. Event wiring extraído a sysex_monitor_events.js.
