/**
 * @purpose Vocoder microphone audio core: getUserMedia, AudioContext, AnalyserNode,
 *          ScriptProcessorNode PCM capture, and JUCE bridge forwarding.
 *          Receives state via window._vocoderMicState (set by vocoder_mic_input.js).
 * @classification Module/Vocoder/Audio
 * @dependencies Requires window._vocoderMicState to be initialized first.
 */

(function () {
    'use strict';

    // Shared state (consumed by audio, UI, and facade modules)
    window._vocoderMicState = {
        audioContext: null,
        micStream: null,
        analyserNode: null,
        micEnabled: false,
        vuIntervalId: null,
        micSourceNode: null,
        captureNode: null,
        pcmBuffer: [],
        bridgeActive: false
    };

    const state = window._vocoderMicState;

    /** Solicita permiso de micrófono y captura el MediaStream */
    async function requestMic() {
        if (state.micStream) {return true;}
        try {
            state.micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
            return true;
        } catch (err) {
            console.warn('[VocoderMic] Mic permission denied or unavailable:', err.message);
            return false;
        }
    }

    /** Construye AudioContext + AnalyserNode + ScriptProcessorNode para PCM */
    function startAudioPipeline() {
        if (state.audioContext) {return;}

        try {
            state.audioContext = new (window.AudioContext || window.webkitAudioContext)();
            state.analyserNode = state.audioContext.createAnalyser();
            state.analyserNode.fftSize = 256;

            if (state.micStream) {
                state.micSourceNode = state.audioContext.createMediaStreamSource(state.micStream);
                state.micSourceNode.connect(state.analyserNode);

                state.captureNode = state.audioContext.createScriptProcessor(1024, 1, 1);
                state.analyserNode.connect(state.captureNode);
                state.captureNode.connect(state.audioContext.destination);

                state.captureNode.onaudioprocess = function (e) {
                    const input = e.inputBuffer.getChannelData(0);
                    state.pcmBuffer = Array.from(input);

                    if (state.bridgeActive &&
                        typeof window.juce !== 'undefined' && window.juce !== null &&
                        typeof window.juce.sendModulatorAudioBuffer === 'function') {
                        try {
                            window.juce.sendModulatorAudioBuffer(state.pcmBuffer);
                        } catch (err) {
                            // bridge not available in this context
                        }
                    }
                };
            }
        } catch (err) {
            console.warn('[VocoderMic] Audio pipeline error:', err.message);
        }
    }

    /** Detiene y limpia todo el pipeline de audio */
    function stopAudioPipeline() {
        if (state.captureNode) {
            try { state.captureNode.disconnect(); } catch (e) { /* ignore */ }
            state.captureNode = null;
        }
        if (state.analyserNode) {
            try { state.analyserNode.disconnect(); } catch (e) { /* ignore */ }
            state.analyserNode = null;
        }
        if (state.micSourceNode) {
            try { state.micSourceNode.disconnect(); } catch (e) { /* ignore */ }
            state.micSourceNode = null;
        }
        if (state.audioContext) {
            state.audioContext.close().catch(function () {});
            state.audioContext = null;
        }
        state.pcmBuffer = [];
    }

    /** Detiene el MediaStream y libera los tracks */
    function stopMicStream() {
        if (state.micStream) {
            state.micStream.getTracks().forEach(function (t) { t.stop(); });
            state.micStream = null;
        }
    }

    /** Detecta si el bridge JUCE está disponible para recibir buffers PCM */
    function detectBridge() {
        state.bridgeActive = !!(typeof window.juce !== 'undefined' && window.juce !== null &&
            typeof window.juce.sendModulatorAudioBuffer === 'function');
    }

    // --- Public API ---
    window._vocoderMicAudio = {
        requestMic: requestMic,
        startAudioPipeline: startAudioPipeline,
        stopAudioPipeline: stopAudioPipeline,
        stopMicStream: stopMicStream,
        detectBridge: detectBridge
    };

    if (typeof module !== 'undefined' && module.exports) {
        module.exports = window._vocoderMicAudio;
    }
})();

/**
 * @purpose Vocoder microphone input: facade that initializes shared state and wires
 *          audio (vocoder_mic_audio.js) and UI (vocoder_mic_ui.js) modules.
 *          Load AFTER both sub-modules in index.html.
 * @classification Module/Vocoder/Facade
 * @dependencies vocoder_mic_audio.js → vocoder_mic_ui.js → vocoder_mic_input.js
 */

(function () {
    'use strict';

    const audio = window._vocoderMicAudio;
    const ui = window._vocoderMicUI;

    if (!audio || !ui) {
        console.warn('[VocoderMic] Audio or UI module not loaded');
        return;
    }

    // --- Public API ---

    /** Inicializa el módulo: detecta bridge, inyecta UI, observa cambios */
    window.initVocoderMic = function () {
        audio.detectBridge();
        ui.injectVocoderUI();

        // MutationObserver: reacciona a cambios en el modal FX
        const fxModal = document.querySelector('fx-modal') || document.getElementById('fx-modal');
        if (fxModal) {
            let timer = null;
            const observer = new MutationObserver(function () {
                if (timer) {clearTimeout(timer);}
                timer = setTimeout(function () {
                    window.syncVocoderMicUI();
                }, 150);
            });
            observer.observe(fxModal, { childList: true, subtree: true, attributes: false });
        }
    };

    /** Hook para effects.js — se llama después de re-render del panel FX */
    window._onFxTypeChanged = function () {
        window.syncVocoderMicUI();
    };

    /** Sincroniza la UI del vocoder: muestra/oculta según el tipo FX activo */
    window.syncVocoderMicUI = function () {
        if (!ui.isVocoderActive()) {
            if (window._vocoderMicState.micEnabled) {ui.toggleMic();}
            const section = document.getElementById('vocoder-mic-section');
            if (section) {section.remove();}
        } else {
            ui.injectVocoderUI();
        }
    };

    // --- Auto-init cuando el DOM está listo ---
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', window.initVocoderMic);
    } else {
        window.initVocoderMic();
    }

    // Support for vitest / Node.js
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = {
            initVocoderMic: window.initVocoderMic,
            syncVocoderMicUI: window.syncVocoderMicUI,
            _onFxTypeChanged: window._onFxTypeChanged
        };
    }
})();

/**
 * @purpose Vocoder microphone UI: VU meter rendering, toggle button, status display,
 *          DOM injection into Vocoder FX panel. Receives state via window._vocoderMicState.
 * @classification Module/Vocoder/UI
 * @dependencies vocoder_mic_audio.js (calls window._vocoderMicAudio internally)
 */

(function () {
    'use strict';

    const audio = (typeof window !== 'undefined' && window._vocoderMicAudio) || {};
    const state = (typeof window !== 'undefined' && window._vocoderMicState) || {};

    // --- DOM helpers (lazy) ---
    function getVUMeter() { return document.getElementById('vocoder-vu-meter'); }
    function getVUBar()   { return document.getElementById('vocoder-vu-bar'); }
    function getMicBtn()  { return document.getElementById('vocoder-mic-toggle'); }
    function getMicStatus() { return document.getElementById('vocoder-mic-status'); }

    // --- Template ---
    function createVUHTML() {
        return [
            '<div class="vocoder-mic-section" style="display:flex;flex-direction:column;gap:6px;padding:8px;border-top:1px solid var(--border-dim);margin-top:8px">',
            '  <div class="flex-row items-center gap-8" style="justify-content:space-between">',
            '    <span class="label text-xs" style="color:var(--text-secondary)">🎙️ Mic Input</span>',
            '    <button id="vocoder-mic-toggle" class="toggle-box" data-active="false"',
            '      style="padding:4px 12px;border-radius:var(--radius);cursor:pointer"',
            '      data-ctrl-tooltip="Enable microphone for Vocoder modulation">',
            '      <span class="toggle-label">Enable</span>',
            '      <div class="toggle-led"></div>',
            '    </button>',
            '  </div>',
            '  <div id="vocoder-vu-meter" style="height:6px;background:var(--bg-deepest);border-radius:3px;overflow:hidden;opacity:0.3;transition:opacity 0.3s">',
            '    <div id="vocoder-vu-bar" style="height:100%;width:0%;background:var(--accent-green);border-radius:3px;transition:width 0.08s ease"></div>',
            '  </div>',
            '  <span id="vocoder-mic-status" class="text-2xs" style="color:var(--text-dim);font-family:&#39;Share Tech Mono&#39;,monospace">MICROPHONE DISABLED</span>',
            '</div>'
        ].join('\n');
    }

    // --- VU Meter ---
    function startVUMeter() {
        stopVUMeter();
        if (!state.analyserNode) {return;}

        const dataArray = new Uint8Array(state.analyserNode.frequencyBinCount);
        state.vuIntervalId = setInterval(function () {
            const bar = getVUBar();
            const meter = getVUMeter();
            if (!bar || !meter) {return;}

            state.analyserNode.getByteTimeDomainData(dataArray);
            let max = 0;
            for (let i = 0; i < dataArray.length; i++) {
                const val = Math.abs(dataArray[i] - 128) / 128;
                if (val > max) {max = val;}
            }

            const pct = Math.min(max * 100, 100);
            bar.style.width = pct + '%';

            if (pct > 80) {
                bar.style.background = 'var(--accent-red)';
            } else if (pct > 50) {
                bar.style.background = 'var(--accent-pink)';
            } else {
                bar.style.background = 'var(--accent-green)';
            }
        }, 80);
    }

    function stopVUMeter() {
        if (state.vuIntervalId) {
            clearInterval(state.vuIntervalId);
            state.vuIntervalId = null;
        }
        const bar = getVUBar();
        if (bar) {
            bar.style.width = '0%';
            bar.style.background = 'var(--accent-green)';
        }
    }

    // --- UI state update ---
    function updateUI(enabled) {
        const btn = getMicBtn();
        const meter = getVUMeter();
        const status = getMicStatus();

        if (btn) {
            btn.dataset.active = enabled ? 'true' : 'false';
            const label = btn.querySelector('.toggle-label');
            if (label) {label.textContent = enabled ? 'Enabled' : 'Enable';}
        }
        if (meter) {
            meter.style.opacity = enabled ? '1' : '0.3';
        }
        if (status) {
            status.textContent = enabled
                ? 'MICROPHONE ACTIVE — ' + (state.bridgeActive ? 'BRIDGE CONNECTED' : 'LOCAL ONLY')
                : 'MICROPHONE DISABLED';
            status.style.color = enabled ? 'var(--accent-green)' : 'var(--text-dim)';
        }
    }

    // --- Check if any FX slot has Vocoder (type 49) ---
    function isVocoderActive() {
        const selectors = document.querySelectorAll('.fx-type-select');
        for (let i = 0; i < selectors.length; i++) {
            if (parseInt(selectors[i].value, 10) === 49) {return true;}
        }
        return false;
    }

    // --- Toggle mic on/off (orchestrates audio + UI) ---
    async function toggleMic() {
        if (state.micEnabled) {
            // Disable
            state.micEnabled = false;
            stopVUMeter();
            audio.stopAudioPipeline();
            audio.stopMicStream();
            updateUI(false);
            return;
        }

        // Enable
        const granted = await audio.requestMic();
        if (!granted) {
            const status = getMicStatus();
            if (status) {
                status.textContent = '\u26A0\uFE0F MICROPHONE ACCESS DENIED \u2014 using internal noise';
                status.style.color = 'var(--accent-red)';
            }
            return;
        }

        state.micEnabled = true;
        audio.startAudioPipeline();
        startVUMeter();
        updateUI(true);
    }

    // --- Inject VU meter DOM into Vocoder FX panel ---
    function injectVocoderUI() {
        if (!isVocoderActive()) {return;}

        const container = document.querySelector('.fx-param-panel[data-fx-type="49"]');
        if (!container) {return;}
        if (document.getElementById('vocoder-mic-section')) {return;}

        const section = document.createElement('div');
        section.id = 'vocoder-mic-section';
        section.innerHTML = createVUHTML();
        container.appendChild(section);

        const btn = getMicBtn();
        if (btn) {
            btn.addEventListener('click', function (e) {
                e.preventDefault();
                toggleMic();
            });
        }
    }

    // --- Public API ---
    window._vocoderMicUI = {
        createVUHTML: createVUHTML,
        startVUMeter: startVUMeter,
        stopVUMeter: stopVUMeter,
        updateUI: updateUI,
        isVocoderActive: isVocoderActive,
        toggleMic: toggleMic,
        injectVocoderUI: injectVocoderUI,
        getVUMeter: getVUMeter,
        getVUBar: getVUBar,
        getMicBtn: getMicBtn,
        getMicStatus: getMicStatus
    };

    if (typeof module !== 'undefined' && module.exports) {
        module.exports = window._vocoderMicUI;
    }
})();

/**
 * @purpose Web Audio API AudioWorkletProcessor running the compiled WebAssembly C++ Synth Engine.
 * Runs in a high-priority background audio thread.
 */

class WasmAudioProcessor extends AudioWorkletProcessor {
    constructor() {
        super();
        this.wasmEngineReady = false;
        this.port.onmessage = (e) => this.handleMessage(e.data);
    }

    handleMessage(data) {
        if (!data) {return;}
        if (data.type === 'init_wasm') {
            this.wasmEngineReady = true;
        } else if (data.type === 'note_on') {
            if (globalThis._wasm_note_on) {
                globalThis._wasm_note_on(data.note, data.velocity || 0.8);
            }
        } else if (data.type === 'note_off') {
            if (globalThis._wasm_note_off) {
                globalThis._wasm_note_off(data.note);
            }
        } else if (data.type === 'set_param') {
            if (globalThis._wasm_set_parameter) {
                globalThis._wasm_set_parameter(data.paramId, data.value);
            }
        } else if (data.type === 'pitch_bend') {
            if (globalThis._wasm_pitch_bend) {
                globalThis._wasm_pitch_bend(data.value);
            }
        } else if (data.type === 'panic') {
            if (globalThis._wasm_panic) {
                globalThis._wasm_panic();
            }
        }
    }

    process(inputs, outputs, parameters) {
        const output = outputs[0];
        if (!output || output.length < 2) {return true;}

        const outL = output[0];
        const outR = output[1];
        const numSamples = outL.length;

        if (this.wasmEngineReady && globalThis._wasm_process_audio) {
            // Memory heap buffers passed to WASM
            globalThis._wasm_process_audio(outL, outR, numSamples);
        } else {
            // Silence buffer while engine initializes
            outL.fill(0);
            outR.fill(0);
        }

        return true;
    }
}

registerProcessor('wasm-audio-processor', WasmAudioProcessor);

/**
 * @purpose WasmBridge Manager: mode management, gesture init, and delegation to extracted audio/synth modules.
 * AudioContext init/loop/worklet → wasm_bridge_audio.js
 * Web Audio fallback synthesizer (noteOn/noteOff) → wasm_bridge_synth.js
 *
 * Operating Modes:
 *   1. 'deepmind_hw_controller': Pure canonical MIDI SysEx/NRPN hardware editor.
 *   2. 'deepmind_web_standalone': Canonical synth engine playing 100% in browser via Web Audio / WASM.
 *   3. 'abyssmind_pro': Extended super-synth (32 slots ModMatrix, 57 FX, Moog/MS20 filters).
 */

(function() {
    'use strict';

    /* global _wasmInitAudioContext, _wasmLoadAudioWorklet, _wasmStartScopeLoop */
    /* global _wasmGetAudioOutputDevices, _wasmSetAudioOutputDevice, _wasmUpdateAudioButtonUI */
    /* global _wasmNoteOn, _wasmNoteOff */

    class WasmBridge {
        constructor() {
            this.audioCtx = null;
            this.masterGain = null;
            this.analyser = null;
            this.workletNode = null;
            this.isAudioStarted = false;
            this._isInitializing = false;
            this.isWasmActive = false;
            this.currentMode = localStorage.getItem('abd-eep-operating-mode') || 'abyssmind_pro';
            this.activeVoices = {};
            this._scopeLoopId = null;
        }

        getMode() {
            return this.currentMode;
        }

        setMode(newMode) {
            if (!['deepmind_hw_controller', 'deepmind_web_standalone', 'abyssmind_pro'].includes(newMode)) {
                newMode = 'abyssmind_pro';
            }
            this.currentMode = newMode;
            localStorage.setItem('abd-eep-operating-mode', newMode);
            window.appMode = (newMode === 'deepmind_hw_controller') ? 'standard' : 'advanced';
            localStorage.setItem('abd-eep-app-mode', window.appMode);

            this._updateModeUI();

            const lcdUpdate = window.lcdSafeUpdate || function() {};
            const modeLabels = {
                'deepmind_hw_controller': 'MODE: DM12 HW CONTROLLER',
                'deepmind_web_standalone': 'MODE: DM12 WEB STANDALONE',
                'abyssmind_pro': 'MODE: ABYSSMIND PRO (WEB+HW)'
            };
            lcdUpdate(modeLabels[newMode] || 'MODE: ABYSSMIND PRO (WEB+HW)');
        }

        _updateModeUI() {
            const selector = document.getElementById('app-operating-mode-select');
            if (selector) {selector.value = this.currentMode;}

            const audioBtn = document.getElementById('wasm-audio-toggle-btn');
            if (audioBtn) {
                audioBtn.style.display = (this.currentMode !== 'deepmind_hw_controller') ? 'inline-flex' : 'none';
            }
        }

        // ─── Audio Context Management (delegated to wasm_bridge_audio.js) ───

        initAudioContext() {
            return typeof window._wasmInitAudioContext === 'function'
                ? window._wasmInitAudioContext(this)
                : false;
        }

        _loadAudioWorklet() {
            if (typeof window._wasmLoadAudioWorklet === 'function') {
                return window._wasmLoadAudioWorklet(this);
            }
        }

        _startOscilloscopeLoop() {
            if (typeof window._wasmStartScopeLoop === 'function') {
                window._wasmStartScopeLoop(this);
            }
        }

        async getAudioOutputDevices() {
            return typeof window._wasmGetAudioOutputDevices === 'function'
                ? window._wasmGetAudioOutputDevices()
                : [];
        }

        async setAudioOutputDevice(deviceId) {
            return typeof window._wasmSetAudioOutputDevice === 'function'
                ? window._wasmSetAudioOutputDevice(this, deviceId)
                : false;
        }

        _updateAudioButtonUI(active) {
            if (typeof window._wasmUpdateAudioButtonUI === 'function') {
                window._wasmUpdateAudioButtonUI(active);
            }
        }

        // ─── Synthesizer (delegated to wasm_bridge_synth.js) ───

        noteOn(note, velocity) {
            if (velocity === undefined) {velocity = 0.8;}
            if (this.currentMode === 'deepmind_hw_controller') {return;}

            this.initAudioContext();
            if (!this.audioCtx || !this.masterGain) {return;}

            if (this.audioCtx.state === 'suspended') {
                this.audioCtx.resume().catch(function() {});
            }

            // Forward to AudioWorklet DSP (when available)
            if (this.workletNode && this.workletNode.port) {
                this.workletNode.port.postMessage({ type: 'note_on', note: note, velocity: velocity });
            }

            // If WASM DSP engine is active, skip the fallback synthesis
            if (this.isWasmActive) {return;}

            // Fallback: Web Audio API subtractive synthesizer
            if (typeof window._wasmNoteOn === 'function') {
                window._wasmNoteOn(this, note, velocity);
            }
        }

        noteOff(note) {
            if (this.currentMode === 'deepmind_hw_controller') {return;}

            // Forward to AudioWorklet DSP
            if (this.workletNode && this.workletNode.port) {
                this.workletNode.port.postMessage({ type: 'note_off', note: note });
            }

            if (this.isWasmActive) {return;}

            // Fallback: release voice
            if (typeof window._wasmNoteOff === 'function') {
                window._wasmNoteOff(this, note);
            } else if (this.activeVoices[note]) {
                delete this.activeVoices[note];
            }
        }

        setParameter(paramId, value) {
            if (this.workletNode && this.workletNode.port) {
                this.workletNode.port.postMessage({ type: 'set_param', paramId: paramId, value: value });
            }
        }

        pitchBend(value) {
            if (this.workletNode && this.workletNode.port) {
                this.workletNode.port.postMessage({ type: 'pitch_bend', value: value });
            }
        }

        panic() {
            if (this.workletNode && this.workletNode.port) {
                this.workletNode.port.postMessage({ type: 'panic' });
            }
            const self = this;
            Object.keys(this.activeVoices).forEach(function(note) {
                self.noteOff(parseInt(note));
            });
        }
    }

    window.wasmBridge = new WasmBridge();

    // ─── Gesture handler: resume AudioContext on first user interaction ───

    const resumeAudioOnGesture = function() {
        const bridge = window.wasmBridge;
        if (bridge) {
            if (!bridge.audioCtx) {
                bridge.initAudioContext();
            } else if (bridge.audioCtx.state === 'suspended') {
                bridge.audioCtx.resume().then(function() {
                    bridge._updateAudioButtonUI(true);
                }).catch(function() {});
            }
        }
    };

    if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
        window.addEventListener('mousedown', resumeAudioOnGesture, { capture: true, passive: true });
        window.addEventListener('pointerdown', resumeAudioOnGesture, { capture: true, passive: true });
        window.addEventListener('touchstart', resumeAudioOnGesture, { capture: true, passive: true });
        window.addEventListener('keydown', resumeAudioOnGesture, { capture: true, passive: true });
        window.addEventListener('click', resumeAudioOnGesture, { capture: true, passive: true });
    }

    // ─── DOMContentLoaded: wire up mode selector and audio button ───

    document.addEventListener('DOMContentLoaded', function() {
        window.wasmBridge._updateModeUI();

        const selector = document.getElementById('app-operating-mode-select');
        if (selector) {
            selector.addEventListener('change', function(e) {
                window.wasmBridge.setMode(e.target.value);
            });
        }

        const audioBtn = document.getElementById('wasm-audio-toggle-btn');
        if (audioBtn) {
            audioBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                window.wasmBridge.initAudioContext();
            });
        }
    });
})();

/**
 * @purpose AudioContext initialization, AudioWorklet, oscilloscope loop, and audio output device management.
 * Extracted from wasm_bridge.js. Called via window._wasm* helpers.
 */

(function() {
    'use strict';

    /**
     * Initialize or resume the Web Audio context, master gain, and analyser.
     * @param {object} bridge - The WasmBridge instance
     * @returns {boolean} true if audio context is active, false otherwise
     */
    window._wasmInitAudioContext = function(bridge) {
        if (bridge.audioCtx && bridge.masterGain && bridge.analyser) {
            if (bridge.audioCtx.state === 'suspended') {
                bridge.audioCtx.resume().catch(function() {});
            }
            bridge.isAudioStarted = true;
            window._wasmUpdateAudioButtonUI(bridge, bridge.audioCtx.state === 'running');
            return true;
        }

        try {
            const AudioCtxClass = window.AudioContext || window.webkitAudioContext;
            if (!AudioCtxClass) {
                Logger.warn('[WasmBridge] Web Audio API no soportada.');
                return false;
            }

            const hostname = window.location.hostname || '';
            const isLocal = hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '';
            const isAuthorizedDomain = isLocal || hostname.endsWith('abdsynths.com') || hostname.endsWith('github.io');
            if (!isAuthorizedDomain) {
                Logger.warn('[WasmBridge] Domain protection active: execution restricted to authorized hosts.');
            }

            if (!bridge.audioCtx) {
                bridge.audioCtx = new AudioCtxClass({ sampleRate: 44100 });
            }

            if (!bridge.masterGain) {
                bridge.masterGain = bridge.audioCtx.createGain();
                bridge.masterGain.gain.setValueAtTime(1.0, bridge.audioCtx.currentTime);
                bridge.masterGain.connect(bridge.audioCtx.destination);
            }

            if (!bridge.analyser) {
                bridge.analyser = bridge.audioCtx.createAnalyser();
                bridge.analyser.fftSize = 512;
                bridge.masterGain.connect(bridge.analyser);
                window._wasmStartScopeLoop(bridge);
            }

            bridge.isAudioStarted = true;

            // Cargar el procesador AudioWorklet de forma asíncrona
            window._wasmLoadAudioWorklet(bridge);

            if (bridge.audioCtx.state === 'suspended') {
                bridge.audioCtx.resume().then(function() {
                    window._wasmUpdateAudioButtonUI(bridge, true);
                }).catch(function() {});
            } else {
                window._wasmUpdateAudioButtonUI(bridge, true);
            }

            // Restaurar dispositivo de salida de audio seleccionado previamente si la API lo soporta
            const savedSinkId = localStorage.getItem('abd-eep-audio-sink-id');
            if (savedSinkId && typeof bridge.audioCtx.setSinkId === 'function') {
                try { bridge.audioCtx.setSinkId(savedSinkId); } catch (e) {}
            }

            return true;
        } catch (err) {
            Logger.error('[WasmBridge] Error iniciando AudioContext:', err);
            return false;
        }
    };

    /**
     * Load the AudioWorklet module and create the DSP processor node.
     * @param {object} bridge - The WasmBridge instance
     */
    window._wasmLoadAudioWorklet = async function(bridge) {
        if (bridge._isInitializing || bridge.workletNode) {return;}
        bridge._isInitializing = true;

        try {
            Logger.log('[WasmBridge] Registrando AudioWorkletProcessor...');
            await bridge.audioCtx.audioWorklet.addModule('js/dsp-processor.js', { type: 'module' });

            bridge.workletNode = new AudioWorkletNode(bridge.audioCtx, 'abdeep-dsp-processor', {
                outputChannelCount: [2],
                processorOptions: { sampleRate: bridge.audioCtx.sampleRate }
            });

            // Escuchar el estado de inicialización del WASM
            bridge.workletNode.port.onmessage = function(event) {
                if (event.data && event.data.type === 'status' && event.data.ready) {
                    bridge.isWasmActive = true;
                    Logger.log('[WasmBridge] Motor DSP de C++ en WASM activo y listo para reproducir.');
                    const lcdUpdate = window.lcdSafeUpdate || function() {};
                    lcdUpdate('WASM ENGINE: ACTIVE');
                }
            };

            // Conectar el nodo del procesador WASM a nuestro gain maestro
            bridge.workletNode.connect(bridge.masterGain);
        } catch (e) {
            Logger.error('[WasmBridge] Fallo al cargar AudioWorklet:', e);
        } finally {
            bridge._isInitializing = false;
        }
    };

    /**
     * Start the requestAnimationFrame loop that feeds waveform + frequency data to dualMidiBridge.
     * @param {object} bridge - The WasmBridge instance
     */
    window._wasmStartScopeLoop = function(bridge) {
        if (bridge._scopeLoopId) {return;}
        const sampleArray = new Float32Array(512);
        const freqArray = new Uint8Array(256);

        const updateWaveform = function() {
            if (bridge.analyser) {
                bridge.analyser.getFloatTimeDomainData(sampleArray);
                if (window.dualMidiBridge) {
                    window.dualMidiBridge._lastAudioWaveform = Array.from(sampleArray);
                }
                bridge.analyser.getByteFrequencyData(freqArray);
                if (window.dualMidiBridge) {
                    window.dualMidiBridge._lastAudioFrequencyData = Array.from(freqArray);
                }
            }
            bridge._scopeLoopId = requestAnimationFrame(updateWaveform);
        };
        bridge._scopeLoopId = requestAnimationFrame(updateWaveform);
    };

    /**
     * Enumerate audio output devices available to the browser.
     * @returns {Promise<Array>} List of audiooutput device objects
     */
    window._wasmGetAudioOutputDevices = async function() {
        if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
            return [];
        }
        try {
            const devices = await navigator.mediaDevices.enumerateDevices();
            return devices.filter(function(device) { return device.kind === 'audiooutput'; });
        } catch (e) {
            Logger.warn('[WasmBridge] Error enumerando dispositivos de salida de audio:', e);
            return [];
        }
    };

    /**
     * Set the audio output sink device.
     * @param {object} bridge - The WasmBridge instance
     * @param {string} deviceId - The target audio output device ID
     * @returns {Promise<boolean>} true if device was set successfully
     */
    window._wasmSetAudioOutputDevice = async function(bridge, deviceId) {
        if (bridge.audioCtx && typeof bridge.audioCtx.setSinkId === 'function') {
            try {
                await bridge.audioCtx.setSinkId(deviceId);
                localStorage.setItem('abd-eep-audio-sink-id', deviceId);
                return true;
            } catch (e) {
                Logger.warn('[WasmBridge] Error cambiando dispositivo de salida de audio:', e);
                return false;
            }
        }
        return false;
    };

    /**
     * Update the audio toggle button UI state.
     * @param {boolean} active - Whether audio context is active
     */
    window._wasmUpdateAudioButtonUI = function(active) {
        const btn = document.getElementById('wasm-audio-toggle-btn');
        if (btn) {
            btn.classList.toggle('active', active);
            btn.innerText = active ? '\u{1F50A} WEB AUDIO: ON' : '\u{1F50A} ACTIVAR AUDIO WEB';
            btn.style.borderColor = active ? 'var(--accent-green,#00ffcc)' : 'var(--border,#444)';
            btn.style.color = active ? 'var(--accent-green,#00ffcc)' : 'var(--text-secondary,#ccc)';
        }
    };
})();

/**
 * @purpose Web Audio API fallback synthesizer engine extracted from wasm_bridge.js.
 * Contains _wasmNoteOn and _wasmNoteOff — the polyphonic subtractive synth (OSC1+OSC2+Noise→VCF→VCA).
 * Called by WasmBridge when AudioWorklet/WASM is not active.
 */

(function() {
    'use strict';

    /**
     * Build and start a polyphonic voice using Web Audio API nodes (fallback).
     * Emulates: OSC1 + OSC2 + Noise → VCF (ENV1) → VCA (ENV2) → masterGain
     * @param {object} bridge - The WasmBridge instance (provides audioCtx, masterGain, activeVoices)
     * @param {number} note - MIDI note number (0-127)
     * @param {number} velocity - Note velocity (0.0-1.0)
     */
    window._wasmNoteOn = function(bridge, note, velocity) {
        if (!bridge.audioCtx || !bridge.masterGain) {return;}

        // Kill any existing voice on this note
        window._wasmNoteOff(bridge, note);

        try {
            const cache = window.dualMidiBridge ? window.dualMidiBridge.parameterCache : {};
            const p = function(id, def) { return cache[id] !== undefined ? cache[id] : def; };
            const now = bridge.audioCtx.currentTime;

            // ── OSC1: Waveforms ──
            const osc1RangeVal = Math.round(p('osc1_range', 1)); // 0=16', 1=8', 2=4'
            const osc1OctShift = [-12, 0, 12][osc1RangeVal] || 0;
            const freq1 = 440 * Math.pow(2, (note + osc1OctShift - 69) / 12);

            const squareEn = p('osc1_square_enable', 0) > 0.5;
            const sawEn = p('osc1_saw_enable', 1) > 0.5;

            const oscNodes = [];
            const mixGain = bridge.audioCtx.createGain();

            // OSC1 — Saw
            if (sawEn || (!sawEn && !squareEn)) {
                const osc1s = bridge.audioCtx.createOscillator();
                osc1s.type = 'sawtooth';
                osc1s.frequency.setValueAtTime(freq1, now);
                const g1s = bridge.audioCtx.createGain();
                g1s.gain.setValueAtTime(squareEn ? 0.5 : 0.7, now);
                osc1s.connect(g1s);
                g1s.connect(mixGain);
                osc1s.start(now);
                oscNodes.push({ osc: osc1s, gain: g1s });
            }

            // OSC1 — Square/Pulse
            if (squareEn) {
                const osc1p = bridge.audioCtx.createOscillator();
                osc1p.type = 'square';
                osc1p.frequency.setValueAtTime(freq1, now);
                const g1p = bridge.audioCtx.createGain();
                g1p.gain.setValueAtTime(sawEn ? 0.5 : 0.7, now);
                osc1p.connect(g1p);
                g1p.connect(mixGain);
                osc1p.start(now);
                oscNodes.push({ osc: osc1p, gain: g1p });
            }

            // ── OSC2 ──
            const osc2Level = p('osc2_level', 0.5);
            if (osc2Level > 0.01) {
                const osc2RangeVal = Math.round(p('osc2_range', 1));
                const osc2OctShift = [-12, 0, 12][osc2RangeVal] || 0;
                const osc2PitchRaw = p('osc2_pitch', 0.5);
                const osc2Detune = (osc2PitchRaw - 0.5) * 24; // ±12 semitonos
                const freq2 = 440 * Math.pow(2, (note + osc2OctShift + osc2Detune - 69) / 12);

                const osc2 = bridge.audioCtx.createOscillator();
                osc2.type = 'sawtooth';
                osc2.frequency.setValueAtTime(freq2, now);
                const g2 = bridge.audioCtx.createGain();
                g2.gain.setValueAtTime(osc2Level * 0.7, now);
                osc2.connect(g2);
                g2.connect(mixGain);
                osc2.start(now);
                oscNodes.push({ osc: osc2, gain: g2 });
            }

            // ── Noise ──
            const noiseLevel = p('noise_level', 0);
            let noiseSource = null;
            if (noiseLevel > 0.02) {
                const bufSize = bridge.audioCtx.sampleRate * 2;
                const noiseBuf = bridge.audioCtx.createBuffer(1, bufSize, bridge.audioCtx.sampleRate);
                const data = noiseBuf.getChannelData(0);
                for (let i = 0; i < bufSize; i++) {data[i] = Math.random() * 2 - 1;}
                noiseSource = bridge.audioCtx.createBufferSource();
                noiseSource.buffer = noiseBuf;
                noiseSource.loop = true;
                const ng = bridge.audioCtx.createGain();
                ng.gain.setValueAtTime(noiseLevel * 0.5, now);
                noiseSource.connect(ng);
                ng.connect(mixGain);
                noiseSource.start(now);
            }

            // ── VCF (Filtro) ──
            const filter = bridge.audioCtx.createBiquadFilter();
            filter.type = 'lowpass';
            const rawCutoff = p('vcf_cutoff', 0.7);
            const vcfResNorm = p('vcf_resonance', 0.2);
            const rawVcfEnvDepth = p('vcf_env_depth', 0.5);

            // Bipolar env depth [-1..+1]
            const vcfEnvDepthSigned = (rawVcfEnvDepth - 0.5) * 2.0;

            const baseCutoffHz = Math.max(40, Math.pow(rawCutoff, 2.5) * 18000 + 40);
            const qVal = 0.7 + vcfResNorm * 18.0;
            filter.frequency.setValueAtTime(baseCutoffHz, now);
            filter.Q.setValueAtTime(qVal, now);

            // ── Helper para mapeo de tiempo de envolvente lineal (hardware DM12: 0-10s) ──
            const calcEnvTime = function(id, defVal) {
                const norm = Math.max(0, Math.min(1, p(id, defVal)));
                return norm * 10.0;
            };

            // ── ENV2 (VCF Envelope — Filtro) ──
            const env2A = calcEnvTime('env2_attack', 0.01);
            const env2D = calcEnvTime('env2_decay', 0.3);
            const env2S = p('env2_sustain', 0.5);
            const envPeakHz = Math.max(40, Math.min(20000, baseCutoffHz + vcfEnvDepthSigned * 14000));
            const envSustainHz = Math.max(40, Math.min(20000, baseCutoffHz + (envPeakHz - baseCutoffHz) * env2S));

            if (Math.abs(vcfEnvDepthSigned) > 0.02) {
                filter.frequency.setValueAtTime(baseCutoffHz, now);
                filter.frequency.linearRampToValueAtTime(envPeakHz, now + env2A);
                filter.frequency.linearRampToValueAtTime(envSustainHz, now + env2A + env2D);
            }

            // ── HPF ──
            const hpfCutoff = p('hpf_cutoff', 0);
            let hpf = null;
            if (hpfCutoff > 0.02) {
                hpf = bridge.audioCtx.createBiquadFilter();
                hpf.type = 'highpass';
                hpf.frequency.setValueAtTime(20 + Math.pow(hpfCutoff, 2) * 8000, now);
                hpf.Q.setValueAtTime(0.7, now);
            }

            // ── ENV1 (VCA Envelope — Amplificador / Volumen) ──
            const vcaGain = bridge.audioCtx.createGain();
            const rawVcaLevel = p('vca_level', 0.8);
            const vcaLevelNorm = Math.max(0.1, rawVcaLevel);
            const env1A = calcEnvTime('env1_attack', 0.005);
            const env1D = calcEnvTime('env1_decay', 0.3);
            const env1S = Math.max(0.0, p('env1_sustain', 0.8));
            const peakGain = Math.max(0.1, (velocity || 0.8) * 0.6 * vcaLevelNorm);
            const sustainGain = Math.max(0.001, peakGain * env1S);

            // Attack → Decay → Sustain
            vcaGain.gain.setValueAtTime(0.001, now);
            vcaGain.gain.linearRampToValueAtTime(peakGain, now + env1A);
            vcaGain.gain.linearRampToValueAtTime(sustainGain, now + env1A + env1D);

            // ── Signal chain: mixGain → filter → [hpf] → vcaGain → masterGain ──
            mixGain.connect(filter);
            if (hpf) {
                filter.connect(hpf);
                hpf.connect(vcaGain);
            } else {
                filter.connect(vcaGain);
            }
            vcaGain.connect(bridge.masterGain);

            bridge.activeVoices[note] = { oscNodes: oscNodes, noiseSource: noiseSource, filter: filter, hpf: hpf, vcaGain: vcaGain, mixGain: mixGain };
        } catch (e) {
            console.warn('[WasmBridge] Error en sintetizador Web Audio:', e);
        }
    };

    /**
     * Release a voice: ramp VCA/VCF to zero, stop oscillators, cleanup.
     * @param {object} bridge - The WasmBridge instance
     * @param {number} note - MIDI note number to release
     */
    window._wasmNoteOff = function(bridge, note) {
        if (!bridge || !bridge.activeVoices || !bridge.activeVoices[note] || !bridge.audioCtx) {return;}

        const voice = bridge.activeVoices[note];
        delete bridge.activeVoices[note];

        try {
            const now = bridge.audioCtx.currentTime;
            const cache = window.dualMidiBridge ? window.dualMidiBridge.parameterCache : {};
            const calcEnvTime = function(id, defVal) {
                const v = cache[id] !== undefined ? cache[id] : defVal;
                const norm = Math.max(0, Math.min(1, v));
                return norm * 10.0;
            };

            const env1R = calcEnvTime('env1_release', 0.3);
            const env2R = calcEnvTime('env2_release', 0.3);

            // VCA release (usar env1_release para volumen de VCA)
            if (voice.vcaGain && voice.vcaGain.gain) {
                const currentGain = Math.max(0.001, voice.vcaGain.gain.value || 0.001);
                voice.vcaGain.gain.cancelScheduledValues(now);
                voice.vcaGain.gain.setValueAtTime(currentGain, now);
                voice.vcaGain.gain.linearRampToValueAtTime(0.0001, now + env1R);
            }

            // VCF release (usar env2_release para filtro VCF)
            if (voice.filter && voice.filter.frequency) {
                const currentFreq = Math.max(20, voice.filter.frequency.value || 200);
                voice.filter.frequency.cancelScheduledValues(now);
                voice.filter.frequency.setValueAtTime(currentFreq, now);
                voice.filter.frequency.linearRampToValueAtTime(60, now + env2R);
            }

            // Detener osciladores tras el tiempo de release
            const stopTime = now + Math.max(env2R, env1R) + 0.05;
            if (voice.oscNodes) {
                voice.oscNodes.forEach(function(n) {
                    try { if (n.osc) { n.osc.stop(stopTime); } } catch (e) {}
                });
            }
            if (voice.noiseSource) {
                try { voice.noiseSource.stop(stopTime); } catch (e) {}
            }

            // Limpieza de nodos tras completar el release
            const cleanupDelay = (Math.max(env2R, env1R) + 0.2) * 1000;
            setTimeout(function() {
                if (voice.oscNodes) {
                    voice.oscNodes.forEach(function(n) {
                        try { if (n.osc) { n.osc.disconnect(); } } catch (e) {}
                    });
                }
                if (voice.noiseSource) { try { voice.noiseSource.disconnect(); } catch (e) {} }
                if (voice.filter) { try { voice.filter.disconnect(); } catch (e) {} }
                if (voice.hpf) { try { voice.hpf.disconnect(); } catch (e) {} }
                if (voice.vcaGain) { try { voice.vcaGain.disconnect(); } catch (e) {} }
                if (voice.mixGain) { try { voice.mixGain.disconnect(); } catch (e) {} }
            }, cleanupDelay);
        } catch (e) {
            console.warn('[WasmBridge] Error liberando voz en _wasmNoteOff:', e);
        }
    };
})();

/**
 * @purpose JUCE 8 Native Integration Core — bridges JUCE 8's event-based API
 * (window.__JUCE__.backend.emitEvent/addEventListener) to window.juce.fn() call style.
 * Core protocol: callJuceNative, promise management, native function wrappers, event listeners.
 * @purpose_en JUCE 8 Native Integration Core — protocol layer for the bridge.
 */

// ── Console originals (before any override) ──
const _juceOrigLog = console.log;
const _juceOrigErr = console.error;
const _juceOrigWarn = console.warn;

// ── Promise handler for native function calls ──
let _juceLastPromiseId = 0;
const _jucePromises = {};

// ── Registered native function names (must match C++ withNativeFunction calls) ──
const _juceNativeFunctionNames = [
    'logFromJS',
    'setParameter',
    'beginGesture',
    'endGesture',
    'getSynthState',
    'requestMidiDump',
    'readFactoryBankFile',
    'pianoNoteOn',
    'pianoNoteOff',
    'panic',
    'getVoiceState',
    'getAudioWaveform',
    'getCalibration',
    'setCalibration',
    'getDiagnosticSnapshot',
    'startAudioABRun',
    'renderAudioABSoftwareReference',
    'finishAudioABRun',
    'abortAudioABRun',
    'compareAudioABRun'
];

// ── Core: emit a native function call via JUCE 8 event protocol ──
function _juceCallNative(name, args) {
    const promiseId = _juceLastPromiseId++;
    const payload = { name: name, params: args, resultId: promiseId };

    return new Promise(function(resolve, reject) {
        _jucePromises[promiseId] = { resolve: resolve, reject: reject };

        if (window.__JUCE__ && window.__JUCE__.backend) {
            window.__JUCE__.backend.emitEvent('__juce__invoke', payload);
        } else {
            delete _jucePromises[promiseId];
            reject(new Error('JUCE backend not available'));
        }

        // Safety timeout: resolve with undefined after 5s if no response
        setTimeout(function() {
            if (_jucePromises[promiseId]) {
                _jucePromises[promiseId].resolve(undefined);
                delete _jucePromises[promiseId];
            }
        }, 5000);
    });
}

// ── Log to C++ file when possible ──
function _juceLogToNative(msg) {
    try {
        if (window.__JUCE__ && window.__JUCE__.backend && window._juceNativeFunctions && window._juceNativeFunctions.logFromJS) {
            window._juceNativeFunctions.logFromJS(msg);
        }
    } catch (e) { /* swallow */ }
}

// ── Create wrapper functions ──
(function() {
    const funcs = {};
    for (let i = 0; i < _juceNativeFunctionNames.length; i++) {
        const fnName = _juceNativeFunctionNames[i];
        funcs[fnName] = (function(fName) {
            return function() {
                return _juceCallNative(fName, Array.prototype.slice.call(arguments));
            };
        })(fnName);
    }
    window._juceNativeFunctions = funcs;
})();

// ── Set up __juce__complete listener for promise resolution ──
window._juceInstallCompleteListener = function() {
    if (window.__JUCE__ && window.__JUCE__.backend) {
        window.__JUCE__.backend.addEventListener('__juce__complete', function(data) {
            const p = _jucePromises[data.promiseId];
            if (p) {
                delete _jucePromises[data.promiseId];
                p.resolve(data.result);
            }
        });
        return true;
    }
    return false;
};

// ── Set up C++ → JS event listeners ──
window._juceInstallEventListeners = function() {
    if (!window.__JUCE__ || !window.__JUCE__.backend) { return false; }

    window.__JUCE__.backend.addEventListener('onParameterChanged', function(data) {
        if (window._bridgeInstance && typeof window._bridgeInstance.handleParameterChangeFromBackend === 'function') {
            window._bridgeInstance.handleParameterChangeFromBackend(data.id, data.value);
        }
    });
    return true;
};

// ── Create window.juce compatibility object ──
window._juceCreateCompat = function() {
    const juce = {};

    const keys = Object.keys(window._juceNativeFunctions);
    for (let i = 0; i < keys.length; i++) {
        const name = keys[i];
        juce[name] = window._juceNativeFunctions[name];
    }

    juce._onParameterChangedCallbacks = [];
    return juce;
};

// WebView2 Bootstrap — JUCE 8 Native Integration Compatibility Shim
// Core protocol (callJuceNative, promise handling, native function wrappers,
// listeners, createJuceCompat) is now in webview_juce_core.js.
// This file handles JUCE detection (pollForJuce), console redirect, and error handling.

(function() {
    // ── Polling: wait for window.__JUCE__ to become available ──
    let _juceReady = false;
    let _juceObject = null;

    function pollForJuce(attempt) {
        if (window.__JUCE__ && window.__JUCE__.backend) {
            if (!_juceReady) {
                _juceReady = true;
                _juceObject = window._juceCreateCompat();

                window.juce = _juceObject;
                window._juceInstallCompleteListener();
                window._juceInstallEventListeners();

                const fnNames = [];
                if (window._juceNativeFunctions) {
                    const keys = Object.keys(window._juceNativeFunctions);
                    for (let i = 0; i < keys.length; i++) { fnNames.push(keys[i]); }
                }
                _juceOrigLog.call(console, '[Bootstrap] JUCE 8 native integration ready. window.juce created with functions:',
                    fnNames.join(', '));
            }
            return;
        }

        if (attempt < 200) { // poll for up to 4 seconds (200 * 20ms)
            setTimeout(function() { pollForJuce(attempt + 1); }, 20);
        } else {
            _juceOrigWarn.call(console, '[Bootstrap] JUCE native integration not found after 4s. Running in standalone mode.');
        }
    }

    // ── Lazy getter for window.juce ──
    Object.defineProperty(window, 'juce', {
        get: function() {
            return _juceObject || this.__juceFallback || null;
        },
        set: function(val) {
            if (val && typeof val === 'object') {
                _juceObject = val;
                this.__juceFallback = val;
            }
        },
        configurable: true,
        enumerable: true
    });

    // ── Global error handler ──
    window.onerror = function(message, source, lineno, colno, _error) {
        const errText = '[JS Crash] ' + message + ' at ' + source + ':' + lineno + ':' + colno;
        _juceLogToNative(errText);
    };

    // ── Console redirect (fires only when JUCE is ready) ──
    console.log = function() {
        const args = Array.prototype.slice.call(arguments);
        _juceOrigLog.apply(console, args);
        _juceLogToNative(args.join(' '));
    };

    console.error = function() {
        const args = Array.prototype.slice.call(arguments);
        _juceOrigErr.apply(console, args);
        _juceLogToNative('[ERROR] ' + args.join(' '));
    };

    console.warn = function() {
        const args = Array.prototype.slice.call(arguments);
        _juceOrigWarn.apply(console, args);
        _juceLogToNative('[WARN] ' + args.join(' '));
    };

    // ── Start polling immediately ──
    _juceOrigLog.call(console, '[Bootstrap] Starting JUCE 8 detection poll...');
    pollForJuce(0);
})();

