    bridge.sendWebMidiParameter('osc1_saw_enable', 1.0);

    // channel 3 → statusByte = 0xB0 | (3-1) = 0xB2
    expect(outPort.send).toHaveBeenCalledWith([0xB2, 15, 127]);
