/**
 * Vitest tests for bridge-engines.js — ArpEngine + SeqEngine step algorithms, slew rate, lifecycle.
 *
 * Source:  WebUI/js/bridge-engines.js
 * Run:     npx vitest run WebUI/tests/bridgeEngines.test.js
 *
 * Covers:
 *   - _arpStep mode algorithms (10 modes: UP, DOWN, UP-DOWN, ..., RANDOM, AS-PLAYED)
 *   - _seqStep slew rate interpolation and skip detection
 *   - Engine lifecycle (init, start, stop, add/remove held notes)
 *   - _updateSeqEngine wiring and forced Free Running
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';

/* ================================================================
 * Helpers: create mock bridge state for engine tests
 * ================================================================ */

/** Create a minimal DualMidiBridge-like object for engine tests */
function makeMockBridge(customParams) {
  const bridge = {
    parameterCache: Object.assign({
      arp_enable: 1.0,
      arp_mode: 0.0,      // UP
      arp_octave: 0.0,     // 1 octave
      arp_rate: 0.5,
      arp_clock_divider: 0.0,  // 1/1
      arp_gate_time: 0.5,
      arp_hold: 0.0,
      arp_key_sync: 0.0,
      seq_enable: 0.0,
      seq_clock: 0.0,
      seq_length: 0.0,
      seq_swing: 0.0,
      seq_slew_rate: 0.0,
      seq_key_loop: 0.0,
    }, customParams || {}),
    _arpActiveNotes: [],
    _arpEngine: null,
    _seqEngine: null,
    pianoNoteOn: vi.fn(),
    pianoNoteOff: vi.fn(),
    handleParameterChangeFromBackend: vi.fn(),
    _signalMidiActivity: vi.fn(),
    midiOutput: {
      send: vi.fn(),
    },
    midiChannel: 1,
    initArpEngine: null,  // Will be set by function under test
    initSeqEngine: null,
    _arpStep: null,
    _seqStep: null,
    _arpKillAllNotes: null,
    _updateSeqEngine: null,
  };
  return bridge;
}

/** Create an arp engine object (mirrors DualMidiBridge.prototype.initArpEngine) */
function createArpEngine(bridge) {
  const self = bridge;
  const engine = {
    heldNotes: [],
    running: false,
    stepIndex: 0,
    timerId: null,
    currentDirection: 1,

    isRunning: function() {
      return this.running;
    },

    addHeldNote: function(note, velocity) {
      for (let i = 0; i < this.heldNotes.length; i++) {
        if (this.heldNotes[i].note === note) {return;}
      }
      this.heldNotes.push({ note: note, velocity: velocity });
      this.heldNotes.sort(function(a, b) { return a.note - b.note; });
      if (!this.running && self.parameterCache['arp_enable'] > 0.5) {
        this.start();
      }
    },

    removeHeldNote: function(note) {
      for (let i = 0; i < this.heldNotes.length; i++) {
        if (this.heldNotes[i].note === note) {
          this.heldNotes.splice(i, 1);
          break;
        }
      }
      if (this.heldNotes.length === 0) {
        this.stop();
      }
    },

    start: function() {
      if (this.running || this.heldNotes.length === 0) {return;}
      this.running = true;
      this.stepIndex = 0;
      this.currentDirection = 1;
    },

    stop: function() {
      if (!this.running) {return;}
      this.running = false;
      if (this.timerId) {
        clearInterval(this.timerId);
        this.timerId = null;
      }
      if (self._arpKillAllNotes) {self._arpKillAllNotes();}
    },

    setHeldNotes: function(notes) {
      this.heldNotes = notes;
      if (this.heldNotes.length > 0 && !this.running) {
        this.start();
      } else if (this.heldNotes.length === 0 && this.running) {
        this.stop();
      }
    }
  };
  return engine;
}

/** Create a seq engine object (mirrors DualMidiBridge.prototype.initSeqEngine) */
function createSeqEngine(bridge) {
  const self = bridge;
  const engine = {
    running: false,
    stepIndex: 0,
    timerId: null,
    previousValues: new Array(32).fill(0),
    heldNotes: [],
    _forcedFreeRunning: false,

    addHeldNote: function(note, velocity) {
      for (let i = 0; i < this.heldNotes.length; i++) {
        if (this.heldNotes[i].note === note) {return;}
      }
      this.heldNotes.push({ note: note, velocity: velocity });
      const seqEn = self.parameterCache['seq_enable'] || 0;
      const keyLoop = Math.round((self.parameterCache['seq_key_loop'] || 0) * 2);
      const needsKeySync = (keyLoop === 1 || keyLoop === 2);
      if (seqEn > 0.5 && !this.running && needsKeySync) {
        this.start();
      }
    },

    removeHeldNote: function(note) {
      for (let i = 0; i < this.heldNotes.length; i++) {
        if (this.heldNotes[i].note === note) {
          this.heldNotes.splice(i, 1);
          break;
        }
      }
      const keyLoop = Math.round((self.parameterCache['seq_key_loop'] || 0) * 2);
      const needsKeySync = (keyLoop === 1 || keyLoop === 2);
      if (this.heldNotes.length === 0 && this.running && needsKeySync) {
        this.stop();
      }
    },

    start: function() {
      if (this.running) {return;}
      this.running = true;
      this.stepIndex = 0;
    },

    stop: function() {
      if (!this.running) {return;}
      this.running = false;
      if (this.timerId) {
        clearInterval(this.timerId);
        this.timerId = null;
      }
    },

    _seqStep: function(bridge) {
      const eng = bridge._seqEngine;
      if (!eng || !eng.running) {return;}

      const keyLoop = Math.round((bridge.parameterCache['seq_key_loop'] || 0) * 2);
      const needsKeySync = (keyLoop === 1 || keyLoop === 2);

      if (needsKeySync && eng.heldNotes.length === 0) {
        return;
      }

      const seqLength = Math.round((bridge.parameterCache['seq_length'] || 0) * 31) + 2;
      const swing = bridge.parameterCache['seq_swing'] || 0;
      const slewRate = bridge.parameterCache['seq_slew_rate'] || 0;

      const stepIdx = eng.stepIndex % seqLength;
      const paramId = 'seq_step_' + (stepIdx + 1);
      let stepVal = bridge.parameterCache[paramId];
      let isSkip = false;
      if (stepVal !== undefined && stepVal < 0.001 && Math.round(stepVal * 255) === 0) {
        isSkip = true;
      }
      if (stepVal === undefined) {
        const raw = bridge.parameterCache['seq_step_' + (stepIdx + 1) + '_raw'];
        if (raw === 0) {
          isSkip = true;
        }
        stepVal = stepVal || 0.5;
      }

      if (!isSkip) {
        const prev = eng.previousValues[stepIdx];
        if (prev !== undefined && slewRate > 0.01) {
          const slewFactor = Math.max(0.01, 1.0 - (slewRate * 0.5));
          stepVal = prev + (stepVal - prev) * (1 - slewFactor);
        }
        eng.previousValues[stepIdx] = stepVal;
      }

      bridge.parameterCache['seq_current_value'] = stepVal;
      bridge.parameterCache['seq_current_step'] = stepIdx;
      bridge.parameterCache['seq_current_step_skip'] = isSkip ? 1.0 : 0.0;
      bridge.handleParameterChangeFromBackend('seq_current_value', stepVal);

      eng.stepIndex++;
    }
  };
  return engine;
}

/** _arpStep logic isolated as a pure function for testing */
function _arpStep(engine, parameterCache) {
  if (!engine || !engine.running) {return { played: false };}

  const held = engine.heldNotes;
  if (held.length === 0) {
    engine.stop();
    return { played: false };
  }

  const arpMode = Math.round((parameterCache['arp_mode'] || 0) * 10);
  const arpOctave = Math.round((parameterCache['arp_octave'] || 0) * 3);
  const gateTime = parameterCache['arp_gate_time'] || 0.5;
  const arpHold = (parameterCache['arp_hold'] || 0) > 0.5;
  const arpKeySync = (parameterCache['arp_key_sync'] || 0) > 0.5;

  let noteIdx = engine.stepIndex % held.length;
  let octaveOffset = 0;

  switch (arpMode) {
    case 0:
      noteIdx = engine.stepIndex % held.length;
      octaveOffset = Math.floor(engine.stepIndex / held.length) * 12;
      break;
    case 1:
      noteIdx = (held.length - 1) - (engine.stepIndex % held.length);
      octaveOffset = Math.floor(engine.stepIndex / held.length) * 12;
      break;
    case 2:
const cycleLen = held.length * 2 - (held.length > 1 ? 2 : 1);
const pos = engine.stepIndex % cycleLen;
      if (pos < held.length) {
        noteIdx = pos;
      } else {
        noteIdx = cycleLen - pos;
      }
      octaveOffset = Math.floor(engine.stepIndex / cycleLen) * 12;
      break;
    case 3:
      noteIdx = engine.stepIndex % held.length;
      octaveOffset = Math.floor(engine.stepIndex / held.length) * 12;
      break;
    case 4:
      noteIdx = (held.length - 1) - (engine.stepIndex % held.length);
      octaveOffset = Math.floor(engine.stepIndex / held.length) * 12;
      break;
    case 5:
const cycleLen2 = held.length * 2 - (held.length > 1 ? 2 : 1);
const pos2 = engine.stepIndex % cycleLen2;
      if (pos2 < held.length) {
        noteIdx = pos2;
      } else {
        noteIdx = cycleLen2 - pos2;
      }
      octaveOffset = Math.floor(engine.stepIndex / cycleLen2) * 12;
      break;
    case 6:
      noteIdx = engine.stepIndex % held.length;
      octaveOffset = (Math.floor(engine.stepIndex / held.length) % 2) * 12;
      break;
    case 7:
      noteIdx = (held.length - 1) - (engine.stepIndex % held.length);
      octaveOffset = (Math.floor(engine.stepIndex / held.length) % 2) * 12;
      break;
    case 8:
      noteIdx = Math.floor(Math.random() * held.length);
      octaveOffset = Math.floor(Math.random() * (arpOctave + 1)) * 12;
      break;
    case 9:
      noteIdx = engine.stepIndex % held.length;
      octaveOffset = Math.floor(engine.stepIndex / held.length) * 12;
      break;
    default:
      noteIdx = engine.stepIndex % held.length;
  }

  const maxOctave = Math.min(arpOctave, 4);
  if (octaveOffset > maxOctave * 12) {
    engine.stepIndex = 0;
    noteIdx = 0;
    octaveOffset = 0;
  }

  engine.stepIndex++;

  let playedNote = null;
  if (noteIdx >= 0 && noteIdx < held.length) {
    const h = held[noteIdx];
    const outNote = h.note + octaveOffset;
    if (outNote >= 0 && outNote <= 127) {
      const intervalMs = engine.intervalMs || 200;
      const offDelay = Math.max(10, Math.round(gateTime * intervalMs));
      playedNote = { note: outNote, velocity: h.velocity, octaveOffset: octaveOffset, gateTime: gateTime, offDelay: offDelay };
    }
  }

  return {
    played: playedNote !== null,
    note: playedNote,
    noteIdx: noteIdx,
    octaveOffset: octaveOffset,
    arpMode: arpMode,
    stepIndex: engine.stepIndex,
  };
}

/** _seqStep logic isolated as a pure function for testing */
function _seqStep(engine, parameterCache) {
  if (!engine || !engine.running) {return { processed: false };}

  const keyLoop = Math.round((parameterCache['seq_key_loop'] || 0) * 2);
  const needsKeySync = (keyLoop === 1 || keyLoop === 2);

  if (needsKeySync && engine.heldNotes.length === 0) {
    return { processed: false, reason: 'key_sync_no_notes' };
  }

  const seqLength = Math.round((parameterCache['seq_length'] || 0) * 31) + 2;
  const swing = parameterCache['seq_swing'] || 0;
  const slewRate = parameterCache['seq_slew_rate'] || 0;

  const stepIdx = engine.stepIndex % seqLength;
  const paramId = 'seq_step_' + (stepIdx + 1);
  let stepVal = parameterCache[paramId];
  let isSkip = false;
  if (stepVal !== undefined && stepVal < 0.001 && Math.round(stepVal * 255) === 0) {
    isSkip = true;
  }
  if (stepVal === undefined) {
    const raw = parameterCache['seq_step_' + (stepIdx + 1) + '_raw'];
    if (raw === 0) {
      isSkip = true;
    }
    stepVal = stepVal || 0.5;
  }

  let slewApplied = false;
  if (!isSkip) {
    const prev = engine.previousValues[stepIdx];
    if (prev !== undefined && slewRate > 0.01) {
      const slewFactor = Math.max(0.01, 1.0 - (slewRate * 0.5));
      stepVal = prev + (stepVal - prev) * (1 - slewFactor);
      slewApplied = true;
    }
    engine.previousValues[stepIdx] = stepVal;
  }

  const result = {
    processed: true,
    stepIdx: stepIdx,
    stepVal: stepVal,
    isSkip: isSkip,
    seqLength: seqLength,
    slewApplied: slewApplied,
    slewRate: slewRate,
  };

  engine.stepIndex++;
  return result;
}

