    engine.heldNotes = [{ note: 60, velocity: 0.8 }];
    engine.start();
    engine.timerId = 123;
    engine.stop();
    expect(engine.running).toBe(false);
    expect(engine.timerId).toBeNull();
  });

  it('stop no-ops when not running', () => {
