    expect(result.note.note).toBe(60);
  });

  it('mode 4 (DOWN-INV) step 0 plays inverted highest note', () => {
    const engine = { running: true, stepIndex: 0, heldNotes: [{ note: 60, v: 0.8 }, { note: 64, v: 0.7 }] };
