        const bridge = { parameterCache: {}, setParameter: function() {}, handleParameterChangeFromBackend: function() {} };

        triggerUndo(undoStack, redoStack, bridge, function() { return null; }, {});
        expect(redoStack).toEqual([JSON.stringify({ a: 1 })]);
    });

