        expect(result.valid).toBe(false);
    });

    it('rejects params with out-of-range value', function() {
        const params = new Array(12).fill(0.5);
        params[5] = 1.5;
        const result = validatePresetEntry({ name: 'T', type: 0.5, gain: 0.5, params: params, patches: ['A-001'] });
        expect(result.valid).toBe(false);
    });

    it('rejects empty patches', function() {
        const result = validatePresetEntry({ name: 'T', type: 0.5, gain: 0.5, params: new Array(12).fill(0.5), patches: [] });
        expect(result.valid).toBe(false);
    });

    it('rejects patches with non-string entries', function() {
        const result = validatePresetEntry({ name: 'T', type: 0.5, gain: 0.5, params: new Array(12).fill(0.5), patches: [42] });
        expect(result.valid).toBe(false);
    });
});

