        expect(bridge._chordActiveNotes).toEqual([60, 64, 67]);
    });

    it('creates _chordActiveNotes if missing', function() {
        bridge = makeBridge({ chordType: 1 / 11.0 });
        delete bridge._chordActiveNotes;
