    const bridge = { _chordActiveNotes: [], pianoNoteOn: vi.fn(), parameterCache: { chord_enable: 1.0, chord_type: 1 / 11 } };
    // root=125: Major [0,4,7] → [125, 129, 132] → [125] only (129 and 132 are out of range)
