  it('handles vcf_pole_mode: 4-pole active when val > 0.5', () => {
    cache['vcf_pole_mode'] = 1.0;
    const btnPole2 = _makeToggle('panel-vcf-pole-2', 'vcf_pole_mode');
    const btnPole4 = _makeToggle('panel-vcf-pole-4', 'vcf_pole_mode');
