  beforeEach(() => {
    const registry = {};
    mockBridge = { parameterCache: {} };

    envAttack = _makeSliderUnit('env-ctrl-attack', 'env1_attack');
    envDecay = _makeSliderUnit('env-ctrl-decay', 'env1_decay');
    envSustain = _makeSliderUnit('env-ctrl-sustain', 'env1_sustain');
