    it('lfo_shape (no threshold) returns direct quantized value', function() {
        // lfo1_shape has no threshold gate — always evaluates floor(r*7)/6
        expect(generateMusicalRanges(function() { return 0.0; })['lfo1_shape']).toBe(0.0);
        expect(generateMusicalRanges(function() { return 0.999; })['lfo1_shape']).toBe(1.0);
    });

    it('lfo1_mono_mode: 40% ON (threshold > 0.6)', function() {
        expect(generateMusicalRanges(function() { return 0.6; })['lfo1_mono_mode']).toBe(0.0);
        expect(generateMusicalRanges(function() { return 0.600001; })['lfo1_mono_mode']).toBe(1.0);
    });

    it('mod matrix src uses probability gate (threshold > 0.3) then quantization', function() {
        // With r=0.3 (at threshold): 0.3 > 0.3 false → 0.0
        expect(generateMusicalRanges(function() { return 0.3; })['mod_matrix_slot1_src']).toBe(0.0);
        // With r=0.300001: true → floor(0.300001*22)/22 = floor(6.6)/22 = 6/22
        expect(generateMusicalRanges(function() { return 0.300001; })['mod_matrix_slot1_src']).toBe(6.0 / 22.0);
        // With r=0.999: true → floor(0.999*22)/22 = 21/22
        expect(generateMusicalRanges(function() { return 0.999; })['mod_matrix_slot1_src']).toBe(21.0 / 22.0);
    });
});

describe('generateMusicalRanges — RNG call count', function() {
    it('consumes r() for each random expression in order', function() {
        const calls = [];
        const rng = function() {
            calls.push(calls.length);
            return 0.5;
        };
        generateMusicalRanges(rng);
        expect(calls.length).toBeGreaterThan(50);
        expect(calls[0]).toBe(0);
        expect(calls[1]).toBe(1);
    });
});

describe('generateMusicalRanges — multiple calls produce independent results', function() {
    it('generates different values on successive calls with different RNG', function() {
        const call1 = generateMusicalRanges(function() { return 0.1; });
        const call2 = generateMusicalRanges(function() { return 0.9; });
        // 0.1 > 0.3 false, 0.9 > 0.3 true
        expect(call1['osc1_saw_enable']).toBe(0.0);
        expect(call2['osc1_saw_enable']).toBe(1.0);
    });
});

describe('generateMusicalRanges — edge RNG boundary values', function() {
    it('handles r() returning 0 (minimum)', function() {
        const result = generateMusicalRanges(function() { return 0.0; });
        for (const key in result) {
            if (result.hasOwnProperty(key)) {
                expect(result[key]).toBeGreaterThanOrEqual(0.0, key + ' below 0');
            }
        }
    });

    it('handles r() returning near maximum (0.999)', function() {
        const result = generateMusicalRanges(function() { return 0.999; });
        // All values should be within valid normalized range [0, 1]
        for (const key in result) {
            if (result.hasOwnProperty(key)) {
                expect(result[key]).toBeGreaterThanOrEqual(0.0, key + ' below 0');
                expect(result[key]).toBeLessThanOrEqual(1.0, key + ' above 1 (got ' + result[key] + ')');
            }
        }
    });

    it('all enum-floored values stay within [0, 1] for practical RNG [0, 1)', function() {
        // Math.random() returns [0, 1). With r=0.999, floor(r * n) = n-1, giving (n-1)/(n-1) = 1.0.
        // Only r=1.0 exactly would give floor(n) = n, producing n/n = 1.0 for some formulas
        // or n/(n-1) > 1.0 for others (e.g., floor(1*3)/2 = 3/2 = 1.5).
        // This test verifies that with realistic r() range [0, 1), all values are [0, 1].
        const rng = function() { return 0.999; };
        const result = generateMusicalRanges(rng);
        for (const key in result) {
            if (result.hasOwnProperty(key)) {
                expect(result[key]).toBeGreaterThanOrEqual(0.0);
                expect(result[key]).toBeLessThanOrEqual(1.0, key + '=' + result[key] + ' exceeds 1.0');
            }
        }
    });
});

import { describe, it, expect, beforeEach} from 'vitest';
/**
 * Tests for WebUI/js/script_shortcuts.js — ShortcutConfig CRUD, matching, formatCombo
 *
 * Strategy: self-contained extracted ShortcutConfig object with localStorage stubbing.
 */

// Global stubs for Node.js test environment
let mockStore = {};
const mockLocalStorage = (function() {
    return {
        getItem: function(key) { return mockStore[key] !== undefined ? mockStore[key] : null; },
        setItem: function(key, val) { mockStore[key] = String(val); },
        removeItem: function(key) { delete mockStore[key]; },
        clear: function() { mockStore = {}; },
        get length() { return Object.keys(mockStore).length; },
        key: function(i) { return Object.keys(mockStore)[i] || null; }
    };
})();
globalThis.localStorage = mockLocalStorage;
globalThis.window = globalThis.window || {};
globalThis.document = globalThis.document || { getElementById: function() { return null; } };

// ===== Extracted Source =====

const ShortcutConfig = {
    STORAGE_KEY: 'abd-eep-keyboard-shortcuts',

    _defaults: {
        'midi-learn':     { ctrl: true,  shift: false, alt: false, meta: false, key: 'l' },
        'panic':          { ctrl: true,  shift: true,  alt: false, meta: false, key: 'P' },
        'seq-quickstart': { ctrl: true,  shift: true,  alt: false, meta: false, key: 'S' },
        'seq-debug':      { ctrl: true,  shift: true,  alt: false, meta: false, key: 'D' },
    },

    _meta: {
        'midi-learn':     { label: 'MIDI Learn',     description: 'Toggle Learn mode',                           group: 'global',     color: '--accent-cyan' },
        'panic':          { label: 'PANIC',           description: 'All Notes Off + reset engines',                group: 'global',     color: '--accent-cyan' },
        'seq-quickstart': { label: 'SEQ Quick-Start', description: 'Open panel + enable SEQ',                     group: 'sequencer',  color: '--accent-pink' },
        'seq-debug':      { label: 'SEQ Debug',       description: 'Toggle debug mode',                           group: 'sequencer',  color: '--accent-pink' },
    },

    load: function() {
        let saved = {};
        try {
            const raw = localStorage.getItem(this.STORAGE_KEY);
            if (raw) {saved = JSON.parse(raw);}
        } catch(e) {}
        const result = {};
        for (const id in this._defaults) {
            result[id] = saved[id] ? this._deepClone(saved[id]) : this._deepClone(this._defaults[id]);
        }
        return result;
    },

    save: function(config) {
        try {
            localStorage.setItem(this.STORAGE_KEY, JSON.stringify(config));
        } catch(e) {}
    },

    get: function(id) {
        const all = this.load();
        return all[id] || this._deepClone(this._defaults[id]) || {};
    },

    set: function(id, combo) {
        const all = this.load();
        all[id] = this._deepClone(combo);
        this.save(all);
    },

    reset: function(id) {
        const all = this.load();
        delete all[id];
        this.save(all);
    },

    resetAll: function() {
        try {
            localStorage.removeItem(this.STORAGE_KEY);
        } catch(e) {}
    },

    formatCombo: function(combo) {
        if (!combo) {return '';}
        const parts = [];
        if (combo.ctrl)  {parts.push('Ctrl');}
        if (combo.shift) {parts.push('Shift');}
        if (combo.alt)   {parts.push('Alt');}
        if (combo.meta)  {parts.push('Meta');}
        if (combo.key)   {parts.push(combo.key.length === 1 ? combo.key.toUpperCase() : combo.key);}
        return parts.join(' + ');
    },

    getMeta: function(id) {
        return this._meta[id] || { label: id, description: '', group: 'other', color: '--text-dim' };
    },

    getAllIds: function() {
        return Object.keys(this._defaults);
    },

    matches: function(e, combo) {
        if (!combo) {return false;}
        if (!!e.ctrlKey  !== !!combo.ctrl)  {return false;}
        if (!!e.shiftKey !== !!combo.shift) {return false;}
        if (!!e.altKey   !== !!combo.alt)   {return false;}
        if (!!e.metaKey  !== !!combo.meta)  {return false;}
        const eventKey = e.key;
        if (combo.key && combo.key.length === 1 && eventKey.length === 1) {
            return eventKey.toLowerCase() === combo.key.toLowerCase();
        }
        return eventKey === combo.key;
    },

    _deepClone: function(obj) {
        return JSON.parse(JSON.stringify(obj));
    },

    // Extraída desde initKeyboardShortcuts para testing
    _handleKeydown: function(e) {
        if (window._shortcutCaptureActive) {return;}
        const shortcuts = ShortcutConfig.load();

        if (ShortcutConfig.matches(e, shortcuts['midi-learn'])) {
            e.preventDefault();
const bridge = window.dualMidiBridge;
            if (bridge && typeof bridge.toggleMidiLearn === 'function') {
                bridge.toggleMidiLearn();
            }
            return;
        }

        if (ShortcutConfig.matches(e, shortcuts['seq-quickstart'])) {
            e.preventDefault();
const bridge = window.dualMidiBridge;
            if (!bridge) {return;}
            const seqBtn = document.getElementById('programmer-seq-btn');
            if (seqBtn) {seqBtn.click();}
            const currentSeqEn = bridge.parameterCache['seq_enable'] || 0;
            if (currentSeqEn < 0.5) {
                bridge.setParameter('seq_enable', 1.0);
            }
            return;
        }

        if (ShortcutConfig.matches(e, shortcuts['seq-debug'])) {
            e.preventDefault();
            window._seqDebugMode = !window._seqDebugMode;
            return;
        }

        if (ShortcutConfig.matches(e, shortcuts['panic'])) {
            e.preventDefault();
            const panicBtn = document.getElementById('programmer-panic-btn');
            if (panicBtn) {
                panicBtn.click();
            }
            return;
        }
    }
};

