  const template = getOscSectionTemplate();
  class OscSection {
    constructor() {
      this.innerHTML = '';
      this.children = [];
      this.style = {};
    }
    connectedCallback() {
      if (this.children.length === 0) {
        this.innerHTML = template;
      }
    }
  }
  customElements.define('osc-section', OscSection);
  return OscSection;
}

