  'LFO1':    {bg:'#1a2a3a', fg:'#7fc8ff'},
  'LFO2':    {bg:'#1a2a3a', fg:'#7fc8ff'},
  'OSC1':    {bg:'#2a1a3a', fg:'#c87fff'},
