let _confirmResult = true;
let _clickHandlers = {};

function _resetAll() {
  _storage = {};
  _elementRegistry = {};
  _confirmResult = true;
  _clickHandlers = {};
}

function _setConfirmResult(v) { _confirmResult = v; }

function _createFakeElement(id) {
